# MLX needs Apple silicon; on Intel Macs the starter models run on Ollama
# (CPU) instead, so the same app works everywhere.
IS_MAC = sys.platform == "darwin"
IS_WIN = sys.platform == "win32"
# MLX is Apple-silicon only; everywhere else inference goes through Ollama
# (which uses CUDA automatically on an NVIDIA box).
IS_ARM = IS_MAC and platform.machine() == "arm64"

# THE APP'S WORDS SAY PC OFF A MAC (6b317). Found on Windows: the welcome
# read "private, and entirely on this Mac". The page and the app's own
# replies say "this Mac" in some fifty places; off a Mac they say PC.
_MAC_WORDS = re.compile(r"\b([Tt]his|[Yy]our|[Tt]he) ([Mm])ac\b")


def pc_words(text: str) -> str:
    if IS_MAC:
        return text
    return _MAC_WORDS.sub(
        lambda m: m.group(1) + " " + ("PC" if m.group(2) == "M" else "pc"),
        text)


def app_dir() -> str:
    """Per-user data directory (venv, memory, downloaded engines); a dev
    copy's own MILLENAI_HOME (6b319)."""
    return DEV_HOME or _real_app_dir()


def log_dir() -> str:
    return (os.path.join(app_dir(), "logs") if IS_WIN or DEV_HOME
            else os.path.expanduser("~/Library/Logs/MillenAI"))


# NOTHING PERSONAL ON A COMMAND LINE (0a 5.1, 6b326). Any login on the
# computer can read every process's arguments with `ps`, so a prompt, the
# text being read aloud and the Remote agent's host and commands travel
# in a file only this user can read (0600, under run/), deleted when the
# work ends, or on stdin.
def run_file(prefix: str, text: str, suffix: str = ".txt") -> str:
    """A new 0600 file under run/ holding `text`; its path."""
    d = os.path.join(app_dir(), "run")
    os.makedirs(d, mode=0o700, exist_ok=True)
    fd, path = tempfile.mkstemp(dir=d, prefix=prefix, suffix=suffix)
    try:
        with os.fdopen(fd, "w", encoding="utf-8", newline="") as f:
            f.write(text)
    except Exception:
        drop_run_file(path)
        raise
    return path


def drop_run_file(path):
    if path:
        try:
            os.remove(path)
        except OSError:
            pass


RUN_FILE_KINDS = (("ssh-", ".conf"), ("say-", ".txt"), ("prompt-", ".json"),
                  ("stage-", ""), (".pdf-", ".pdf"), (".pdf-", ".jsonl"))   # a PDF being read (6b546)


def sweep_run_files() -> int:
    """At a start, by the copy holding the instance lock only (no other
    copy can be using them then): the prompt, speech and ssh files a crash
    left under run/. The count."""
    d = os.path.join(app_dir(), "run")
    n = 0
    try:
        names = os.listdir(d)
    except OSError:
        return 0
    for fn in names:
        if any(fn.startswith(a) and fn.endswith(b) for a, b in RUN_FILE_KINDS):
            try:
                os.remove(os.path.join(d, fn))
                n += 1
            except OSError:
                pass
    return n


# THE TITLEBAR LOCKUP'S FONT (6b258). The page pulls Michroma from
# Google, but a native NSTextField in the titlebar cannot — it needs a
# real font file registered with CoreText. Bundled beside this file
# (fonts/) and copied into Contents/Resources by build_macos_app.sh.
_CHROME = {}            # pins the accessory so ObjC can't collect it


def resource(*parts) -> str:
    """A bundled file, whether we're running from the .app or the repo."""
    here = os.path.dirname(os.path.abspath(__file__))
    return os.path.join(here, *parts)


def _load_michroma():
    """Register the bundled Michroma with CoreText — raw ctypes because
    the app's venv has no pyobjc CoreText module. Silent on failure:
    the titlebar just falls back to the system face."""
    if _CHROME.get("font"):
        return
    try:
        import ctypes
        path = resource("fonts", "Michroma-Regular.ttf")
        if not os.path.exists(path):
            return
        CF = ctypes.CDLL("/System/Library/Frameworks/"
                         "CoreFoundation.framework/CoreFoundation")
        CT = ctypes.CDLL("/System/Library/Frameworks/"
                         "CoreText.framework/CoreText")
        CF.CFStringCreateWithCString.restype = ctypes.c_void_p
        CF.CFURLCreateWithFileSystemPath.restype = ctypes.c_void_p
        cfs = CF.CFStringCreateWithCString(
            None, path.encode("utf-8"), 0x08000100)
        cfu = CF.CFURLCreateWithFileSystemPath(
            None, ctypes.c_void_p(cfs), 0, False)
        CT.CTFontManagerRegisterFontsForURL(ctypes.c_void_p(cfu), 1, None)
        _CHROME["font"] = True
    except Exception:
        pass


def reveal(path: str):
    """Show a folder in Finder / Explorer."""
    subprocess.Popen(["explorer", path] if IS_WIN else ["open", path])


