def hw_class(mem_gb: float) -> str:
    for key, _t, ceil in HW_CLASSES:
        if mem_gb <= ceil:
            return key
    return "titan"


_gpus = {"v": None, "ts": 0.0}

# Windows keeps every display adapter's driver record here, with its real
# memory size (HardwareInformation.qwMemorySize), for any vendor
_DISPLAY_CLASS = (r"SYSTEM\CurrentControlSet\Control\Class"
                  r"\{4d36e968-e325-11ce-bfc1-08002be10318}")
_DISPLAY_GUID = "{4d36e968-e325-11ce-bfc1-08002be10318}"
# AMD integrated graphics: "Radeon(TM) Graphics", the 7x0M/8x0M laptop
# parts, Vega, and the Ryzen AI Max 80x0S. A discrete card's name has
# RX, PRO or AI PRO after "Radeon", so it never matches.
_AMD_IGPU = re.compile(
    r"Radeon\W*(?:\(TM\)\s*)?(?:Graphics\b|\d{3,4}M\b|80[4-6]0S\b|Vega\b)",
    re.I)
# the AMD integrated GPUs Ollama can use at graphics-card speed: the
# Ryzen AI Max ("Strix Halo") parts, whose shared memory is set in the
# BIOS or AMD's software (VGM) and can reach 96 GB or more
_BIG_IGPU = re.compile(r"Radeon\W*(?:\(TM\)\s*)?80[4-6]0S", re.I)
# Intel's discrete cards (A380-A770, B570/B580, Pro A60, and the laptop
# A370M-A770M, review of the port); the integrated "Intel(R) Arc(TM)
# Graphics" and "Arc 140V" have no model number here, and an integrated
# part that has one reports far under the 6 GB floor
_INTEL_DGPU = re.compile(r"Arc\W*(?:\(TM\)\s*)?(?:Pro\s+)?[AB]\d{2,3}M?\b", re.I)


def _nvidia_cards() -> list:
    """[(name, bytes)] for every NVIDIA card nvidia-smi reports."""
    out = subprocess.run(
        ["nvidia-smi", "--query-gpu=name,memory.total",
         "--format=csv,noheader,nounits"],
        capture_output=True, text=True, timeout=4,
        creationflags=getattr(subprocess, "CREATE_NO_WINDOW", 0)).stdout
    cards = []
    for line in out.splitlines():
        name, _, mb = line.rpartition(",")
        if mb.strip().isdigit():
            cards.append((name.strip(), int(mb.strip()) * 1024 * 1024))
    return cards


def _present_display_keys():
    """The display-class subkeys ("0000", "0001"...) of adapters that are
    present right now, or None when that can't be read. Windows keeps a
    removed card's driver key, memory size and all, so counting every
    key counted a card twice after a slot move or a swap (6b315, from
    review). Each PCI device names its driver key; the configuration
    manager answers only for devices that are present."""
    import winreg
    import ctypes
    locate = ctypes.windll.cfgmgr32.CM_Locate_DevNodeW
    found = set()
    enum = winreg.OpenKey(winreg.HKEY_LOCAL_MACHINE,
                          r"SYSTEM\CurrentControlSet\Enum\PCI")
    i = 0
    while True:
        try:
            dev = winreg.EnumKey(enum, i)
        except OSError:
            break
        i += 1
        try:
            dk = winreg.OpenKey(enum, dev)
        except OSError:
            continue
        j = 0
        while True:
            try:
                inst = winreg.EnumKey(dk, j)
            except OSError:
                break
            j += 1
            try:
                drv = str(winreg.QueryValueEx(winreg.OpenKey(dk, inst),
                                              "Driver")[0])
            except OSError:
                continue
            if not drv.lower().startswith(_DISPLAY_GUID):
                continue
            node = ctypes.c_uint32()
            if locate(ctypes.byref(node), "PCI\\%s\\%s" % (dev, inst),
                      0) == 0:                # CR_SUCCESS: present
                found.add(drv.rsplit("\\", 1)[-1])
    return found


def _windows_adapters() -> list:
    """[(name, provider, bytes)] for the display adapters present, from
    their drivers' registry records, which name the card and give its
    real memory for any vendor (the WMI AdapterRAM field stops at 4 GB)."""
    import winreg
    try:
        present = _present_display_keys()
    except Exception:
        present = None
    out = []
    root = winreg.OpenKey(winreg.HKEY_LOCAL_MACHINE, _DISPLAY_CLASS)
    i = 0
    while True:
        try:
            sub = winreg.EnumKey(root, i)
        except OSError:
            break
        i += 1
        if not sub.isdigit():
            continue                        # "Properties" and the like
        if present is not None and sub not in present:
            continue                        # a card that's gone
        try:
            k = winreg.OpenKey(root, sub)
        except OSError:
            continue

        def val(n):
            try:
                return winreg.QueryValueEx(k, n)[0]
            except OSError:
                return None
        mem = val("HardwareInformation.qwMemorySize")
        if not isinstance(mem, int):
            mem = 0
        row = (str(val("DriverDesc") or ""), str(val("ProviderName") or ""),
               mem)
        if present is None and row in out:
            continue          # can't tell present from gone: count once
        out.append(row)
    return out


def gpu_inventory() -> dict:
    """The graphics memory local models can use (6b315, per Patrick: a
    few words a second on the CPU "is going to be useless to anybody").
    It used to read ONE NVIDIA card: two or four cards counted as one,
    and AMD cards on Windows didn't count at all.
      cards  [(vendor, name, bytes)] of discrete cards Ollama runs on
      vram   the memory of one vendor's cards, summed: the vendor with
             the most (review of the port: an NVIDIA card and an AMD
             card don't make one pool a model can split across)
      vendor "NVIDIA", "AMD", "Intel" or "": the vendor with the most
             graphics memory, NVIDIA on a tie (the same every launch)
      igpu   bytes of an AMD Ryzen AI Max's shared graphics memory, or
             0. Ollama uses it only with OLLAMA_IGPU_ENABLE, so it
             counts only while our own Ollama runs (gpu_room_bytes)
    Other integrated graphics (Radeon 780M/890M, Intel Arc 140V) are
    left out: Ollama skips them and runs on the CPU. Cached; a failed
    read is retried after a minute. Macs report nothing: Apple silicon
    shares one pool."""
    now = time.time()
    if _gpus["v"] is not None and (_gpus["v"]["cards"] or _gpus["v"]["igpu"]
                                   or now - _gpus["ts"] < 60):
        return _gpus["v"]
    cards, igpu = [], 0
    if not IS_MAC:
        try:
            cards += [("NVIDIA", n, b) for n, b in _nvidia_cards()]
        except Exception:
            pass
        if IS_WIN:
            try:
                for name, prov, mem in _windows_adapters():
                    if "nvidia" in (name + prov).lower():
                        continue            # counted by nvidia-smi above
                    amd = ("amd" in prov.lower() or "advanced micro" in
                           prov.lower() or "radeon" in name.lower())
                    if amd and _AMD_IGPU.search(name):
                        if _BIG_IGPU.search(name) and mem >= 8 << 30:
                            igpu = max(igpu, mem)
                        continue            # integrated: Ollama skips it
                    if amd and mem >= 6 << 30:
                        cards.append(("AMD", name, mem))
                    elif (_INTEL_DGPU.search(name) and "intel" in
                          (name + prov).lower() and mem >= 6 << 30):
                        cards.append(("Intel", name, mem))
            except Exception:
                pass
    by = {}
    for v, _n, b in cards:
        by[v] = by.get(v, 0) + b
    if igpu:
        by["AMD"] = by.get("AMD", 0) + igpu
    inv = {"cards": cards, "vram": max(
               [sum(c[2] for c in cards if c[0] == v) for v in by] or [0]),
           "vendor": (max(by, key=lambda v: (by[v], v == "NVIDIA"))
                      if by else ""),
           "igpu": igpu}
    _gpus.update(v=inv, ts=now)
    return inv


def _igpu_in_use() -> bool:
    """A Ryzen AI Max's graphics memory runs models only in an Ollama
    started with OLLAMA_IGPU_ENABLE, which is ours; a user's own Ollama
    may leave it idle and run on the CPU (6b315, from review)."""
    try:
        return _managed_serve() is not None
    except Exception:           # at import, before the engines exist
        return False


def _gpu_pool() -> tuple:
    """(bytes, cards) of the largest single vendor's graphics memory,
    a Ryzen AI Max's shared memory counted with AMD while our own Ollama
    runs. Vendors are never added together (review of the port)."""
    inv = gpu_inventory()
    per = {}
    for v, _n, b in inv["cards"]:
        got = per.get(v, (0, 0))
        per[v] = (got[0] + b, got[1] + 1)
    if inv["igpu"] and _igpu_in_use():
        got = per.get("AMD", (0, 0))
        per["AMD"] = (got[0] + inv["igpu"], got[1] + 1)
    return max(per.values(), default=(0, 0))


def gpu_vram_bytes():
    """Graphics memory local models can use, one vendor's, or 0."""
    return _gpu_pool()[0]


def gpu_room_bytes():
    """What models can fill on the graphics cards: their memory less
    about 1 GiB each for the driver, the display and Ollama's buffers."""
    b, n = _gpu_pool()
    return max(0, b - n * (1 << 30))


def machine_budget_bytes(moe: bool = False):
    """What this machine can hold resident and still be FAST.

    Apple silicon shares one pool, so 75% of total memory is the real
    wired ceiling. A PC with a discrete GPU is different: what matters is
    VRAM, not the 165 GB of system RAM sitting behind it — sizing by RAM
    would offer a 120B to a 24 GB 3090, which technically runs and then
    crawls at a token a second with most layers spilled to CPU. Budget
    the card, plus a modest spill allowance, and cap by system RAM.
    None when psutil is missing — then nothing is hidden.

    6b315: a model that fits on the graphics cards runs there at full
    speed whatever the system RAM (a 96 GB card in a 64 GB PC was denied
    GPT-OSS 120B by the RAM cap), and a mixture-of-experts model (`moe`)
    runs at a usable speed with the cards full and its experts in RAM,
    so it may use both. Ollama loads without mmap on Windows, so the
    part in RAM has to fit in RAM."""
    if not HAS_PSUTIL:
        return None
    ram = int(psutil.virtual_memory().total * 0.75)
    vram = gpu_vram_bytes()
    if vram:
        room = gpu_room_bytes()
        budget = max(room, int(min(ram, vram * 1.25)))
        if moe:
            budget = max(budget, room + ram)
        return budget
    return ram


def giant_fits_here(label: str) -> bool:
    """A Windows giant is for WORKSTATIONS (6b315, per Patrick: "keep the
    giants workstation-only"). Ollama loads it without mmap, so system
    RAM and graphics memory together must hold the whole file, with 5%
    to spare. Anything smaller never sees it, whatever the boxes say."""
    if label not in WINDOWS_ONLY:
        return True
    if not HAS_PSUTIL:
        return False
    have = psutil.virtual_memory().total + gpu_vram_bytes()
    # and the row's own estimate of what it holds while answering, beside
    # what Windows and this app hold (review of the port)
    return have >= max(MODEL_INFO[label]["gb"] * 1e9 * 1.05,
                       MODEL_INFO[label]["mem"] + BASELINE_RAM)


_no_limits = {"v": None}


def no_limits() -> bool:
    if _no_limits["v"] is None:
        # NEVER CACHE A FAILED READ (6b307, found in review): this runs at
        # import, before load_prefs exists, and the NameError used to be
        # cached as False, so "no limits" was off after every restart
        # while its box still showed ticked
        try:
            _no_limits["v"] = bool(machine_prefs().get("no_limits"))
        except Exception:
            return False
    return bool(_no_limits["v"])


_giants = {"v": None}


def giants_on() -> bool:
    """The second box only counts while the first is ticked."""
    if not no_limits():
        return False
    if _giants["v"] is None:
        try:
            _giants["v"] = bool(machine_prefs().get("include_giants"))
        except Exception:
            return False           # see no_limits: a failed read isn't an answer
    return bool(_giants["v"])


def model_is_giant(label: str) -> bool:
    return MODEL_MEM_BYTES.get(label, 0) > GIANT_GB * 1e9


# A GIANT ON OLLAMA (6b314) runs mostly from system RAM on a Windows
# box, at a few words a second, and each cold load reads 290-405 GB
# from disk. It answers when picked by hand; no tier, blend, preset or
# fallback seats one on its own. The MLX giants on a 512 GB Mac Studio
# are fast enough to stay in councils.
GIANT_CTX = 32768           # Ollama would pick 256k with a big GPU (+67 GB)
GIANT_KEEP_ALIVE = "30m"    # a pause must not throw away a 400 GB load
GIANT_LOAD_TIMEOUT = 3600   # Ollama sends nothing until the load is done
BIG_MODEL_BYTES = 30e9      # over this, a fixed context and a long keep-alive
# giants whose Ollama template thinks by default; the others reject "think"
OLLAMA_THINK_OFF = {"deepseek-v3.1:671b"}


def slow_giant(label: str) -> bool:
    """A giant on Ollama that doesn't fit on the graphics cards, so most of
    it runs from system RAM (6b315: on 3-5 workstation cards it doesn't,
    and it is as quick as any model)."""
    return (model_is_giant(label)
            and MODEL_ROUTES.get(label, ("",))[0] == "ollama"
            and MODEL_MEM_BYTES.get(label, 0) > gpu_room_bytes())


_html_escape = html.escape   # do_GET's page builder names a local `html`


def giant_blurb() -> tuple:
    """(label, tooltip) for the giants box, from the catalog (6b312, per
    Patrick: "128 GB+" undersold models that download about 400 GB and
    only run with 512 GB of memory). Nothing in the catalog sits between
    GPT-OSS 120B's 64 GB and the giants' 300 GB, so the honest line is
    the memory they need, and the tooltip names them. It says "systems",
    not "Macs" (6b313), and names only the giants this computer can run
    (6b314): GLM 5.3 and DeepSeek V3.2 on an Apple-silicon Mac, DeepSeek
    V3.1 and Qwen 3 Coder on Windows. Where none can run (an Intel Mac),
    it names them all and says where they do."""
    every = [l for l in MODEL_INFO if model_is_giant(l)]
    if not every:
        return ("Include the largest models", "None in this version.")
    here = [l for l in every if SUPPORTED.get(l)]
    g = sorted(here or every, key=lambda l: MODEL_INFO[l]["mem"])

    def tier_of(label):      # the memory size a machine is sold with
        need = MODEL_INFO[label]["mem"] / 1e9
        return next((m for m in (192, 256, 384, 512, 1024) if m >= need),
                    int(need))
    tiers = sorted({tier_of(l) for l in g})
    tier = tiers[-1]

    def span(xs):
        xs = [int(x + 0.5) for x in xs]      # 404.5 reads 405, not 404
        lo, hi = min(xs), max(xs)
        return "%d" % lo if lo == hi else "%d\u2013%d" % (lo, hi)
    names = (" and ".join(g) if len(g) < 3
             else ", ".join(g[:-1]) + " and " + g[-1])
    tip = ("%s. Needs %s GB of memory and a %s GB download." % (
               names,
               "\u2013".join(map(str, tiers)),
               span([MODEL_INFO[l]["gb"] for l in g])))
    if not here:
        tip += " Won't run on this computer."
    elif any(l in WINDOWS_ONLY for l in g):
        # WORKSTATION-ONLY, AND HONEST ABOUT SPEED (6b315, per Patrick: a
        # few words a second "is going to be useless to anybody")
        tip += (" On a workstation with one graphics card: about 5\u201312 tokens a "
                "second. Fast only when it all fits in graphics memory.")
        short = [l for l in g if not giant_fits_here(l)]
        if short:
            tip += (" This computer can't hold %s." % (
                "them" if len(short) == len(g) else " or ".join(short)))
    return ("Models for %d GB+ systems" % tier, tip)


def model_fits_machine(label: str) -> bool:
    if model_is_giant(label) and not giants_on():
        return False
    if not giant_fits_here(label):
        return False               # a workstation's model, never a PC's
    if no_limits():
        # Patrick's "disobey the limits" switch: every supported model is
        # offered. The runtime admission check still referees actual RAM.
        return SUPPORTED.get(label, False)
    return fits_by_memory(label)


def fits_by_memory(label: str) -> bool:
    """model_fits_machine's memory rule alone, whatever the No limits box
    says (6b405): Light and Recommended are sized by it, so ticking the box
    only ever adds to Everything."""
    budget = machine_budget_bytes(moe=label in MOE_ROWS)
    need = MODEL_MEM_BYTES.get(label)
    if budget is None or need is None:
        return True
    if need > budget:
        return False
    if (MODEL_ROUTES.get(label, ("",))[0] == "ollama" and not IS_ARM
            and HAS_PSUTIL):
        # OFFER WHAT WILL RUN (6b315, from review): the list offered, and
        # made first-run flagships of, models that model_fits_memory then
        # refused on every ordinary day. On a PC (and an Intel Mac) the
        # same rule now decides both: the part in system RAM, with its
        # headroom, must fit beside what the OS and this app hold.
        part = _ram_part(label)
        return (part == 0 or part * _mem_factor(label)
                <= psutil.virtual_memory().total - BASELINE_RAM)
    return True


BASELINE_RAM = 6e9      # what Windows and this app hold on a working PC


def _ram_part(label: str) -> int:
    """The bytes of a model that land in system RAM. On a PC an Ollama
    model fills the graphics cards first (6b315)."""
    need = MODEL_MEM_BYTES.get(label, 0)
    if MODEL_ROUTES.get(label, ("",))[0] == "ollama" and not IS_MAC:
        need = max(0, need - gpu_room_bytes())
    return need


def _mem_factor(label: str) -> float:
    """Headroom for the KV cache and activations while a model answers:
    1.5, or 1.3 for a mixture of experts. MLX rows keep the rule the
    Macs were tuned on (the label says MoE); on Ollama every MOE_ROWS
    model counts, GPT-OSS and Gemma 4 26B included."""
    if "MoE" in label:
        return 1.3
    if (label in MOE_ROWS
            and MODEL_ROUTES.get(label, ("",))[0] == "ollama"):
        return 1.3
    return 1.5

MODEL_INFO = {c[0]: dict(icon=c[1], size=c[2], group=c[3], mlx=c[4],
                         ollama=c[5], port=c[6],
                         mem=int(c[7] * 1e9), gb=c[8], star=c[9],
                         # the catalog's size, which the picks are tuned
                         # to; gb becomes Ollama's file on an Ollama route
                         cat_gb=c[8])
              for c in CATALOG}

# a model is usable here if it has an engine this computer can actually
# run. The Windows giants are Windows only (6b314): on a Mac, Apple
# silicon or Intel, they are neither offered nor routed, so a copy
# pulled by hand in Ollama can't be seated by a tier or a fallback.
def _mlx_runs(label: str) -> bool:
    """Whether the mlx-lm here loads the row's MLX build (MLX_REQUIRES,
    6b494); True when that isn't known."""
    need = MLX_REQUIRES.get(label)
    return not need or MLX_LM_VERSION is None or tuple(MLX_LM_VERSION) >= need


SUPPORTED = {l: bool(((i["mlx"] and IS_ARM and _mlx_runs(l)) or i["ollama"])
                     and (IS_WIN or l not in WINDOWS_ONLY))
             for l, i in MODEL_INFO.items()}

# prefer MLX on Apple silicon (fast Metal), else Ollama
MODEL_ROUTES = {}
for _l, _i in MODEL_INFO.items():
    if _l in WINDOWS_ONLY and not IS_WIN:
        continue
    if _i["mlx"] and IS_ARM and _i["port"] and _mlx_runs(_l):
        MODEL_ROUTES[_l] = ("mlx", _i["port"])
    elif _i["ollama"]:
        MODEL_ROUTES[_l] = ("ollama", _i["ollama"])

# an Ollama route downloads Ollama's file (6b315): size the row from it,
# keeping the same allowance above the file for the KV cache and buffers
for _l, (_k, _t) in MODEL_ROUTES.items():
    if _k == "ollama" and _t in OLLAMA_BYTES:
        _i = MODEL_INFO[_l]
        _extra = max(0, _i["mem"] - int(_i["gb"] * 1e9))
        _i["gb"] = round(OLLAMA_BYTES[_t] / 1e9, 1)
        _i["mem"] = max(_i["mem"], OLLAMA_BYTES[_t] + _extra)

MLX_REPOS = {l: i["mlx"] for l, i in MODEL_INFO.items() if i["mlx"]}
MLX_EST_BYTES = {l: int(i["gb"] * 1e9) for l, i in MODEL_INFO.items()}
MODEL_MEM_BYTES = {l: i["mem"] for l, i in MODEL_INFO.items()}
OLLAMA_TAGS = {l: i["ollama"] for l, i in MODEL_INFO.items() if i["ollama"]}

# ------------------------------------------------------------------ turbo
# FREE CLOUD GPU, opt-in: Groq, Cloudflare Workers AI, OpenRouter and
# Together all speak the OpenAI chat-completions dialect and all have a
# free tier. Drop a JSON file at ~/…/MillenAI/cloud.json:
#   {"name":"Groq 120B","base":"https://api.groq.com/openai/v1",
#    "key":"YOUR_KEY","model":"openai/gpt-oss-120b"}
# Keep the example on a CURRENT model — it used to name
# llama-3.3-70b-versatile, which Groq decommissioned 2026-08-16.
# Chats reach it only while Use cloud power is on (or on Cloud Only);
# a saved key is used for pictures, video, model discovery and the
# balance whatever the switch says (6b326, see cloud_allowed).
# A dev copy has its own, empty until a key is pasted into it: the
# plaintext cloud-dev-<port>.json copies of the real keys are gone
# (6b319), and the real app's boot sweep removes old ones.
# EACH PROFILE HAS ITS OWN (1a 5.7, 6b329): the keys, picks, rests and
# the provider choice belong to the profile the thread works for.
# Readers keep every field they don't use (3.1.3's shape fits later).
CLOUD_NAME = "cloud.json"


def _cloud_file() -> str:
    """cloud.json of the profile this thread works for."""
    return _pfile(CLOUD_NAME, bound_ctx())


# THE FOUR PROVIDERS' ADDRESSES, IN ONE PLACE (0a 5.14, 6b326). The
# key-save route, Gemini's pictures and Veo all read them from here. A
# dev copy's `provider-stub=http://127.0.0.1:<port>` hook points every
# one at a recording stub on this computer (the provider's host becomes
# the first part of the path, so _provider_of still reads it); nothing
# else can move them, so the shipped app always talks to the providers.
_PROVIDER_STUB = _hook_arg("provider-stub")
if not re.match(r"^http://127\.0\.0\.1:\d+$", _PROVIDER_STUB):
    _PROVIDER_STUB = ""


def _provider_url(url: str) -> str:
    return (_PROVIDER_STUB + "/" + url.split("://", 1)[1]
            if _PROVIDER_STUB else url)


PROVIDER_BASES = {
    pid: _provider_url(u) for pid, u in (
        ("gemini", "https://generativelanguage.googleapis.com/v1beta/openai"),
        ("groq", "https://api.groq.com/openai/v1"),
        ("claude", "https://api.anthropic.com/v1"),
        ("kimi", "https://api.moonshot.ai/v1"))}
# Gemini's own API, beside its OpenAI layer: pictures and Veo
GEMINI_API = _provider_url("https://generativelanguage.googleapis.com/v1beta/")


# THE CHAT GATE (0a 5.5, 6b326). Use cloud power decides one thing:
# whether a chat is answered by cloud models. Everything that is part of
# answering a chat asks this: the Fast lane, a pasted picture read in a
# chat, the council's cloud bench and merge, the funnel, the Remote
# agent's driver, titles, memory and place pins. The Cloud Only tier is
# its own opt-in. An Advanced list (`cloud: [...]`) or a named cloud
# compositor only narrows the choice; before this they turned the cloud
# on by themselves. Settings that can't be read count as off.
# What doesn't ask it (Patrick, 2026-09-28: "if the user wants to use a
# paid API key, they enter it"): a saved key is permission to use it, so
# Gemini pictures and Veo, model discovery and the Kimi balance run
# whenever a working key is saved; services that need no key (search,
# weather, maps, backdrops) run as before.
def cloud_allowed(cloud_only: bool = False) -> bool:
    if cloud_only:
        return True
    # PRIVATE CONTEXT STAYS ON THIS MAC (6b530, per Patrick): an answer
    # that carries the person's own notes and chats (and no leave to share
    # them) opens no cloud door for the rest of its request: no seat, no
    # ladder, no polish, no title or memory pass
    if know_private_now():
        return False
    try:
        # the thread's own profile's switch (6b329): a thread with none
        # counts as off
        return bool(profile_local(bound_ctx()).get("turbo"))
    except Exception:
        return False


def gate_ladder(ladder: list, req_cloud=None, cloud_only=False) -> list:
    """A cloud ladder as a question may use it: empty unless the gate is
    open, then narrowed to an Advanced run's providers (None: no list; []:
    none at all). The list never opens the gate."""
    if not cloud_allowed(cloud_only):
        return []
    if req_cloud is not None:
        ladder = [c for c in ladder if _provider_of(c) in req_cloud]
    return list(ladder)

# WHAT EACH PROVIDER'S KEY LOOKS LIKE (6b234). A half-pasted key and a
# revoked one both come back "Invalid API Key", and telling them apart by
# eye is hopeless — the field is a password box.
# Only GROQ publishes a fixed width (gsk_ + 52 = 56), so only Groq may be
# judged on an exact length. The other two are FLOORS and nothing more:
# measured against this machine's own working keys, Google's is 53 — not
# the 39 that older AIza keys ran to — and Anthropic's is 108. Calling
# either "the" length would have told a user with a perfectly good key
# that their paste was truncated, which is the exact failure this block
# exists to prevent. Prefix first, always: judge length only once the
# prefix confirms the vendor, so a format change upstream can't block a
# good key.
#   (prefix, length, is that length exact?)
KEY_SHAPE = {
    "gemini": ("AIza", 39, False),
    "groq": ("gsk_", 56, True),
    "claude": ("sk-ant-", 40, False),
    # Moonshot keys are OpenAI-styled bare "sk-" (no vendor infix), so
    # the floor stays conservative — the shape check is per-selected-
    # provider, so this can never collide with sk-ant-
    "kimi": ("sk-", 40, False),
}

# WHAT EACH PROVIDER COSTS, AND WHAT CLOUD ONLY'S MODES SEAT (6b440, per
# Patrick: "So fast doesn't gobble up all your API money and usage"). One
# table, one place to tune. The class is about the provider's CHEAPEST way
# of answering, not its best model:
#   "free"  a free tier answers (Gemini, Groq): used first in every mode.
#   "cheap" a paid key that has a small, low-priced model (Claude's
#           Haiku): in Fast and Thinking only that small model is ever
#           used (CLOUD_CHEAP_MODEL says which ids count), never Sonnet
#           or Opus.
#   "paid"  a paid key with no small model (Kimi K3): never in Fast; in
#           Thinking only after the free and cheap ones; in Pro as today.
# A rule, not a price list: nothing here reads usage.jsonl or the cost
# screen, those only show what a model cost afterwards.
CLOUD_COST = {"gemini": "free", "groq": "free", "claude": "cheap", "kimi": "paid"}
CLOUD_COST_RANK = {"free": 0, "cheap": 1, "paid": 2}
CLOUD_COST_WORDS = {"free": "free tier", "cheap": "low cost", "paid": "paid"}
CLOUD_CHEAP_MODEL = {"claude": re.compile(r"haiku", re.I)}
CLOUD_NAMES = {"gemini": "Gemini", "groq": "Groq", "claude": "Claude", "kimi": "Kimi K3"}
# the order the providers are tried in within one cost class: the strength
# order the compositor ladder has always used
CLOUD_STRENGTH = ("claude", "kimi", "gemini", "groq")
# how many models each mode seats: Fast one, Thinking three (from different
# providers), Pro every available provider as Cloud Only always did
CLOUD_MODE_SEATS = {"Fast": 1, "Thinking": 3, "Pro": 99}
CLOUD_MODE_KEYS = {"fast": "Fast", "think": "Thinking", "pro": "Pro"}
CLOUD_PROMISE = "Only cloud models answer. Nothing runs on this computer."
CLOUD_ADD_KEY = "Add a key in Settings > Models > Cloud"
# "cloud:fast", ":think", ":pro" and "cloud:m:<provider>" are Cloud Only's
# modes and picks; plain "Cloud Only" keeps its old meaning. Read in one
# place: cloud_tier_parse
_CLOUD_TIER_RX = re.compile(r"cloud:(?:(fast|think|pro)|m:(%s))" % "|".join(PROVIDER_BASES))


# NO KEYLESS CLOUD (6b310, per Patrick: remove it). Pollinations, the
# free public service that used to answer when cloud power was on with
# no key and to paint when nothing local could, received the whole
# prompt, memory and name included, never with its private flag, and
# its feed is public. Images went there with no opt-in at all. Nothing
# leaves this computer now unless the person added a key.

# A PROVIDER'S ERROR NOTICE IS NOT AN ANSWER (6b288, per Patrick, seen
# live: "The API key used for this request has reached its budget…" was
# shown to the reader as the reply, sources and all). Some endpoints
# return the failure as a 200 with the notice in the content field, so
# the HTTP-error paths never see it. Short text about keys, budgets,
# quotas or billing instead of the question IS the provider failing —
# treat it like a 402: skip that rung, rest the key, and let the next
# rung answer, down to local silicon. The reader always gets an answer.
_PROVIDER_ERR_RX = re.compile(
    r"(api[ _-]?key\b.{0,80}\b(budget|quota|limit|invalid|expired|missing|"
    r"required|revoked|rejected)|reached its budget|raise the key budget|"
    r"topping up the wallet|rate[ -]?limit(ed)?\b|too many requests|"
    r"insufficient[ _](credits?|balance|quota|funds)|payment required|"
    r"quota (exceeded|exhausted)|billing (issue|required|account)|"
    r"contact whoever runs the app|^\s*\{\s*\"error\"|^\s*error code:? \d)",
    re.I | re.S)


def _is_provider_error(text: str) -> bool:
    """True when a completion's CONTENT is the provider's own failure
    notice rather than an answer. Only short texts qualify — a real
    answer about API budgets runs long and talks about the question."""
    t = (text or "").strip()
    return 0 < len(t) < 700 and _PROVIDER_ERR_RX.search(t[:600]) is not None


def _cloud_budget_hit(c: dict):
    """Rest a keyed provider whose reply was its own budget/quota notice
    — an hour, like the free tier: the key works, the wallet doesn't."""
    try:
        pid = _provider_of(c)
        if pid:
            cloud_cool(pid, "key out of budget \u2014 resting", 3600.0,
                       key=c.get("key"))
    except Exception:
        pass


def _cloud_all() -> dict:
    """Full multi-provider state (6b218): {providers:{id:{...}}, active}.
    Legacy single-provider files are wrapped on read — the provider id
    is inferred from the base URL."""
    try:
        with open(_cloud_file()) as f:
            c = json.load(f)
    except Exception:
        return {"providers": {}, "active": ""}
    if "providers" in c:
        return c
    if c.get("base") and c.get("key"):
        which = ("gemini" if "generativelanguage" in c["base"]
                 else "claude" if "anthropic" in c["base"] else "groq")
        c["status"] = "ok"
        return {"providers": {which: c}, "active": which}
    return {"providers": {}, "active": ""}


# CLOUD.JSON WRITES ARE ATOMIC AND SERIALIZED (6b304). Every writer used
# to read, mutate, then open(CLOUD_FILE, "w") — which TRUNCATES first —
# with no lock. Council seats run on their own threads and each rests a
# provider through cloud_cool, so writers raced: a reader landing mid-write
# saw an unparseable file, _cloud_all returned {} for it, and the next
# save persisted that — erasing every other provider's API key. Measured
# by the leak hunt: 75 of 500 four-thread rounds lost keys, 210 left the
# file unparseable, and a real cloud.json.corrupt-backup sits in the
# data dir from August. Now: one re-entrant lock in-process, an flock
# across processes (belt and braces: one copy per data folder since
# 6b319), a temp-file + os.replace so no reader ever sees half a file,
# and a writer that REFUSES to persist over a file it could not parse.
try:
    import fcntl as _fcntl
except ImportError:            # Windows: the in-process lock still holds
    _fcntl = None
_cloud_lock = threading.RLock()
_cloud_depth = [0]


@contextlib.contextmanager
def _cloud_txn():
    with _cloud_lock:
        _cloud_depth[0] += 1
        lf = None
        try:
            if _cloud_depth[0] == 1 and _fcntl is not None:
                try:
                    # run/, not the profile (6b329): nothing is made in a
                    # profile's folder but its own files
                    os.makedirs(os.path.join(app_dir(), "run"), mode=0o700,
                                exist_ok=True)
                    lf = open(os.path.join(app_dir(), "run", "cloud.lock"),
                              "a")
                    _fcntl.flock(lf, _fcntl.LOCK_EX)
                except OSError:
                    lf = None
            yield
        finally:
            if lf is not None:
                try:
                    _fcntl.flock(lf, _fcntl.LOCK_UN)
                finally:
                    lf.close()
            _cloud_depth[0] -= 1


def _cloud_read_strict() -> dict:
    """Like _cloud_all, but RAISES when the file exists and cannot be
    parsed, so a writer never mistakes a damaged file for an empty one."""
    if not os.path.exists(_cloud_file()):
        return {"providers": {}, "active": ""}
    with open(_cloud_file()) as f:
        json.load(f)            # raises on damage; the value is re-read below
    return _cloud_all()


def _cloud_write(d: dict):
    """Write the whole state atomically: a sibling temp file, fsynced,
    then os.replace — readers see the old file or the new one, never half.
    0600 (_write_raw skips os.fchmod on Windows, where it only exists from
    Python 3.13, 6b317; Windows' own ACL on %LOCALAPPDATA% keeps the file
    private there). Into the thread's own profile, epoch-checked."""
    _cloud_write_to(bound_ctx(), d)


def _cloud_write_to(ctx, d: dict):
    _hook_delay("cloud-write")
    _write_raw(CLOUD_NAME, json.dumps(d).encode("utf-8"), ctx, mode=0o600)


_KEY_NOT_SAVED = ("the key works, but this computer couldn't save it "
                  "\u2014 check that the ConcordeAI folder isn't read-only")


def _cloud_save_state(ctx, which: str, entry: dict, make_active=False) -> bool:
    """False when the state couldn't be written (the key-save route says
    so rather than "saved", 6b317). Into ctx's cloud.json only (1a 5.3)."""
    prev = bind_ctx(ctx)
    try:
        with _cloud_txn():
            d = _cloud_read_strict()
            d.setdefault("providers", {})[which] = entry
            if make_active or not d.get("active"):
                if entry.get("status") == "ok":
                    d["active"] = which
            _cloud_write_to(ctx, d)
        return True
    except StaleProfile:
        raise
    except Exception:
        return False
    finally:
        bind_ctx(prev)


# A FAILED PASTE NEVER REPLACES A WORKING KEY (6b326, from review). A
# key that failed its test was saved over the provider's entry, so a
# wrong paste, a dropped connection or a DNS failure lost the key that
# worked. Now the working entry stays exactly as it was; a failed paste
# is recorded only where there was no working key.
def _cloud_save_failed(which: str, entry: dict, auth: bool = False):
    """Record a pasted key that failed its test. None when recorded; the
    kept entry's status ("ok" or "fail") when the saved entry was left as
    it was: a working key, or the same key failing for a reason that isn't
    the provider rejecting it (a timeout, no network, a busy provider:
    that says nothing about the key, from review). "" when nothing could
    be written."""
    try:
        with _cloud_txn():
            d = _cloud_read_strict()
            cur = (d.get("providers") or {}).get(which)
            if isinstance(cur, dict) and cur.get("key"):
                same = cur.get("key") == entry.get("key")
                if ((not same and cur.get("status", "ok") == "ok")
                        or (same and not auth)):
                    return cur.get("status", "ok")
            d.setdefault("providers", {})[which] = entry
            _cloud_write(d)
        return None
    except StaleProfile:
        raise
    except Exception:
        return ""


def _kept_note(name: str, kept) -> str:
    if kept == "ok":
        return ". Your saved %s key still works" % name
    if kept:
        return ". Your saved %s key is unchanged" % name
    return ""


# A KEY'S FINGERPRINT (0a 5.12 item 13, 6b326): an HMAC under a secret
# made at each launch, kept in memory only. It tells whether the key a
# request used is still the saved one without holding the key itself.
_KEY_FP_SALT = secrets.token_bytes(32)


def _key_fp(key) -> str:
    return hmac.new(_KEY_FP_SALT, str(key or "").encode("utf-8"),
                    hashlib.sha256).hexdigest()


def _same_key(saved, used) -> bool:
    return bool(saved) and bool(used) and hmac.compare_digest(
        _key_fp(saved), _key_fp(used))


# what a failure may change in a provider's entry: this computer's view
# of it. Never key, base or name.
_FAIL_FIELDS = ("status", "note", "cool", "dead", "dead_at")


def _cloud_patch(pid: str, key, fields: dict, drop=()) -> bool:
    """ONE LOCKED UPDATE of a provider's per-computer fields, applied only
    while its saved key is the one the failing request used (6b326).
    Before this a failure read the entry outside the lock and wrote the
    whole entry back, key included, so a 401 that came back after the key
    was replaced marked the new key failed, and a model retirement landing
    in the same window could put the old key back. True when written."""
    with _cloud_txn():
        d = _cloud_read_strict()
        cur = (d.get("providers") or {}).get(pid)
        if not isinstance(cur, dict) or not _same_key(cur.get("key"), key):
            return False
        for k in drop:
            if k in _FAIL_FIELDS:
                cur.pop(k, None)
        for k, v in fields.items():
            if k in _FAIL_FIELDS:
                cur[k] = v
        _cloud_write(d)
    return True


# WHY A CLOUD CALL FAILED (6b233). cloud_text swallowed every exception
# and returned "", so a revoked key and a retired model both looked like
# "that model had nothing to say": Groq showed a green tick in Settings
# while every single call came back 401, and the gemini-2.5-pro seat
# 404'd on every question ("no longer available to new users") — both
# found live while testing Cloud Only. Two failures, two consequences.
#   401/403 — the KEY is bad, so the provider is marked failed. That is
#             what makes "grey it out when no keys are active" TRUE
#             rather than "no keys were active the last time one was
#             typed in".
#   400/404 — the MODEL is gone, so only that model is retired; the
#             provider's other models carry on. Since 6b307 a 400 counts
#             only when it says the model is gone, and a retirement
#             lasts a day.
_dead_models = profile_cache("_dead_models", set())
_dead_lock = threading.Lock()


def _provider_of(c: dict) -> str:
    """Provider id for a conf, inferred from its base URL (same rule
    _cloud_all uses when it wraps a legacy single-provider file)."""
    b = c.get("base", "")
    if "generativelanguage" in b:
        return "gemini"
    if "anthropic" in b:
        return "claude"
    if "groq" in b:
        return "groq"
    if "moonshot" in b:
        return "kimi"
    return ""


_dead_loaded = profile_cache("_dead_loaded", [False])


def _dead_seed():
    """Retirements persist, or every launch re-donates a council seat to
    a model the provider has already withdrawn. Cleared for a provider
    whenever its key is re-saved — that re-runs model discovery, and is
    exactly the gesture that means "try again". Only a thread working for
    a profile reads them: one with none would set the latch having read
    nothing (review of 6b329)."""
    if _dead_loaded[0] or getattr(_tl_ctx, "ctx", None) is None:
        return
    _dead_loaded[0] = True
    try:
        now = time.time()
        for v in (_cloud_all().get("providers") or {}).values():
            stamps = v.get("dead_at") or {}
            for m in (v.get("dead") or []):
                # AN ENTRY WITHOUT A STAMP GETS ANOTHER CHANCE (6b307).
                # Every one was written by the old any-400-is-forever
                # rule: Patrick's Groq pick, openai/gpt-oss-120b, had sat
                # on this list for a month, so Groq took no council seat
                # and no Fast answer. A model really gone 404s once more
                # and is retired again, with a stamp this time.
                if m not in stamps:
                    continue
                when = float(stamps[m])
                if now - when <= DEAD_TTL:
                    _dead_models.add(m)
                    _dead_when[m] = when
    except Exception:
        pass


_QUOTA_RX = re.compile(
    r"quota|rate.?limit|resource.?exhausted|too many requests|billing",
    re.I)
# how long a throttled provider sits out. Long enough to stop hammering a
# spent per-minute bucket, short enough to come back inside one sitting.
QUOTA_COOLDOWN = 600.0
# ANY other way of not working — a 500, a timeout, a dropped connection,
# an empty completion — rests it too, just briefly. The rule Patrick
# asked for (6b236) is simply: a cloud model that isn't working gets
# dropped and the query carries on with whatever is. Short, because a
# glitch is usually a glitch, and the provider is wanted back.
GLITCH_COOLDOWN = 120.0


def _http_body(exc) -> str:
    """The provider's own words out of an HTTPError, read at most once."""
    body = getattr(exc, "cached_body", None)
    if body is None:
        try:
            body = exc.read().decode("utf-8", "replace")
        except Exception:
            body = ""
        try:
            exc.cached_body = body
        except Exception:
            pass
    return body or ""


def cloud_failure_kind(code: int, body: str) -> str:
    """'auth' — the key is bad. 'quota' — the key is FINE and merely
    throttled. 'other' — anything else.

    THE BODY GETS A VOTE, not just the status code. Google answers 429
    RESOURCE_EXHAUSTED for a spent free tier and has been seen using 403
    for the same condition, and treating that as a bad key is how a
    perfectly good Gemini key ended up permanently red in Settings while
    /models still returned 200 (found live, 6b235). A quota that resets
    by itself must never down a provider.
    """
    if code == 429 or _QUOTA_RX.search(body or ""):
        return "quota"
    if code in (401, 403):
        return "auth"
    # Google answers a revoked or expired key with 400, not 401 (6b307):
    # read as a bad request, it rotated models forever and the provider
    # never turned red
    if code == 400 and _BAD_KEY_RX.search(body or ""):
        return "auth"
    return "other"


_BAD_KEY_RX = re.compile(
    r"api[ _-]?key (not valid|invalid|expired)|API_KEY_INVALID|"
    r"invalid[ _-]api[ _-]key|invalid x-api-key", re.I)


def cloud_cool(pid: str, note: str, secs: float = QUOTA_COOLDOWN, *, key):
    """Bench a provider WITHOUT marking it failed: status stays ok, so it
    returns on its own when the window passes. `key` is the key the
    request used: a provider whose key has changed since is left alone
    (6b326)."""
    try:
        _cloud_patch(pid, key, {"status": "ok", "cool": time.time() + secs,
                                "note": note[:120]})
    except Exception:
        pass


def _key_live(c: dict) -> bool:
    """True while the key a conf carries is still its provider's saved
    one. The in-memory rests ask this first (6b326), so a late failure of
    a replaced key doesn't bench the new key's model."""
    try:
        cur = (_cloud_all().get("providers") or {}).get(_provider_of(c))
        return isinstance(cur, dict) and _same_key(cur.get("key"),
                                                   c.get("key"))
    except Exception:
        return False


def cloud_glitch(c: dict, why: str):
    """A cloud model that didn't work, for any reason short of a bad key:
    drop it for a couple of minutes so the NEXT question doesn't spend a
    council seat on it, and let it come back by itself. Never raises —
    this runs on the answer path. Since 6b307 the MODEL rests and the
    provider's next ranked model stands in; only a conf with no model
    benches the whole provider. Only while its key is still the saved
    one (6b326)."""
    try:
        if c.get("model"):
            # the check and the rest under the cloud lock (6b326), so a
            # key saved in between can't be benched by the old one
            with _cloud_txn():
                if _key_live(c):
                    cloud_rest_model(c["model"], GLITCH_COOLDOWN)
            return
        pid = _provider_of(c)
        if pid:
            cloud_cool(pid, why, GLITCH_COOLDOWN, key=c.get("key"))
    except Exception:
        pass


# An account out of money is not a throttle (6b307, found live: Moonshot
# answers 429 "suspended due to insufficient balance", which read as a
# rate limit and was retried every ten minutes forever).
_NO_CREDIT_RX = re.compile(
    r"insufficient[ _](balance|credits?|funds)|suspended|recharge|"
    r"credit balance is too low|payment required", re.I)
# A 400 that means the model is GONE, not that the request was wrong
# (6b307): any 400 used to retire a model for good, across restarts,
# including "prompt is too long" and a rejected parameter.
_MODEL_GONE_RX = re.compile(
    r"not[ _]found|no longer (available|supported)|deprecat|"
    r"decommission|does not exist|unknown model|invalid model|"
    r"model[^.]{0,40}not (available|supported)", re.I)
DEAD_TTL = 24 * 3600.0


_dead_when = profile_cache("_dead_when", {})          # model -> when it was retired (6b307)


def cloud_model_alive(model: str) -> bool:
    """False for a model the provider withdrew. A retirement lasts a day
    (6b307): an unlucky 404 during an outage used to bench a model until
    its key was re-pasted."""
    _dead_seed()
    with _dead_lock:
        if model not in _dead_models:
            return True
        when = _dead_when.get(model)
        if when and time.time() - when > DEAD_TTL:
            _dead_models.discard(model)
            _dead_when.pop(model, None)
            return True
        return False


def cloud_revive(models: list):
    """Un-retire models — called when a key is re-saved."""
    _dead_seed()
    with _dead_lock:
        for m in models or []:
            _dead_models.discard(m)
            _dead_when.pop(m, None)
    with _model_rest_lock:
        for m in models or []:
            _model_rest.pop(m, None)


def cloud_note_failure(c: dict, exc: Exception):
    """Record a cloud failure so the UI stops reporting a dead key as
    healthy. Best-effort: never raises into the answer path.

    ONE LOCKED, KEY-CHECKED UPDATE (0a 5.12 item 13, 6b326). The read,
    the decision and the write happen inside one _cloud_txn, and only
    while the provider's saved key is the key this request used
    (compare_digest on fingerprints). It writes status, note, cool, dead
    and dead_at, never key, base or name, so a failure that comes back
    after the key was replaced or removed changes nothing: not the new
    key's status, not a model's rest, and it can't write the old key
    back."""
    try:
        code = getattr(exc, "code", 0)
        model = c.get("model", "")
        body = _http_body(exc)
        kind = cloud_failure_kind(code, body)
        pid, key = _provider_of(c), c.get("key")
        if not pid:
            return
        with _cloud_txn():
            cur = (_cloud_read_strict().get("providers") or {}).get(pid)
            if not isinstance(cur, dict) or not _same_key(cur.get("key"),
                                                          key):
                return
            if kind == "quota" and _NO_CREDIT_RX.search(body):
                _cloud_patch(pid, key, {
                    "status": "ok", "cool": time.time() + 3600.0,
                    "note": "out of credit \u2014 top up the account"})
                return
            if kind == "quota":
                # the key WORKS. When the provider names the model (Groq's
                # per-model token budgets, Gemini's per-model free quota),
                # only that model rests (6b307); otherwise the provider does
                if model and model.lower() in body.lower():
                    cloud_rest_model(model, 300.0)
                    return
                _cloud_patch(pid, key, {
                    "status": "ok", "cool": time.time() + QUOTA_COOLDOWN,
                    "note": "rate limited \u2014 resting"})
                return
            if kind == "auth":
                if cur.get("status") == "fail":
                    return
                # the entry keeps its key, so the user can see which
                # provider to re-paste
                _cloud_patch(pid, key, {
                    "status": "fail",
                    "note": "key rejected (HTTP %d)" % code}, drop=("cool",))
            elif kind == "other" and (code not in (400, 404) or (
                    code == 400 and not _MODEL_GONE_RX.search(body))):
                # a 5xx ("high demand"), or a 400 about the REQUEST: not
                # the key's fault, so the model rests briefly and the
                # provider's next ranked model answers (6b307)
                if model:
                    cloud_rest_model(model, GLITCH_COOLDOWN)
                    return
                _cloud_patch(pid, key, {
                    "status": "ok", "cool": time.time() + GLITCH_COOLDOWN,
                    "note": "not answering (HTTP %d)" % code})
            elif code in (400, 404) and model:
                with _dead_lock:
                    _dead_models.add(model)
                    _dead_when[model] = time.time()
                # stamped EVERY time (6b307): an entry already on the list
                # but unstamped or expired must be retired again on disk
                dead = [m for m in (cur.get("dead") or []) if m != model]
                dead.append(model)
                dead = dead[-12:]
                stamps = dict(cur.get("dead_at") or {})
                stamps[model] = time.time()
                _cloud_patch(pid, key, {
                    "dead": dead,
                    "dead_at": {m: stamps[m] for m in dead if m in stamps}})
    except Exception:
        pass


def cloud_conf():
    """The ACTIVE working provider in the classic shape — everything
    downstream (cloud_stream, tiers) keeps its old contract."""
    live = cloud_ok_providers()          # honours status AND the cooldown
    if not live:
        return None
    d = _cloud_all()
    want = d.get("active") or ""
    # match on the PROVIDER ID, not on dict equality — the two reads are
    # separate loads of the file and only happen to compare equal
    for pid, c in (d.get("providers") or {}).items():
        if pid == want and any(v.get("key") == c.get("key")
                               and v.get("model") == c.get("model")
                               for v in live):
            return c
    # the active one is failed or resting: any other working provider
    # beats dropping the whole turbo path back to local silicon
    return live[0]


def _anthropic_stream(c: dict, messages: list, emit) -> bool:
    """Anthropic speaks its own dialect: x-api-key, a version header, a
    hoisted system prompt, and content_block_delta events."""
    sys_txt = "\n\n".join(m["content"] for m in messages
                           if m.get("role") == "system")
    turns = _anthropic_turns(messages)
    body = _anthropic_body(c, turns, sys_txt, CLOUD_MAX_OUT["claude"],
                           stream=True)
    req = urllib.request.Request(
        c["base"].rstrip("/") + "/messages", data=json.dumps(body).encode(),
        headers={"Content-Type": "application/json",
                 "x-api-key": c["key"],
                 "anthropic-version": "2023-06-01",
                 "User-Agent": "MillenAI/%s" % APP_VERSION})
    got, stop = False, ""
    # the usage ledger (6b325): message_start carries the input counts,
    # message_delta the output so far; its own output_tokens (1 or so)
    # would pass a stream cut short for exact, so it's dropped
    t0, sent, u = time.time(), [0], {}
    try:
        with urllib.request.urlopen(req, timeout=120) as r:
            for raw in r:
                line = raw.decode("utf-8", "replace").strip()
                if not line.startswith("data:"):
                    continue
                try:
                    d = json.loads(line[5:].strip())
                except Exception:
                    continue
                if d.get("type") == "content_block_delta":
                    # thinking_delta blocks carry no "text": skipped
                    tok = (d.get("delta") or {}).get("text") or ""
                    if tok:
                        got = True
                        sent[0] += len(tok)
                        emit(tok)
                elif d.get("type") == "message_delta":
                    stop = (d.get("delta") or {}).get("stop_reason") or stop
                    if isinstance(d.get("usage"), dict):
                        # a null here must not wipe message_start's count
                        u.update({k: v for k, v in d["usage"].items()
                                  if v is not None})
                elif d.get("type") == "message_start":
                    _mu = (d.get("message") or {}).get("usage")
                    if isinstance(_mu, dict):
                        u.update({k: v for k, v in _mu.items()
                                  if k != "output_tokens"})
    except urllib.error.HTTPError as exc:
        if not got:
            cloud_note_failure(c, exc)
        return got
    except Exception:
        if not got:
            cloud_glitch(c, "not responding")
        return got
    finally:
        try:
            usage_note(c.get("model"), _provider_of(c) or "cloud",
                       messages, sent[0], u, t0)
        except Exception:
            pass
    # A REFUSAL IS ABOUT THE QUESTION, NOT THE MODEL (6b307): Opus 5.5
    # runs safety classifiers that can stop a turn, even after text has
    # gone out. Wipe what was shown and let the next rung answer; resting
    # a healthy Claude for it would punish the key. `_stop` tells a
    # caller not to ask the same model again.
    c["_stop"] = stop
    if stop == "refusal":
        if got:
            try:
                emit(Ctl(NUL + "RESET" + NUL))
            except Exception:
                pass
        return False
    if not got and stop != "max_tokens":
        cloud_glitch(c, "returned nothing")
    if got:
        _mark_answered(c)
    return got


def cloud_text(c: dict, messages: list, timeout: int = 120,
               max_tokens: int = 4096, quiet: bool = False,
               timeout_rests: bool = True) -> str:
    """One buffered completion from a SPECIFIC provider conf — the
    council/merge offload path (6b219). Empty string = didn't work."""
    t0 = time.time()
    try:
        if "anthropic.com" in c.get("base", ""):
            sys_txt = "\n\n".join(m["content"] for m in messages
                                   if m["role"] == "system")
            # the caller's cap is a floor here: a thinking model pays for
            # its reasoning out of max_tokens, and a short cap returned
            # nothing at all (6b255, 6b307). Billing is by what's used.
            payload = json.dumps(_anthropic_body(
                c, _anthropic_turns(messages), sys_txt,
                max(max_tokens, 16000), stream=False)).encode()
            req = urllib.request.Request(
                c["base"].rstrip("/") + "/messages", data=payload,
                headers={"x-api-key": c["key"],
                         "anthropic-version": "2023-06-01",
                         "Content-Type": "application/json",
                         "User-Agent": "MillenAI/%s" % APP_VERSION})
            with urllib.request.urlopen(req, timeout=timeout) as r:
                d = json.loads(r.read().decode("utf-8", "replace"))
            try:                               # the usage ledger (6b325)
                usage_note(c.get("model"), _provider_of(c) or "cloud",
                           messages, sum(len(b.get("text") or "") for b in
                                         d.get("content") or []
                                         if isinstance(b, dict)),
                           d.get("usage"), t0)
            except Exception:
                pass
            c["_stop"] = d.get("stop_reason") or ""
            if d.get("stop_reason") == "refusal":
                return ""          # partial text of a refused turn: no draft
            out = "".join(b.get("text", "")
                          for b in d.get("content", []))
            # A THINKING MODEL CAN SPEND THE WHOLE BUDGET THINKING
            # (6b255, found live). claude-sonnet-5 emits a `thinking`
            # block before its text, and max_tokens covers BOTH — so a
            # turn that reasons hard hits the cap mid-thought and
            # returns no text block at all. That is OUR budget running
            # out, not a broken provider: resting the key for it took a
            # healthy Claude off the bench for ten minutes.
            if not out.strip():
                if d.get("stop_reason") in ("max_tokens", "refusal"):
                    return ""
                if not quiet:
                    cloud_glitch(c, "returned nothing")
            if _is_provider_error(out):
                if not quiet:
                    _cloud_budget_hit(c)
                return ""
            return out
        # per-provider body (6b307): effort by role, Moonshot's pinned
        # temperature left out, the provider's own output ceiling
        body = _openai_body(c, messages, max(max_tokens, CLOUD_MAX_OUT.get(
            _provider_of(c), 4096)), stream=False)
        payload = json.dumps(body).encode()
        req = urllib.request.Request(
            c["base"].rstrip("/") + "/chat/completions", data=payload,
            headers={"Content-Type": "application/json",
                     "User-Agent": "MillenAI/%s" % APP_VERSION,
                     "Authorization": "Bearer " + c["key"]})
        with urllib.request.urlopen(req, timeout=timeout) as r:
            d = json.loads(r.read().decode("utf-8", "replace"))
        out = (((d.get("choices") or [{}])[0].get("message") or {})
               .get("content", "") or "")
        try:                                   # the usage ledger (6b325)
            usage_note(c.get("model"), _provider_of(c) or "cloud", messages,
                       len(out) if isinstance(out, str) else 0,
                       d.get("usage"), t0)
        except Exception:
            pass
        if not out.strip() and not quiet:
            # answered, said nothing: still "not working" as far as the
            # council is concerned, so rest it rather than ask again
            cloud_glitch(c, "returned nothing")
        if _is_provider_error(out):
            if not quiet:        # a title that merely mentions billing
                _cloud_budget_hit(c)
            return ""
        return out
    except urllib.error.HTTPError as exc:
        # QUIET (6b308): a background job (title, memory, map pins) must
        # never rest the model the reader's next answer needs. Only a
        # bad key or a withdrawn model is worth recording from there.
        _b = _http_body(exc)
        if (not quiet or cloud_failure_kind(exc.code, _b) == "auth"
                or exc.code == 404 or (exc.code == 400
                                       and _MODEL_GONE_RX.search(_b))):
            cloud_note_failure(c, exc)
        return ""
    except Exception:
        # timeout, dropped connection, malformed JSON — all the same to
        # the reader waiting for an answer. A council seat that simply
        # ran past the council's own deadline is not broken, and resting
        # it took Opus 5.5 away from the final answer (6b308)
        if not quiet and timeout_rests:
            cloud_glitch(c, "not responding")
        return ""


# ONE pick policy, shared by key-save and the boot refresh (6b247):
# which inventory ids count as chat-capable, and which id each provider
# should field, in preference order.
CLOUD_SKIP_IDS = ("embed", "tts", "image", "imagen", "veo", "aqa",
                  "audio", "live", "learnlm", "exp", "-code",
                  # classifiers are not chat models: Groq's inventory
                  # carries llama-prompt-guard, and it once took a
                  # council seat (6b247, seen live)
                  "guard", "moderation",
                  # 6b307: speech-to-text, voices, music, agents and a
                  # 4K-context legacy model were all counting as chat
                  "whisper", "orpheus", "allam", "safeguard", "lyria",
                  "banana", "transcribe", "robotics", "computer-use",
                  "deep-research", "antigravity", "customtools", "omni",
                  "-eap")
CLOUD_PICK_ORDER = {
    "gemini": ["gemini-3-flash", "gemini-3.0-flash", "flash-latest",
               "gemini-2.5-flash", "flash", "pro"],
    "groq": ["gpt-oss-120b", "llama", "qwen"],
    "claude": ["sonnet", "haiku", "opus"],
    "kimi": ["kimi-k3", "k3", "kimi-latest", "k2"],
}


# RANKED, NOT MATCHED (6b307, per Patrick: "are all our cloud ones using
# the most capable models?"). The substring lists above each named one
# generation: "gemini-3-flash" never matched gemini-3.8-flash, and
# "sonnet" beat opus. Each provider's ids are parsed for their version
# and ranked, so a newer model is picked the day it shows up in the
# inventory. CLOUD_PICK_ORDER stays as the tail for ids nobody parses.
# Fable is left out on purpose: Opus 5.5 beats it on every published
# benchmark at 40% of the price per task (Patrick chose Opus).
_CLAUDE_ID = re.compile(
    r"^claude-(opus|sonnet|haiku)-(\d+)(?:-(\d{1,2}))?(?:-\d{8})?$")
_GEM_FLASH = re.compile(r"^gemini-(\d+(?:\.\d+)*)-flash(-lite)?(-preview)?$")
_QWEN_ID = re.compile(r"^qwen/qwen(\d+(?:\.\d+)*)-(\d+)b$")
_KIMI_ID = re.compile(r"^kimi-k(\d+(?:\.\d+)*)$")


def _vtuple(v: str) -> tuple:
    return tuple(int(x) for x in v.split("."))


def _probe_model(base: str, key: str, model: str):
    """An 8-token hello to one model; raises HTTPError as the provider
    answered. The key-save check, shared by every provider."""
    hdr = {"Content-Type": "application/json",
           "User-Agent": "MillenAI/%s" % APP_VERSION}
    if "anthropic" in base:
        hdr.update({"x-api-key": key, "anthropic-version": "2023-06-01"})
        url = base + "/messages"
    else:
        hdr["Authorization"] = "Bearer " + key
        url = base + "/chat/completions"
    tq = urllib.request.Request(url, headers=hdr, data=json.dumps(
        {"model": model, "max_tokens": 8,
         "messages": [{"role": "user", "content": "hi"}]}).encode())
    urllib.request.urlopen(tq, timeout=25).read(400)


def cloud_candidates(pid: str, ids, role: str = "seat",
                     vision: bool = False) -> list:
    """This provider's models for `role`, best first (6b307; per task
    since 6b308, per Patrick: "selecting the ideal model for different
    tasks … keep it up to date as the models get cycled in and cycled
    out"). Roles: "seat" (council draft), "composite" (the final
    answer), "work" (a single quality answer: writing, resumes,
    exports, funnel verdicts, the remote agent), "code" (the Code tab),
    "fast" (the quick answer) and "utility" (titles, memory, map pins).
    Picked by parsed version with a FLOOR per line, so a model below
    the current generation drops out on its own and a newer one is
    fielded the day it shows up; nothing here names a model id. When
    a key reaches no model above the floor, the floor gives way."""
    ids = [i for i in dict.fromkeys(ids or []) if i]
    quick = role in ("fast", "utility")

    def ranked(floored: bool) -> list:
        out = []
        if pid == "claude":
            fams = {}
            for i in ids:
                m = _CLAUDE_ID.match(i)
                if m:
                    fams.setdefault(m.group(1), []).append(
                        ((int(m.group(2)), int(m.group(3) or 0)), i))
            low = (5, 0) if floored else (0, 0)

            def line(f, floor=(0, 0)):
                return [i for v, i in sorted(fams.get(f, []), reverse=True)
                        if v >= floor]
            if quick:
                out = line("haiku") + line("sonnet", low)
            elif role == "code":
                # Patrick's pick for the Code tab: Sonnet at medium
                out = line("sonnet", low) + line("opus", low)
            else:
                out = line("opus", low) + line("sonnet", low)
                if not floored:
                    out += line("haiku")
        elif pid == "gemini":
            flash, lite = [], []
            for i in ids:
                m = _GEM_FLASH.match(i)
                if not m:
                    continue
                v = _vtuple(m.group(1))
                key = (v, not m.group(3))    # a tie goes to the GA id
                if m.group(2):
                    lite.append((key, i))
                elif not floored or v >= (3, 6):
                    flash.append((key, i))
            flash = [i for _k, i in sorted(flash, reverse=True)]
            lite = [i for _k, i in sorted(lite, reverse=True)]
            # no pro rung: 3.x Pro has no free tier, and its 429 (limit
            # 0) used to bench the whole provider
            out = (lite + flash) if quick else flash
        elif pid == "groq":
            if vision:
                return []        # nothing on Groq was seen to read images
            qw = []
            for i in ids:
                m = _QWEN_ID.match(i)
                if m:
                    qw.append(((_vtuple(m.group(1)), int(m.group(2))), i))
            qw = [i for _k, i in sorted(qw, reverse=True)]
            oss = [i for i in ("openai/gpt-oss-120b", "openai/gpt-oss-20b")
                   if i in ids]
            # Qwen holds the council SEAT (Patrick's pick). Everything
            # else stays on gpt-oss: ~500 tok/s with no thinking wall,
            # and a long answer is exactly what the free tier's ~1,000
            # output tokens a minute turns away for Qwen (seen live)
            out = (qw + oss) if role == "seat" else oss
        elif pid == "kimi":
            if vision:
                return []        # untested: the account is suspended
            ks = []
            for i in ids:
                m = _KIMI_ID.match(i)
                if m:
                    ks.append((_vtuple(m.group(1)), i))
            out = [i for _k, i in sorted(ks, reverse=True)]
        return list(dict.fromkeys(out))
    got = ranked(True) or ranked(False)
    if not got and not vision:
        # a lineup nothing above parses (a provider renamed its line):
        # the old substring order is the last resort, never the first
        for want in CLOUD_PICK_ORDER.get(pid, []):
            got += [i for i in ids if want in i.lower() and i not in got]
    return got


# ONE MODEL RESTS, NOT THE PROVIDER (6b307). Found live the day these
# picks moved: Groq's free tier gives qwen3.8-27b about 1,000 output
# tokens a minute and turns away requests on a rolling estimate, and
# gemini-3.8-flash answered 503 "high demand" twice while 3.7 answered
# in 2.7s. Benching the whole provider for that took gpt-oss (the Fast
# tier's first rung) down with Qwen. Now the model rests and the next
# ranked model from the same provider takes its place.
# model id -> unix time it may be asked again
_model_rest = profile_cache("_model_rest", {})
_model_rest_lock = threading.Lock()


def cloud_rest_model(model: str, secs: float):
    if model:
        with _model_rest_lock:
            _model_rest[model] = max(_model_rest.get(model, 0.0),
                                     time.time() + secs)


def cloud_model_resting(model: str) -> bool:
    with _model_rest_lock:
        return _model_rest.get(model, 0.0) > time.time()


def cloud_rest_left(pid: str, v: dict) -> int:
    """Seconds until this provider can answer again, 0 if it can now.
    Counts a provider-wide rest AND the case where every model it would
    field is resting (6b307: those rests were invisible to Settings and
    to Cloud Only, which told a user with a working key to add one)."""
    now = time.time()
    try:
        left = float(v.get("cool") or 0) - now
    except (TypeError, ValueError):
        left = 0.0
    if left > 0:
        return int(left)
    if not (v.get("key") and v.get("status", "ok") == "ok"):
        return 0
    if cloud_role_model(pid, v, "seat"):
        return 0
    ids = [v.get("model", "")] + list(v.get("models") or [])
    with _model_rest_lock:
        ends = [_model_rest.get(m, 0.0)
                for m in cloud_candidates(pid, ids, "seat")[:4]]
    ends = [e for e in ends if e > now]
    return int(min(ends) - now) if ends else 0


def cloud_role_model(pid: str, c: dict, role: str, vision: bool = False,
                     exclude=()) -> str:
    """The model this provider fields for `role` right now: the best
    ranked one that is neither retired, resting nor excluded (a model
    that just refused, for the rest of that run). Only the top few are
    considered, so a provider never falls back to something far below
    its pick; '' when all of them are out."""
    ids = [c.get("model", "")] + list(c.get("models") or [])
    cands = cloud_candidates(pid, ids, role, vision)[:4]
    for m in cands:
        if (m and m not in exclude and cloud_model_alive(m)
                and not cloud_model_resting(m)):
            return m
    return ""


# EFFORT PER ROLE (6b307). Every one of these models reasons before it
# answers, and max_tokens pays for the reasoning too: at the old 4096
# ceiling a hard question could spend it all thinking, come back empty,
# and bench a healthy provider. Each value below was sent live first.
_EFFORT = {"fast": "low", "utility": "low", "seat": "medium",
           "work": "medium", "code": "medium", "composite": "high"}
# K3's effort values (low/high/max, no medium) could not be sent live:
# the account was suspended. Until they are, Kimi keeps its old body,
# stays off the quick ladders and sits last on the work ladder.
KIMI_TESTED = False
CLOUD_MAX_OUT = {"claude": 32000, "gemini": 16000, "groq": 8192,
                 "kimi": 16000}


def _img_parts(m: dict) -> list:
    """(media type, base64) for each image on a user message (6b308):
    the chat handler keeps the data URLs in image_urls; a bare base64
    list is sniffed by its first bytes."""
    out = []
    for u in m.get("image_urls") or []:
        mm = re.match(r"data:([\w/+.-]+);base64,(.*)", str(u), re.S)
        if mm:
            out.append((mm.group(1), mm.group(2)))
    if not out:
        for b in m.get("images") or []:
            b = str(b)
            mt = ("image/png" if b.startswith("iVBOR") else
                  "image/gif" if b.startswith("R0lG") else
                  "image/webp" if b.startswith("UklGR") else "image/jpeg")
            out.append((mt, b))
    return out


def _anthropic_turns(messages: list) -> list:
    turns = []
    for m in messages:
        if m.get("role") not in ("user", "assistant"):
            continue
        imgs = _img_parts(m) if m.get("role") == "user" else []
        if imgs:
            content = [{"type": "image", "source": {
                "type": "base64", "media_type": mt, "data": b}}
                for mt, b in imgs]
            content.append({"type": "text", "text":
                            m.get("content") or "Describe this image."})
        else:
            content = m.get("content", "")
        turns.append({"role": m["role"], "content": content})
    return turns


def _openai_messages(messages: list) -> list:
    out = []
    for m in messages:
        imgs = _img_parts(m) if m.get("role") == "user" else []
        if imgs:
            out.append({"role": "user", "content": [
                {"type": "text",
                 "text": m.get("content") or "Describe this image."}] + [
                {"type": "image_url",
                 "image_url": {"url": "data:%s;base64,%s" % (mt, b)}}
                for mt, b in imgs]})
        else:
            out.append({"role": m.get("role", "user"),
                        "content": m.get("content", "")})
    return out


def _anthropic_body(c: dict, turns: list, sys_txt: str, max_tokens: int,
                    stream: bool) -> dict:
    body = {"model": c["model"], "messages": turns,
            "max_tokens": max_tokens}
    if stream:
        body["stream"] = True
    if sys_txt:
        body["system"] = sys_txt
    # EFFORT ONLY WHERE IT WAS SEEN TO WORK (6b307, each sent live):
    # Opus 4.5 and later, Sonnet 4.6 and later, Fable. Haiku 4.5 and
    # Sonnet 4.5 400 on it. An id we can't parse gets none. No
    # temperature: the thinking models own it.
    if _claude_takes_effort(c["model"]):
        body["output_config"] = {
            "effort": _EFFORT.get(c.get("role") or "seat", "medium")}
    return body


def _claude_takes_effort(model: str) -> bool:
    if model.startswith("claude-fable-"):
        return True
    m = _CLAUDE_ID.match(model)
    if not m:
        return False
    ver = (int(m.group(2)), int(m.group(3) or 0))
    return ((m.group(1) == "opus" and ver >= (4, 5))
            or (m.group(1) == "sonnet" and ver >= (4, 6)))


def _openai_body(c: dict, messages: list, max_tokens: int,
                 stream: bool) -> dict:
    base, model = c.get("base", ""), c.get("model", "")
    role = c.get("role") or "seat"
    body = {"model": model, "messages": _openai_messages(messages),
            "max_tokens": max_tokens, "temperature": 0.75}
    if stream:
        body["stream"] = True
    if "moonshot" in base:
        # MOONSHOT PINS EACH MODEL'S LEGAL TEMPERATURE (6b247, found
        # live: kimi-k2.7-code 400s "only 1 is allowed" on 0.75). Omit it
        # and take the server default, which is always legal.
        body.pop("temperature")
    elif "generativelanguage" in base:
        # Gemini 3 is tuned at its default temperature; below it the
        # thinking models can loop. Flash-Lite thinks minimally by
        # default and is the Fast tier because of it: no effort sent.
        body.pop("temperature")
        if "-lite" not in model:
            # medium even for the composite: "high" took 70s to say one
            # word and drew 503s under load (both seen live, 6b307)
            body["reasoning_effort"] = ("low" if role in ("fast", "utility")
                                        else "medium")
    elif "groq" in base:
        if model.startswith("qwen/"):
            # Qwen thinks in <think> tags unless told to hide them
            body["reasoning_format"] = "hidden"
        elif "gpt-oss" in model:
            body["reasoning_effort"] = _EFFORT.get(role, "medium")
    return body


def _cloud_refresh_picks():
    """Re-run model discovery for every healthy provider and upgrade
    stale picks (6b247). A provider's inventory GROWS after the key is
    saved — seen live: a Moonshot account funded after save gained
    kimi-k3, but discovery only ever ran at save time, so the stored
    pick stayed kimi-k2.7-code (a code specialist) in every council
    forever. Runs once per boot on a background thread; any provider
    that is offline or resting just keeps its pick until next boot."""
    try:
        d = _cloud_all()
        updates = {}
        for pid, v in (d.get("providers") or {}).items():
            if not (v.get("status", "ok") == "ok" and v.get("key")
                    and v.get("base")):
                continue
            try:
                if "anthropic" in v["base"]:
                    # 20 per page by default: past 20 models the oldest,
                    # Haiku first, fell off the list (6b307)
                    lq = urllib.request.Request(
                        v["base"].rstrip("/") + "/models?limit=1000",
                        headers={"x-api-key": v["key"],
                                 "anthropic-version": "2023-06-01",
                                 "User-Agent":
                                     "MillenAI/%s" % APP_VERSION})
                else:
                    lq = urllib.request.Request(
                        v["base"].rstrip("/") + "/models",
                        headers={"Authorization": "Bearer " + v["key"],
                                 "User-Agent":
                                     "MillenAI/%s" % APP_VERSION})
                raw = json.loads(urllib.request.urlopen(
                    lq, timeout=15).read().decode("utf-8", "replace"))
                found = [str(m.get("id", "")).replace("models/", "")
                         for m in (raw.get("data") or []) if m.get("id")]
            except Exception:
                continue
            if not found:
                continue
            chat = [i for i in found
                    if not any(k in i.lower() for k in CLOUD_SKIP_IDS)]
            ranked = [i for i in cloud_candidates(pid, chat, "seat")
                      if cloud_model_alive(i)]
            pick = (ranked[0] if ranked
                    else (v.get("model") if v.get("model") in chat
                          else (chat[0] if chat else "")))
            # the WHOLE chat inventory (6b307): six ids hid Haiku (11th
            # of 12), gemini-3.8-flash and every Gemini 3.x model
            inv = chat or found[:6]
            if pick and (pick != v.get("model")
                         or inv != v.get("models")
                         or v.get("name") == "Groq 120B"):
                updates[pid] = (v.get("key"), pick, inv)
        # the network calls above ran OUTSIDE the lock; apply the result
        # to a FRESH read inside it, and only to a provider whose key is
        # still the one we asked about (6b304)
        if updates:
            with _cloud_txn():
                d2 = _cloud_read_strict()
                for pid, (key, pick, inv) in updates.items():
                    v2 = (d2.get("providers") or {}).get(pid)
                    if v2 and v2.get("key") == key:
                        v2["model"], v2["models"] = pick, inv
                        if v2.get("name") == "Groq 120B":
                            v2["name"] = "Groq"
                _cloud_write(d2)
    except Exception:
        pass


_repaired = profile_cache("_repaired", [False])


def _cloud_repair():
    """ONE-TIME, ONCE PER PROCESS: undo the damage b233/b234 could do.
    Those builds marked a provider FAILED for any HTTP error, so a spent
    free-tier quota — which resets by itself — left a perfectly good key
    showing a red ✗ until it was re-pasted by hand. A stored note that
    reads like a quota message is exactly that case: put it back to ok
    and let the cooldown decide when it returns. Per profile, like the
    file it repairs; never from a thread with none (review of 6b329)."""
    if _repaired[0] or getattr(_tl_ctx, "ctx", None) is None:
        return
    _repaired[0] = True
    # stale-pick refresh rides the same once-per-process latch, but on
    # its own thread — it makes one network call per provider and must
    # never sit in front of the first answer
    ctx_thread(target=_cloud_refresh_picks, daemon=True).start()
    try:
        with _cloud_txn():
            d = _cloud_read_strict()
            changed = False
            for v in (d.get("providers") or {}).values():
                if v.get("status") == "fail" and _QUOTA_RX.search(
                        v.get("note") or ""):
                    v["status"] = "ok"
                    v["cool"] = time.time() + QUOTA_COOLDOWN
                    v["note"] = "rate limited — resting"
                    changed = True
            if changed:
                _cloud_write(d)
    except Exception:
        pass


def cloud_ok_providers() -> list:
    """Every provider whose key currently reports ok — the council's
    cloud bench."""
    _cloud_repair()
    d = _cloud_all()
    now = time.time()
    out = []
    for v in (d.get("providers") or {}).values():
        if not (v.get("status", "ok") == "ok" and v.get("key")
                and v.get("base") and v.get("model")):
            continue
        # a throttled provider is healthy but resting — leaving it on the
        # bench just spends a council seat on a guaranteed 429
        try:
            if float(v.get("cool") or 0) > now:
                continue
        except (TypeError, ValueError):
            pass
        out.append(v)
    return out


def cloud_bench() -> list:
    """(label, conf) pairs that draft SIMULTANEOUSLY in councils
    (6b220, per Patrick: 'ALL available cloud models… not just one'):
    each working provider fields its picked model plus one alternate
    from its stored inventory (a pro-class sibling when there is one).
    Capped at two per provider — free tiers have rate limits."""
    bench = []
    for c in cloud_ok_providers():
        # a model the provider has retired 404s on every question — it
        # burned a whole seat per council until it was skipped (6b233);
        # a resting one gives way to the next ranked model (6b307)
        pid = _provider_of(c)
        seat = cloud_role_model(pid, c, "seat")
        if not seat:
            continue
        c = dict(c, model=seat, role="seat")
        bench.append((c["name"], c))
        # alternates only on FREE tiers — Anthropic and Moonshot bill
        # per token, and the blind alternate once benched claude-opus-5
        # on every council question (caught live). One paid seat is
        # plenty; the compositor ladder is where the paid rungs earn
        # their keep.
        if ("anthropic" in c.get("base", "")
                or "moonshot" in c.get("base", "")):
            continue
        # Gemini fields no second seat (6b307): its "pro" sibling has no
        # free tier and 429'd the whole provider (limit 0)
        if pid == "gemini":
            continue
        alts = [m for m in c.get("models", []) if m != c.get("model")
                and cloud_model_alive(m) and not cloud_model_resting(m)]
        # A STRONGER SIBLING OR NONE (6b233). The old fallback took
        # alts[0] — any model at all — and once retired models started
        # being skipped it walked the inventory into things like
        # "gemini-3.7-flash-video-understanding-eap", seating a random
        # unknown voice on the council. An alternate has to earn its
        # seat by being a bigger sibling, or the provider fields one.
        # "pro" as a WORD, not a substring — "pro" in "llama-PROmpt-
        # guard-2-22m" seated a 22M safety classifier as the stronger
        # sibling on every Groq council (6b247, seen live)
        alt = next((m for m in alts
                    if re.search(r"(^|[^a-z])pro($|[^a-z])", m.lower())
                    or "120b" in m.lower() or "70b" in m.lower()), "")
        if alt:
            c2 = dict(c)
            c2["model"] = alt
            bench.append((alt, c2))
    return bench


def _cloud_ladder(role: str, order, vision: bool = False) -> list:
    """Confs for `role`, one per healthy provider in `order`, each
    fielding its ranked best for that role (6b308). A provider that is
    resting, out of credit or has every model resting is left out."""
    pv = _cloud_all().get("providers") or {}
    now = time.time()
    out = []
    for pid in order:
        c = pv.get(pid)
        if not (c and c.get("status", "ok") == "ok" and c.get("key")
                and c.get("base") and c.get("model")):
            continue
        try:                       # out of credit / quota: it 429s anyway
            if float(c.get("cool") or 0) > now:
                continue
        except (TypeError, ValueError):
            pass
        m = cloud_role_model(pid, c, role, vision=vision)
        if m:
            out.append(dict(c, model=m, role=role))
    return out


def compositor_ladder() -> list:
    """Confs for the COMPOSITE (the final written answer), strongest
    first (6b220): Claude, then Kimi K3 (6b245), then Gemini, then Groq,
    each at its ranked best: Opus 5.5 at high effort for Claude
    (Patrick's pick). Local Gemma 4 stays the no-cloud floor."""
    return _cloud_ladder("composite", ("claude", "kimi", "gemini", "groq"))


def work_ladder(role: str = "work") -> list:
    """A single answer where quality is the point (6b308): writing,
    resumes, exports, funnel verdicts, the remote agent ("work": Opus
    5.5 at medium), or the Code tab ("code": Sonnet 5 at medium, per
    Patrick). Groq before Gemini, so a free-tier user keeps Gemini
    Flash's small daily quota for council seats; Kimi last until its
    effort values have been tried live."""
    order = (("claude", "kimi", "groq", "gemini") if KIMI_TESTED
             else ("claude", "groq", "gemini", "kimi"))
    return _cloud_ladder(role, order)


def fast_cloud_ladder(utility: bool = False) -> list:
    """The QUICK answer (6b246; Haiku first since 6b308, per Patrick:
    "fast haiku"). `utility` is for background jobs (titles, memory, map
    pins, funnel stages): low effort, never Kimi."""
    order = ("claude", "groq", "gemini")
    if KIMI_TESTED and not utility:
        order += ("kimi",)
    return _cloud_ladder("utility" if utility else "fast", order)


def vision_ladder(tier: str = "") -> list:
    """A pasted image, per Patrick (6b308): Haiku on Fast, Opus 5.5 at
    medium on Thinking and Cloud Only, Opus 5.5 at high on Pro, with
    Gemini's Flash line beside it. Only providers whose models were seen
    to read images; the local vision model is the floor."""
    role = {"Pro": "composite", "Thinking": "seat",
            "Cloud Only": "seat"}.get(tier, "fast")
    return _cloud_ladder(role, ("claude", "gemini"), vision=True)


# ---- CLOUD ONLY'S MODES AND PICKS (6b440)
# Patrick (2026-10-07): "Let's also have an option under cloud only, similar to
# what we have for the server pop out menu to pick fast, thinking, or pro. And
# based on that, it determines which models and how many models to use. So fast
# doesn't gobble up all your API money and usage, etc. And under that, similar
# to the servers pop out, the option to pick a specific model that it uses from
# the available ones. If one of the cloud models is unavailable for any reason,
# just have it gray out." Tier ids "cloud:fast", "cloud:think", "cloud:pro" and
# "cloud:m:<provider>" (cloud_tier_parse); plain "Cloud Only" is unchanged.
# Fast: ONE model, the cheapest that answers (a free tier first, a paid key only
# through its small model). Thinking: up to three from different providers, free
# first, and the cheapest capable one writes the merge. Pro: every available
# provider, the strongest merge: what Cloud Only has always done. A pick runs
# that one model alone. No local model, no server, in any of them.


def cloud_tier_parse(tier) -> tuple:
    """(mode, provider id) of a Cloud Only mode or pick: ("Fast" | "Thinking" |
    "Pro", "") for "cloud:fast", ":think", ":pro"; ("Model", "<id>") for
    "cloud:m:<id>"; ("", "") for anything else, plain "Cloud Only" included."""
    m = _CLOUD_TIER_RX.fullmatch(tier) if isinstance(tier, str) else None
    if not m:
        return "", ""
    return (CLOUD_MODE_KEYS[m.group(1)], "") if m.group(1) else ("Model", m.group(2))


def cloud_only_tier(tier) -> bool:
    """Plain Cloud Only, or one of its modes or picks: the tiers on which only
    cloud models answer."""
    return bool(isinstance(tier, str) and (TIERS.get(tier, {}).get("cloud_only")
                                           or cloud_tier_parse(tier)[0]))


def cloud_tier_pid(tier) -> str:
    """The provider a "cloud:m:<id>" pick names, else ''."""
    return cloud_tier_parse(tier)[1]


def _cloud_clock(ts: float) -> str:
    return time.strftime("%I:%M", time.localtime(ts)).lstrip("0")


def cloud_provider_state(pid: str, v, now=None) -> dict:
    """One provider as the Cloud power pane sees it: {id, name, cost, ok, why,
    until, model}. Unavailable for any reason is ok False with the reason in a
    few words: no key, a key the provider rejected, resting (quota, glitch, out
    of credit: until when) or no current model (every one retired or resting).
    model: what a pick of it would ask ("work" role)."""
    now = time.time() if now is None else now
    out = {"id": pid, "name": CLOUD_NAMES.get(pid) or pid.title(),
           "cost": CLOUD_COST.get(pid, "paid"), "ok": False, "why": "",
           "until": 0, "model": ""}
    if not (isinstance(v, dict) and v.get("key")):
        out["why"] = "no key yet"
    elif v.get("status", "ok") != "ok":
        out["why"] = "key rejected"
    elif not (v.get("base") and v.get("model")):
        out["why"] = "not set up"
    else:
        try:
            left = int(cloud_rest_left(pid, v))
        except Exception:
            left = 0
        if left > 0:
            out["until"] = int(now + left)
            try:
                broke = float(v.get("cool") or 0) > now and bool(
                    _NO_CREDIT_RX.search(str(v.get("note") or "")) or "out of credit" in str(v.get("note") or ""))
            except (TypeError, ValueError):
                broke = False
            out["why"] = "out of credit" if broke else "resting until " + _cloud_clock(now + left)
        else:
            m = cloud_role_model(pid, v, "work")
            if m:
                out.update(ok=True, model=m)
            else:
                out["why"] = "no current model"
    return out


def cloud_provider_states() -> list:
    """cloud_provider_state of every provider, in the Cloud power pane's order
    (the four of PROVIDER_BASES), a provider with no entry as "no key yet"."""
    _cloud_repair()
    pv = _cloud_all().get("providers") or {}
    now = time.time()
    return [cloud_provider_state(pid, pv.get(pid), now) for pid in PROVIDER_BASES]


def _cloud_cheap(pid: str, c):
    """c when it is a model cheap enough for Fast and Thinking: any model of a
    free provider, only a small one of a "cheap" provider (CLOUD_CHEAP_MODEL),
    none of a "paid" one."""
    cls = CLOUD_COST.get(pid, "paid")
    if not c or cls == "paid":
        return None
    rx = CLOUD_CHEAP_MODEL.get(pid)
    return c if cls == "free" or (rx and rx.search(str(c.get("model") or ""))) else None


def _cloud_by_pid(role: str, order) -> dict:
    return {_provider_of(c): c for c in _cloud_ladder(role, order)}


def cloud_mode_plan(mode: str, pid: str = "") -> dict:
    """What a Cloud Only mode seats right now: {mode, seats [(label, conf)],
    comp [conf, cheapest first for Thinking, strongest first for Pro], spare
    [conf], why}. Fast: the first of the speed-first quick ladder, free
    providers before the low-cost ones and a paid provider's only ever through
    its small model; the rest of that list is `spare`, what answers if the
    first doesn't. Thinking: up to CLOUD_MODE_SEATS, one per provider, free
    first, a low-cost provider through its small model; the merge by the
    cheapest capable. Pro: today's whole bench and the strength ladder. Model
    (pid): that provider's quality model alone. `why` says what to do when
    there is no seat."""
    rank = lambda p: (CLOUD_COST_RANK.get(CLOUD_COST.get(p, "paid"), 2),
                      CLOUD_STRENGTH.index(p) if p in CLOUD_STRENGTH else 9)
    plan = {"mode": mode, "pid": pid, "seats": [], "comp": [], "spare": [], "why": ""}
    if mode == "Fast":
        fl = [c for c in fast_cloud_ladder() if _cloud_cheap(_provider_of(c), c)]
        fl.sort(key=lambda c: CLOUD_COST_RANK.get(CLOUD_COST.get(_provider_of(c), "paid"), 2))
        n = CLOUD_MODE_SEATS["Fast"]
        plan["seats"] = [(c["name"], c) for c in fl[:n]]
        plan["spare"] = fl[n:]
    elif mode == "Thinking":
        seat, fast = _cloud_by_pid("seat", CLOUD_STRENGTH), _cloud_by_pid("fast", CLOUD_STRENGTH)
        comp = _cloud_by_pid("composite", CLOUD_STRENGTH)
        seats, merge = [], []
        for p in sorted(CLOUD_STRENGTH, key=rank):
            cheap = CLOUD_COST.get(p) == "cheap"
            c = _cloud_cheap(p, fast.get(p)) if cheap else seat.get(p)
            if c:
                seats.append((c["name"], c))
            m = _cloud_cheap(p, fast.get(p)) if cheap else comp.get(p)
            if m:
                merge.append(m)
        plan["seats"] = seats[:CLOUD_MODE_SEATS["Thinking"]]
        plan["comp"] = merge
    elif mode == "Pro":
        plan["seats"] = cloud_bench()[:CLOUD_MODE_SEATS["Pro"]]
        plan["comp"] = compositor_ladder()
    elif mode == "Model":
        c = _cloud_by_pid("work", (pid,)).get(pid)
        plan["seats"] = [(c["name"], c)] if c else []
    if not plan["seats"]:
        plan["why"] = cloud_plan_why(mode, pid)
    return plan


def cloud_plan_why(mode: str, pid: str = "") -> str:
    """The sentence for a mode with nothing to seat: what to do about it."""
    sts = cloud_provider_states()
    keyed = [s for s in sts if s["why"] != "no key yet"]
    if mode == "Model":
        s = next((x for x in sts if x["id"] == pid), None)
        n = s["name"] if s else "That model"
        return ("%s has no key. %s." % (n, CLOUD_ADD_KEY) if s and s["why"] == "no key yet"
                else "%s is unavailable: %s." % (n, s["why"] if s else "unknown"))
    if not keyed:
        return "%s. Gemini and Groq are free." % CLOUD_ADD_KEY
    if mode in ("Fast", "Thinking") and any(s["ok"] for s in sts):
        return ("%s uses free or low-cost models, and none is available. %s." % (mode, CLOUD_ADD_KEY))
    bits = ["%s (%s)" % (s["name"], s["why"]) for s in keyed]
    return "Every cloud model is unavailable: %s." % ", ".join(bits)


def cloud_mode_state(mode: str, pid: str = "", plan=None) -> dict:
    """/api/tiers' row for a Cloud Only mode or pick: {ok, available, title,
    mode, models [labels], detail ["Groq · model"], note, why, short}. why is
    the sentence, short the few words a greyed row shows."""
    plan = plan or cloud_mode_plan(mode, pid)
    seats = plan["seats"]
    title = ("%s only" % CLOUD_NAMES.get(pid, pid.title()) if mode == "Model"
             else "%s · cloud only" % mode)
    out = {"ok": bool(seats), "available": bool(seats), "mode": mode, "title": title,
           "models": [l for l, _c in seats],
           "detail": ["%s · %s" % (c.get("name", ""), c.get("model", "")) for _l, c in seats],
           "skipped": [], "why": plan["why"], "short": "", "note": "",
           # who writes the blend: the plan's first merge rung, with two or more seats
           "blend": (blend_text((plan["comp"] or [{}])[0].get("name", ""))
                     if mode in ("Thinking", "Pro") and len(seats) > 1 else ""),
           # who writes it, and who else could (6b442)
           "comp": (cloud_comp_choices(plan)
                    if mode in ("Thinking", "Pro") and len(seats) > 1 else None)}
    if not seats:
        w = plan["why"]
        out["short"] = ("no key yet" if "no key yet" in w or "Add a key" in w
                        else "no free or low-cost model" if "free or low-cost" in w else "unavailable")
        return out
    out["note"] = {
        "Fast": "One model, the cheapest and fastest you have (a free tier first; a paid key only "
                "through its small model): %s. " % out["detail"][0],
        "Thinking": "%d model%s draft, free ones first, then the cheapest that can writes the "
                    "final answer. " % (len(seats), "" if len(seats) == 1 else "s"),
        "Pro": "Every available cloud model drafts, then the strongest writes the final "
               "answer. ",
        "Model": "%s answers alone, with no other model and no blend. " % out["detail"][0],
    }[mode] + CLOUD_PROMISE
    return out


def cloud_mode_tiers() -> dict:
    """/api/tiers' rows for Cloud Only's modes ("cloud:fast", ":think", ":pro")
    and one pick per provider ("cloud:m:<id>"), each with its availability and
    the reason it is off; a pick's row carries the provider's own state."""
    out = {}
    for k, mode in CLOUD_MODE_KEYS.items():
        out["cloud:" + k] = dict(cloud_mode_state(mode), desc="cloud only")
    for s in cloud_provider_states():
        st = cloud_mode_state("Model", s["id"])
        row = dict(st, desc=CLOUD_COST_WORDS.get(s["cost"], ""), model=s["model"], name=s["name"],
                   until=s["until"], cost=s["cost"], ok=s["ok"], available=s["ok"])
        if not s["ok"]:
            row.update(short=s["why"], why=s["why"][:1].upper() + s["why"][1:] + ".", models=[], detail=[])
        else:
            row["short"] = s["model"]
        out["cloud:m:" + s["id"]] = row
    return out


# ---- MAX, AND WHO WRITES EACH MODE'S BLEND (6b440)
# Patrick (2026-10-07), confirmed: a new "Max" under Pro that uses every
# available model, and under each mode's row a small line naming the model that
# will write the blend. The merge of Max is written by the first AVAILABLE AND
# HEALTHY of this list (the owner's order): Claude, Kimi K3, Gemini, Groq, then
# the largest model of the person's server that fits, then the largest model of
# this computer that fits. Provider ids are cloud providers; "server" and
# "local" are the two last resorts. Resolved in ONE function (max_compositor),
# which the chat and /api/tiers both read, so the label cannot disagree with
# what runs.
MAX_COMPOSITOR_ORDER = ["claude", "kimi", "gemini", "groq", "server", "local"]
BLEND_NONE = "blend: none available"


def blend_text(label: str) -> str:
    """The small line under a mode's row: who writes its blend."""
    return ("blend: " + label) if label else BLEND_NONE


def max_tier_seats(ctx) -> list:
    """The seats of Max that are not cloud: [{label, fb, params}]. Every model
    of ctx's paired servers that may take a general question (srv_role_ok
    "all", strongest first, no seat cap: the loop budget grows with the seats,
    run_council's SRV_DRAFT_S), then every model of this computer that fits,
    EXCEPT one a server also holds (the same Ollama tag, _srv_tag_key): the
    server's copy runs faster, so the local one is dropped; it stays behind the
    server's seat as its fallback (`fb`), as in resolve_tier_seats."""
    ready = _tier_ready("Max")
    cands = []
    if ctx is not None:
        try:
            cands = [m for m in server_mode_candidates(ctx) if srv_role_ok(m["name"], "all")]
        except Exception:
            cands = []
    seats = []
    if cands:
        for m in srv_rank(cands, "all", "normal", server_speeds(ctx)):
            seats.append({"label": m["label"], "fb": "", "params": m.get("params"),
                          "tag": _srv_tag_key(m["name"])})
    taken = {st["tag"] for st in seats}
    local_tag = {_srv_tag_key((MODEL_INFO.get(l) or {}).get("ollama")): l for l in ready}
    for l in ready:
        if _srv_tag_key((MODEL_INFO.get(l) or {}).get("ollama")) in taken:
            continue
        seats.append({"label": l, "fb": "", "params": _label_params(l)})
    first_local = next((st["label"] for st in seats if not server_label(st["label"])), "")
    for st in seats:
        if server_label(st["label"]):
            st["fb"] = local_tag.get(st.pop("tag", ""), "") or first_local
    return seats


def max_cloud_ladder() -> list:
    """Max's cloud merge rungs, in MAX_COMPOSITOR_ORDER, each at its composite
    model; a resting, rejected or keyless provider is left out."""
    pids = [p for p in MAX_COMPOSITOR_ORDER if p in PROVIDER_BASES]
    by = _cloud_by_pid("composite", pids)
    return [by[p] for p in pids if p in by]


def max_compositor(ctx, seat_labels=None) -> dict:
    """{kind, label} of whoever writes Max's blend: the first available and
    healthy of MAX_COMPOSITOR_ORDER. kind is the provider id, "server" or
    "local"; "" with no label when nothing at all can. seat_labels: the seats
    Max actually runs, so a local model dropped for its server copy is not
    named; None looks at every local model."""
    by = {_provider_of(c): c for c in max_cloud_ladder()}
    for k in MAX_COMPOSITOR_ORDER:
        if k in PROVIDER_BASES:
            if k in by:
                return {"kind": k, "label": by[k]["name"]}
        elif k == "server":
            try:
                m = server_compositor(ctx) if ctx is not None else None
            except Exception:
                m = None
            if m:
                return {"kind": "server", "label": m["label"]}
        elif k == "local":
            pulled = ollama_pulled_tags() or set()
            for l in MERGE_RANK:
                if (l in MODEL_ROUTES and model_cached(l, pulled) and model_fits_memory(l)
                        and l not in BLEND_EXCLUDE and not slow_giant(l)
                        and (seat_labels is None or l in seat_labels)):
                    return {"kind": "local", "label": l}
    return {"kind": "", "label": ""}


def max_tier_row(ctx) -> dict:
    """/api/tiers' row for Max: every model it would use (this computer's and
    the servers', then the cloud's), whether any exists, the blend's writer and
    the plain warning that paid cloud keys are used."""
    try:
        seats = max_tier_seats(ctx)
    except Exception:
        seats = []
    labels = [s["label"] for s in seats]
    cloud = [l for l, _c in cloud_bench()]
    n = len(labels) + len(cloud)
    comp = max_compositor(ctx, labels)
    return {"desc": TIERS["Max"]["desc"], "models": labels, "cloud": cloud, "skipped": [],
            "available": n > 0, "count": n,
            "why": "" if n else ("Nothing available. Add a model in Settings > Models, "
                                 "pair a server, or add a key in Settings > Models > Cloud."),
            "blend": blend_text(comp["label"]) if n > 1 else "",
            # who writes it, and who else could (6b442)
            "comp": max_comp_choices(ctx, labels) if n > 1 else None,
            "warn": "Every model, paid cloud keys included. Each question can spend money "
                    "on every key you have."}


def mode_blend_pick(ctx, chosen: list, bench_n: int) -> tuple:
    """(id, label) of who writes the merge of Thinking or Pro by default, by
    the same rules run_council follows: the cloud ladder when cloud power is
    on (id: the provider), else the strongest suitable model of the person's
    server, else the largest Gemma this computer holds (or the strongest seat
    that fits), its server copy standing in when there is one (id: the
    label). ("", "") when fewer than two models answer; (None, "") when
    nothing can write it."""
    if len(chosen) + (bench_n if cloud_allowed() else 0) < 2:
        return "", ""
    if cloud_allowed():
        lad = compositor_ladder()
        if lad:
            return _provider_of(lad[0]), lad[0]["name"]
    try:
        m = server_compositor(ctx)
    except Exception:
        m = None
    if m:
        return m["label"], m["label"]
    merger = merge_pref_label() or next(
        (l for l in MERGE_RANK if l in chosen and model_fits_memory(l)), "")
    if merger in MODEL_ROUTES:
        try:
            sc = server_copy((MODEL_INFO.get(merger) or {}).get("ollama"),
                             server_mode_candidates(ctx), server_speeds(ctx))
        except Exception:
            sc = None
        if sc is not None:
            merger = sc["label"]
    return (merger or None), merger


def mode_blend(ctx, chosen: list, bench_n: int) -> str:
    """The blend words of Thinking or Pro (mode_blend_pick's label): "" when
    fewer than two models answer."""
    pid, label = mode_blend_pick(ctx, chosen, bench_n)
    return "" if pid == "" else blend_text(label)


# ---- WHO WRITES EACH MODE'S ANSWER, CHOSEN BY THE PERSON (6b442)
# Patrick (2026-10-07): "have it so you can hold the cursor over each one. And
# then in the menu that pops out, listing what models it uses, allow the user
# to hover over that pop out. And at the bottom, highlight the compositor and
# change it. Also mark which one was the default in case they want to go back."
# Every mode that blends (Thinking, Pro, Max; Cloud Only's Thinking and Pro; a
# server's Thinking, Pro and Max) has a row "comp" in /api/tiers: {def: the id
# of who writes it by default, cands: [{id, name, where, kind, ok, why}]}. An id
# is a cloud provider ("claude"), a server's label ("Desk · gpt-oss:20b") or a
# model of this computer ("Gemma 4 26B"). The page keeps the person's pick per
# mode (prefs "comps") and sends it as `mode_comp`; run_council takes it as
# `pen` (pen_resolve), and a pick that can't write the answer at that moment is
# set aside for the default, said in the status line. Fast has nothing to blend.
COMP_LIST_MAX = 6          # rows of one kind (a server's or this computer's) in the list


def _comp_cloud_cands(ladder, order, gate=""):
    """The cloud rows: each provider with a key saved, in `order`; usable when it is
    on `ladder` (the confs that mode's merge may use) and gate (the reason the
    whole cloud is shut, "cloud power is off") is empty."""
    on = {_provider_of(c): c for c in ladder or []}
    sts = {s["id"]: s for s in cloud_provider_states()}
    out = []
    for pid in order:
        s = sts.get(pid)
        if not s or s["why"] == "no key yet":
            continue
        ok = pid in on and not gate
        out.append({"id": pid, "name": s["name"], "where": "cloud", "kind": "cloud", "ok": ok,
                    "why": "" if ok else (gate or (s["why"] if not s["ok"] else "Not used in this mode"))})
    return out


def _comp_srv_cands(cands, speeds=None) -> list:
    """A server's rows: its models that may write a merge (srv_rank "compose"),
    strongest first, named by model with the server as where."""
    try:
        ranked = srv_rank(cands or [], "compose", "normal", speeds)
    except Exception:
        ranked = []
    return [{"id": m["label"], "name": m["label"].split(SERVER_SEP, 1)[-1],
             "where": m["label"].split(SERVER_SEP, 1)[0], "kind": "server", "ok": True, "why": ""}
            for m in ranked[:COMP_LIST_MAX]]


def _comp_local_cands() -> list:
    """This computer's rows: the models MERGE_RANK says may write a merge that
    are downloaded; one that doesn't fit memory now is listed, unusable."""
    pulled = ollama_pulled_tags() or set()
    out = []
    for l in MERGE_RANK:
        if (l in MODEL_ROUTES and model_cached(l, pulled) and l not in BLEND_EXCLUDE
                and not slow_giant(l)):
            fits = model_fits_memory(l)
            out.append({"id": l, "name": l, "where": "this computer", "kind": "local", "ok": fits,
                        "why": "" if fits else "Needs more memory"})
    return out[:COMP_LIST_MAX]


def _comp_row(default_id, default_label, cands) -> dict:
    """{def, cands}: the default always among the rows (first, when the lists
    didn't hold it), each id once."""
    seen, rows = set(), []
    for c in cands:
        if c["id"] not in seen:
            seen.add(c["id"])
            rows.append(c)
    if default_id and default_id not in seen:
        srv = server_label(default_id)
        rows.insert(0, {"id": default_id, "name": (default_label or default_id).split(SERVER_SEP, 1)[-1],
                        "where": (default_id.split(SERVER_SEP, 1)[0] if srv else
                                  "cloud" if default_id in PROVIDER_BASES else "this computer"),
                        "kind": "server" if srv else "cloud" if default_id in PROVIDER_BASES else "local",
                        "ok": True, "why": ""})
    return {"def": default_id or "", "cands": rows}


def mode_comp_choices(ctx, chosen: list, bench_n: int):
    """Thinking's or Pro's compositor rows: the cloud (strength order, shut while
    cloud power is off), the person's server's suitable models, this computer's.
    None when the mode doesn't blend."""
    pid, label = mode_blend_pick(ctx, chosen, bench_n)
    if pid == "":
        return None
    try:
        srv = _comp_srv_cands(server_mode_candidates(ctx), server_speeds(ctx))
    except Exception:
        srv = []
    return _comp_row(pid, label,
                     _comp_cloud_cands(compositor_ladder(), CLOUD_STRENGTH,
                                       "" if cloud_allowed() else "Cloud models are off")
                     + srv + _comp_local_cands())


def max_comp_choices(ctx, seat_labels=None):
    """Max's compositor rows, in MAX_COMPOSITOR_ORDER (its cloud opens whatever
    cloud power says), the default max_compositor's pick."""
    comp = max_compositor(ctx, seat_labels)
    did = comp["kind"] if comp["kind"] in PROVIDER_BASES else comp["label"]
    try:
        srv = _comp_srv_cands(server_mode_candidates(ctx), server_speeds(ctx))
    except Exception:
        srv = []
    return _comp_row(did, comp["label"],
                     _comp_cloud_cands(max_cloud_ladder(),
                                       [p for p in MAX_COMPOSITOR_ORDER if p in PROVIDER_BASES])
                     + srv + _comp_local_cands())


def server_comp_choices(ctx, e, default=None, speeds=None) -> dict:
    """The compositor rows of a mode on server e alone (6b442): that server's
    models that may write a merge, then (only while cloud power is on) the
    cloud's; the default is the server's own pen (server_compositor)."""
    try:
        rows = _comp_srv_cands(server_only_cands(e), speeds)
    except Exception:
        rows = []
    if cloud_allowed():
        rows += _comp_cloud_cands(compositor_ladder(), CLOUD_STRENGTH)
    return _comp_row(default["label"] if default else None,
                     default["label"] if default else "", rows)


def cloud_comp_choices(plan):
    """A Cloud Only mode's rows: the providers with a key, usable when the plan's
    merge ladder holds them (Thinking's is the cheap one), the first by default."""
    lad = plan.get("comp") or []
    did = _provider_of(lad[0]) if lad else None
    return _comp_row(did, lad[0]["name"] if lad else "", _comp_cloud_cands(lad, CLOUD_STRENGTH))


def pen_resolve(pen, ladder, srv_pool, cloud_ok=True, local_ok=True) -> tuple:
    """(kind, what) of a mode's chosen compositor at answer time: ("cloud", the
    conf from `ladder`), ("server", the row of `srv_pool`), ("local", label), or
    ("", None) when it can't write the answer now (the key is resting, the
    cloud is shut for this mode, the server no longer lists it, the model
    doesn't fit or isn't here) and the default writes it."""
    if not pen or not isinstance(pen, str):
        return "", None
    if pen in PROVIDER_BASES:
        c = next((c for c in ladder or [] if _provider_of(c) == pen), None) if cloud_ok else None
        return ("cloud", c) if c else ("", None)
    if server_label(pen):
        m = next((m for m in srv_pool or [] if m.get("label") == pen), None)
        return ("server", m) if m else ("", None)
    if local_ok and pen in MODEL_ROUTES and model_cached(pen) and model_fits_memory(pen):
        return "local", pen
    return "", None


def pen_name(pen: str) -> str:
    """How the status line names a chosen compositor."""
    return CLOUD_NAMES.get(pen) or str(pen or "").split(SERVER_SEP, 1)[-1] or "That model"


def claude_refusal_conf(c: dict):
    """One more try after a Claude REFUSAL (6b308): the newest Opus of
    the previous generation. Opus 5.x runs safety classifiers that can
    stop benign firewall, SSH and VPN work (Patrick's daily work); the
    generation before was not built with them. A rule, not a name, so
    it moves along with the lineup. None when there is no such model or
    the stop was anything but a refusal."""
    if not c or _provider_of(c) != "claude" or c.get("_stop") != "refusal":
        return None
    m0 = _CLAUDE_ID.match(c.get("model", ""))
    if not m0:
        return None
    major = int(m0.group(2))
    older = []
    for i in [c.get("model", "")] + list(c.get("models") or []):
        m = _CLAUDE_ID.match(i)
        if (m and m.group(1) == "opus" and int(m.group(2)) < major
                and cloud_model_alive(i) and not cloud_model_resting(i)):
            older.append(((int(m.group(2)), int(m.group(3) or 0)), i))
    if not older:
        return None
    return dict(c, model=max(older)[1], _stop="")


# WHO WROTE THE ANSWER (6b308): the conf that streamed the final answer
# on this request's thread. Titles, memory and map pins then use THAT
# provider's quick model, so a chat's words never reach a second
# company, and a chat answered on this Mac never leaves it.
#
# NO KEY IN THEM (0a 5.12 item 13, 6b326): both hold a TICKET, the
# provider, the model that answered and the key's fingerprint, never the
# key. /api/title held the whole conf for 5 minutes, so a key removed or
# replaced in Settings went on being used for titles and memory. Whoever
# uses a ticket re-reads the key from cloud.json under the cloud lock
# (_ticket_conf) and makes no call when the provider is gone or its key
# is no longer the one that answered.
_answered = profile_cache("_answered", {})            # thread -> ticket of the answer it streamed
# (user key, chat id) -> (ticket, time), /api/title
_last_cloud = profile_cache("_last_cloud", {})


def _cloud_ticket(c: dict) -> dict:
    return {"pid": _provider_of(c), "fp": _key_fp(c.get("key")),
            "model": str(c.get("model") or ""),
            "name": str(c.get("name") or "")}


def _ticket_conf(t):
    """The provider's saved conf for a ticket, key re-read under the cloud
    lock, or None when the provider was removed, its key replaced, or it
    is marked failed."""
    if not isinstance(t, dict) or not t.get("pid"):
        return None
    try:
        with _cloud_txn():
            cur = (_cloud_read_strict().get("providers") or {}).get(t["pid"])
            if (not isinstance(cur, dict) or not cur.get("key")
                    or cur.get("status", "ok") != "ok"
                    or not hmac.compare_digest(_key_fp(cur.get("key")),
                                               str(t.get("fp") or ""))):
                return None
            return dict(cur)
    except Exception:
        return None


def _mark_answered(c: dict):
    try:
        _answered[threading.get_ident()] = _cloud_ticket(c)
    except Exception:
        pass


# (pid, key fingerprint) -> (expires_ts, text): a balance is never shown
# for a key since replaced; scoped to the profile like every profile
# cache (1a 5.4)
_bal_cache = profile_cache("_bal_cache", {})


def cloud_balance(pid: str, c: dict) -> str:
    """Money left on a provider, when its API will say — '' otherwise.
    ONLY MOONSHOT exposes balance to a normal key (/users/me/balance,
    USD on the .ai platform). Anthropic shows cost only to an org ADMIN
    key, Groq and Gemini only in their dashboards — so those rows show
    nothing rather than something invented. Cached 5 minutes; Settings
    repaints constantly and must not spend a request each time."""
    if pid != "kimi" or not (c.get("key") and c.get("base")):
        return ""
    now = time.time()
    ck = (pid, _key_fp(c.get("key")))
    hit = _bal_cache.get(ck)
    if hit and hit[0] > now:
        return hit[1]
    text = ""
    try:
        req = urllib.request.Request(
            c["base"].rstrip("/") + "/users/me/balance",
            headers={"Authorization": "Bearer " + c["key"],
                     "User-Agent": "MillenAI/%s" % APP_VERSION})
        d = json.loads(urllib.request.urlopen(req, timeout=6).read())
        avail = (d.get("data") or {}).get("available_balance")
        if isinstance(avail, (int, float)):
            text = "$%.2f left" % avail
    except Exception:
        text = ""                 # a balance is a nicety, never a blocker
    _bal_cache[ck] = (now + 300, text)
    return text


def cloud_balance_est(ctx) -> dict:
    """{provider: estimate} for each provider this profile typed a balance
    for (6b441). A ledger that can't be read leaves the estimate out
    rather than showing the typed amount as if nothing was spent."""
    out = {}
    try:
        bals = profile_local(ctx).get("cloud_balance")
        if not isinstance(bals, dict):
            return out
        recs = None
        for pid in BALANCE_PROVIDERS:
            if isinstance(bals.get(pid), dict):
                if recs is None:
                    recs = usage_read(ctx)
                e = balance_estimate(pid, bals[pid], recs)
                if e:
                    out[pid] = e
    except Exception:
        pass
    return out


def cloud_stream(messages: list, emit) -> bool:
    """Stream from the configured cloud endpoint. False = fall back local."""
    return cloud_stream_conf(cloud_conf(), messages, emit)


# THE COUNTS IN A STREAM (6b325). Groq and Gemini put them in a last
# chunk when asked (stream_options); Moonshot puts them in its last
# choice unasked. A provider that 400s on the flag loses it for the rest
# of the launch and the stream is sent again without it, so the usage
# ledger never costs an answer.
_STREAM_USAGE_ASK = ("groq", "gemini")
_stream_usage_off = set()


def cloud_stream_conf(c: dict, messages: list, emit) -> bool:
    """Stream from ONE named provider conf. Cloud Only picks its own rung
    off the ladder rather than whichever provider happens to be active."""
    if not c:
        return False
    if "anthropic.com" in c.get("base", ""):
        return _anthropic_stream(c, messages, emit)
    body = _openai_body(c, messages, CLOUD_MAX_OUT.get(
        _provider_of(c), 4096), stream=True)
    _ask = (_provider_of(c) in _STREAM_USAGE_ASK
            and _provider_of(c) not in _stream_usage_off)
    if _ask:
        body["stream_options"] = {"include_usage": True}
    payload = json.dumps(body).encode()
    req = urllib.request.Request(
        c["base"].rstrip("/") + "/chat/completions", data=payload,
        headers={"Content-Type": "application/json",
                 "Accept": "text/event-stream",
                 # a bare Python-urllib UA gets 403'd by provider edges
                 # (Cloudflare "error code: 1010" from Groq — seen live)
                 "User-Agent": "MillenAI/%s" % APP_VERSION,
                 "Authorization": "Bearer " + c["key"]})
    got = False
    # HOLD THE HEAD (6b288): the first ~240 characters wait in a buffer
    # so a budget/quota notice sent as content never reaches the reader;
    # once the head reads like an answer it streams as before. A stream
    # that dies inside the head emits nothing and lets the next rung
    # answer whole, instead of leaving a two-line stub on screen.
    head = []

    def _flush():
        for t in head:
            emit(t)
        head.clear()
    t0, sent, u = time.time(), [0], {}
    try:
        with urllib.request.urlopen(req, timeout=90) as r:
            for raw in r:
                line = raw.decode("utf-8", "replace").strip()
                if not line.startswith("data:"):
                    continue
                blob = line[5:].strip()
                if blob == "[DONE]":
                    break
                try:
                    d = json.loads(blob)
                    tok = (d.get("choices") or [{}])[0].get(
                        "delta", {}).get("content") or ""
                except Exception:
                    d, tok = None, ""
                try:
                    _cu = (d.get("usage")
                           or (d.get("x_groq") or {}).get("usage")
                           or ((d.get("choices") or [{}])[0] or {})
                           .get("usage"))
                    if isinstance(_cu, dict):
                        u = _cu
                except Exception:
                    pass
                if not tok:
                    continue
                sent[0] += len(tok)
                if got:
                    emit(tok)
                    continue
                head.append(tok)
                if sum(len(t) for t in head) >= 240:
                    if _is_provider_error("".join(head)):
                        _cloud_budget_hit(c)
                        return False
                    got = True
                    _flush()
    except urllib.error.HTTPError as exc:
        if not got and _ask and exc.code == 400 and re.search(
                r"stream_options|include_usage", _http_body(exc)):
            _stream_usage_off.add(_provider_of(c))
            return cloud_stream_conf(c, messages, emit)
        if not got:
            cloud_note_failure(c, exc)
        return got
    except Exception:
        return got
    finally:
        try:
            usage_note(c.get("model"), _provider_of(c) or "cloud",
                       messages, sent[0], u, t0)
        except Exception:
            pass
    if not got and head:
        if _is_provider_error("".join(head)):
            _cloud_budget_hit(c)
            return False
        got = True
        _flush()
    if got:
        _mark_answered(c)
    return got


