_STUDIO_ROWS = {v["row"]: k for k, v in STUDIOS.items()}
# RETIRED STUDIO MODELS (6b445): a rung's old weights, by repo: (its name,
# disk GB, the rung that replaces it). Auto-clean deletes them (nothing
# reads them any more: the rung names its new repo), the Update models card
# offers the replacement, and Remove takes them with the studio.
# FLUX.1 schnell's real peak was about 20 GB, not the 12 the rung said.
STUDIO_RETIRED = {
    "image": {"dhairyashil/FLUX.1-schnell-mflux-4bit": ("FLUX.1 schnell", 9.6, "quick")},
}


def studio_supported() -> bool:
    return IS_MAC and IS_ARM


def studio_tier_id(key: str) -> str:
    want = str(machine_prefs().get("studio_" + key) or "").strip()
    ids = [t["id"] for t in STUDIOS[key]["tiers"]]
    return want if want in ids else ids[0]


def studio_tier(key: str, tid: str = "") -> dict:
    tid = tid or studio_tier_id(key)
    for t in STUDIOS[key]["tiers"]:
        if t["id"] == tid:
            return t
    return STUDIOS[key]["tiers"][0]


def tier_fit(mem_gb: float) -> str:
    """green / amber / red for one rung on THIS machine.

    green  comfortably inside what the machine can hold and stay quick
    amber  it fits, but only with the machine reasonably clear
    red    more memory than there is; offered, never pretended
    """
    if not HAS_PSUTIL:
        return "amber"                      # unknown: never promise green
    total = psutil.virtual_memory().total / 1e9
    if mem_gb <= total * 0.5:
        return "green"
    if mem_gb <= total * 0.8:
        return "amber"
    return "red"



# ------------------------------------------------------- studio settings
# THE GEAR (6b303, per Patrick: "a gear icon into the corner of each that
# opens a pop-up giving options like resolution, frame rate, effort …
# then also allow in the query the user to say things to describe the
# sort of quality they want … while still leaving their default settings
# the same").
#
# Three layers, innermost wins: the RUNG's defaults, then the user's saved
# settings for that studio, then a ONE-SHOT override parsed out of the
# message. Only the last is forgotten afterwards.
#
# Two controls are deliberately absent because the engines ignore them,
# which I confirmed by running them rather than by reading docs:
#   --negative-prompt  mflux warns "ignored; FLUX.1 uses distilled
#                      guidance and has no negative branch" (real on video)
#   --lora-style       parsed by mflux-generate and never read; it is
#                      wired only into the in-context entry point
# A control that does nothing is worse than no control.

STUDIO_RANGE = {
    "image": {"w": (256, 2048), "h": (256, 2048), "steps": (1, 50),
              "guidance": (1.0, 10.0)},
    "video": {"w": (256, 1280), "h": (256, 1280), "steps": (12, 40),
              "frames": (5, 97), "guidance": (1.0, 10.0)},
}
STUDIO_FORMATS = {"image": ("png", "jpg", "webp"),
                  "video": ("mp4", "gif", "webm")}
# read off the model's own config.json rather than hardcoded: Wan aligns
# to patch_size[1] * vae_stride[1] = 32 and caps area at 901,120 px
_ENGINE_CFG = {"image": {"align": 16, "max_area": 0, "fps": 0},
               "video": {"align": 32, "max_area": 901120, "fps": 24}}


def engine_cfg(key: str) -> dict:
    out = dict(_ENGINE_CFG.get(key) or {})
    try:
        snap = _snap_dir(studio_tier(key)["repo"])
        with open(os.path.join(snap, "config.json")) as f:
            c = json.load(f)
        ps, vs = c.get("patch_size") or [], c.get("vae_stride") or []
        if len(ps) > 1 and len(vs) > 1:
            out["align"] = int(ps[1]) * int(vs[1])
        if c.get("max_area"):
            out["max_area"] = int(c["max_area"])
        if c.get("sample_fps"):
            out["fps"] = int(c["sample_fps"])
    except Exception:
        pass
    return out


def _fit_area(w: int, h: int, max_area: int, align: int) -> tuple:
    """Shrink onto the grid until w*h fits, keeping the shape — the way
    the engine does it. It tries width-first AND height-first and keeps
    whichever preserves the aspect ratio better; doing only one branch
    disagrees with the engine on most inputs. Never GROWS a dimension:
    the result is clamped back to what was asked for, so a memory or
    time estimate taken from it can never under-read the real render."""
    w, h = max(align, int(w)), max(align, int(h))
    if not max_area or w * h <= max_area:
        return (w // align) * align or align, (h // align) * align or align
    ratio = w / float(h)
    ow1 = max(align, int(round((max_area * ratio) ** 0.5 / align)) * align)
    oh1 = max(align, int(round((max_area / ratio) ** 0.5 / align)) * align)
    oh2 = max(align, int(round((max_area / ratio) ** 0.5 / align)) * align)
    ow2 = max(align, int(round(oh2 * ratio / align)) * align)
    def err(a, b):
        r = a / float(b)
        return max(r / ratio, ratio / r)
    ow, oh = ((ow1, oh1) if err(ow1, oh1) <= err(ow2, oh2) else (ow2, oh2))
    ow, oh = min(ow, w), min(oh, h)
    # rounding to the nearest grid step can land ABOVE the cap, and the
    # engine would then rewrite it behind our back — step down until the
    # number we report is the number it renders
    while ow * oh > max_area and (ow > align or oh > align):
        if ow >= oh:
            ow = max(align, ow - align)
        else:
            oh = max(align, oh - align)
    return ow, oh


def _snap_frames(n: int) -> int:
    """Wan asserts num_frames == 4n+1 — an assert, not a clamp, so an
    unsnapped value is a crash rather than a rounded render."""
    n = max(5, int(n))
    return ((n - 1) // 4) * 4 + 1


def _num(v, fallback):
    try:
        f = float(v)
        if f != f or f in (float("inf"), float("-inf")):
            return fallback
        return f
    except (TypeError, ValueError):
        return fallback


def studio_prefs(key: str) -> dict:
    """The saved settings for one studio: the machine's fields, and the
    negative prompt of the profile this thread works for (1a 5.6, G1:
    B's renders never use A's text)."""
    d = machine_prefs().get("studio_opts") or {}
    out = dict(d.get(key) or {}) if isinstance(d, dict) else {}
    try:
        neg = (profile_local(bound_ctx()).get("studio_opts.*.neg")
               or {}).get(key)
    except NoProfile:
        neg = None
    if neg is not None:
        out[STUDIO_NEG] = neg
    return out


def _img_distilled(base) -> bool:
    """A 4-step distilled image model (schnell; FLUX.2 klein, not its base)."""
    b = str(base or "")
    return b == "schnell" or (b.startswith("flux2-klein") and "base" not in b)


def studio_opts(key: str, over: dict = None) -> dict:
    """The settings one render will actually use. Never raises: every
    value is coerced and clamped, because the override layer comes from
    free text and the saved layer comes from a JSON file a user can edit."""
    t = studio_tier(key)
    cfg = engine_cfg(key)
    out = {"w": t.get("w", 1024), "h": t.get("h", 1024),
           "steps": t.get("steps", 4), "guidance": t.get("guidance", 3.5),
           "fmt": STUDIO_FORMATS[key][0], "seed": 0, "neg": ""}
    if key == "video":
        out.update(frames=t.get("frames", 33), fps=cfg.get("fps") or 24)
    base = dict(out)          # the rung's own numbers, to fall back on
    for layer in (studio_prefs(key), over or {}):
        for k, v in (layer or {}).items():
            if k in out and v not in (None, ""):
                out[k] = v
    rng = STUDIO_RANGE.get(key) or {}
    # SIZE KEEPS ITS SHAPE (6b304): clamping width and height separately
    # turned a 3840x2160 ask into 1280x1280 on video — a square. Scale
    # both sides by ONE factor to fit the per-axis limits first.
    _w, _h = _num(out.get("w"), base.get("w", 1024)), _num(out.get("h"),
                                                            base.get("h", 1024))
    if _w > 0 and _h > 0 and "w" in rng and "h" in rng:
        f = min(1.0, rng["w"][1] / _w, rng["h"][1] / _h)
        f = max(f, rng["w"][0] / _w, rng["h"][0] / _h)
        out["w"], out["h"] = _w * f, _h * f
    for field, (lo, hi) in rng.items():
        if field not in out:
            continue
        # an unreadable value falls back to the RUNG's default, not to
        # the floor: "abc" steps should render normally, not at 1 step
        val = _num(out[field], _num(base.get(field), lo))
        out[field] = min(max(val, lo), hi)
    out["steps"] = int(out["steps"])
    out["w"], out["h"] = int(out["w"]), int(out["h"])
    out["w"], out["h"] = _fit_area(out["w"], out["h"],
                                   cfg.get("max_area", 0),
                                   cfg.get("align", 16))
    if key == "video":
        out["frames"] = _snap_frames(out["frames"])
        out["fps"] = int(min(max(_num(out.get("fps"), 24), 8), 60))
    if out.get("fmt") not in STUDIO_FORMATS[key]:
        out["fmt"] = STUDIO_FORMATS[key][0]
    out["seed"] = int(_num(out.get("seed"), 0))
    out["neg"] = str(out.get("neg") or "")[:300]
    return out


def studio_save_opts(key: str, patch: dict) -> dict:
    """Merge one change into the saved settings, under the prefs lock —
    generations now write prefs too (the time calibration), so an
    unlocked read-modify-write here would lose whichever landed first.
    Each field goes to its own place (1a 5.6, G1): the negative prompt to
    the profile, the rest to the machine."""
    patch = patch if isinstance(patch, dict) else {}
    ctx = bound_ctx()

    def _mach(view):
        allopt = dict(view.get("studio_opts") or {})
        cur = dict(allopt.get(key) or {})
        if patch.get("_reset"):
            cur = {}
        else:
            for k, v in patch.items():
                if k.startswith("_") or k == STUDIO_NEG:
                    continue
                if v in (None, ""):
                    cur.pop(k, None)
                else:
                    cur[k] = v
        allopt[key] = cur
        view["studio_opts"] = allopt

    def _loc(view):
        neg = dict(view.get("studio_opts.*.neg") or {})
        if patch.get("_reset") or patch.get(STUDIO_NEG) in (None, ""):
            neg.pop(key, None)
        else:
            neg[key] = patch[STUDIO_NEG]
        if neg:
            view["studio_opts.*.neg"] = neg
        else:
            view.pop("studio_opts.*.neg", None)
    with _prefs_lock:
        machine_prefs_update(_mach)
        if patch.get("_reset") or STUDIO_NEG in patch:
            profile_local_update(ctx, _loc)
    return studio_opts(key)


# ------------------------------------------------- one-shot overrides
# Deterministic on purpose. An override is a NUMBER handed to a renderer:
# a model that reads "double it" as 4096 costs twenty minutes and a
# swapped machine. Detection has to be trustworthy, so it is regex; the
# PROMPT rewrite stays with the model, which is what it is good at.
#
# loose=1 rules only fire on a FOLLOW-UP. "4k", "1080p", "portrait",
# "faster", "sharper", "gif" are all ordinary subject words — "a 4k
# webcam", "draw a portrait of a woman", "a faster car" — and stripping
# them out of a fresh commission would eat the subject.
_OV_RULES = [
    # (regex, loose, handler-key)
    (r"\b(?:double|2\s*x|twice)\s+(?:the\s+)?(?:resolution|res|size)\b", 0, "x2"),
    (r"\b(?:half|halve)\s+(?:the\s+)?(?:resolution|res|size)\b", 0, "x05"),
    (r"\b(?:at|in|to|into)\s+(4k|8k|1080p?|720p?|480p?|hd|full\s*hd|uhd)\b", 0, "res"),
    (r"\b(4k|8k|1080p|720p|480p)\b", 1, "res"),
    (r"\b(\d{3,4})\s*(?:x|by|×)\s*(\d{3,4})\b", 0, "wh"),
    (r"\b(?:make\s+it\s+|in\s+|as\s+|to\s+|switch\s+to\s+|crop\s+to\s+)"
     r"(square|portrait|landscape|widescreen|vertical|horizontal|wide|tall)\b", 0, "ar"),
    (r"^\s*(square|portrait|landscape|widescreen|vertical|horizontal)\s*$", 0, "ar"),
    (r"\b(?:higher|better|best|more)\s+(?:quality|detail|detailed)\b", 0, "up"),
    (r"\b(?:highest|maximum|max)\s+(?:quality|detail|effort)\b", 0, "up2"),
    (r"\bmore\s+steps\b", 0, "up"),
    (r"\b(?:quick\s+and\s+dirty|lower\s+quality|just\s+a\s+draft|"
     r"speed\s+it\s+up|less\s+detail|fewer\s+steps)\b", 0, "down"),
    (r"\b(?:sharper|crisper|cleaner|more\s+detailed)\b", 1, "up"),
    (r"\b(?:faster|quicker|quickly|rougher)\b", 1, "down"),
    (r"\b(?:bigger|larger)\b", 1, "x15"),
    (r"\b(?:smaller|tinier)\b", 1, "x075"),
    (r"\b(\d{1,2}(?:\.\d)?)\s*(?:s|sec|secs|second|seconds)\s*(?:long)?\b", 0, "secs"),
    (r"\b(\d{1,3})\s*frames\b", 0, "frames"),
    (r"\b(?:longer|make\s+it\s+longer)\b", 1, "longer"),
    (r"\b(?:shorter)\b", 1, "shorter"),
    (r"\b(\d{1,3})\s*fps\b", 0, "fps"),
    (r"\b(?:as|in|to|into|make\s+it)\s+(?:an?\s+)?"
     r"(gif|webm|mp4|jpe?g|png|webp)\b", 0, "fmt"),
]
_OV_RES = {"8k": (7680, 4320), "4k": (3840, 2160), "uhd": (3840, 2160),
           "1080p": (1920, 1080), "1080": (1920, 1080),
           "full hd": (1920, 1080), "fullhd": (1920, 1080),
           "hd": (1280, 720), "720p": (1280, 720), "720": (1280, 720),
           "480p": (854, 480), "480": (854, 480)}
_OV_AR = {"square": 1.0, "portrait": 0.75, "vertical": 0.5625, "tall": 0.75,
          "landscape": 1.3333, "horizontal": 1.3333, "widescreen": 1.7778,
          "wide": 1.7778}
_OV_COMPILED = [(re.compile(rx, re.I), loose, kind) for rx, loose, kind in _OV_RULES]


def gen_overrides(text: str, key: str, loose: bool, prev: dict = None):
    """(overrides, cleaned_text). The matched phrases are REMOVED from the
    text so the prompt rewrite never sees "at 4K" and paints it into the
    picture. Relative asks resolve against the previous render when there
    is one; absolute ones never need it."""
    t = " " + re.sub(r"\s+", " ", (text or "").strip()) + " "
    base = dict(prev or {})
    ov, notes = {}, []
    bw = _num(base.get("w"), 0) or 0
    bh = _num(base.get("h"), 0) or 0
    for rx, lo, kind in _OV_COMPILED:
        if lo and not loose:
            continue
        m = rx.search(t)
        if not m:
            continue
        g = [x for x in (m.groups() or ()) if x]
        if kind in ("x2", "x05", "x15", "x075"):
            f = {"x2": 2.0, "x05": 0.5, "x15": 1.5, "x075": 0.75}[kind]
            if bw and bh:
                ov["w"], ov["h"] = int(bw * f), int(bh * f)
            else:
                ov["_scale"] = f
        elif kind == "res":
            r = _OV_RES.get(g[0].lower().replace(" ", ""))
            if not r:
                r = _OV_RES.get(g[0].lower())
            if r:
                ov["w"], ov["h"] = r
        elif kind == "wh" and len(g) >= 2:
            ov["w"], ov["h"] = int(g[0]), int(g[1])
        elif kind == "ar":
            a = _OV_AR.get(g[0].lower())
            if a:
                ov["_ar"] = a
        elif kind in ("up", "up2", "down"):
            ov["_effort"] = {"up": 1, "up2": 2, "down": -1}[kind]
        elif kind == "secs":
            ov["frames"] = _snap_frames(round(_num(g[0], 2) * 24))
        elif kind == "frames":
            ov["frames"] = _snap_frames(int(g[0]))
        elif kind == "longer":
            ov["_len"] = 1.5
        elif kind == "shorter":
            ov["_len"] = 0.6
        elif kind == "fps":
            ov["fps"] = int(g[0])
        elif kind == "fmt":
            f = g[0].lower().replace("jpeg", "jpg")
            if f in STUDIO_FORMATS.get(key, ()):
                ov["fmt"] = f
            else:
                notes.append("%s isn't a %s format" % (f.upper(), key))
        t = t[:m.start()] + " " + t[m.end():]
    cleaned = re.sub(r"\s+", " ", t).strip()
    # a matched clause leaves conjunctions and punctuation behind: "make
    # the piano white and double the resolution" -> "make the piano white
    # and". Left in, that dangling "and" reaches the prompt.
    cleaned = re.sub(r"^(?:and|but|then|so|also|plus|with|,|;)\s+", "",
                     cleaned, flags=re.I)
    # a removed clause also leaves its governing preposition and any
    # pronoun behind — "do that again at 1920x1080" -> "do that again at",
    # "make it bigger" -> "make it". Both would reach the prompt.
    for _ in range(3):
        cleaned = re.sub(
            r"[\s,;]*\b(?:and|but|then|so|also|plus|with|at|to|in|into|as|"
            r"it|this|that|them)\s*$", "", cleaned, flags=re.I).strip(" ,;.")
    return ov, cleaned, notes


def resolve_overrides(key: str, ov: dict, prev: dict = None) -> tuple:
    """Fold the relative parts of an override against the settings that
    are actually in force, and say plainly when a number had to move."""
    if not ov:
        return {}, []
    cur = studio_opts(key)
    base = dict(cur)
    base.update({k: v for k, v in (prev or {}).items() if k in cur})
    out = {k: v for k, v in ov.items() if not k.startswith("_")}
    notes = []
    if ov.get("_scale"):
        out["w"] = int(base["w"] * ov["_scale"])
        out["h"] = int(base["h"] * ov["_scale"])
    if ov.get("_ar"):
        area = (out.get("w", base["w"])) * (out.get("h", base["h"]))
        a = ov["_ar"]
        out["w"] = int((area * a) ** 0.5)
        out["h"] = int((area / a) ** 0.5)
    if ov.get("_len"):
        out["frames"] = _snap_frames(base.get("frames", 33) * ov["_len"])
    eff = ov.get("_effort")
    if eff:
        if key == "video":
            # steps below 20 come out washed out (measured), so effort on
            # video buys its time from frames and size instead
            if eff < 0:
                out["frames"] = _snap_frames(base.get("frames", 33) * 0.85)
                out["w"] = int(base["w"] * 0.8)
                out["h"] = int(base["h"] * 0.8)
                notes.append("smaller and shorter for speed")
            else:
                out["steps"] = min(40, base["steps"] + (8 * eff))
        elif _img_distilled(studio_tier("image").get("base")) and eff > 0:
            # schnell and klein are 4-step distillations: more steps buy
            # nothing, so quality comes from pixels
            out["w"] = int(base["w"] * (1.4 if eff == 1 else 1.75))
            out["h"] = int(base["h"] * (1.4 if eff == 1 else 1.75))
            notes.append("larger for detail")
        else:
            out["steps"] = max(1, min(50, base["steps"]
                                      + (6 * eff if eff > 0 else -6)))
    want = dict(out)
    final = studio_opts(key, out)
    for f in ("w", "h", "frames"):
        if f in want and int(_num(want[f], 0)) != final.get(f):
            notes.append("%s capped at %s, the engine\u2019s most"
                         % ({"w": "width", "h": "height",
                             "frames": "length"}[f], final.get(f)))
    return out, notes

def _studio_engine_ok(key: str) -> bool:
    """Is the engine installed? A FILESYSTEM check, deliberately (6b304).

    The video studio used to prove it by running `python -c "import
    mlx_video"` — a cold Python + MLX start costing ~1.1s wall and ~0.8s
    CPU. It ran twice per /api/setup, and /api/setup is polled every
    1.2-4s by four tickers: two-thirds of that endpoint's 2.3s, measured,
    and a machine held at half a core just to say "yes, still installed".
    The package's own __init__.py on disk answers the same question in
    a tenth of a millisecond."""
    st = STUDIOS[key]
    if st.get("probe"):
        return os.path.exists(os.path.join(st["venv"], "bin", st["probe"]))
    if not os.path.exists(os.path.join(st["venv"], "bin", "python3")):
        return False
    top = st["module"].split(".", 1)[0]
    return bool(glob.glob(os.path.join(st["venv"], "lib", "python*",
                                       "site-packages", top, "__init__.py")))


def _snap_dir(repo: str) -> str:
    """The snapshot main points at (a FLUX.2 repo has no config.json at its
    top, 6b445), else the first one holding a config.json."""
    d = _hf_model_dir(repo)
    try:
        with open(os.path.join(d, "refs", "main"), encoding="utf-8") as f:
            cur = os.path.join(d, "snapshots", f.read(80).strip())
        if os.path.isdir(cur) and os.path.basename(cur):
            return cur
    except OSError:
        pass
    snaps = glob.glob(os.path.join(d, "snapshots", "*", "config.json"))
    return os.path.dirname(snaps[0]) if snaps else ""


def _studio_model_ok(key: str, tid: str = "") -> bool:
    repo = studio_tier(key, tid)["repo"]
    snap = _snap_dir(repo)
    if not snap:
        return False
    if glob.glob(os.path.join(_hf_model_dir(repo), "blobs", "*.incomplete")):
        return False
    return bool(glob.glob(os.path.join(snap, "**", "*.safetensors"),
                          recursive=True))


def studio_ready(key: str, tid: str = "") -> bool:
    return (studio_supported() and _studio_engine_ok(key)
            and _studio_model_ok(key, tid))


_studio_bytes_cache = {}        # key -> (ts, bytes); cleared on change


def _studio_bytes_forget(key: str):
    _studio_bytes_cache.pop(key, None)


def studio_bytes(key: str) -> int:
    """Cached for ten minutes, and cleared on install and remove (6b304).
    Walking both venvs and every rung's weights is ~58k files and ~200k
    stat calls, and it ran three times per /api/setup, holding the GIL
    and slowing chat streaming, to report a number that changes only
    when something is installed or removed."""
    hit = _studio_bytes_cache.get(key)
    if hit and time.time() - hit[0] < 3600:
        return hit[1]
    val = _studio_bytes_uncached(key)
    _studio_bytes_cache[key] = (time.time(), val)
    return val


def _studio_bytes_uncached(key: str) -> int:
    """Everything this studio occupies: its venv and EVERY rung of its
    ladder that was ever downloaded, so Remove promises the truth."""
    total = _dir_bytes_real(STUDIOS[key]["venv"])
    # rungs may SHARE a repo (quick and accurate differ only in how many
    # frames they render), so count each repo once or Remove promises
    # twice the disk it can free
    for repo in dict.fromkeys([t["repo"] for t in STUDIOS[key]["tiers"]]
                              + list(STUDIO_RETIRED.get(key) or {})):
        total += _dir_bytes_real(_hf_model_dir(repo))
    return total


def _studio_install_worker(key: str, tid: str):
    st, row = STUDIOS[key], STUDIOS[key]["row"]
    try:
        with _setup_lock:
            _setup_jobs[row] = {"status": "downloading", "pct": 0,
                                "note": "installing the engine"}
        if not _studio_engine_ok(key):
            py = os.path.join(app_dir(), "venv", "bin", "python3")
            if not os.path.exists(py):
                py = sys.executable
            subprocess.run([py, "-m", "venv", st["venv"]], check=True,
                           timeout=300, capture_output=True)
            # marked FROM THE START (6b308): fresh while pip runs, so no
            # instance's sweep takes it; a killed install ages out
            try:
                open(os.path.join(st["venv"], STUDIO_FAIL_MARK), "w").close()
            except OSError:
                pass
            subprocess.run([os.path.join(st["venv"], "bin", "pip"), "install",
                            "--quiet", "--upgrade", "pip"],
                           timeout=300, capture_output=True)
            r = subprocess.run([os.path.join(st["venv"], "bin", "pip"),
                                "install", "--quiet"] + st["pip"],
                               timeout=2400, capture_output=True, text=True)
            if r.returncode != 0 or not _studio_engine_ok(key):
                raise RuntimeError("Engine install failed: "
                                   + (r.stderr or "")[-160:])
        # a good engine clears the failed-install mark (6b307)
        try:
            os.remove(os.path.join(st["venv"], STUDIO_FAIL_MARK))
        except OSError:
            pass
        with _setup_lock:
            _setup_jobs[row]["note"] = ""
        if not _studio_model_ok(key, tid):
            from huggingface_hub import snapshot_download
            snapshot_download(studio_tier(key, tid)["repo"])
            for pth in glob.glob(os.path.join(
                    _hf_model_dir(studio_tier(key, tid)["repo"]),
                    "blobs", "*.incomplete")):
                try:
                    os.remove(pth)
                except OSError:
                    pass
        with _setup_lock:
            _setup_jobs[row] = {"status": "done", "note": "", "pct": 100}
    except Exception as exc:
        with _setup_lock:
            _setup_jobs[row] = {"status": "error", "note": str(exc)[:200],
                                "pct": 0}
        # MARK A HALF-BUILT ENGINE (6b307): a failed pip run leaves GBs of
        # venv behind that nothing would ever use. The mark is how the
        # leftover sweep tells it from a working install; a retry that
        # succeeds removes it.
        try:
            if os.path.isdir(st["venv"]) and not _studio_engine_ok(key):
                open(os.path.join(st["venv"], STUDIO_FAIL_MARK), "w").close()
        except OSError:
            pass
    finally:
        _studio_bytes_forget(key)


STUDIO_FAIL_MARK = ".concorde-install-failed"


def start_studio_install(key: str, tid: str = "") -> bool:
    if key not in STUDIOS or not studio_supported():
        return False
    tid = tid or studio_tier_id(key)
    if tid not in [t["id"] for t in STUDIOS[key]["tiers"]]:
        return False
    machine_prefs_update(lambda v: v.__setitem__("studio_" + key, tid))
    if studio_ready(key, tid):
        return False
    row = STUDIOS[key]["row"]
    with _setup_lock:
        if _setup_jobs.get(row, {}).get("status") in ("downloading", "queued"):
            return False
        _setup_jobs[row] = {"status": "queued", "note": "", "pct": 0}
    _reset_dl_window()
    ctx_thread(target=_studio_install_worker, args=(key, tid),
                     daemon=True).start()
    return True


def studio_remove(key: str) -> dict:
    """Take the whole studio back off the disk — the venv and every rung
    that was downloaded — and clear the job so the box reads as a fresh
    install rather than a finished one."""
    freed, errs = _studio_bytes_uncached(key), []
    _studio_bytes_forget(key)
    targets = [STUDIOS[key]["venv"]] + [
        _hf_model_dir(r) for r in
        dict.fromkeys([t["repo"] for t in STUDIOS[key]["tiers"]]
                      + list(STUDIO_RETIRED.get(key) or {}))]
    for target in targets:
        try:
            if os.path.isdir(target):
                shutil.rmtree(target)
        except OSError as exc:
            errs.append(str(exc)[:120])
    with _setup_lock:
        _setup_jobs.pop(STUDIOS[key]["row"], None)
    return {"ok": not errs, "freed_gb": round(freed / 1e9, 1), "errors": errs}


def studio_status(key: str) -> dict:
    st = STUDIOS[key]
    with _setup_lock:
        job = dict(_setup_jobs.get(st["row"], {}))
    tid = studio_tier_id(key)
    tier = studio_tier(key, tid)
    engine = _studio_engine_ok(key)
    ready = studio_supported() and engine and _studio_model_ok(key, tid)
    est = int(tier["gb"] * 1e9)
    pct = 100 if ready else min(99, round(
        _dir_bytes_real(_hf_model_dir(tier["repo"])) / est * 100))
    return {
        "key": key, "supported": studio_supported(), "ready": ready,
        "engine": engine, "tier": tid,
        "gb": tier["gb"], "pct": pct,
        "on_disk_gb": round(studio_bytes(key) / 1e9, 1) if ready else 0,
        "status": "ready" if ready else job.get("status", "missing"),
        "note": job.get("note", ""),
        "opts": studio_opts(key), "saved": studio_prefs(key),
        "ranges": STUDIO_RANGE.get(key) or {},
        "formats": list(STUDIO_FORMATS.get(key) or ()),
        "native_fps": engine_cfg(key).get("fps") or 0,
        "tiers": [{"id": t["id"], "name": t["name"], "gb": t["gb"],
                   "mem_gb": t["mem_gb"], "note": t["note"],
                   "fit": tier_fit(t["mem_gb"]),
                   "have": _studio_model_ok(key, t["id"])}
                  for t in st["tiers"]],
    }


IMAGE_ROW = "Image generation"
IMAGE_REPO = "mflux-community/flux2-klein-4b-mflux-q4"
IMAGE_GB = 4.6
IMAGE_VENV = os.path.join(app_dir(), "venv-image")
IMAGE_SUB = "images"      # a profile's pictures (1a 5.5): image_dir(ctx)


def image_dir(ctx) -> str:
    return ctx.path(IMAGE_SUB)
_IMG_VERBS = r"(?:generate|create|make|draw|paint|render|produce|design|illustrate|sketch)"
_IMG_NOUNS = (r"(?:image|picture|photo(?:graph)?|illustration|drawing|painting|"
              r"logo|poster|sketch|artwork|icon|wallpaper|portrait|banner)s?")
_IMAGE_RX = re.compile(
    r"^\s*(?:please\s+|hey\s+|ok(?:ay)?\s+)?(?:(?:can|could|would|will)\s+you\s+)?"
    r"(?:please\s+)?" + _IMG_VERBS + r"\s+(?:me\s+)?(?:an?\s+|some\s+|the\s+|\d+\s+)?"
    r"(?:(?!of\b)\w+\s+){0,2}" + _IMG_NOUNS +
    r"\b\s*(?:of|showing|depicting|featuring|with|for|:|-|—)?\s*(?P<subject>.*)$",
    re.I | re.S)
_DRAW_RX = re.compile(
    r"^\s*(?:please\s+)?(?:draw|paint|sketch|illustrate)\s+(?:me\s+)?(?P<subject>.+)$",
    re.I | re.S)


# A CONVERSATIONAL LEAD-IN IS NOT A DIFFERENT REQUEST (6b296, per Patrick:
# "try again, generate an image of a cat" produced a model's hallucinated
# tool call instead of a picture). Both matchers below are ^-anchored on
# the verb, so ANY preamble — "try again,", "now", "actually," — made them
# miss and the ask fell through to the chat path. Strip the filler first.
_IMG_PRE = re.compile(
    r"^\s*(?:(?:ok(?:ay)?|alright|sure|cool|great|nice|thanks|thank\s+you|"
    r"hey|hi|hmm+|um+|so|and|but|well|now|then|next|also|too|actually|"
    r"instead|again|please|just|quick(?:ly)?|final(?:ly)?|"
    r"(?:lets|let\u2019s|let's)|"
    r"try(?:\s+(?:it|that|this))?\s+again|one\s+more\s+time|"
    r"another\s+(?:one|go|try))"
    r"[\s,.;:!\u2014-]+){1,4}", re.I)


def _img_strip_pre(t: str) -> str:
    """Drop up to four filler openers, leaving the actual request."""
    prev = None
    while prev != t:
        prev = t
        t = _IMG_PRE.sub("", t, count=1).lstrip()
    return t


def image_intent(text: str):
    """The subject to paint when the message asks for a picture, else
    None. "Generate an image of a cat." -> "a cat"; "draw me a red
    bicycle" -> "a red bicycle"; "what is an image sensor" -> None."""
    t = (text or "").strip()
    if len(t) > 600:
        return None
    m = _IMAGE_RX.match(t) or _DRAW_RX.match(t)
    if not m:
        t2 = _img_strip_pre(t)
        if t2 != t and t2:
            m = _IMAGE_RX.match(t2) or _DRAW_RX.match(t2)
            if m:
                t = t2
    if not m:
        return None
    # the prompt is everything after the verb — "a realistic photo of the
    # Eiffel tower at night", "a logo for a coffee shop" — minus a bare
    # "an image of", which says nothing a painter needs
    rest = re.match(r"^\s*(?:please\s+|hey\s+|ok(?:ay)?\s+)?"
                    r"(?:(?:can|could|would|will)\s+you\s+)?(?:please\s+)?"
                    r"(?:generate|create|make|draw|paint|render|produce|design|"
                    r"illustrate|sketch)\s+(?:me\s+)?(?P<rest>.*)$", t, re.I | re.S)
    subj = (rest.group("rest") if rest else m.group("subject")).strip()
    subj = re.sub(r"^(?:an?|some|the)\s+(?:image|picture|pic|photo(?:graph)?)s?"
                  r"\s+(?:of|showing|depicting)\s+", "", subj, flags=re.I)
    subj = subj.strip().strip(".!?").strip()
    if _BACKREF.match(subj):
        return None               # points at what was made: a follow-up
    return subj or "something beautiful"


# the image studio's old names, kept so every existing caller works
# FETCH OR PAINT (6b300, per Patrick: "if they say 'I'd like to see a
# picture of a cookie from the Internet' it will try to fetch an image
# that already exists online. However, if the user says create me a
# picture of a cookie, it should generate").
_IMG_FIND = re.compile(
    r"\b(?:from\s+(?:the\s+)?(?:internet|web|google|online)|on\s+the\s+"
    r"(?:internet|web)|online|search\s+for|look\s+up|google|find\s+me|"
    r"find\s+(?:an?|some)|real\s+(?:photo|picture|image)|actual\s+"
    r"(?:photo|picture|image)|existing|stock\s+(?:photo|image))\b", re.I)
# a bare "show me / I'd like to see a picture of X" is a LOOK request, not
# a commission — only an explicit make-verb commissions a new one
_IMG_SEE = re.compile(
    r"^\s*(?:(?:i(?:'| a)?d\s+like\s+to\s+see|i\s+want\s+to\s+see|"
    r"show\s+me|let\s+me\s+see|got\s+(?:any|a))\b)", re.I)
_IMG_MAKE_VERB = re.compile(
    r"\b(?:generate|create|draw|paint|render|illustrate|sketch|design|"
    r"make\s+me|make\s+a|make\s+an|imagine)\b", re.I)


def image_wants_fetch(text: str) -> bool:
    """True when the ask is for a picture that already exists."""
    t = (text or "").strip()
    if _IMG_MAKE_VERB.search(t) and not _IMG_FIND.search(t):
        return False              # an explicit commission always paints
    return bool(_IMG_FIND.search(t) or _IMG_SEE.match(_img_strip_pre(t)))


# REFINEMENTS (6b300/6b301, per Patrick: "we've got to do way better at
# detecting when a query is applying to a previously generated image or
# video … my query was to regenerate the image, but make the piano
# white"). Pattern-matching a handful of phrasings was never going to
# hold. The default flips instead: right after a picture, a SHORT message
# that is not a question and not a fresh commission is about that
# picture. That is what a person means essentially every time.
_IMG_NEWTOPIC = re.compile(
    r"^\s*(?:what|why|how|who|when|where|which|is|are|was|were|do|does|did|"
    r"can\s+you\s+(?:explain|tell|describe|list|write|help)|tell\s+me|"
    r"explain|describe|summari[sz]e|translate|write|code|search|find\s+out|"
    r"look\s+up|remind|calculate|convert)\b", re.I)
_IMG_CHANGE = re.compile(
    r"^\s*(?:please\s+)?(?:(?:can|could|would)\s+you\s+)?(?:please\s+)?"
    r"(?:now\s+|instead\s+|but\s+|also\s+|and\s+)?"
    r"(?:make|turn|change|paint|colou?r|set|give|add|put|remove|drop|"
    r"swap|replace|redo|regenerate|re-?draw|re-?make|try|do)\b\s*"
    r"(?P<rest>.*)$", re.I | re.S)
_IMG_LEADIN = re.compile(
    r"^\s*(?:it|them|this|that|these|those|the\s+image|the\s+picture|"
    r"the\s+photo|the\s+video|the\s+clip|again|it\s+again)\b[\s,]*", re.I)


def _subject_words(subject: str) -> set:
    return {w for w in re.findall(r"[a-z]{3,}", (subject or "").lower())
            if w not in ("the", "and", "with", "for", "from", "that")}


# A BACK-REFERENCE IS NOT A NEW SUBJECT (6b304). Both commission regexes
# accepted "make the video longer" and "make it a gif" as fresh requests
# and filmed the literal words "the video" / "it a gif". A subject that
# opens by pointing at the thing already made belongs to the follow-up
# path, never to a new render.
_MEDIUM = (r"(?:image|picture|photo|pic|video|clip|animation|gif|movie|"
           r"render|one)s?")
_BACKREF = re.compile(
    r"^(?:it|them|its)\b"
    r"|^(?:this|that|these|those)\s+(?:a|an|into|to|as|the)\b"
    r"|^(?:the|this|that|these|those|my|your)\s+" + _MEDIUM + r"\b", re.I)
# "make it a gif", "turn this into a video", "animate it" — after a still,
# that asks for MOTION of the same subject
_TO_MOTION = re.compile(
    r"\b(?:make|turn|convert|change)\s+(?:it|this|that)\s+(?:into\s+)?"
    r"(?:an?\s+)?(?:short\s+)?(?:gif|video|clip|animation|movie)\b"
    r"|\banimate\s+(?:it|this|that)\b", re.I)
# what is left of a message once the filler and the medium are gone; if
# nothing is, the message carried no CONTENT change at all
_FILLER = re.compile(
    r"\b(?:same|again|but|please|it|this|that|these|those|now|and|then|"
    r"the|a|an|do|redo|regenerate|re-?render|re-?draw|re-?make|make|try|"
    r"one|more|time|just|so|also|with|of|for|at|in|to|as|can|could|you|"
    r"would|me|us|let's|lets|give|go|another|version|" + _MEDIUM[3:-3] +
    r")\b", re.I)


def _residual(text: str) -> str:
    return re.sub(r"[\s,.;:!?]+", " ", _FILLER.sub(" ", text or "")).strip()


def image_followup(text: str, prev_subject: str, refine: bool = True, server: bool = True):
    """A new prompt when this message refines the picture just made, else
    None. Liberal by design: after an image, the burden is on a message
    to look like a NEW topic, not on it to look like a refinement.

    DETECTION is deterministic (it has to be trustworthy). Composing the
    new prompt is not: "remove the lamp" and "now put it in a jazz club"
    defeat string surgery, so a resident model rewrites it when there is
    one, and the surgery below is the floor when there is not."""
    t = re.sub(r"\s+", " ", (text or "").strip())
    if not prev_subject or not t or len(t.split()) > 16 or t.endswith("?"):
        return None
    if _IMG_NEWTOPIC.match(t):
        return None
    if image_intent(t) or video_intent(t) or export_intent(t, True):
        return None               # a fresh commission, or a file request
    m = _IMG_CHANGE.match(t)
    known = _subject_words(prev_subject)
    words = set(re.findall(r"[a-z]{3,}", t.lower()))
    # either it is phrased as a change, or it names something already in
    # the picture ("the piano ..."), or it is a bare descriptive fragment
    if not m and not (words & known) and len(t.split()) > 4:
        return None
    rest = (m.group("rest") if m else t).strip()
    rest = _IMG_LEADIN.sub("", rest).strip().strip(".!?,")
    # drop a reference to something the subject already names, so
    # "the piano white" becomes "white" and can be folded in properly
    toks = rest.split()
    while toks and re.sub(r"[^a-z]", "", toks[0].lower()) in (
            "a", "an", "the", "its", "his", "her", "their"):
        toks.pop(0)
    while toks and re.sub(r"[^a-z]", "", toks[0].lower()) in known:
        toks.pop(0)
    rest = " ".join(toks).strip(" ,.")
    # refine=False: a model of this computer may not be asked ("<name> Only",
    # 6b339: it makes no picture, so it asks no model to word one)
    said = _refine_with_model(prev_subject, t, server) if refine else ""
    if said:
        return said
    if not rest:
        return prev_subject                     # "redo it", "try again"
    if len(rest.split()) >= 4:
        return rest                             # a subject of its own
    # a short modifier reads best folded into the subject itself:
    # "a piano" + "white" -> "a white piano"
    ps = prev_subject.split()
    if len(ps) >= 2 and len(rest.split()) <= 2:
        return " ".join(ps[:-1] + rest.split() + ps[-1:])
    return prev_subject + ", " + rest


_REFINE_PROMPT = (
    "You rewrite image prompts. The last picture was made from this "
    "prompt:\n  %s\nThe person now says:\n  %s\n\nWrite the FULL new "
    "image prompt: the original subject with their change applied. Keep "
    "everything they did not ask to change. Reply with ONLY the prompt, "
    "one line, under 30 words, no quotes, no preamble, no explanation.")


def _refine_with_model(prev_subject: str, said: str, server: bool = True) -> str:
    """Let a model fold the change into the prompt. Only a model that is
    ALREADY resident is used — a cold multi-GB load to rewrite eight
    words would cost more than the picture (make_title, 6b247, uses the
    same rule). Returns "" when there is nothing suitable or the answer
    does not look like a prompt."""
    try:
        # the person's server first (6b357), then a model already resident here
        out = (server_side_text([{"role": "user", "content": _REFINE_PROMPT % (prev_subject, said)}])
               if server else None)
        if out is None:
            pulled = ollama_pulled_tags() or set()
            live = [l for l in MODEL_ROUTES
                    if MODEL_ROUTES[l][0] == "mlx" and model_cached(l, pulled)
                    and _engine_up(MODEL_ROUTES[l][1])]
            if not live:
                return ""
            parts = []
            run_model(live[0], [{"role": "user",
                                 "content": _REFINE_PROMPT % (prev_subject,
                                                              said)}],
                      parts.append)
            out = "".join(parts)
        out = " ".join(strip_think(strip_special(out)).split())
        out = out.split("\n")[0].strip().strip('"\u201c\u201d\'*`')
        out = re.sub(r"^(?:prompt|new prompt|here(?:'s| is)[^:]*)\s*:\s*",
                     "", out, flags=re.I).strip()
        if not (3 <= len(out.split()) <= 40) or _looks_degenerate(out):
            return ""
        if re.search(r"\b(?:i can(?:not|'t)|as an ai|sorry)\b", out, re.I):
            return ""
        return out
    except Exception:
        return ""


