def _media_id() -> str:
    """A new image or video's name (6b321): 128 random bits. It was
    <unix time>-<6 hex>, 24 bits a second, which a script holding the
    launch cookie could walk. Old names are still served: the API token
    guards them now."""
    return secrets.token_hex(16)


def _write_image_bytes(ctx, data: bytes) -> str:
    """Save what a cloud painter returned under its TRUE type — Gemini
    sends PNG today, and a JPEG or WebP must not be called .png (a coin
    toss in WebKit) — so the route can serve an honest Content-Type. In
    the profile that asked (1a 5.3): after a switch, nothing lands."""
    ext = (".jpg" if data[:2] == b"\xff\xd8"
           else ".webp" if data[:4] == b"RIFF" and data[8:12] == b"WEBP"
           else ".png")
    name = IMAGE_SUB + "/" + _media_id() + ext
    _hook_delay("image-write")
    ctx.write_bytes(name, data)
    return ctx.path(name)


def _media_land(ctx, sub: str, path: str) -> str:
    """A finished render made in run/ (stage_path), and the .render.json
    beside it, moved into ctx's pictures or videos under a new name. After
    a switch neither lands and both are deleted (1a 5.3). The path."""
    note = os.path.splitext(path)[0] + ".render.json"
    iid = _media_id()
    try:
        final = ctx.adopt(path, sub + "/" + iid + os.path.splitext(path)[1])
        if os.path.exists(note):
            try:
                ctx.adopt(note, sub + "/" + iid + ".render.json")
            except OSError:
                pass
        return final
    finally:
        drop_run_file(note)


# ONE RENDER AT A TIME, AND A RENDER THAT CAN BE STOPPED (6b304). Both
# engines ran under subprocess.run from the chat thread: nothing could
# stop them, and the server is threaded, so Stop followed by a re-ask ran
# TWO diffusion jobs side by side in unified memory — one of them
# rendering for a reader who had already left.
_render_lock = threading.Lock()


class RenderBusy(RuntimeError):
    """Another local render is running. Not a reason to spend the user's
    cloud quota on a fallback — the caller says so instead."""


def _client_gone(sock) -> bool:
    """True once the reader has hung up. A closed TCP peer reads as
    ready-with-zero-bytes; a peek never consumes anything."""
    if sock is None:
        return False
    try:
        r, _, _ = select.select([sock], [], [], 0)
        if not r:
            return False
        return sock.recv(1, socket.MSG_PEEK) == b""
    except (OSError, ValueError):
        return True


# THE PROMPT FILE (0a 5.1, 6b326). mflux and the video renderer took the
# prompt, and the video one the negative prompt, as arguments, which
# `ps` shows to every login. They now run under this fixed runner: it
# reads a 0600 JSON file under run/, puts each "@prompt:<name>" argument's
# words back in place inside the process, and runs the tool (the console
# script, or `python -m <module>`) as it would have run. The runner
# deletes the file as soon as it has read it, the app again when the
# render ends, however it ends, and a crash's leftover at the next start.
_PROMPT_RUNNER = (
    # '' (the working directory, which -c puts first) goes before the
    # runner imports anything, so no file there can stand in for json,
    # os or runpy; the tool then gets the path it would have had: its
    # own folder for a script, the working directory for -m
    "import sys\n"
    "if sys.path and sys.path[0] in ('', '.'):\n"
    "    del sys.path[0]\n"
    "import json, os, runpy\n"
    "f, kind, tool = sys.argv[1:4]\n"
    "with open(f, encoding='utf-8') as h:\n"
    "    d = json.load(h)\n"
    "try:\n"
    "    os.remove(f)\n"
    "except OSError:\n"
    "    pass\n"
    "sys.argv = [tool] + [d.get(a[8:], '') if a.startswith('@prompt:')"
    " else a for a in sys.argv[4:]]\n"
    "if kind == 'module':\n"
    "    sys.path.insert(0, os.getcwd())\n"
    "    runpy.run_module(tool, run_name='__main__', alter_sys=True)\n"
    "else:\n"
    "    sys.path.insert(0, os.path.dirname(os.path.abspath(tool)))\n"
    "    runpy.run_path(tool, run_name='__main__')\n")


def prompt_cmd(python: str, kind: str, tool: str, args: list,
               words: dict) -> tuple:
    """(argv, prompt file): `tool` ("script": a console script's path,
    "module": a module name) run by `python` with `args`, whose
    "@prompt:<name>" entries take words[name] from the file. The caller
    deletes the file (drop_run_file) when the render ends."""
    path = run_file("prompt-", json.dumps(words), ".json")
    return [python, "-c", _PROMPT_RUNNER, path, kind, tool] + list(args), path


def _run_render(cmd: list, timeout: float, sock=None) -> tuple:
    """Run a render in its own process group, polling once a second.
    Stops it cleanly when the reader leaves or the clock runs out.
    Output goes to a temp file, not a pipe: Popen with PIPE and a loop of
    polls deadlocks the moment the child fills the pipe buffer.
    Returns (returncode, output_tail, cancelled)."""
    log = tempfile.TemporaryFile(mode="w+")
    proc = subprocess.Popen(cmd, stdout=log, stderr=subprocess.STDOUT,
                            start_new_session=True)
    end = time.time() + timeout
    cancelled = False
    try:
        while proc.poll() is None:
            if _client_gone(sock) or time.time() > end:
                cancelled = True
                try:
                    os.killpg(proc.pid, signal.SIGTERM)
                except OSError:
                    pass
                try:
                    proc.wait(5)
                except subprocess.TimeoutExpired:
                    try:
                        os.killpg(proc.pid, signal.SIGKILL)
                    except OSError:
                        pass
                    proc.wait()
                break
            time.sleep(1.0)
        log.seek(0)
        tail = log.read()[-400:]
    finally:
        log.close()
    return proc.returncode, tail, cancelled


def _render_note(path: str, opts: dict, secs: float = 0.0):
    """What this file was actually rendered with, beside the file. The
    transcript keeps the filename, so "double the resolution" can resolve
    against the real numbers days later — an in-memory dict would forget
    overnight. The serve routes reject .render.json, so it is invisible."""
    try:
        d = dict(opts or {})
        d["secs"] = round(secs, 1)
        with open(os.path.splitext(path)[0] + ".render.json", "w") as f:
            json.dump(d, f)
    except OSError:
        pass


def render_note(key: str, fname: str) -> dict:
    """The settings a previous render used, or {}."""
    try:
        base = bound_ctx().path(IMAGE_SUB if key == "image" else VIDEO_SUB)
        with open(os.path.join(base,
                               os.path.splitext(fname)[0] + ".render.json")) as f:
            d = json.load(f)
        return d if isinstance(d, dict) else {}
    except Exception:
        return {}


def _ffmpeg_convert(src: str, fmt: str, fps: int) -> str:
    """mp4 -> gif / webm, or a plain rate change. ffmpeg only; when it is
    missing or fails the original file stands, because a clip in the
    wrong container beats no clip."""
    if fmt == "mp4" and not fps:
        return src
    out = os.path.splitext(src)[0] + "." + fmt
    try:
        if fmt == "gif":
            pal = os.path.splitext(src)[0] + ".png"
            subprocess.run(["ffmpeg", "-loglevel", "error", "-y", "-i", src,
                            "-vf", "fps=%d,palettegen" % (fps or 24), pal],
                           capture_output=True, timeout=180)
            subprocess.run(["ffmpeg", "-loglevel", "error", "-y", "-i", src,
                            "-i", pal, "-lavfi",
                            "fps=%d [x]; [x][1:v] paletteuse" % (fps or 24),
                            out], capture_output=True, timeout=300)
            try:
                os.remove(pal)
            except OSError:
                pass
        elif fmt == "webm":
            subprocess.run(["ffmpeg", "-loglevel", "error", "-y", "-i", src,
                            "-c:v", "libvpx-vp9", "-crf", "32", "-b:v", "0"]
                           + (["-r", str(fps)] if fps else []) + [out],
                           capture_output=True, timeout=600)
        else:
            # 6b304: out == src here (mp4 -> mp4), and ffmpeg cannot write
            # over its own input — the setting silently did nothing. Write
            # beside it and swap. And "-r" alone keeps the duration and
            # just drops or duplicates frames; a PLAYBACK RATE re-times
            # the clip, so the same frames play faster or slower.
            native = engine_cfg("video").get("fps") or 24
            out = os.path.splitext(src)[0] + ".rt.mp4"
            subprocess.run(["ffmpeg", "-loglevel", "error", "-y", "-i", src,
                            "-vf", "setpts=PTS*%s" % (float(native) / fps),
                            "-r", str(fps), "-an", out],
                           capture_output=True, timeout=300)
            if os.path.exists(out) and os.path.getsize(out) > 2000:
                final = os.path.splitext(src)[0] + ".mp4"
                os.replace(out, final)
                return final
            return src
        if os.path.exists(out) and os.path.getsize(out) > 2000:
            if out != src:
                try:
                    os.rename(os.path.splitext(src)[0] + ".render.json",
                              os.path.splitext(out)[0] + ".render.json")
                except OSError:
                    pass
                try:
                    os.remove(src)
                except OSError:
                    pass
            return out
    except Exception:
        pass
    return src


def generate_image(ctx, prompt: str, over: dict = None, sock=None) -> tuple:
    """(png path, source) — local FLUX first, a Gemini key second.
    Raises when neither could paint. A saved Gemini key is permission to
    paint with it, whatever Use cloud power says (Patrick, 6b326). The
    picture is made in run/ and lands in ctx's pictures (1a 5.3)."""
    errs = []
    # a benchmark owns this computer's memory (review of 6b334): the local
    # painter sits it out whoever asked (/api/chat holds the benchmark off
    # while it paints); a saved Gemini key still may
    _mine = image_ready()
    if _mine and _bench["running"]:
        _mine = False
        errs.append("local: " + BENCH_BUSY)
    if _mine:
        # mflux 0.19: a local/third-party model is --model <dir> with
        # --base-model naming the architecture (the old --path is gone)
        _t = studio_tier("image")
        o = studio_opts("image", over)
        out = stage_path("." + o["fmt"])
        # the prompt reaches mflux through a 0600 file (6b326), never
        # its command line
        _base = _t.get("base", "schnell")
        args = ["--model", _snap_dir(_t["repo"]),
                "--base-model", _base,
                "--prompt", "@prompt:prompt", "--steps", str(o["steps"]),
                # a distilled FLUX.2 takes 1.0 and nothing else (6b445)
                "--guidance", ("1.0" if _base.startswith("flux2") and _img_distilled(_base)
                               else str(o["guidance"])),
                "--seed", str(o["seed"] or secrets.randbelow(10 ** 6)),
                "--width", str(o["w"]), "--height", str(o["h"]),
                "--output", out]
        if not _render_lock.acquire(timeout=5):
            raise RenderBusy("already making one; ask again when it lands")
        pf = None
        try:
            _vb = os.path.join(STUDIOS["image"]["venv"], "bin")
            cmd, pf = prompt_cmd(os.path.join(_vb, "python3"), "script",
                                 os.path.join(_vb, _t.get("cmd") or (
                                     "mflux-generate-flux2" if _base.startswith("flux2")
                                     else "mflux-generate")), args,
                                 {"prompt": prompt})
            _t0 = time.time()
            rc, tail, cut = _run_render(cmd, 900, sock)
            if cut:
                raise RenderBusy("stopped")
            if rc == 0 and os.path.exists(out):
                _render_note(out, o, time.time() - _t0)
                return _media_land(ctx, IMAGE_SUB, out), "local"
            errs.append("local: " + tail[-200:].strip())
        except (RenderBusy, NotLanded):
            raise
        except StaleProfile:
            raise
        except Exception as exc:
            errs.append("local: %s" % exc)
        finally:
            drop_run_file(pf)
            _render_lock.release()
    gem = (_cloud_all().get("providers") or {}).get("gemini") or {}
    if gem.get("key") and gem.get("status", "ok") == "ok":
        # newest first, as Google lists them today (6b294, probed live)
        # gemini-2.5-flash-image shuts down 2026-10-02 (6b307)
        for mdl in ("gemini-3.1-flash-lite-image", "gemini-3.1-flash-image"):
            try:
                # the key rides in a header (6b308): in the URL it could
                # surface in an error message
                req = urllib.request.Request(
                    GEMINI_API + "models/%s:generateContent" % mdl,
                    data=json.dumps({
                        "contents": [{"parts": [{"text": prompt}]}],
                        "generationConfig": {"responseModalities": ["IMAGE"]}
                    }).encode(),
                    headers={"Content-Type": "application/json",
                             "x-goog-api-key": gem["key"],
                             "User-Agent": "MillenAI/%s" % APP_VERSION})
                with urllib.request.urlopen(req, timeout=120) as r:
                    d = json.loads(r.read().decode("utf-8", "replace"))
                for part in ((d.get("candidates") or [{}])[0]
                             .get("content") or {}).get("parts") or []:
                    inl = part.get("inlineData") or part.get("inline_data") or {}
                    if inl.get("data"):
                        return _write_image_bytes(
                            ctx, base64.b64decode(inl["data"])), "gemini"
                errs.append("gemini: no image in the reply")
            except StaleProfile:
                raise
            except Exception as exc:
                errs.append("gemini: %s" % str(exc)[:120])
    # no keyless fallback (6b310): Pollinations got the description with
    # no opt-in, in a URL, onto a public feed
    raise RuntimeError("; ".join(errs) or "No image engine")


# ==== photoedit: begin ====
# EDIT THIS PICTURE (6b472, per Patrick: "Build photo editing" after a photo
# of himself and "different hairstyles" got a refusal in words). A message
# with a photo attached that asks to CHANGE it runs FLUX.2 klein's edit
# command (mflux-generate-flux2-edit, mflux 0.19) on this Mac with the photo
# as the reference. LOCAL ONLY: the photo never goes to a cloud painter or a
# server, and a failed edit is never retried anywhere else. The segment holds
# no cloud or server call on purpose; the gauntlet checks that.
PE_NOTE = "Edited on this computer. Your photo wasn’t sent anywhere."
PE_TIER = "quick"                     # the klein rung: the only edit weights
PE_BASE = "flux2-klein-4b"
PE_TOOL = "mflux-generate-flux2-edit"
PE_ETA_DEFAULT = 45.0                 # measured 32 s warm at 768 px, plus a cold load
_PE_QUESTION = re.compile(
    r"^\s*(?:what|which|who|whom|whose|why|how|where|when|is|are|was|were|"
    r"does|do|did|tell\s+me|describe|explain|identify|read|translate|"
    r"summari[sz]e|list|count|recommend|suggest)\b", re.I)
_PE_WOULD = re.compile(
    r"\b(?:what|how)\s+(?:would|will|might|could)\s+(?:i|he|she|they|we|it|this|"
    r"my\s+\w+)\s+look\s*(?:like\s+)?(?:with|in|as|if|wearing|having)\b", re.I)
_PE_PARTS = (r"hair(?:style|cut|line)?s?|background|backdrop|shirt|t-?shirt|outfit|"
             r"clothes|clothing|jacket|suit|dress|hat|glasses|eyes?|eye\s+colou?r|"
             r"skin|beard|mustache|moustache|sky|lighting|expression|face|"
             r"colou?rs?|picture|photo|image|pic")
_PE_RX = (
    # change / swap / retouch a named part
    re.compile(r"\b(?:change|swap|replace|recolou?r|restyle|retouch|edit|alter|"
               r"modify|touch\s+up)\b\s+(?:out\s+)?(?:the|this|that|my|his|her|"
               r"their|its|a|an)?\s*(?:\w+\s+)?(?:" + _PE_PARTS + r")\b", re.I),
    # remove / erase a thing or a person
    re.compile(r"\b(?:remove|erase|delete|get\s+rid\s+of|take\s+(?:out|away)|"
               r"cut\s+out)\b\s+(?:the\s+|this\s+|that\s+|my\s+|his\s+|her\s+|"
               r"their\s+|all\s+(?:the\s+)?|any\s+|everyone\s+|everything\s+)?"
               r"(?:\w+\s+){0,2}(?:person|people|man|men|woman|women|guy|girl|"
               r"kid|child|children|background|backdrop|object|car|sign|logo|"
               r"watermark|text|tree|building|dog|cat|glasses|sunglasses|hat|"
               r"beard|mustache|moustache|wrinkles|blemish\w*|pimples?|acne|"
               r"tattoos?|stains?|shadows?|reflection|crowd|strangers?|"
               r"photobomber|him|her|them|everyone|background\s+people)\b", re.I),
    # add / give / put a thing on the subject
    re.compile(r"\b(?:add|put|give|paste|place)\b\s+(?:me|him|her|them|us|"
               r"my\s+\w+|the\s+\w+)?\s*(?:an?\s+|some\s+|the\s+)?(?:\w+\s+){0,2}"
               r"(?:hair(?:style|cut)?|buzz\s*cut|crew\s*cut|undercut|pixie|"
               r"beard|mustache|moustache|sunglasses|glasses|hat|cap|tattoos?|earrings?|necklace|scarf|tie|mask|"
               r"crown|wings|horns|bangs|fringe|mohawk|afro|ponytail|braids?|"
               r"dreadlocks|wig|makeup|lipstick|snow|rain|rainbow|sunset|"
               r"bokeh|filter|border|halo)\b", re.I),
    re.compile(r"\bput\s+(?:me|him|her|us|them)\s+(?:in|on|at|into|onto|"
               r"next\s+to|inside)\b", re.I),
    # show me with / in / as ...
    re.compile(r"\b(?:show|let\s+me\s+see|i\s+(?:want|d\s+like|would\s+like)"
               r"\s+to\s+see)\s+(?:me|him|her|us|them)\s+(?:again\s+|also\s+|"
               r"now\s+)?(?:with|in|as|wearing|having|if)\b", re.I),
    # try / give a few styles
    re.compile(r"\btry\b\s+(?:on\s+|out\s+)?(?:an?\s+|some\s+|the\s+|different\s+|"
               r"other\s+|a\s+few\s+|several\s+|various\s+)?(?:\w+\s+){0,2}"
               r"(?:hair\w*|bang\w*|beard|mustache|moustache|glasses|sunglasses|"
               r"hat|buzz\s*cut|mohawk|afro|bald|wig|colou?rs?)\b", re.I),
    re.compile(r"\b(?:show|give|try|see|make|do|generate|create|gimme)\b.{0,40}?"
               r"\b(?:different|other|new|various|several|a\s+few|some)\s+"
               r"(?:hair\s*(?:style|cut|colou?r)s?|haircuts?|hairstyles?|looks|"
               r"outfits|beards|glasses|hats)\b", re.I),
    # whole-picture verbs
    re.compile(r"\b(?:redraw|repaint|reimagine|re-?imagine|cartoonif\w+|"
               r"colori[sz]e|photoshop|airbrush|de-?age)\b", re.I),
)
# make / turn / transform it into something LOOKING different: the rest of
# the sentence must name a look, so "turn this into a table" stays a read
_PE_MAKE = re.compile(
    r"\b(?P<v>make|turn|transform|convert|render|redo)\b\s+(?:me|him|her|them|us|it|"
    r"this|that|these|the\s+\w+(?:\s+\w+)?|my\s+\w+(?:\s+\w+)?)\b"
    r"(?!\s+(?:an?|some)\b)(?P<rest>.*)$", re.I | re.S)
_PE_LOOK = re.compile(
    r"\b(?:look|looks|appear|older|younger|bald|blond|blonde|brunette|redhead|"
    r"ginger|grey|gray|black|white|blue|green|red|pink|purple|orange|yellow|"
    r"brown|silver|gold|smil\w*|taller|thinner|slimmer|muscular|cartoon|anime|"
    r"pixar|disney|lego|clay|painting|painted|watercolou?r|oil|sketch|drawing|"
    r"pencil|comic|manga|pop\s*art|cyberpunk|vintage|retro|noir|sepia|"
    r"polaroid|sunny|sunset|night|dark|darker|bright|brighter|colou?rful|snow|"
    r"winter|summer|stylis\w+|hair\w*|curly|straight|wavy|short|long|buzz|"
    r"mohawk|beard|shaved?|clean-shaven|3d|sticker|statue|marble|sharper|"
    r"clearer|background|sky)\b", re.I)


def photo_edit_intent(text: str):
    """The request to run on the attached photo when the message asks to
    CHANGE it ("show me with different hairstyles", "make my hair blonde",
    "remove the person on the left"), else None. Conservative: questions
    about a photo ("what hairstyle suits me") and plain reads of it never
    match. Only called when a photo is attached to this message."""
    t = (text or "").strip()
    if not t or len(t) > 400:
        return None
    t = _img_strip_pre(t) or t
    if _PE_QUESTION.match(t) and not _PE_WOULD.search(t):
        return None
    if _PE_WOULD.search(t) or any(r.search(t) for r in _PE_RX):
        return t.strip()
    m = _PE_MAKE.search(t)
    if m and _PE_LOOK.search(m.group(0)[len(m.group("v")):]):
        return t.strip()
    return None


# shrink the photo to what the engine holds (long side 1024, sides a
# multiple of 16, EXIF turn applied) with the engine's own Pillow
_PE_PREP = (
    "import sys\n"
    "from PIL import Image, ImageOps\n"
    "im = ImageOps.exif_transpose(Image.open(sys.argv[1])).convert('RGB')\n"
    "w, h = im.size\n"
    "s = min(1.0, 1024.0 / max(w, h))\n"
    "w, h = max(256, int(w * s) // 16 * 16), max(256, int(h * s) // 16 * 16)\n"
    "im.resize((w, h), Image.LANCZOS).save(sys.argv[2])\n"
    "print('SIZE %d %d' % (w, h))\n")
# the dev-only stand-in for the engine (hook photoedit-stub, gauntlet): copies
# the reference to the output, or fails on photoedit-stub=fail
_PE_STUB = (
    "import shutil, sys\n"
    "if sys.argv[3] == 'fail':\n"
    "    sys.stderr.write('stub engine failed'); sys.exit(1)\n"
    "shutil.copyfile(sys.argv[1], sys.argv[2])\n")


def _pe_stage_photo(raw: bytes) -> str:
    """The attached photo's bytes in a new 0600 stage file under run/ (the
    engine's reference); its path. A machine path, never a profile's: the
    caller drops it when the edit ends (6b511, the gauntlet's write lint)."""
    src = stage_path(".src")
    try:
        fd = os.open(src, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600)
        with os.fdopen(fd, "wb") as f:
            f.write(raw)
    except BaseException:
        drop_run_file(src)
        raise
    return src


class PhotoEditUnavailable(RuntimeError):
    """The edit can't run here; the message says why, in a sentence."""


def photo_edit_unavailable():
    """'' when this Mac can edit a photo now, else the sentence that says
    why not (nothing was sent anywhere)."""
    if not studio_supported():
        return ("Photo editing needs an Apple silicon Mac. Nothing was edited or sent.")
    t = studio_tier("image", PE_TIER)
    tool = os.path.join(STUDIOS["image"]["venv"], "bin", PE_TOOL)
    if not _studio_engine_ok("image") or not os.path.exists(tool):
        return ("Photo editing needs image generation. Add it in Settings > Models. Your photo wasn’t sent anywhere.")
    if not _studio_model_ok("image", PE_TIER) or not _snap_dir(t["repo"]):
        return ("Photo editing needs the Quick picture model (%s GB). Add it in Settings > Models. Your photo wasn’t sent anywhere." % t.get("gb", 4.6))
    return ""


def photo_edit_eta(ctx) -> dict:
    """The time-left plan for an edit (X-Eta): the median of the edits this
    profile has timed (their .render.json), else the measured default,
    flagged as an estimate."""
    secs = []
    try:
        fs = sorted(glob.glob(os.path.join(ctx.path(IMAGE_SUB), "*.render.json")),
                    key=os.path.getmtime)[-30:]
        for f in fs:
            with open(f) as h:
                d = json.load(h)
            if d.get("edit") and float(d.get("secs") or 0) > 0:
                secs.append(float(d["secs"]))
    except Exception:
        secs = []
    if secs:
        secs.sort()
        return {"search": 0.0, "models": [], "final": round(secs[len(secs) // 2], 1),
                "ftok": 0, "est": False}
    return {"search": 0.0, "models": [], "final": PE_ETA_DEFAULT, "ftok": 0,
            "est": True}


def edit_photo(ctx, b64: str, request: str, sock=None, step=None) -> str:
    """The edited picture's path, in ctx's pictures. Local FLUX.2 klein
    only; raises PhotoEditUnavailable (say why), RenderBusy, or a plain
    error from the engine. Never asks a cloud painter or a server."""
    stub = _hook_arg("photoedit-stub") or (
        "ok" if "photoedit-stub" in TEST_HOOKS else "")
    if not stub:
        why = photo_edit_unavailable()
        if why:
            raise PhotoEditUnavailable(why)
    try:
        raw = base64.b64decode(b64, validate=False)
        if len(raw) < 16:
            raise ValueError("empty")
    except Exception:
        raise PhotoEditUnavailable("Couldn’t read that photo. Nothing was edited.")
    if stub and raw.startswith(b"FAIL-STUB"):
        stub = "fail"                  # the gauntlet's failing engine
    if not _render_lock.acquire(timeout=5):
        raise RenderBusy("already making one; ask again when it lands")
    src = prepped = pf = None
    out = stage_path(".png")
    landed = False
    try:
        src = _pe_stage_photo(raw)
        _vb = os.path.join(STUDIOS["image"]["venv"], "bin")
        t0 = time.time()
        w = h = 0
        if stub:
            cmd = [sys.executable, "-c", _PE_STUB, src, out, stub]
        else:
            prepped = stage_path(".png")
            rc, tail, cut = _run_render(
                [os.path.join(_vb, "python3"), "-I", "-c", _PE_PREP, src, prepped],
                120, sock)
            if cut:
                raise RenderBusy("stopped")
            m = re.search(r"SIZE (\d+) (\d+)", tail)
            if rc != 0 or not m or not os.path.exists(prepped):
                raise PhotoEditUnavailable(
                    "I couldn’t open that photo, so nothing was edited.")
            w, h = int(m.group(1)), int(m.group(2))
            t = studio_tier("image", PE_TIER)
            # the request, then what must not move: a hairstyle ask leaves
            # the face, the clothes and the background alone
            ask = (request.strip().rstrip(".") + ". Keep everything else the "
                   "same: the same person, face, pose, clothes and background.")
            args = ["--model", _snap_dir(t["repo"]), "--base-model", PE_BASE,
                    "--image-paths", prepped, "--prompt", "@prompt:prompt",
                    "--steps", "4", "--guidance", "1.0",
                    "--seed", str(secrets.randbelow(10 ** 6)),
                    "--width", str(w), "--height", str(h),
                    "--no-metadata", "--output", out]
            cmd, pf = prompt_cmd(os.path.join(_vb, "python3"), "script",
                                 os.path.join(_vb, PE_TOOL), args,
                                 {"prompt": ask})
        rc, tail, cut = _run_render(cmd, 900, sock)
        if cut:
            raise RenderBusy("stopped")
        if rc != 0 or not os.path.exists(out):
            raise RuntimeError(tail[-200:].strip() or "The engine stopped.")
        _render_note(out, {"w": w, "h": h, "steps": 4, "guidance": 1.0,
                           "fmt": "png", "seed": 0, "neg": "", "edit": True},
                     time.time() - t0)
        final = _media_land(ctx, IMAGE_SUB, out)
        landed = True
        return final
    finally:
        for p in (src, prepped, pf):
            drop_run_file(p)
        if not landed:
            drop_run_file(out)
            drop_run_file(os.path.splitext(out)[0] + ".render.json")
        _render_lock.release()
# ==== photoedit: end ====


# ---------------------------------------------------------------- export
# FILES OUT (6b295, per Patrick: "add export for all the following formats
# … performed intelligently, so that if the user asks 'can I export a
# mermaid file of this', then it knows exactly which engine to go to").
#
# THE SHAPE. One registry keyed by extension; one router that decides
# format and where the bytes come from; one writer per KIND, not per
# format. Light formats (text, data, calendar, cards, archives) are pure
# stdlib and work the moment you ask. The four heavy document formats
# need wheels, fetched once on demand — so the app ships small and export
# still works out of the box for most of what people ask for.
#
# EVERY export is served as application/octet-stream with an attachment
# disposition and nosniff, never the format's real MIME. Model-authored
# HTML served as text/html from the app's own origin would be stored XSS
# against the app itself; octet-stream closes that and costs nothing.

EXPORT_KEEP_N = 60               # per identity, newest kept
EXPORT_TTL_H = 72                # and nothing older than this
EXPORT_MAX_BYTES = 25_000_000
EXPORT_DEPS = ("reportlab", "openpyxl", "python-docx", "python-pptx")

# ext -> (kind, human name). KIND picks the writer; there is no per-format
# branching anywhere else. "text" means the model's own text is the file.
EXPORT_KIND = {
    "pdf": ("doc", "PDF"), "docx": ("doc", "Word document"),
    "pptx": ("slides", "PowerPoint deck"),
    "xlsx": ("table", "Excel workbook"), "csv": ("table", "CSV"),
    "ics": ("calendar", "calendar file"), "anki": ("cards", "Anki deck"),
    "zip": ("archive", "archive"),
    "md": ("text", "Markdown"), "txt": ("text", "text file"),
    "json": ("text", "JSON"), "yaml": ("text", "YAML"),
    "toml": ("text", "TOML"), "env": ("text", ".env file"),
    "html": ("text", "HTML page"), "svg": ("text", "SVG"),
    "mmd": ("text", "Mermaid diagram"), "xml": ("text", "XML"),
    "py": ("text", "Python script"), "js": ("text", "JavaScript"),
    "jsx": ("text", "JSX component"), "ts": ("text", "TypeScript"),
    "tsx": ("text", "TSX component"), "sh": ("text", "shell script"),
    "sql": ("text", "SQL"), "tf": ("text", "Terraform config"),
    "rb": ("text", "Ruby script"), "go": ("text", "Go source"),
    "rs": ("text", "Rust source"), "css": ("text", "stylesheet"),
}
# the heavy four; everything else is stdlib
EXPORT_NEEDS_DEPS = {"pdf", "docx", "pptx", "xlsx"}

# what the user might call each one. Longest match wins, so "xlsx" beats
# "excel" beats "sheet" — order matters inside each list only for display.
EXPORT_WORDS = {
    "pdf": ["pdf"],
    "docx": ["docx", "word doc", "word document", "word file", "word"],
    "pptx": ["pptx", "powerpoint", "power point", "keynote", "slide deck",
             "slides", "deck", "presentation"],
    "xlsx": ["xlsx", "excel", "spreadsheet", "workbook", "google sheet",
             "sheets", "sheet"],
    "csv": ["csv", "comma separated", "comma-separated"],
    "ics": ["ics", "ical", "icalendar", "calendar file", "calendar invite",
            "calendar event"],
    "anki": ["anki", "flashcard", "flash card", "flashcards", "flash cards"],
    "zip": ["zip", "zip file", "archive", "bundle"],
    "md": ["md", "markdown", "readme"],
    "txt": ["txt", "text file", "plain text", "plaintext"],
    "json": ["json"], "yaml": ["yaml", "yml"], "toml": ["toml"],
    "env": ["dotenv", ".env", "env file"],
    "html": ["html", "web page", "webpage", "landing page"],
    "svg": ["svg", "vector"], "png": ["png"],
    "mmd": ["mermaid", "mmd"],
    "xml": ["xml"],
    "py": ["python script", "python file", "py file", ".py"],
    "js": ["javascript file", "js file", ".js"],
    "jsx": ["jsx", ".jsx"], "ts": ["typescript file", ".ts"],
    "tsx": ["tsx", ".tsx"],
    "sh": ["shell script", "bash script", "sh file", ".sh"],
    "sql": ["sql", "sql file", "migration"],
    "tf": ["terraform", ".tf"],
    "rb": ["ruby script", ".rb"], "go": ["go file", ".go"],
    "rs": ["rust file", ".rs"], "css": ["css file", "stylesheet"],
}
# png is drawn, not written — it rides the image path but is named here so
# "export that chart as a png" routes rather than falling to the painter
EXPORT_KIND["png"] = ("image", "PNG image")

_EXPORT_ALIASES = sorted(
    ((w, ext) for ext, ws in EXPORT_WORDS.items() for w in ws),
    key=lambda p: -len(p[0]))


def _export_deps_ok() -> bool:
    try:
        import reportlab, openpyxl, docx, pptx      # noqa: F401
        return True
    except Exception:
        return False


_export_install = {"state": "idle", "note": ""}


def _install_export_deps_worker():
    if getattr(sys, "frozen", False):
        # an installed (frozen) app can't pip-install into itself; its
        # build carries these libraries (6b317)
        _export_install.update(state="error",
                               note="not included in this build")
        return
    try:
        _export_install.update(state="installing", note="")
        pip = os.path.join(app_dir(), "venv", "bin", "pip")
        if not os.path.exists(pip):
            pip = os.path.join(os.path.dirname(sys.executable), "pip")
        r = subprocess.run([pip, "install", "--quiet", "--only-binary=:all:"]
                           + list(EXPORT_DEPS),
                           capture_output=True, text=True, timeout=900,
                           # no console window flashing up on Windows
                           creationflags=getattr(subprocess,
                                                 "CREATE_NO_WINDOW", 0))
        if r.returncode != 0:
            raise RuntimeError((r.stderr or "")[-200:])
        _export_install.update(state="ready" if _export_deps_ok() else "error",
                               note="")
    except Exception as exc:
        _export_install.update(state="error", note=str(exc)[:200])


def ensure_export_deps(block_s: float = 0.0) -> bool:
    """True when the document engines are importable. Kicks off a one-time
    background install otherwise; never blocks the answer path by default."""
    if _export_deps_ok():
        return True
    if _export_install["state"] not in ("installing",):
        ctx_thread(target=_install_export_deps_worker,
                         daemon=True).start()
    if block_s > 0:
        end = time.time() + block_s
        while time.time() < end and _export_install["state"] == "installing":
            time.sleep(0.5)
            if _export_deps_ok():
                return True
    return _export_deps_ok()


# ---------------------------------------------------------- the router
# Anchored on the FORMAT WORD, not on a leading verb. An export ask puts
# its discriminating token near the end ("…as a PDF", "…to run.py"), so
# image_intent()'s ^verb shape would miss most of them. Score the frame
# around the format word; 3 fires, less does not.
_XF_AS = re.compile(                                     # "... as a PDF"
    r"\b(?:as|into)\s+(?:an?\s+|the\s+)?(?:\w+\s+){0,2}$", re.I)
# "make me a CSV", "get a PDF of ..." — produce-a-thing, article included
_XF_ARTICLE = re.compile(r"\b(?:an?|the)\s+$", re.I)
_XF_CONVERT = re.compile(
    r"\b(?:convert|turn|change|export|save|render|translate)\b", re.I)
_XF_TOFILE = re.compile(
    r"\b(?:to|in)\s+(?:an?\s+|the\s+)?$", re.I)            # weak on its own
_XF_NOUN = re.compile(
    r"^\s*(?:file|doc|document|version|copy|format|export|download)\b", re.I)
_XF_VERB = re.compile(
    r"\b(?:export|download|save|convert|turn|render|generate|produce|"
    r"write|give|make|send|attach|get)\b", re.I)
# a real filename, but ONLY with a naming cue in front of it — otherwise
# "the error in Main.java" and "we use Next.js" become exports
_XF_FILENAME = re.compile(
    r"\b(?:save|export|write|download|call(?:\s+it)?|name(?:\s+it)?)\b"
    r"[^.\n]{0,40}?\b(?:as|to|named|called)\s+[\"'`]?"
    r"(?P<fn>[\w][\w.-]{0,60}\.(?P<ext>[A-Za-z][A-Za-z0-9]{0,5}))", re.I)
# hard vetoes: the format word is the TOPIC, not the destination
_XV_ABSOLUTE = [
    re.compile(r"\b(?:what|which|whats|what's)\s+(?:is|are)\s+(?:an?\s+)?"
               r"(?:\w+\s+){0,2}(?:file|format)\b", re.I),
    re.compile(r"\b(?:how\s+do\s+i|how\s+can\s+i|how\s+to)\b.{0,40}"
               r"\b(?:open|read|import|convert|edit)\b", re.I),
    re.compile(r"\b(?:respond|reply|answer|format\s+your\s+(?:reply|answer))"
               r"\s+(?:in|with|using)\b", re.I),
    re.compile(r"\b(?:i|we)\s+(?:attached|uploaded|sent|pasted)\b", re.I),
    re.compile(r"\b(?:summari[sz]e|read|analy[sz]e|explain|review)\s+"
               r"(?:the|this|my|that)\s+(?:attached\s+)?\w{2,6}\b", re.I),
    # a capability question is never a request, however it scores
    re.compile(r"\b(?:do(?:es)?\s+(?:you|this|the|it)\s+"
               r"(?:app|support|handle|do)|are\s+you\s+able|"
               r"can\s+(?:you|this|it)\s+(?:even|actually)?\s*"
               r"(?:support|handle|do)\b)", re.I),
]
# conditional: an interrogative opener only vetoes when no strong frame
_XV_SOFT = [
    re.compile(r"^\s*(?:what|why|when|who|explain|describe|tell\s+me\s+about)"
               r"\b", re.I),
    re.compile(r"\b(?:are\s+you\s+able|can\s+you\s+(?:even|actually)|"
               r"do\s+you\s+support|does\s+(?:this|the)\s+app)\b", re.I),
]
# "write a python script that makes a PDF" — the format is the SCRIPT's
# output, not ours. Absolute, unless a cued filename names our own output
# ("...and save it as gen.py"), which is the only unambiguous signal there is.
_XV_PROGRAM = re.compile(
    r"\b(?:script|program|code|function|app|tool|cli|command)\s+"
    r"(?:that|which|to|for)\b", re.I)


def _export_shape(text: str) -> str:
    """What the previous answer looks like, when no format was named."""
    t = text or ""
    if re.search(r"^\|.*\|\s*$", t, re.M) and re.search(r"^\|[\s:|-]+\|\s*$",
                                                        t, re.M):
        return "table"
    if re.search(r"^```", t, re.M):
        return "code"
    if re.search(r"(?:-->|->|\bflowchart\b|\bgraph\s+(?:TD|LR)\b)", t):
        return "diagram"
    if re.search(r"^#{1,3}\s", t, re.M):
        return "doc"
    return "prose"


_SHAPE_FMT = {"table": "xlsx", "code": "txt", "diagram": "mmd",
              "doc": "pdf", "prose": "md"}


# ALIASES THAT ARE ALSO ORDINARY WORDS (6b304). "give me a word for
# tired", "a deck building strategy", "a sheet cake recipe", "a zip line
# plan", "a migration plan", "a presentation tip", "turn this into a word
# cloud" all scored 5 and produced a FILE. For these the article+verb
# frame alone is not enough: the word must be a DESTINATION — nothing
# after it, or a file noun ("word doc", "zip file") — and even after
# "as/into" it must not be the first half of a compound noun.
_X_AMBIG = {"word", "deck", "sheet", "sheets", "bundle", "archive", "zip",
            "migration", "presentation", "slides", "vector", "readme",
            "keynote", "sql", "terraform", "markdown"}
_X_AFTER_OK = {"for", "to", "about", "on", "with", "so", "please", "and",
               "then", "i", "we", "that", "which", "by", "in", "please."}


def export_intent(text: str, has_prior: bool = False):
    """None, or what to export and where the content comes from.

    {"ext", "lane", "filename", "score"} — lane "retro" converts the
    previous answer, lane "draft" asks the model to write it first.
    """
    t = (text or "").strip()
    if not t or len(t) > 600:
        return None
    low = t.lower()

    fn_m = _XF_FILENAME.search(t)
    fn_ext = (fn_m.group("ext") or "").lower() if fn_m else ""
    if fn_ext and fn_ext not in EXPORT_KIND:
        fn_ext, fn_m = "", None

    # find the last format word that is a whole-word match
    hit_ext, hit_at, hit_word = "", -1, ""
    for word, ext in _EXPORT_ALIASES:
        for m in re.finditer(r"(?<!\w)" + re.escape(word) + r"(?!\w)", low):
            if m.start() > hit_at:
                hit_ext, hit_at, hit_word = ext, m.start(), word
    if not hit_ext and not fn_ext:
        # no format named at all: only an explicit export verb about a
        # previous answer opens the shape path
        if has_prior and re.search(r"\b(?:export|download|save)\b", low) \
                and re.search(r"\b(?:this|that|it|the above|them)\b", low):
            return {"ext": "", "lane": "retro", "filename": "", "score": 3,
                    "shape": True}
        return None

    score = 0
    if hit_at >= 0 and hit_word in _X_AMBIG and not fn_ext:
        _b = t[:hit_at]
        _a = t[hit_at + len(hit_word):]
        _first = (re.findall(r"[A-Za-z']+", _a) or [""])[0].lower()
        _as = bool(_XF_AS.search(_b))
        if _XF_NOUN.search(_a):
            pass                          # "word doc", "zip file": a file
        elif _as:
            if _first and _first not in _X_AFTER_OK:
                return None               # "into a word cloud": a compound
        elif _first:
            return None                   # "a word for tired": just a word
    if hit_at >= 0:
        before = t[:hit_at]
        after = t[hit_at + len(hit_word):]
        win = before[-70:] if len(before) > 70 else before
        noun_after = _XF_NOUN.search(after)
        if _XF_AS.search(before):
            score = 3
        elif noun_after and _XF_TOFILE.search(before):
            score = 3
        elif _XF_TOFILE.search(before) and _XF_CONVERT.search(win):
            score = 3                     # "convert this to markdown"
        elif _XF_ARTICLE.search(before) and _XF_VERB.search(win):
            score = 3                     # "make me a CSV", "get a PDF of"
        elif noun_after:
            score = max(score, 2)
        # a verb NEAR the format word corroborates — but the word right
        # after it cannot count as both the noun and the verb ("pdf export")
        if _XF_VERB.search(win):
            score += 2
        elif not noun_after and _XF_VERB.search(after[:40]):
            score += 1
    if fn_ext:
        score += 3                       # a cued filename is near-decisive

    for rx in _XV_ABSOLUTE:
        if rx.search(t):
            return None
    if _XV_PROGRAM.search(t) and not fn_ext:
        return None
    if score < 3:
        for rx in _XV_SOFT:
            if rx.search(t):
                return None
    if score < 3:
        return None

    ext = fn_ext or hit_ext
    # LANE. "convert/export/save this" needs content that already exists;
    # "make me a PDF guide for tomorrow" needs it written first.
    retro_vb = re.search(r"\b(?:export|convert|save|turn|render|download|"
                         r"give\s+me\s+(?:this|that|it))\b", low)
    anaphor = re.search(r"\b(?:this|that|it|the above|them|these|those)\b", low)
    lane = "retro" if (has_prior and retro_vb and anaphor) else \
           ("retro" if (has_prior and anaphor and not
                        re.search(r"\b(?:make|create|generate|build|write|"
                                  r"draft|design)\b", low)) else "draft")
    return {"ext": ext, "lane": lane,
            "filename": (fn_m.group("fn") if fn_m else ""),
            "score": score, "shape": False}


# ------------------------------------------------------- reading the answer
# The fence grammar has to survive real model output: attributes in the
# info string (```python title="app.py"), tilde fences, and four or more
# backticks. Anchored to line start, closing fence matched by backreference.
_X_FENCE = re.compile(
    r"^(?P<f>`{3,}|~{3,})[ \t]*(?P<lang>[\w.+-]*)[^\n]*\n"
    r"(?P<code>.*?)^(?P=f)[ \t]*$", re.S | re.M)
# a line that is JUST a filename, sitting above a fence
_X_FNLINE = re.compile(
    r"^[\s#>*`_-]*([\w][\w./-]*\.[A-Za-z][A-Za-z0-9]{0,5})[`*_:]{0,3}\s*$")
# a pipe table, gated on a real divider row the way the client renderer is
_X_TABLE = re.compile(r"(?:^\|[^\n]*\|[ \t]*$\n?){2,}", re.M)
_X_DIVIDER = re.compile(r"^\|[\s:|-]+\|$")
_X_LANG_EXT = {
    "python": "py", "py": "py", "javascript": "js", "js": "js",
    "jsx": "jsx", "typescript": "ts", "ts": "ts", "tsx": "tsx",
    "bash": "sh", "sh": "sh", "shell": "sh", "zsh": "sh",
    "sql": "sql", "terraform": "tf", "hcl": "tf", "tf": "tf",
    "ruby": "rb", "rb": "rb", "go": "go", "rust": "rs", "rs": "rs",
    "json": "json", "yaml": "yaml", "yml": "yaml", "toml": "toml",
    "html": "html", "css": "css", "xml": "xml", "markdown": "md",
    "md": "md", "mermaid": "mmd", "svg": "svg", "csv": "csv",
    "dotenv": "env", "env": "env",
}
# unlabelled fences: sniff the first few lines. re.M throughout, because
# ^ without it only ever matches position zero.
_X_SNIFF = [
    ("sh", re.compile(r"^[ \t]*#!/", re.M)),
    ("py", re.compile(r"^[ \t]*(?:def |class |import |from \w+ import)", re.M)),
    ("mmd", re.compile(r"^[ \t]*(?:flowchart|graph\s+(?:TD|LR|RL|BT)|"
                       r"sequenceDiagram|classDiagram|gantt|erDiagram)", re.M)),
    ("sql", re.compile(r"^[ \t]*(?:SELECT|INSERT|UPDATE|CREATE|ALTER|WITH)\b",
                       re.I | re.M)),
    ("tf", re.compile(r"^[ \t]*(?:resource|provider|variable|module)\s+\"",
                      re.M)),
    ("html", re.compile(r"^[ \t]*<(?:!DOCTYPE|html|div|body)\b", re.I | re.M)),
    ("json", re.compile(r"^[ \t]*[\{\[]", re.M)),
    ("js", re.compile(r"^[ \t]*(?:const |let |function |export |import )", re.M)),
]


def x_code_blocks(text: str) -> list:
    """[(ext, code, suggested_filename)] for every fenced block."""
    out = []
    for m in _X_FENCE.finditer(text or ""):
        code = m.group("code")
        lang = (m.group("lang") or "").lower()
        ext = _X_LANG_EXT.get(lang, "")
        if not ext:
            for cand, rx in _X_SNIFF:
                if rx.search(code):
                    ext = cand
                    break
        ext = ext or "txt"
        name = ""
        head = (text[:m.start()].rstrip().rsplit("\n", 1) or [""])[-1]
        fm = _X_FNLINE.match(head.strip())
        if fm and fm.group(1).rsplit(".", 1)[-1].lower() == ext:
            name = fm.group(1)
        out.append((ext, code.rstrip("\n"), name))
    return out


def x_tables(text: str) -> list:
    """Every pipe table as a list of rows, divider row dropped. Uses the
    same divider gate the client renderer applies, so what the file holds
    and what the screen showed can never disagree."""
    out = []
    for m in _X_TABLE.finditer(text or ""):
        rows = [r.strip() for r in m.group(0).strip().split("\n") if r.strip()]
        if len(rows) < 2 or not _X_DIVIDER.match(re.sub(r"\s+", "", rows[1])):
            continue
        cells = []
        for i, r in enumerate(rows):
            if i == 1:
                continue
            parts = r.strip().strip("|").split("|")
            cells.append([p.strip() for p in parts])
        if cells:
            out.append(cells)
    return out


def x_blocks(text: str) -> list:
    """Markdown to a flat block list the document writers share:
    ('h', level, text) ('p', text) ('li', text) ('table', rows) ('code', s)"""
    blocks, pos = [], 0
    marks = []
    for m in _X_FENCE.finditer(text or ""):
        marks.append((m.start(), m.end(), "code", m.group("code").rstrip("\n")))
    for m in _X_TABLE.finditer(text or ""):
        rows = [r.strip() for r in m.group(0).strip().split("\n") if r.strip()]
        if len(rows) >= 2 and _X_DIVIDER.match(re.sub(r"\s+", "", rows[1])):
            cells = [[c.strip() for c in r.strip().strip("|").split("|")]
                     for i, r in enumerate(rows) if i != 1]
            marks.append((m.start(), m.end(), "table", cells))
    marks.sort()
    def _prose(chunk):
        for line in (chunk or "").split("\n"):
            t = line.rstrip()
            if not t.strip():
                continue
            hm = re.match(r"^(#{1,6})\s+(.*)$", t)
            if hm:
                blocks.append(("h", len(hm.group(1)), hm.group(2).strip()))
                continue
            lm = re.match(r"^\s*(?:[-*+]|\d+[.)])\s+(.*)$", t)
            if lm:
                blocks.append(("li", lm.group(1).strip()))
                continue
            if re.match(r"^\s*(?:-{3,}|\*{3,}|_{3,})\s*$", t):
                continue
            if blocks and blocks[-1][0] == "p":
                blocks[-1] = ("p", blocks[-1][1] + " " + t.strip())
            else:
                blocks.append(("p", t.strip()))
    for a, b, kind, payload in marks:
        _prose(text[pos:a])
        blocks.append((kind, payload))
        pos = b
    _prose(text[pos:])
    return blocks


_X_MD_INLINE = [
    (re.compile(r"\*\*([^*]+)\*\*"), r"<b>\1</b>"),
    (re.compile(r"(?<![\w*])\*([^*\n]+)\*(?![\w*])"), r"<i>\1</i>"),
    (re.compile(r"`([^`\n]+)`"), r"<font face='Courier'>\1</font>"),
]
_X_MD_LINK = re.compile(r"\[([^\]\n]+)\]\(([^)\s]+)\)")


def x_inline_pdf(s: str) -> str:
    """Markdown inline to reportlab's mini-markup. Escape EVERYTHING first,
    then reintroduce only the tags Paragraph parses — and allow a link only
    when its scheme is http(s), so a model-authored javascript: URI can
    never become a live annotation in the PDF."""
    out = html.escape(s or "", quote=False)
    for rx, rep in _X_MD_INLINE:
        out = rx.sub(rep, out)
    def _a(m):
        url = html.unescape(m.group(2))
        if not re.match(r"^https?://", url, re.I):
            return m.group(1)
        return '<a href="%s" color="#2a6bd4">%s</a>' % (
            html.escape(url, quote=True), m.group(1))
    return _X_MD_LINK.sub(_a, out)


def x_strip_md(s: str) -> str:
    s = re.sub(r"\*\*([^*]+)\*\*", r"\1", s or "")
    s = re.sub(r"(?<![\w*])\*([^*\n]+)\*(?![\w*])", r"\1", s)
    s = re.sub(r"`([^`\n]+)`", r"\1", s)
    return _X_MD_LINK.sub(r"\1", s)


# ------------------------------------------------------------- the writers
_X_FORMULA = re.compile(r"^=[A-Za-z_$][A-Za-z0-9_.$]*\s*\(")


def _x_cell(ws, row, col, raw):
    """One spreadsheet cell, honestly typed. A string that merely starts
    with '=' is NOT a formula — openpyxl validates nothing and Excel calls
    the result damaged — so only a well-formed call with balanced parens
    goes in live. Numbers stay numbers, negatives included."""
    c = ws.cell(row=row, column=col)
    s = (raw or "").strip()
    if s and _X_FORMULA.match(s) and s.count("(") == s.count(")"):
        c.value = s
        return c
    try:
        if s and re.fullmatch(r"-?\d{1,15}(?:\.\d+)?", s.replace(",", "")):
            c.value = float(s.replace(",", "")) if "." in s \
                else int(s.replace(",", ""))
            return c
    except (ValueError, OverflowError):
        pass
    # anything that could be read as a formula by a spreadsheet — including
    # the leading-whitespace evasion — is pinned to text
    t = s.lstrip("\t\r\n\x00 ")
    c.value = s
    if t[:1] in ("=", "+", "-", "@"):
        c.data_type = "s"          # assign first: the setter re-infers type
    return c


def ex_table(text, ext, path):
    rows_all = x_tables(text)
    if not rows_all:
        raise RuntimeError("no table in that answer to export")
    if ext == "csv":
        import csv as _csv
        with open(path, "w", newline="", encoding="utf-8") as f:
            w = _csv.writer(f)
            for r in rows_all[0]:
                w.writerow([("'" + c) if c.lstrip("\t\r\n ")[:1]
                            in ("=", "+", "-", "@")
                            and not re.fullmatch(r"-?[\d.,]+", c.strip())
                            else c for c in r])
        return
    from openpyxl import Workbook
    from openpyxl.styles import Font, Alignment
    from openpyxl.chart import BarChart, Reference
    wb = Workbook()
    for i, rows in enumerate(rows_all[:8]):
        ws = wb.active if i == 0 else wb.create_sheet()
        ws.title = ("Sheet%d" % (i + 1)) if i else "Data"
        for r, row in enumerate(rows, 1):
            for c, val in enumerate(row, 1):
                cell = _x_cell(ws, r, c, x_strip_md(val))
                if r == 1:
                    cell.font = Font(bold=True)
                    cell.alignment = Alignment(horizontal="center")
        for c in range(1, len(rows[0]) + 1):
            width = max((len(str(rows[r][c - 1])) for r in range(len(rows))
                         if c - 1 < len(rows[r])), default=10)
            ws.column_dimensions[chr(64 + c) if c <= 26 else "A"].width = \
                min(48, max(10, width + 2))
        ws.freeze_panes = "A2"
        # a numeric column earns a real Excel chart — the point of xlsx
        if i == 0 and len(rows) > 2 and len(rows[0]) > 1:
            num_col = 0
            for c in range(2, len(rows[0]) + 1):
                vals = [rows[r][c - 1] for r in range(1, len(rows))
                        if c - 1 < len(rows[r])]
                if vals and all(re.fullmatch(r"-?[\d.,]+\s*%?", (v or "").strip())
                                for v in vals):
                    num_col = c
                    break
            if num_col:
                ch = BarChart()
                ch.title = rows[0][num_col - 1]
                ch.add_data(Reference(ws, min_col=num_col, min_row=1,
                                      max_row=len(rows)), titles_from_data=True)
                ch.set_categories(Reference(ws, min_col=1, min_row=2,
                                            max_row=len(rows)))
                ch.height, ch.width = 8, 16
                ws.add_chart(ch, "A%d" % (len(rows) + 3))
    wb.save(path)


def ex_doc(text, ext, path, title=""):
    blocks = x_blocks(text)
    if ext == "docx":
        from docx import Document
        from docx.shared import Pt
        d = Document()
        if title:
            d.add_heading(x_strip_md(title)[:120], 0)
        for b in blocks:
            if b[0] == "h":
                d.add_heading(x_strip_md(b[2])[:200], min(4, max(1, b[1])))
            elif b[0] == "p":
                d.add_paragraph(x_strip_md(b[1]))
            elif b[0] == "li":
                d.add_paragraph(x_strip_md(b[1]), style="List Bullet")
            elif b[0] == "code":
                p = d.add_paragraph()
                run = p.add_run(b[1])
                run.font.name = "Courier New"
                run.font.size = Pt(9)
            elif b[0] == "table" and b[1]:
                rows = b[1]
                t = d.add_table(rows=len(rows), cols=len(rows[0]))
                t.style = "Table Grid"
                for r, row in enumerate(rows):
                    for c, val in enumerate(row[:len(rows[0])]):
                        t.cell(r, c).text = x_strip_md(val)
        d.save(path)
        return
    # PDF. Base-14 fonts on purpose: reportlab substitutes Symbol and
    # ZapfDingbats for glyphs Helvetica lacks, so checks, arrows and
    # bullets render for free. Registering a custom TTF is what silently
    # drops them — so we do not.
    from reportlab.lib.pagesizes import LETTER
    from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
    from reportlab.lib.units import inch
    from reportlab.lib import colors
    from reportlab.platypus import (SimpleDocTemplate, Paragraph, Spacer,
                                    Table, TableStyle, Preformatted)
    ss = getSampleStyleSheet()
    body = ParagraphStyle("b", parent=ss["BodyText"], fontSize=10.5,
                          leading=15, spaceAfter=7)
    mono = ParagraphStyle("m", parent=ss["Code"], fontSize=8.5, leading=11)
    doc = SimpleDocTemplate(path, pagesize=LETTER,
                            leftMargin=0.9 * inch, rightMargin=0.9 * inch,
                            topMargin=0.9 * inch, bottomMargin=0.8 * inch,
                            title=(title or "ConcordeAI export")[:120])
    story, drawn = [], 0
    if title:
        story += [Paragraph(x_inline_pdf(title), ss["Title"]), Spacer(1, 10)]
    for b in blocks:
        if drawn > 400_000:        # pre-flight bound: reportlab buffers it all
            story.append(Paragraph("<i>(truncated)</i>", body))
            break
        if b[0] == "h":
            story += [Spacer(1, 6),
                      Paragraph(x_inline_pdf(b[2]),
                                ss["Heading%d" % min(4, max(1, b[1]))])]
            drawn += len(b[2])
        elif b[0] == "p":
            story.append(Paragraph(x_inline_pdf(b[1]), body))
            drawn += len(b[1])
        elif b[0] == "li":
            story.append(Paragraph("• " + x_inline_pdf(b[1]), body))
            drawn += len(b[1])
        elif b[0] == "code":
            story += [Preformatted(b[1][:6000], mono), Spacer(1, 6)]
            drawn += min(6000, len(b[1]))
        elif b[0] == "table" and b[1]:
            rows = [[Paragraph(x_inline_pdf(c), body) for c in r]
                    for r in b[1][:80]]
            t = Table(rows, hAlign="LEFT", repeatRows=1)
            t.setStyle(TableStyle([
                ("GRID", (0, 0), (-1, -1), 0.4, colors.HexColor("#c9ccd4")),
                ("BACKGROUND", (0, 0), (-1, 0), colors.HexColor("#eef0f4")),
                ("VALIGN", (0, 0), (-1, -1), "TOP"),
                ("LEFTPADDING", (0, 0), (-1, -1), 5),
                ("RIGHTPADDING", (0, 0), (-1, -1), 5),
                ("TOPPADDING", (0, 0), (-1, -1), 4),
                ("BOTTOMPADDING", (0, 0), (-1, -1), 4)]))
            story += [t, Spacer(1, 9)]
            drawn += sum(len(c) for r in b[1] for c in r)
    if not story:
        story = [Paragraph("(empty)", body)]
    doc.build(story)


def ex_slides(text, ext, path, title=""):
    from pptx import Presentation
    from pptx.util import Inches, Pt
    prs = Presentation()
    blocks = x_blocks(text)
    s = prs.slides.add_slide(prs.slide_layouts[0])
    s.shapes.title.text = x_strip_md(title or "ConcordeAI")[:120]
    if len(s.placeholders) > 1:
        # the date under the title: _venue_stamp() was called without the
        # format it needs, so every deck export threw (review, 6b317); and
        # it's the chat's venue clock ("... in Tokyo"), not a document date
        s.placeholders[1].text = strftime_np("%B %-d, %Y")
    cur, bullets = None, []

    def flush():
        if cur is None and not bullets:
            return
        sl = prs.slides.add_slide(prs.slide_layouts[1])
        sl.shapes.title.text = (cur or "Notes")[:120]
        tf = sl.placeholders[1].text_frame
        tf.clear()
        for i, bl in enumerate(bullets[:9]):
            p = tf.paragraphs[0] if i == 0 else tf.add_paragraph()
            p.text = bl[:220]
            p.font.size = Pt(18)
    for b in blocks:
        if b[0] == "h" and b[1] <= 2:
            flush()
            cur, bullets = x_strip_md(b[2]), []
        elif b[0] in ("p", "li"):
            bullets.append(x_strip_md(b[1]))
        elif b[0] == "table" and b[1]:
            for r in b[1][1:8]:
                bullets.append(" — ".join(x_strip_md(c) for c in r[:3]))
    flush()
    if len(prs.slides) == 1:
        sl = prs.slides.add_slide(prs.slide_layouts[1])
        sl.shapes.title.text = "Notes"
        sl.placeholders[1].text_frame.text = x_strip_md(text)[:800]
    prs.save(path)


_X_ICS_ESC = str.maketrans({"\\": r"\\", ";": r"\;", ",": r"\,", "\n": r"\n"})


def _ics_fold(line: str) -> str:
    """RFC 5545 octet folding at 75, continuation lines start with a space."""
    out, buf = [], line.encode("utf-8")
    while len(buf) > 73:
        cut = 73
        while cut > 1 and (buf[cut] & 0xC0) == 0x80:
            cut -= 1                        # never split a UTF-8 sequence
        out.append(buf[:cut].decode("utf-8"))
        buf = b" " + buf[cut:]
    out.append(buf.decode("utf-8"))
    return "\r\n".join(out)


def ex_calendar(text, ext, path, title=""):
    """RFC 5545 from a schedule. All-day events take DTEND as the day AFTER
    the last day, which is what the spec requires and what every calendar
    app expects."""
    # FLOATING local times (6b304): _home_tz() returns a (tz, place)
    # TUPLE, which this used to concatenate into the string — every timed
    # event raised TypeError. A bare TZID with no VTIMEZONE block is also
    # out of spec (RFC 5545 3.2.19) and Outlook can reject it, so timed
    # events carry no zone at all and read as "this time, where you are".
    tz = ""
    now = time.strftime("%Y%m%dT%H%M%SZ", time.gmtime())
    evs = []
    for line in x_strip_md(text).split("\n"):
        t = line.strip().lstrip("-*+ ").strip()
        if not t:
            continue
        dm = re.search(r"\b(\d{4})-(\d{2})-(\d{2})\b", t)
        tm = re.search(r"\b([01]?\d|2[0-3]):([0-5]\d)\s*(am|pm)?\b", t, re.I)
        tm2 = re.search(r"\b(1[0-2]|0?[1-9])\s*(am|pm)\b", t, re.I)
        if not dm and not (tm or tm2):
            continue
        day = ("%s%s%s" % dm.groups()) if dm else \
            time.strftime("%Y%m%d", time.localtime())
        summary = re.sub(r"\s{2,}", " ", re.sub(
            r"\b\d{4}-\d{2}-\d{2}\b|\b([01]?\d|2[0-3]):[0-5]\d\s*(am|pm)?\b",
            "", t, flags=re.I)).strip(" —-:,") or "Event"
        if tm or tm2:
            if tm:
                hh, mm = int(tm.group(1)), int(tm.group(2))
                ap = (tm.group(3) or "").lower()
            else:
                hh, mm = int(tm2.group(1)), 0
                ap = tm2.group(2).lower()
            if ap == "pm" and hh < 12:
                hh += 12
            if ap == "am" and hh == 12:
                hh = 0
            st = "%sT%02d%02d00" % (day, hh, mm)
            en = "%sT%02d%02d00" % (day, (hh + 1) % 24, mm)
            evs.append(("DTSTART%s:%s" % (";TZID=" + tz if tz else "", st),
                        "DTEND%s:%s" % (";TZID=" + tz if tz else "", en),
                        summary))
        else:
            # calendar arithmetic, not epoch seconds (6b317, from the
            # Windows sweep): Windows' mktime can't go before 1970, so a
            # 1969 date sank the whole file, and on a fall-back day
            # "+86400 s" landed on the same date everywhere
            import datetime as _dt
            try:
                nxt = (_dt.datetime.strptime(day, "%Y%m%d").date()
                       + _dt.timedelta(days=1)).strftime("%Y%m%d")
            except ValueError:
                continue                    # an impossible date: skip it
            evs.append(("DTSTART;VALUE=DATE:" + day,
                        "DTEND;VALUE=DATE:" + nxt, summary))
    if not evs:
        raise RuntimeError("no dated items in that answer to put in a calendar")
    lines = ["BEGIN:VCALENDAR", "VERSION:2.0",
             "PRODID:-//ConcordeAI//EN", "CALSCALE:GREGORIAN"]
    for i, (st, en, summary) in enumerate(evs[:200]):
        lines += ["BEGIN:VEVENT",
                  "UID:%s-%d@concordeai" % (secrets.token_hex(8), i),
                  "DTSTAMP:" + now, st, en,
                  "SUMMARY:" + summary.translate(_X_ICS_ESC)[:300],
                  "END:VEVENT"]
    lines.append("END:VCALENDAR")
    with open(path, "w", newline="", encoding="utf-8") as f:
        f.write("\r\n".join(_ics_fold(x) for x in lines) + "\r\n")


def ex_cards(text, ext, path):
    """Anki's plain importer: one note per line, fields separated by tab,
    the separator declared up front so the import dialog needs no fiddling."""
    pairs = []
    for m in re.finditer(r"^\s*(?:[-*+]\s*)?(?:\*\*)?(?:Q|Question)"
                             r"(?:\*\*)?\s*[:.)]\s*(.+?)\s*\n+\s*"
                             r"(?:[-*+]\s*)?(?:\*\*)?(?:A|Answer)(?:\*\*)?"
                             r"\s*[:.)]\s*(.+?)\s*$",
                         text or "", re.I | re.M):
        pairs.append((x_strip_md(m.group(1)), x_strip_md(m.group(2))))
    if not pairs:
        # a two-column table is card-shaped; a wider one is a comparison
        for rows in x_tables(text):
            if rows and len(rows[0]) == 2:
                for r in rows[1:]:
                    if len(r) >= 2 and r[0].strip():
                        pairs.append((x_strip_md(r[0]), x_strip_md(r[1])))
    if not pairs:
        raise RuntimeError("no question-and-answer pairs found to make cards")
    with open(path, "w", newline="", encoding="utf-8") as f:
        f.write("#separator:tab\n#html:false\n")
        for q, a in pairs[:2000]:
            f.write("%s\t%s\n" % (q.replace("\t", " "), a.replace("\t", " ")))


def ex_archive(text, ext, path):
    import zipfile
    blocks = x_code_blocks(text)
    if not blocks:
        raise RuntimeError("no files in that answer to put in an archive")
    seen = {}
    with zipfile.ZipFile(path, "w", zipfile.ZIP_DEFLATED) as z:
        for i, (bext, code, name) in enumerate(blocks[:60]):
            nm = name or ("file%d.%s" % (i + 1, bext))
            nm = re.sub(r"[^\w./-]", "_", nm).lstrip("./")
            while ".." in nm:
                nm = nm.replace("..", "_")
            seen[nm] = seen.get(nm, 0) + 1
            if seen[nm] > 1:
                nm = "%s-%d.%s" % (nm.rsplit(".", 1)[0], seen[nm],
                                   nm.rsplit(".", 1)[-1])
            z.writestr(nm, code)


def ex_text(text, ext, path):
    """The model's own text IS the file. For code and diagrams take the
    matching fenced block; otherwise the answer, markdown intact."""
    body = text or ""
    if ext in ("md", "txt"):
        body = text if ext == "md" else x_strip_md(text)
    else:
        blocks = x_code_blocks(text)
        exact = [b for b in blocks if b[0] == ext]
        if exact:
            body = exact[0][1]
        elif ext == "mmd":
            # NEVER fall back to an unrelated fence here: a Mermaid export
            # that hands back a Python function is worse than an honest miss
            body = _mermaid_from(text)
        elif ext in ("json", "yaml", "toml", "env", "html", "svg", "xml",
                     "css"):
            raise RuntimeError("no %s block in that answer to export"
                               % ext.upper())
        elif blocks:
            body = blocks[0][1]          # a code ask takes the only code
        else:
            body = x_strip_md(text)
    with open(path, "w", encoding="utf-8") as f:
        f.write(body.rstrip("\n") + "\n")


def _mermaid_from(text: str) -> str:
    """Turn an arrow sketch into valid Mermaid. Every label gets a synthetic
    id and quotes — multi-word labels and parentheses are not legal bare
    node ids, and a diagram that will not render is worse than none."""
    edges, ids, order = [], {}, []
    for line in (text or "").split("\n"):
        t = x_strip_md(line).strip().lstrip("-*+ ").strip()
        if "-->" not in t and "->" not in t and "→" not in t:
            continue
        parts = re.split(r"\s*(?:-->|->|→)\s*", t)
        parts = [p.strip(" .;:") for p in parts if p.strip(" .;:")]
        for a, b in zip(parts, parts[1:]):
            for nm in (a, b):
                if nm not in ids:
                    ids[nm] = "n%d" % len(ids)
                    order.append(nm)
            edges.append((ids[a], ids[b]))
    if not edges:
        raise RuntimeError("no diagram in that answer to export as Mermaid")
    out = ["graph TD"]
    for nm in order:
        out.append('    %s["%s"]' % (ids[nm], nm.replace('"', "'")[:80]))
    for a, b in edges[:200]:
        out.append("    %s --> %s" % (a, b))
    return "\n".join(out)


# ------------------------------------------------------------- delivery
# Files live in the profile that asked (1a 5.5, 6b329): made in run/ and
# moved into its exports/ whole, only while it is the active one.
EXPORT_DIRNAME = "exports"
_X_ID_RX = re.compile(r"^[A-Za-z0-9_-]{16,48}\.[a-z0-9]{1,5}$")


def export_dir(ctx) -> str:
    """ctx's exports folder, for reading."""
    return ctx.path(EXPORT_DIRNAME)


def export_name(want: str, ext: str, title: str = "") -> str:
    """The pretty name the browser saves as. Never touches the filesystem —
    on disk everything is an opaque token."""
    stem = (want.rsplit(".", 1)[0] if want else "") or x_strip_md(title or "")
    stem = re.sub(r"\s+", "-", stem.strip())[:60]
    stem = re.sub(r"[^\w.-]", "", stem, flags=re.UNICODE).strip("-.") or "export"
    return "%s.%s" % (stem, ext)


def header_text(v: str) -> str:
    """A header value any text survives: printable ASCII but % as it is,
    the rest percent-encoded as UTF-8 (the page's hdrText reverses it)."""
    return urllib.parse.quote(str(v), safe=_HDR_SAFE)


_HDR_SAFE = "".join(chr(c) for c in range(32, 127) if chr(c) != "%")


def _x_disposition(name: str) -> str:
    """RFC 6266. http.server encodes headers as latin-1 strict, so a CJK or
    Cyrillic filename in a bare filename= raises inside send_header and kills
    the response — the ascii fold plus filename* is what makes it survive."""
    ascii_name = unicodedata.normalize("NFKD", name).encode(
        "ascii", "ignore").decode("ascii")
    ascii_name = re.sub(r'[^\w.\-()\[\] ]', "", ascii_name).strip() or (
        "export." + (name.rsplit(".", 1)[-1] if "." in name else "txt"))
    out = 'attachment; filename="%s"' % ascii_name.replace('"', "")
    if ascii_name != name:
        out += "; filename*=UTF-8''" + urllib.parse.quote(name, safe="")
    return out


def run_export(text: str, ext: str, title: str, base,
               want_name: str = "") -> dict:
    """Write one export and describe it. Raises with a sentence a person can
    act on — never a traceback."""
    text = x_clean(text)
    ext = (ext or "").lower().lstrip(".")
    if ext not in EXPORT_KIND:
        raise RuntimeError("Can’t write .%s files" % ext)
    kind = EXPORT_KIND[ext][0]
    if ext in EXPORT_NEEDS_DEPS and not ensure_export_deps(block_s=90):
        # a failed install says why, not "still installing" forever
        # (6b317, from the Windows sweep)
        if _export_install.get("state") == "error":
            raise RuntimeError(
                "the document engines for .%s didn’t install (%s); Markdown, CSV or HTML still work"
                % (ext, (_export_install.get("note") or "no details")[:120]))
        raise RuntimeError(
            "the document engines are still installing; ask again in a minute")
    token = secrets.token_urlsafe(16)
    suffix = "csv" if ext == "anki" else ext
    # written in run/, then moved into the profile whole (1a 5.3): an
    # export that finishes after a switch lands nowhere
    path = stage_path("." + suffix)
    kept = False
    try:
        if kind == "table":
            ex_table(text, ext, path)
        elif kind == "doc":
            ex_doc(text, ext, path, title)
        elif kind == "slides":
            ex_slides(text, ext, path, title)
        elif kind == "calendar":
            ex_calendar(text, ext, path, title)
        elif kind == "cards":
            ex_cards(text, ext, path)
        elif kind == "archive":
            ex_archive(text, ext, path)
        else:
            ex_text(text, ext, path)
        size = os.path.getsize(path)
        if size > EXPORT_MAX_BYTES:
            raise RuntimeError("the file is over the %d MB limit"
                               % (EXPORT_MAX_BYTES // 1_000_000))
        _hook_delay("export")
        try:
            base.adopt(path, "%s/%s.%s" % (EXPORT_DIRNAME, token, suffix))
        except NotLanded:
            kept = True         # adopt kept it in run/, and says so
            raise
    finally:
        if not kept:
            drop_run_file(path)
    name = export_name(want_name, ext, title)
    try:
        base.write("%s/%s.meta" % (EXPORT_DIRNAME, token),
                   {"name": name, "ext": ext, "ts": time.time(),
                    "size": size})
    except StaleProfile:
        raise
    except OSError:
        pass
    _sweep_exports(base)
    return {"id": "%s.%s" % (token, suffix), "name": name, "ext": ext,
            "size": size, "kind": EXPORT_KIND[ext][1]}


_X_SENTINEL = re.compile("\x00[A-Z0-9]+:.*?\x00", re.S)


def x_clean(text: str) -> str:
    """The answer as prose, with the stream's control markers removed.
    _run_lbl() emits RUN through emit(), so anything reading answer_buf
    gets sentinels glued to the first line of real text (found live: a
    perfectly good budget table would not export)."""
    t = _X_SENTINEL.sub("", text or "")
    t = re.sub("\x00[A-Z0-9]+:[^\x00]*$", "", t)
    return t.replace("\x00", "")


_X_NAME_STRIP = re.compile(
    r"^\s*(?:please\s+|can\s+you\s+|could\s+you\s+|i\s+(?:want|need)\s+)?"
    r"(?:generate|create|make|build|write|draft|export|save|give|produce|"
    r"turn|convert|send)\s+(?:me\s+)?(?:an?\s+|the\s+)?"
    r"(?:\w+\s+)?(?:file|doc|document|sheet|deck|copy|version)?\s*"
    r"(?:of|for|with|about|on|showing)?\s*", re.I)


def x_title(prompt: str, text: str = "") -> str:
    """A filename a person would have chosen. The answer's own first
    heading beats the request, and the request beats nothing — but the
    request has its 'generate an excel file of' preamble removed first,
    or every budget is called Generate-an-Excel-file-of-a-budget."""
    for b in x_blocks(text or ""):
        if b[0] == "h" and len(b[2].strip()) > 2:
            return x_strip_md(b[2]).strip()[:60]
    t = _X_NAME_STRIP.sub("", x_strip_md(prompt or "").strip())
    t = re.split(r"[.:;\n]| based on | using | that ", t)[0]
    return " ".join(t.split()[:7])[:60] or "export"


def _x_size(n: int) -> str:
    return ("%.1f MB" % (n / 1e6)) if n >= 1e6 else ("%d KB" % max(1, n // 1000))


def _sweep_exports(ctx):
    """Newest EXPORT_KEEP_N per identity, nothing past the TTL. Exports are
    cover letters and budgets — they should not pile up forever."""
    d = export_dir(ctx)
    try:
        cut = time.time() - EXPORT_TTL_H * 3600
        files = []
        for nm in os.listdir(d):
            if nm.endswith(".meta"):
                continue
            try:
                files.append((os.path.getmtime(os.path.join(d, nm)), nm))
            except OSError:
                pass
        files.sort(reverse=True)
        for i, (mt, nm) in enumerate(files):
            if i >= EXPORT_KEEP_N or mt < cut:
                for q in (nm, os.path.splitext(nm)[0] + ".meta"):
                    try:
                        ctx.remove(EXPORT_DIRNAME + "/" + q)
                    except OSError:
                        pass
    except OSError:
        pass


def sweep_all_exports():
    """The active profile's exports, on the janitor's tick. The web
    version's users/ folders are no longer walked (6b320): a leftover one
    on an old machine is never touched, let alone deleted, by the app.
    Each removal is epoch-checked, so a switch mid-sweep stops it."""
    try:
        ctx = current_ctx()
        if os.path.isdir(export_dir(ctx)):
            _sweep_exports(ctx)
    except (OSError, NoProfile):
        pass


def reveal_in_finder(path: str) -> bool:
    """The native move: put the file in front of the user rather than
    fighting WKWebView's download plumbing. Desktop only."""
    if not (IS_MAC and os.path.exists(path)):
        return False
    try:
        subprocess.run(["open", "-R", path], timeout=10,
                       capture_output=True)
        return True
    except Exception:
        return False


# ==== image annotate: begin ====
# DRAW ON A PICTURE (6b355, per Patrick: "I paste it in a map and ask the
# app to draw over it showing good neighborhoods for an Airbnb, but it was
# unable to modify the photo. It should be able to do this sort of
# modification to images."). The model never edits pixels: it says WHERE,
# as shapes in 0..1 coordinates inside an ```annotate fence, and the page
# draws them over the picture the person attached. The gate below is a
# small word pattern and FAILS CLOSED: a picture with a plain question
# ("what is this?") goes the way it always did.
# 6b355 REVIEW: the first gate fired on "add up the numbers on this
# receipt", "put the text in a table" and "show me where this was taken",
# and on a cloud vision route that sent a picture out on a message that was
# not about drawing. A request now needs a MARKING verb at the head of an
# instruction; the weaker verbs (draw, outline, point out; add, put, place)
# also need a shape or the picture as their target; a question that is not
# a request ("label the parts of this cell?") never counts.
_ANN_LEAD = re.compile(
    r"^(?:(?:ok(?:ay)?|hey|hi|now|then|also|so|well|just|please|pls|kindly|"
    r"thanks?|thank\s+you|great|good)\b[\s,.!:;-]*|"
    r"(?:can|could|would|will)\s+you\b[\s,]*|"
    r"i['’]?d\s+like\s+(?:you\s+)?to\b\s*|"
    r"i\s+(?:want|need)\s+(?:you\s+)?to\b\s*|let['’]?s\b\s*|"
    r"go\s+ahead\s+and\b\s*|try\s+to\b\s*|you\s+should\b\s*|"
    r"i['’]?d\s+like\s+(?:it\s+)?if\s+you\b\s*|ask\s+(?:the\s+app|"
    r"you)\s+to\b\s*|and\b\s*)+", re.I)
# a question mark only belongs to a REQUEST when it opens like one
_ANN_REQ = re.compile(
    r"^(?:(?:ok(?:ay)?|hey|so|now|also|and|please|pls|kindly)\b[\s,]*)*"
    r"(?:(?:can|could|would|will)\s+you|please|i['’]?d\s+like\s+you\s+"
    r"to|i\s+(?:want|need)\s+you\s+to)\b", re.I)
_ANN_QUESTION = re.compile(
    r"^\s*(?:what|why|who|whose|which|how|is|are|was|were|does|do|did|"
    r"when|where|whats|what['’]s)\b", re.I)
_ANN_SHAPE = (r"(?:circles?|box(?:es)?|arrows?|outlines?|rectangles?|ovals?|"
              r"ellipses?|squares?|borders?|boundar(?:y|ies)|polygons?|"
              r"markers?|pins?|dots?|lines?|x['’]?s)")
_ANN_TARGET = (r"(?:on|over|onto|across|atop|upon)\s+(?:it|this|that|them|"
               r"(?:the|this|that|my|your)\s+(?:map|image|picture|photo|pic|"
               r"screenshot|screen\s*shot|diagram|floor\s*plan|plan|chart|"
               r"drawing|layout|scan|figure))\b")
# verbs that mean marking whenever they open an instruction
_ANN_STRONG = re.compile(
    r"^(?:annotate|highlight|circle|underline|mark\s+up|colou?r\s+in)\b"
    r"\s*\S", re.I)
# "mark", "label", "box", "shade": nouns as often as verbs, so only an
# imperative one, and not "mark as read" / "mark my words"
_ANN_MARK = re.compile(
    r"^(?:mark|label|box|shade)\b\s*(?!as\b|down\b|off\b|my\s+words|me\b|"
    r"sure\b|(?:it|this|that|them)\s+as\b|up\b)\S", re.I)
# these draw only with a shape or onto the picture
_ANN_DRAW = re.compile(
    r"^(?:draw|sketch|outline|point\s+out|point\s+to)\b(?P<rest>.*)$", re.I)
# and these only with a shape AND a place for it
_ANN_PLACE = re.compile(r"^(?:add|put|place|insert)\b(?P<rest>.*)$", re.I)
_ANN_PASSIVE = re.compile(
    r"\b(?:want|like|need)\s+(?:the|all|every|each|those|these|them|it|"
    r"some|any|my)\b[^.?!]{0,80}?\s(?:highlighted|circled|marked(?:\s+up)?|"
    r"outlined|annotated|shaded|boxed)(?:\s+(?:on|in|with)\b[^.?!]*)?"
    r"\s*(?:please\s*)?$", re.I)


def _ann_sentences(text: str):
    """(sentence, is_a_question_that_is_not_a_request) for each sentence."""
    for m in re.finditer(r"[^.!?\n;]+[.!?;]*", text or ""):
        raw = m.group(0).strip()
        body = raw.rstrip(".!?; ").strip()
        if body:
            yield body, (raw.endswith("?") and not _ANN_REQ.match(body))


def _ann_clauses(text: str):
    """The instructions in a request: each sentence that is not a question,
    split where an 'and' or a comma starts another one."""
    for sent, asks in _ann_sentences(text):
        sent = _ANN_LEAD.sub("", sent)
        if not sent or asks or _ANN_QUESTION.match(sent):
            continue
        for cl in re.split(r"\b(?:and|then|but|so|to)\b|[,:&]", sent,
                           flags=re.I):
            cl = _ANN_LEAD.sub("", cl.strip())
            if cl and not _ANN_QUESTION.match(cl):
                yield cl


def annotate_wants(text: str) -> bool:
    """True when the request asks to mark, draw on, or label the attached
    picture. Fail-closed: no match means the picture is read as before."""
    t = str(text or "")[:2000]
    for sent, asks in _ann_sentences(t):
        if not asks and _ANN_PASSIVE.search(sent):
            return True
    for cl in _ann_clauses(t):
        if _ANN_STRONG.match(cl) or _ANN_MARK.match(cl):
            return True
        m = _ANN_DRAW.match(cl)
        if m:
            rest = m.group("rest")[:120]
            if re.match(r"\s*me\s+an?\s+\w+\s*$", rest, re.I):
                continue                 # "draw me a circle": a commission
            if re.search(r"\b" + _ANN_SHAPE + r"\b", rest, re.I) \
                    or re.search(r"\b" + _ANN_TARGET, rest, re.I):
                return True
        m = _ANN_PLACE.match(cl)
        if m:
            rest = m.group("rest")[:120]
            if re.search(r"\b" + _ANN_SHAPE + r"\b", rest, re.I) and (
                    re.search(r"\b" + _ANN_TARGET, rest, re.I)
                    or re.search(r"\b(?:around|pointing)\b", rest, re.I)):
                return True
    return False


# a FOLLOW-UP changes the drawing only when a change verb is aimed at a
# drawn thing ("make the red box bigger", "remove the blue circle", "move it
# left"); "tell me more", "explain", "recommend" and questions never do
_ANN_CHANGE = re.compile(
    r"^(?:make|move|shift|nudge|resize|recolou?r|colou?r|remove|delete|"
    r"erase|drop|add|redo|enlarge|shrink|expand|widen|narrow|change|swap|"
    r"turn|rename|relabel|extend|thicken)\b(?P<rest>.*)$", re.I)
_ANN_DRAWN = re.compile(
    r"^\s*(?:(?:the|a|an|another|one|more|that|this|those|these|all|every|"
    r"each|some|two|three|new|extra|big|bigger|small|other|red|blue|green|"
    r"yellow|orange|purple|pink|black|white|grey|gray)\s+){0,3}(?:\w+\s+)?"
    r"(?:box(?:es)?|circles?|marks?|markers?|labels?|outlines?|arrows?|"
    r"shapes?|areas?|zones?|regions?|polygons?|ellipses?|ovals?|"
    r"rectangles?|lines?|highlights?|pins?|dots?|colou?rs?|ones?|"
    r"map|picture|image|photo|drawing|overlay)\b", re.I)
_ANN_IT = re.compile(
    r"^\s*(?:it|them|those|these)\b[^.?!]*\b(?:bigger|larger|smaller|wider|"
    r"narrower|thicker|thinner|left|right|up|down|higher|lower|red|blue|"
    r"green|yellow|orange|purple|pink)\b", re.I)


def annotate_edit_wants(text: str) -> bool:
    """A follow-up to marks already drawn ('make the red box bigger',
    'also mark the park'): a change aimed at the drawing, never a question,
    never 'tell me more'."""
    t = str(text or "")[:2000]
    if annotate_wants(t):
        return True
    for cl in _ann_clauses(t):
        m = _ANN_CHANGE.match(cl)
        if m and (_ANN_DRAWN.match(m.group("rest"))
                  or _ANN_IT.match(m.group("rest"))):
            return True
    return False


def annotate_prev(messages) -> bool:
    """The last assistant turn before the question carries an annotate
    fence, so there are marks to change."""
    for m in reversed(messages[:-1] if messages else []):
        if isinstance(m, dict) and m.get("role") == "assistant":
            return "```annotate" in str(m.get("content") or "")
    return False


ANNOTATE_RULES = """
HOW TO MARK THE PICTURE. The person wants marks drawn ON the attached picture. You cannot change pixels; you say where the marks go and the app draws them. Do two things:
1. Answer in a few plain sentences: what you marked and why.
2. End with ONE fenced block opened by three backticks and the word annotate, holding JSON only:
{"shapes":[{"type":"rect","x":0.2,"y":0.3,"w":0.15,"h":0.1,"text":"Park","color":"#22c55e","note":"Quiet, near the train"}]}
Rules:
- Coordinates are fractions of the picture, 0 to 1, origin at the TOP-LEFT: x grows to the right, y grows downward.
- Types: "rect" and "ellipse" (x, y = top-left corner, w, h = size); "polygon" ("points":[[x,y],[x,y],[x,y],...], at least 3); "arrow" and "line" ("points":[[from x,y],[to x,y]]); "label" (x, y = where the text goes, "text").
- Each shape may have "text" (a label, at most 40 characters), "color" ("#rrggbb"; give different areas different colors) and "note" (one short sentence on why).
- At most 30 shapes. Put only what the person asked for in the block.
- If the person asks to change earlier marks (bigger, smaller, move, remove, add, recolor), reply with the FULL updated block, not just the change.
"""
ANNOTATE_GRID = """
THE GRID. The picture you see has a thin grid drawn over it by the app: columns A to J from left to right and rows 1 to 10 from top to bottom, each cell 0.1 wide and 0.1 tall, with the numbers 0.1 to 0.9 along the bottom edge (for x) and the left edge (for y), in blue. Place every shape by that grid: cell C4 spans x 0.2 to 0.3 and y 0.3 to 0.4. Read coordinates off the grid; do not guess. The grid is not part of the picture and is never drawn in the answer.
"""


def annotate_instruction(request: str, grid: bool) -> str:
    """The question as the model gets it: the person's words, then the
    rules for answering with shapes."""
    return (str(request or "").strip() + "\n" + ANNOTATE_RULES
            + (ANNOTATE_GRID if grid else ""))


ANNOTATE_SAVE_MAX = 16_000_000


def save_annotated_png(ctx, data_url: str) -> dict:
    """The flattened picture, saved the way an export is (an opaque name in
    exports/, a .meta with the pretty one) so the desktop app can reveal it
    in Finder and a plain browser can download it. Raises ValueError for
    anything that is not a PNG data URL of a sane size."""
    s = str(data_url or "")
    if not s.startswith("data:image/png;base64,"):
        raise ValueError("not a PNG")
    raw = base64.b64decode(s.split(",", 1)[1], validate=False)
    if not raw.startswith(b"\x89PNG\r\n\x1a\n") or len(raw) > ANNOTATE_SAVE_MAX:
        raise ValueError("not a PNG")
    token = secrets.token_urlsafe(16)
    # through the profile's own writer (checked against the active profile
    # at the moment of writing): after a switch nothing lands, and the
    # caller is told by StaleProfile
    ctx.write_bytes("%s/%s.png" % (EXPORT_DIRNAME, token), raw, mode=0o600)
    name = "annotated-picture.png"
    try:
        ctx.write("%s/%s.meta" % (EXPORT_DIRNAME, token),
                  {"name": name, "ext": "png", "ts": time.time(),
                   "size": len(raw)})
    except StaleProfile:
        raise
    except OSError:
        pass
    return {"id": token + ".png", "name": name, "size": len(raw)}
# ==== image annotate: end ====


VIDEO_SUB = "videos"      # a profile's videos (1a 5.5): video_dir(ctx)


def video_dir(ctx) -> str:
    return ctx.path(VIDEO_SUB)
_VID_VERBS = (r"(?:generate|create|make|render|produce|animate|shoot|film|"
              r"put\s+together)")
_VID_NOUNS = (r"(?:video|clip|animation|movie|short|reel|gif|"
              r"time-?lapse|montage)s?")
_VIDEO_RX = re.compile(
    r"^\s*(?:please\s+|hey\s+|ok(?:ay)?\s+)?(?:(?:can|could|would|will)"
    r"\s+you\s+)?(?:please\s+)?" + _VID_VERBS +
    r"\s+(?:me\s+)?(?:an?\s+|some\s+|the\s+|\d+\s+)?"
    r"(?:(?!of\b)\w+\s+){0,2}" + _VID_NOUNS +
    r"\b\s*(?:of|showing|depicting|featuring|with|for|:|-|\u2014)?\s*"
    r"(?P<subject>.*)$", re.I | re.S)


def video_intent(text: str):
    """The subject to film when the message asks for a video, else None.
    Shares image_intent's preamble strip, so "try again, make a video of a
    cat" works the same way (6b296)."""
    t = (text or "").strip()
    if len(t) > 600:
        return None
    m = _VIDEO_RX.match(t)
    if not m:
        t2 = _img_strip_pre(t)
        if t2 != t and t2:
            m = _VIDEO_RX.match(t2)
            if m:
                t = t2
    if not m:
        return None
    rest = re.match(r"^\s*(?:please\s+|hey\s+|ok(?:ay)?\s+)?"
                    r"(?:(?:can|could|would|will)\s+you\s+)?(?:please\s+)?"
                    + _VID_VERBS + r"\s+(?:me\s+)?(?P<rest>.*)$",
                    t, re.I | re.S)
    subj = (rest.group("rest") if rest else m.group("subject")).strip()
    subj = re.sub(r"^(?:an?|some|the)\s+(?:short\s+)?" + _VID_NOUNS +
                  r"\s+(?:of|showing|depicting)\s+", "", subj, flags=re.I)
    subj = subj.strip().strip(".!?").strip()
    if _BACKREF.match(subj):
        return None               # points at what was made: a follow-up
    return subj or "something beautiful"


def video_ready() -> bool:
    return studio_ready("video")


VEO_DAILY_CAP = 5        # cloud clips a day (6b309); pref veo_daily_cap


def _veo_video(ctx, prompt: str) -> str:
    """Google's Veo, via the key the user already added. It is a long
    running operation: submit, then poll until the file is there.
    A DAILY CAP (6b309): about $0.80 a clip adds up quietly, so after
    VEO_DAILY_CAP clips in a day the cloud stops making video."""
    # no key, no slot: this check came after the reservation, so a
    # request with no key spent a clip of the day (6b326)
    gem = (_cloud_all().get("providers") or {}).get("gemini") or {}
    if not (gem.get("key") and gem.get("status", "ok") == "ok"):
        raise RuntimeError("No cloud key can make video.")
    today = time.strftime("%Y-%m-%d")
    # RESERVE THE SLOT FIRST (6b309, review): checking, then counting
    # after the submit let two requests at once both slip under the cap

    def _reserve(_pr):
        _cap = int(_pr.get("veo_daily_cap", VEO_DAILY_CAP) or 0)
        if _pr.get("veo_day") != today:
            _pr["veo_day"], _pr["veo_count"] = today, 0
        if _cap and int(_pr.get("veo_count", 0)) >= _cap:
            raise RuntimeError("VEO_CAP: today's cloud-video limit of %d "
                               "clips (about $0.80 each) is reached" % _cap)
        _pr["veo_count"] = int(_pr.get("veo_count", 0)) + 1
    # the counters are this profile's own (1a 5.6)
    profile_local_update(ctx, _reserve)
    _started = [False]

    def _give_back():
        # no render started, so nothing is billed: the slot goes back
        if _started[0]:
            return
        def _back(_p):
            if _p.get("veo_day") == today and int(_p.get("veo_count", 0)):
                _p["veo_count"] = int(_p["veo_count"]) - 1
        try:
            profile_local_update(ctx, _back)
        except Exception:
            pass
    key = gem["key"]
    base = GEMINI_API
    last = ""
    # standard Veo costs 4x Fast ($3.20 an 8 s clip) and is never a
    # silent fallback (6b308)
    for mdl in ("veo-3.1-fast-generate-preview",
                "veo-3.1-lite-generate-preview"):
        try:
            req = urllib.request.Request(
                base + "models/%s:predictLongRunning?key=%s" % (mdl, key),
                data=json.dumps({"instances": [{"prompt": prompt}]}).encode(),
                headers={"Content-Type": "application/json",
                         "User-Agent": "MillenAI/%s" % APP_VERSION})
            with urllib.request.urlopen(req, timeout=60) as r:
                op = json.loads(r.read().decode("utf-8", "replace"))
            name = op.get("name") or ""
            if not name:
                last = "no operation returned"
                continue
            _started[0] = True       # billed from here: the slot is spent
        except Exception as exc:
            # only a SUBMIT that fails (quota, a withdrawn model) hands
            # over to the next model (6b307)
            last = str(exc)[:160]
            continue
        # A RENDER THAT STARTED IS THE ONLY TRY (6b307). Timing out and
        # moving on started a second paid render while the first could
        # still finish and bill, and three models in a row made the
        # reader wait about twenty minutes. A refusal from one model
        # is a refusal from the next.
        try:
            for _ in range(90):               # up to ~7 minutes
                time.sleep(5)
                # the profile that asked is no longer active: stop polling
                # (review of 6b329); the clip would land nowhere anyway
                if ctx.cancel.is_set():
                    raise StaleProfile("the profile changed")
                pr = urllib.request.Request(base + name + "?key=" + key,
                                            headers={"User-Agent": "MillenAI"})
                with urllib.request.urlopen(pr, timeout=30) as r:
                    st = json.loads(r.read().decode("utf-8", "replace"))
                if not st.get("done"):
                    continue
                if st.get("error"):
                    last = str(st["error"].get("message", ""))[:160]
                    break
                resp = st.get("response") or {}
                vids = (resp.get("generateVideoResponse", {})
                        .get("generatedSamples")
                        or resp.get("generatedSamples") or [])
                uri = ((vids[0].get("video") or {}).get("uri") if vids else "")
                if not uri:
                    last = "no video in the reply"
                    break
                vr = urllib.request.Request(
                    uri + ("&" if "?" in uri else "?") + "key=" + key,
                    headers={"User-Agent": "MillenAI"})
                with urllib.request.urlopen(vr, timeout=300) as r:
                    data = r.read()
                # the clip lands in the profile that asked, or nowhere
                # (1a 5.3): a switch during the render drops it
                _hook_delay("veo-download")
                name = VIDEO_SUB + "/" + _media_id() + ".mp4"
                ctx.write_bytes(name, data)
                return ctx.path(name)
            else:
                last = "timed out waiting for the render"
        except StaleProfile:
            raise
        except Exception as exc:
            last = str(exc)[:160]
        break
    _give_back()
    raise RuntimeError(last or "The cloud couldn’t make that video.")


def generate_video(ctx, prompt: str, over: dict = None, sock=None) -> tuple:
    """(mp4 path, source). Local first, then a cloud key. Video has no
    keyless tier — nobody gives it away — so when neither is there the
    caller says so plainly rather than pretending. A saved Gemini key is
    permission to use it, whatever Use cloud power says (6b326). Made in
    run/, landed in ctx's videos (1a 5.3)."""
    errs = []
    # sits a running benchmark out, as the painter does (review of 6b334)
    _mine = video_ready()
    if _mine and _bench["running"]:
        _mine = False
        errs.append("local: " + BENCH_BUSY)
    if _mine:
        out = stage_path(".mp4")
        t = studio_tier("video")
        o = studio_opts("video", over)
        # the prompt and the negative prompt reach the renderer through one
        # 0600 file (6b326), never its command line
        args = ["--model-dir", _snap_dir(t["repo"]),
                "--prompt", "@prompt:prompt",
                "--num-frames", str(o["frames"]),
                "--width", str(o["w"]), "--height", str(o["h"]),
                "--steps", str(o["steps"]),
                "--guide-scale", str(o["guidance"]),
                "--seed", str(o["seed"] or secrets.randbelow(10 ** 6)),
                "--output-path", out]
        if o.get("neg"):
            args += ["--negative-prompt", "@prompt:neg"]
        if not _render_lock.acquire(timeout=5):
            raise RenderBusy("already making one; ask again when it lands")
        pf = None
        try:
            cmd, pf = prompt_cmd(
                os.path.join(STUDIOS["video"]["venv"], "bin", "python3"),
                "module", STUDIOS["video"]["module"], args,
                {"prompt": prompt, "neg": o.get("neg") or ""})
            _vt0 = time.time()
            rc, tail, cut = _run_render(cmd, 3600, sock)
            if cut:
                raise RenderBusy("stopped")
            if rc == 0 and os.path.exists(out):
                cfg = engine_cfg("video")
                native = cfg.get("fps") or 24
                _render_note(out, o, time.time() - _vt0)
                return _media_land(ctx, VIDEO_SUB, _ffmpeg_convert(
                    out, o["fmt"],
                    0 if (o["fmt"] == "mp4" and o["fps"] == native)
                    else o["fps"])), "local"
            errs.append("local: " + tail[-200:].strip())
        except (RenderBusy, NotLanded):
            raise
        except StaleProfile:
            raise
        except Exception as exc:
            errs.append("local: %s" % str(exc)[:160])
        finally:
            drop_run_file(pf)
            _render_lock.release()
    try:
        return _veo_video(ctx, prompt), "cloud"
    except StaleProfile:
        raise
    except Exception as exc:
        errs.append("cloud: %s" % str(exc)[:160])
    raise RuntimeError("; ".join(errs) or "No video engine")


def studio_needs(kind: str) -> str:
    """What the reader is told when a picture or video can't be made on
    this computer and no working Gemini key is saved (6b326). Nothing has
    been sent anywhere."""
    if studio_supported():
        return ("Add a Gemini key in Settings > Models > Cloud, or add %s generation in Settings > Models." % ("image" if kind == "image" else "video"))
    how = ("Add a Gemini key in Settings > Models > Cloud to make this "
           "with Gemini.")
    if kind == "image":
        return "Pictures on this computer need Apple silicon. " + how
    return "Video on this computer needs Apple silicon. " + how


# ------------------------------------------------------------- updates
_update = {"state": "idle", "pct": 0, "note": "", "latest": "", "url": "",
           "size": 0}

# THE SWAP KNOWS BOTH BUNDLES (6b537): the Python app's main executable is
# Contents/MacOS/MillenAI (6b443); the native shell's is
# Contents/MacOS/ConcordeAI (shell/, 6b532), and from 7.0 the .dmg a
# release carries is the shell's. The helper waits for whichever of the
# two owns the bundle to be gone (the shell quits when its sidecar exits
# with 0, which _do_update's os._exit is), swaps the bundle whole, and
# `open -n` relaunches whatever the new bundle's executable is — so a
# Python install updates into the shell and a shell install into the
# next shell by the one path. Resources/millenai.py sits at the same
# place in both layouts, so _app_bundle_path needs no second rule.
_SWAP_SCRIPT = """#!/bin/zsh
# Wait for the app (its launcher or its shell) to quit so its bundle can
# be replaced safely.
for i in $(seq 1 60); do
  pgrep -f "%(app)s/Contents/MacOS/" >/dev/null || break
  sleep 0.5
done
MP=$(mktemp -d)
hdiutil attach -nobrowse -readonly -quiet -mountpoint "$MP" "%(dmg)s" || exit 1
NEW=$(ls -d "$MP"/*.app 2>/dev/null | head -1)
if [[ -n "$NEW" ]]; then
  ditto "$NEW" "%(app)s.new" && rm -rf "%(app)s" && mv "%(app)s.new" "%(app)s"
  xattr -dr com.apple.quarantine "%(app)s" 2>/dev/null
fi
hdiutil detach -quiet "$MP"
rm -rf "%(tmp)s"
open -n "%(app)s"
"""


def _app_bundle_path():
    """/Applications/MillenAI.app when running from a bundle, else None.

    Windows installs aren't a single swappable bundle, so in-place update is
    macOS-only for now; Windows users are pointed at the release page.
    """
    if not IS_MAC:
        return None
    here = os.path.abspath(__file__)
    root = os.path.dirname(os.path.dirname(os.path.dirname(here)))
    return root if root.endswith(".app") else None


def _own_build_time() -> float:
    """When this build was produced — the yardstick for 'newer release'."""
    if APP_BUILD_DATE:
        try:
            return time.mktime(time.strptime(APP_BUILD_DATE, "%Y-%m-%d"))
        except ValueError:
            pass
    try:
        return os.path.getmtime(os.path.abspath(__file__))
    except OSError:
        return 0.0


def _gh_time(iso: str) -> float:
    # GitHub stamps releases in UTC; mktime would read them as local time
    # and make every release look hours newer than it is
    try:
        return calendar.timegm(time.strptime(iso, "%Y-%m-%dT%H:%M:%SZ"))
    except (ValueError, TypeError):
        return 0.0


def _build_from_tag(tag):
    nums = re.findall(r"\d+", tag or "")
    return int(nums[-1]) if nums else 0


def update_channel() -> str:
    """stable | beta | nightly. A stored choice always wins; the old
    beta_updates checkbox migrates to beta once. With nothing chosen the
    build decides (7.0 beta, per Patrick): a nightly build stays on the
    nightly channel, a beta or release-candidate build (APP_BETA or APP_RC
    above 0) on beta, so an install that came by a beta keeps getting
    betas instead of falling back to stable; anything else is stable."""
    pr = machine_prefs()
    ch = str(pr.get("update_channel") or "").strip().lower()
    if ch in ("stable", "beta", "nightly"):
        return ch
    if pr.get("beta_updates"):
        return "beta"
    return _channel_default()


def _channel_default() -> str:
    """The channel a build is on when nothing was chosen (update_channel)."""
    if APP_NIGHTLY:
        return "nightly"
    if APP_BETA > 0 or APP_RC > 0:
        return "beta"
    return "stable"


def _channel_release():
    """The newest release this machine's CHANNEL allows. Stable reads
    /releases/latest (GitHub excludes prereleases there); the beta
    opt-in (Settings) scans the list and takes the newest non-draft —
    prereleases included. That's the whole beta programme (6.0b4)."""
    hdrs = {"Accept": "application/vnd.github+json",
            "User-Agent": "MillenAI"}
    ch = update_channel()
    if ch in ("beta", "nightly"):
        req = urllib.request.Request(
            UPDATE_API + "/repos/%s/releases?per_page=20"
            % UPDATE_REPO, headers=hdrs)
        with urllib.request.urlopen(req, timeout=8) as r:
            rels = json.loads(r.read().decode("utf-8"))
        rels = [x for x in rels if not x.get("draft")]
        if ch == "nightly":
            # the one rolling nightly (6b285) — if it is missing, the
            # newest release of any kind is the honest fallback. Its body
            # is a list of commit subjects, so it carries the newest
            # numbered release's notes for people to read (6b551)
            human = next((x.get("body") or "" for x in rels
                          if x.get("tag_name") != "nightly"
                          and (x.get("body") or "").strip()), "")
            rels = ([dict(x, _human_notes=human) for x in rels
                     if x.get("tag_name") == "nightly"] or rels)
        else:
            # beta: newest release that is not the nightly
            rels = [x for x in rels if x.get("tag_name") != "nightly"]
        if not rels:
            raise urllib.error.HTTPError(
                UPDATE_REPO, 404, "no releases", None, None)
        return rels[0]                    # GitHub lists newest first
    req = urllib.request.Request(
        UPDATE_API + "/repos/%s/releases/latest" % UPDATE_REPO,
        headers=hdrs)
    with urllib.request.urlopen(req, timeout=8) as r:
        return json.loads(r.read().decode("utf-8"))


_chk_cache = {"ts": 0.0, "data": None, "beta": None, "chan": None}


# WHAT'S NEW ON A NIGHTLY (6b551, per Patrick: the About pane listed "beta-1 gauntlet: the
# MLX engine's boot-order pin…"). The nightly release's body is the workflow's commit
# subjects, written for us, not for people. A nightly shows the newest numbered release's
# notes instead, or one plain line when there are none to read; never a commit subject.
def _nightly_line() -> str:
    m = re.match(r"(\d+\.\d+)", APP_VERSION or "")
    return "Latest changes from the %s line." % (m.group(1) if m else "current")


def _release_notes(rel) -> str:
    if (rel or {}).get("tag_name") != "nightly":
        return ((rel or {}).get("body") or "")[:4000]
    human = ((rel or {}).get("_human_notes") or "").strip()
    return human[:4000] if human else _nightly_line()


def check_update(force=False):
    """Cached wrapper — every open client now polls hourly (the owner
    auto-check, 6b257), so one GitHub hit per 15 min serves them all:
    the unauthenticated API budget is 60/hr per IP and check_update
    used to spend one on EVERY call. The Settings button passes
    force=True so a human click still reaches GitHub every time.
    Failures are never cached — a launch-time DNS blip must not read
    as an authoritative "no update" for 15 minutes — and the cache is
    keyed to the beta pref, so toggling the channel never serves the
    other channel's verdict."""
    # AUTOMATIC CHECKS ARE A CHOICE (6b292, per Patrick): with the About
    # switch off, only the button (force) reaches GitHub — the launch and
    # daily calls get an honest "off", uncached.
    if not force and machine_prefs().get("auto_update_check") is False:
        return {"configured": True, "available": False, "auto": False,
                "note": "Automatic checks are off"}
    if not UPDATE_REPO:
        return {"configured": False, "available": False}
    beta = update_channel()          # the cache is keyed per channel
    if not force and _chk_cache["data"] is not None \
            and _chk_cache["beta"] == beta \
            and time.time() - _chk_cache["ts"] < 900:
        return _chk_cache["data"]
    out = _check_update_live()
    if "note" not in out:
        _chk_cache.update(ts=time.time(), data=out, beta=beta)
    return out


def _check_update_live():
    try:
        rel = _channel_release()
    except urllib.error.HTTPError as exc:
        # 404 simply means the repo has no releases yet — not a failure
        note = ("No releases yet" if exc.code == 404
                else "HTTP %s" % exc.code)
        return {"configured": True, "available": False, "note": note}
    except Exception as exc:
        return {"configured": True, "available": False, "note": str(exc)[:120]}
    tag = rel.get("tag_name", "")
    # the tag is a build counter (v19); the release *title* is the version
    # people recognise (1.0.3) — show that, but still compare on the tag
    shown = (rel.get("name") or "").strip() or tag
    # betas all share a title ("6.0 beta") — append the tag's build so
    # the offer reads "6 beta 208", never "update 6.0.0 to 6.0.0"
    # betas all share one title, so the tag's build disambiguates them.
    # An RC does NOT get that treatment (6b258, per Patrick): "6.1 RC1"
    # is the name, and appending a build would put the number back.
    if re.search(r"beta$", shown):
        shown = "%s %d" % (shown, _build_from_tag(tag))
    # and the numeric part obeys the same trailing-.0 truncation: ONE .0,
    # as short_version does (6b242). The loop here kept going (6b537,
    # seen against a fake feed): the release named "7.0 beta 2" was
    # offered as "7 beta 2", a major line rather than a version
    mnum = re.match(r"^([\d.]+)(.*)$", shown)
    if mnum:
        num = mnum.group(1)
        if num.count(".") >= 2 and num.endswith(".0"):
            num = num[:-2]
        shown = num + mnum.group(2)
    dmg = next((a for a in rel.get("assets", [])
                if a.get("name", "").endswith(".dmg")), None)
    if dmg:
        _update["url"] = dmg["browser_download_url"]
        _update["size"] = dmg.get("size", 0)
    _update["latest"] = shown
    published = _gh_time(rel.get("published_at", ""))
    # a release is newer ONLY if its tag carries a higher build number.
    # (The old published-after-my-build-time clause false-alarmed on every
    # release when the bundle had been hot-patched: its mtime never moves,
    # so "Update available 2.0.1 — you have 2.0.1". Seen live.)
    if tag == "nightly":
        # a nightly is "newer" when its commit differs from ours; a
        # stable/beta install switching to nightly always gets one
        _m = re.search(r"nightly\s+([0-9a-f]{7,40})", rel.get("name") or "")
        _rsha = _m.group(1)[:7] if _m else ""
        _mine = APP_NIGHTLY.split()[-1] if APP_NIGHTLY else ""
        newer = bool(_rsha) and _rsha != _mine
    else:
        newer = _build_from_tag(tag) > APP_BUILD
        # never "update" to an older version (6b317, found testing in a
        # Windows VM): 6.0.4's tag v274 outnumbers the 6.1 code's
        # APP_BUILD 273, so a 6.1 build on the stable channel was offered
        # 6.0.4
        _rv = re.match(r"\s*(\d+(?:\.\d+)*)", rel.get("name") or "")
        if newer and _rv:
            def _vt(v):
                return (tuple(int(x) for x in v.split(".")) + (0, 0, 0))[:3]
            if _vt(_rv.group(1)) < _vt(APP_VERSION):
                newer = False
    # WINDOWS IS OFFERED ITS DOWNLOAD (6b317, from the Windows sweep):
    # "available" needed a .dmg and a Mac app bundle, so a PC was told
    # "You're up to date" beside a newer release's notes. There the offer
    # is the release's own Windows file (the .msi for an installed app,
    # the zip otherwise), opened in the browser: nothing installs itself.
    if not IS_MAC:
        _frozen = getattr(sys, "frozen", False)
        if _frozen and IS_WIN_ARM and not IS_WIN_EMULATED:
            # a native ARM64 install never gets the x64 installer (review):
            # its own .msi, or the release page when there is none
            def _mine(n):
                return n.endswith(".msi") and "arm64" in n.lower()
        elif _frozen:
            def _mine(n):
                return n.endswith(".msi") and "arm64" not in n.lower()
        else:
            def _mine(n):
                return n.endswith("-Windows.zip")
        win = next((a for a in rel.get("assets", [])
                    if _mine(a.get("name", ""))), None) or {}
        manual = (win.get("browser_download_url")
                  or rel.get("html_url") or "") if newer else ""
        _update["manual"] = manual
        return {"configured": True, "available": bool(manual),
                "manual": manual,
                "latest": shown, "tag": tag, "current": short_version(),
                "published": rel.get("published_at", ""),
                "notes": _release_notes(rel),
                "size_mb": round(win.get("size", 0) / 1e6, 1)}
    return {"configured": True,
            "available": bool(dmg) and newer
                         and _app_bundle_path() is not None,
            "latest": shown, "tag": tag, "current": short_version(),
            "published": rel.get("published_at", ""),
            "notes": _release_notes(rel),
            "size_mb": round(dmg.get("size", 0) / 1e6, 1) if dmg else 0}


_whatsnew_cache = {}


def whats_new(prev: str) -> dict:
    """The notes for THIS build, for the post-update dialog (6b288).
    Nightly (6b551): the newest numbered release's notes, or one plain
    line; its commit subjects (the rolling release's body, the compare
    API) were written for us and are never shown. Stable/beta: OUR
    release by tag — never the channel's newest, which may be a
    different build."""
    key = (prev or "", short_version())
    if key in _whatsnew_cache:
        return _whatsnew_cache[key]
    hdrs = {"Accept": "application/vnd.github+json",
            "User-Agent": "MillenAI"}

    def _get(path):
        req = urllib.request.Request(
            UPDATE_API + "/repos/%s/%s" % (UPDATE_REPO, path),
            headers=hdrs)
        with urllib.request.urlopen(req, timeout=8) as r:
            return json.loads(r.read().decode("utf-8"))
    notes = ""
    try:
        if APP_NIGHTLY:
            # a nightly: the newest numbered release's notes, or one plain
            # line; never its commit subjects (6b551)
            try:
                rels = _get("releases?per_page=20")
                notes = next(((x.get("body") or "")[:4000] for x in rels
                              if not x.get("draft")
                              and x.get("tag_name") != "nightly"
                              and (x.get("body") or "").strip()), "")
            except Exception:
                notes = ""
            notes = notes or _nightly_line()
        else:
            rel = _get("releases/tags/v%d" % APP_BUILD)
            notes = (rel.get("body") or "")[:4000]
    except Exception:
        notes = ""
    out = {"title": short_version(), "prev": prev or "", "notes": notes}
    _whatsnew_cache[key] = out
    return out


def _do_update():
    """Download the release DMG, then hand off to a helper that swaps the
    bundle after we quit and relaunches. Chats live in WebKit storage and
    memory in Application Support, so both survive the swap."""
    app = _app_bundle_path()
    if not app or not _update.get("url"):
        _update.update(state="error", note="no update available")
        return
    try:
        _update.update(state="downloading", pct=0, note="")
        tmp = tempfile.mkdtemp(prefix="millenai-up-")
        dmg = os.path.join(tmp, "update.dmg")
        req = urllib.request.Request(_update["url"],
                                     headers={"User-Agent": "MillenAI"})
        with urllib.request.urlopen(req, timeout=60) as r, open(dmg, "wb") as f:
            total = int(r.headers.get("Content-Length") or _update["size"] or 1)
            done = 0
            while True:
                chunk = r.read(262144)
                if not chunk:
                    break
                f.write(chunk)
                done += len(chunk)
                _update["pct"] = min(99, int(done / total * 100))
        _update.update(state="installing", pct=100)
        script = os.path.join(tmp, "swap.sh")
        with open(script, "w", encoding="utf-8") as f:
            f.write(_SWAP_SCRIPT % {"app": app, "dmg": dmg, "tmp": tmp})
        os.chmod(script, 0o755)
        subprocess.Popen(["/bin/zsh", script], start_new_session=True)
        _update["state"] = "restarting"
        ctx_timer(1.5, lambda: os._exit(0)).start()
    except Exception as exc:
        _update.update(state="error", note=str(exc)[:180])


# ------------------------------------------------------------- memory
# Lasting facts about the user (name, job, interests…) live in a local
# JSON file and are folded into the system prompt of every chat, so any
# model can reference them across conversations. Extraction runs in the
# background after each message, using the model that just answered
# (it's already loaded — no engine thrash).
# Chats live on disk, not in browser storage: WebKit keys its storage to
# the process's bundle identity, and the app runs as the venv's python3
# (org.python.python) whether started from source or from the .app, so its
# WebKit store is Python's, shared with every pywebview app that Python
# runs, and isn't guaranteed to survive a Python update. These files are
# the app's own.
#
# Every function below takes a `base`: the ProfileCtx the files belong
# to (6b329; it was a folder, None meaning app_dir()).


# ==== profile: begin ====
# PROFILES (1a 5.2-5.7, accounts step 8, 6b329). One profile is active per
# process: "This computer" (the data folder itself, laid out as before)
# or one folder under accounts/ (a local test profile until accounts
# exist). Each activation carries a random 64-bit epoch. Every personal
# read and write goes through the ctx of the profile it belongs to:
#   * a request takes current_ctx() once, at its start (StudioHandler._run),
#     and binds it to its thread;
#   * a background job runs on the ctx of whoever started it: ctx_thread
#     and ctx_timer carry the starting thread's ctx into the new thread,
#     and bound_ctx() reads it back. Nothing but a request's start, the
#     boot and a switch asks which profile is active (the gauntlet's
#     AST check);
#   * a write under a ctx that is no longer the active one raises
#     StaleProfile, writes nothing and creates nothing (no file, no
#     folder), and is counted.
# This section is the only code that writes a personal file, makes a
# folder or replaces a file for a profile. Machine files (models,
# engines, run/, logs, the backdrops, the updater) are written by the
# functions MACHINE_IO names, which never touch a ctx. The gauntlet
# lints both, and every module-level container is declared a
# profile_cache (personal: emptied at every switch) or MACHINE_STATE.

def _pfile(name: str, base) -> str:
    """A personal or machine file's path. base is a ProfileCtx, or
    MACHINE_ROOT for the machine's own files in the data folder. A
    missing base is a bug, never "the data folder" (6b329): that was how
    a write reached the wrong profile. A personal file is never the
    machine's (review of 6b329): MACHINE_ROOT skips the epoch check."""
    if isinstance(base, ProfileCtx):
        return os.path.join(base.dir, name)
    if isinstance(base, _MachineRoot):
        if name.replace("\\", "/").split("/")[0] in PERSONAL_NAMES:
            raise NoProfile("%s is a profile's, not the machine's" % name)
        return os.path.join(base.dir, name)
    raise NoProfile("no profile for %s" % name)


# THE FILES (0b 5.2, 6b324). "This computer" keeps its chats and memory
# in the .v2 files. chats.json and memory.json are the pre-Phase-0 files
# that older builds keep using: this build never writes anything new
# into them, it only takes out what has left the .v2 files (0b L7, 5.8).
# profile.json holds legacy_base (what the legacy files held at this
# build's last look), the record of which root files have had their
# first write, and (6b329) which profile is active and its epoch.
CHATS_FILE = "chats.v2.json"
MEMORY_FILE = "memory.v2.json"
LEGACY_CHATS = "chats.json"
LEGACY_MEMORY = "memory.json"
PROFILE_FILE = "profile.json"
# an account folder's settings (1a 5.6): the synced ones, and the ones
# that stay with this profile on this computer. "This computer" keeps
# both in prefs.json, as before
PERSONAL_FILE = "personal.json"
QUALITY_FILE = "quality.jsonl"   # one line per answer (1a 5.7: per profile)
LOCAL_FILE = "local.json"
# an account folder's first-write record (1a 5.2; root's is profile.json)
STATE_FILE = "sync/state.json"
ACCOUNTS_DIR = "accounts"
# a profile's own files and folders: never reached through MACHINE_ROOT
PERSONAL_NAMES = frozenset((
    CHATS_FILE, MEMORY_FILE, LEGACY_CHATS, LEGACY_MEMORY, PERSONAL_FILE,
    LOCAL_FILE, QUALITY_FILE, "usage.jsonl", "cloud.json", "remote.json",
    "remote_known_hosts", "bench_targets.jsonl", "suggest.json", "images", "videos",
    "exports", "sync",
    "know", "know.json",       # (6b530) the index of your stuff, and its settings
    "account.key", "servers.json", "imports"))      # imports (6b529): the brought-in chats' ledger and pictures
# absent means "not written yet" for these only until their first write
# (0b 5.2, L1); after it a missing file is a read error, never empty
_FIRST_WRITE = (CHATS_FILE, MEMORY_FILE, "prefs.json", PERSONAL_FILE,
                LOCAL_FILE)


class StoreReadError(Exception):
    """A personal file is there but can't be read (0b L1, 6b322). It is
    never taken for empty: the route answers 503 and nothing that
    depends on it is written. Only a file that isn't there yet reads as
    empty. The argument is the file's name."""


class StaleProfile(OSError):
    """A write under a profile that is no longer the active one (1a 5.2).
    Nothing was written or created. An OSError, so every writer that
    already treats a failed write as "not saved" drops it the same way."""


class NotLanded(OSError):
    """A finished file that couldn't be moved into its profile: it is
    kept in run/ and the message says where (never a reason to make it
    again elsewhere, or with a paid key)."""


class NoProfile(RuntimeError):
    """Personal work with no ctx: a thread nobody gave one, or a call
    that passed none. A bug, and it fails closed."""


# what the page shows for each (0b 5.12, Q11). profile.json and the
# legacy files are read for the chat store, so they say "chats"
_RF_CHATS = "Couldn’t read your chats. Nothing changed."
_RF_MEMORY = "Couldn’t read your memories. Nothing changed."
_RF_PREFS = "Couldn’t read your settings. Nothing changed."
READ_FAIL = {CHATS_FILE: _RF_CHATS, LEGACY_CHATS: _RF_CHATS,
             PROFILE_FILE: _RF_CHATS, STATE_FILE: _RF_CHATS,
             MEMORY_FILE: _RF_MEMORY, LEGACY_MEMORY: _RF_MEMORY,
             "prefs.json": _RF_PREFS, PERSONAL_FILE: _RF_PREFS,
             LOCAL_FILE: _RF_PREFS}

_profile_lock = threading.RLock()   # the innermost lock: taken last
# the active profile: {"ctx": ProfileCtx, "stale": writes refused}
_PROFILE = {"ctx": None, "stale": 0, "aside": None}
_written = {}           # folder -> the _FIRST_WRITE names it has written
_tl_ctx = threading.local()         # the ctx this thread works for
# THE PAGE SEES EVERY MODEL CALL (6b528, per Patrick: "shows number of
# tokens and everything"): a chat request installs a tap on its thread,
# every thread the run starts (ctx_thread) carries it, and each
# usage_note() of the run — a draft here, a cloud seat's, the critic's,
# the final writer's, the fact-check's — also goes to the page as a USAGE
# frame. `role` names the stage the thread is in. The handler clears the
# tap as the stream ends, so a memory pass after it reports nowhere.
_tl_usage = threading.local()


class _MachineRoot:
    """The data folder as the machine's: prefs.json's MACHINE keys and
    the other machine files. Never epoch-checked; never personal."""
    kind = "machine"

    @property
    def dir(self):
        return app_dir()


MACHINE_ROOT = _MachineRoot()


class ProfileCtx:
    """One activation of one profile (1a 5.2): kind "local" ("This
    computer", the data folder) or "test" (a local test profile under
    accounts/, dev copies only; "account" from M9). The epoch is random
    per activation and names it on the wire (X-Profile). cancel is set
    when the profile stops being the active one: streams and background
    jobs watch it."""
    __slots__ = ("epoch", "kind", "dir", "name", "acct_id", "cancel")

    def __init__(self, kind: str, folder: str, name: str = "local",
                 acct_id=None):
        self.epoch = secrets.token_hex(8)
        self.kind, self.dir, self.name = kind, folder, name
        self.acct_id = acct_id
        self.cancel = threading.Event()

    def __repr__(self):
        return "<profile %s.%s>" % (self.name, self.epoch[:4])

    @property
    def tag(self) -> str:
        """"<dir|local>.<epoch>": the page's __PROFILE__ and X-Profile."""
        return "%s.%s" % (self.name, self.epoch)

    @property
    def root(self) -> bool:
        return self.kind == "local"

    def alive(self) -> bool:
        return _PROFILE["ctx"] is self

    def check(self):
        """StaleProfile unless this is still the active profile (or the
        root ctx a switch holds aside while an account is still active:
        _aside_root, M9)."""
        if _PROFILE["ctx"] is not self and _PROFILE.get("aside") is not self:
            _PROFILE["stale"] += 1
            raise StaleProfile("the profile changed; not written")

    def path(self, *parts) -> str:
        """A path in this profile's folder, for READING (listings, the
        media routes). Writes go through the methods below."""
        return os.path.join(self.dir, *parts)

    def read(self, name: str, want=dict):
        return _read_json(name, self, want)

    def write(self, name: str, data, **dump) -> str:
        return _write_json(name, data, self, **dump)

    def write_bytes(self, name: str, raw: bytes, mode=None) -> str:
        return _write_raw(name, raw, self, mode=mode)

    def update_json(self, name: str, fn, want=dict, **dump):
        """The read, fn(value) and the write inside one lock (1a 5.2).
        fn gets the file's value (None when absent) and returns the new
        one, or None to write nothing. Returns what fn returned."""
        with _profile_lock:
            self.check()
            new = fn(_read_json(name, self, want))
            if new is not None:
                _write_json(name, new, self, **dump)
            return new

    def append(self, name: str, raw: bytes, mode=0o600):
        """raw added at the end of a log in this profile (quality.jsonl,
        usage.jsonl), fsynced."""
        _append_raw(name, raw, self, mode)

    def adopt(self, src: str, name: str) -> str:
        """Move a file made in run/ (stage_path) into this profile as
        name: a render, a download or an export lands whole, and only
        while this profile is active. Stale: src is deleted and
        StaleProfile raised, so nothing reaches either profile. Any other
        failure leaves src where it is."""
        try:
            with _profile_write(self):
                p = _pfile(name, self)
                _ensure_parent(p, self)
                try:
                    _replace_into(src, p)
                except OSError:
                    # a reader holding it (Windows, an antivirus): a copy,
                    # then the original goes; a finished render is never
                    # deleted because it couldn't be moved (review of
                    # 6b329). If that fails too, src stays in run/ (until
                    # the next start) and the error says where, relative to
                    # the data folder: no user name reaches the chat
                    try:
                        shutil.copyfile(src, p)
                    except OSError as exc:
                        _unlink_quiet(p)
                        raise NotLanded(
                            "couldn't save it into ConcordeAI's folder (%s); "
                            "it is kept at %s until the app next starts" % (
                                exc.strerror or exc.__class__.__name__,
                                os.path.relpath(src, app_dir()))) from exc
                    _unlink_quiet(src)
                return p
        except StaleProfile:
            _unlink_quiet(src)
            raise

    def remove(self, name: str) -> bool:
        """Delete one file of this profile (an expired export, a render's
        leftovers). False when it wasn't there."""
        with _profile_write(self):
            try:
                os.remove(_pfile(name, self))
                return True
            except FileNotFoundError:
                return False


def _unlink_quiet(p) -> bool:
    """Remove p if it is there; True when it went."""
    try:
        os.remove(p)
        return True
    except OSError:
        return False


# RUN/PROFILE.LOCK (1a 5.1). Every profile write and every switch holds
# it, beside the in-process lock, so nothing else writing this folder can
# interleave. Taken once per outermost write (a depth count: flock and
# msvcrt both release on the first unlock).
_PFL = {"f": None, "depth": 0, "bad": False}


@contextlib.contextmanager
def _profile_flock():
    with _profile_lock:
        first = _PFL["depth"] == 0
        locked = False
        if first and not _PFL["bad"] and _PFL["f"] is None:
            try:
                d = os.path.join(app_dir(), "run")
                os.makedirs(d, mode=0o700, exist_ok=True)
                _PFL["f"] = open(os.path.join(d, "profile.lock"), "a+")
            except OSError:
                # a folder where run/ can't be made: the in-process lock
                # alone for this run (single_instance already let it run)
                _PFL["bad"] = True
        if first and _PFL["f"] is not None:
            try:
                if IS_WIN:
                    import msvcrt
                    _PFL["f"].seek(0)
                    msvcrt.locking(_PFL["f"].fileno(), msvcrt.LK_LOCK, 1)
                else:
                    import fcntl
                    fcntl.flock(_PFL["f"].fileno(), fcntl.LOCK_EX)
                locked = True
            except (OSError, ImportError):
                # this write goes under the in-process lock alone; the
                # next one tries the flock again (review of 6b329: one
                # failure used to turn it off for the whole run)
                pass
        _PFL["depth"] += 1
        try:
            yield
        finally:
            _PFL["depth"] -= 1
            if locked:
                try:
                    if IS_WIN:
                        import msvcrt
                        _PFL["f"].seek(0)
                        msvcrt.locking(_PFL["f"].fileno(), msvcrt.LK_UNLCK, 1)
                    else:
                        import fcntl
                        fcntl.flock(_PFL["f"].fileno(), fcntl.LOCK_UN)
                except (OSError, ImportError):
                    pass


@contextlib.contextmanager
def _profile_write(base):
    """Around every write: for a profile, the lock, the flock and the
    epoch check, held until the file is in place, so a switch can't
    slip between the check and the replace. A machine file (or a test's
    plain folder) has no epoch."""
    if not isinstance(base, ProfileCtx):
        yield
        return
    with _profile_lock, _profile_flock():
        base.check()
        yield


def _ensure_parent(p: str, base):
    """The file's folder. A profile's own folder is never made here: one
    that is gone stays gone (a late write for an erased profile creates
    nothing, ISO-7); only a subfolder of a live one (images/, sync/)."""
    d = os.path.dirname(p)
    if isinstance(base, ProfileCtx):
        if not os.path.isdir(base.dir):
            raise StaleProfile("the profile's folder is gone; not written")
        if os.path.normcase(os.path.realpath(d)) != os.path.normcase(
                os.path.realpath(base.dir)):
            os.makedirs(d, exist_ok=True)
        return
    os.makedirs(d, exist_ok=True)


def _bk(base) -> str:
    """One key per data folder."""
    if isinstance(base, (ProfileCtx, _MachineRoot)):
        base = base.dir
    return os.path.realpath(base or app_dir())


def _written_file(base) -> str:
    """Where a folder records its first writes: profile.json for "This
    computer", sync/state.json for an account folder (1a 5.2)."""
    if isinstance(base, ProfileCtx) and not base.root:
        return STATE_FILE
    return PROFILE_FILE


def _was_written(name: str, base) -> bool:
    """The first-write record of each _FIRST_WRITE file.
    Can't tell (the record unreadable): StoreReadError for name."""
    k = _bk(base)
    with _profile_lock:
        if k not in _written:
            try:
                p = _read_json(_written_file(base), base, dict) or {}
            except StoreReadError as exc:
                raise StoreReadError(name) from exc
            w = p.get("written")
            _written[k] = set(x for x in w if isinstance(x, str)) \
                if isinstance(w, list) else set()
        return name in _written[k]


def _mark_written(name: str, base):
    """Record a first write. A record that can't be made now is made at
    the file's next write."""
    with _profile_lock:
        try:
            if _was_written(name, base):
                return
            wf = _written_file(base)
            p = _read_json(wf, base, dict) or {}
            w = p.get("written")
            w = [x for x in w if isinstance(x, str)] if isinstance(w, list) else []
            p["written"] = w + [name]
            _write_json(wf, p, base, indent=1)
            _written[_bk(base)].add(name)
        except (StoreReadError, OSError):
            pass


def _read_json(name: str, base, want):
    """The file's JSON; None when it isn't there (and, for a _FIRST_WRITE
    file, hasn't been written yet); StoreReadError when it is there and
    can't be read, or isn't the shape it must be."""
    return _read_json_h(name, base, want)[0]


def _read_json_h(name: str, base, want):
    """(the JSON, sha256 of its bytes), or (None, None) when absent."""
    try:
        with open(_pfile(name, base), "rb") as f:
            raw = f.read()
    except FileNotFoundError:
        if name in _FIRST_WRITE and _was_written(name, base):
            raise StoreReadError(name)
        return None, None
    except Exception as exc:
        raise StoreReadError(name) from exc
    try:
        d = json.loads(raw.decode("utf-8"))
    except Exception as exc:
        raise StoreReadError(name) from exc
    if not isinstance(d, want):
        raise StoreReadError(name)
    return d, hashlib.sha256(raw).hexdigest()


def _write_json(name: str, data, base, **dump) -> str:
    """Atomic (0b L2): a unique temp file beside it, then os.replace, so a
    crash leaves the old file or the new one and two saves never rename
    each other's half-written file into place (the 6b304 prefs lesson).
    Under a profile, epoch-checked (1a 5.2). Returns the sha256 of the
    bytes written."""
    return _write_raw(name, json.dumps(data, **dump).encode("utf-8"), base)


def _write_raw(name: str, raw: bytes, base, mode=None) -> str:
    with _profile_write(base):
        p = _pfile(name, base)
        _ensure_parent(p, base)
        fd, tmp = tempfile.mkstemp(dir=os.path.dirname(p),
                                   prefix="." + os.path.basename(name).split(".")[0] + "-",
                                   suffix=".tmp")
        try:
            if mode is not None and not IS_WIN:
                os.fchmod(fd, mode)
            with os.fdopen(fd, "wb") as f:
                f.write(raw)
                f.flush()
                os.fsync(f.fileno())
            _replace_into(tmp, p)
        except BaseException:
            _unlink_quiet(tmp)
            raise
        if name in _FIRST_WRITE:
            _mark_written(name, base)
    return hashlib.sha256(raw).hexdigest()


def _append_raw(name: str, raw: bytes, base, mode=0o600):
    """raw at the end of a log, fsynced; under a profile, epoch-checked."""
    with _profile_write(base):
        p = _pfile(name, base)
        _ensure_parent(p, base)
        fd = os.open(p, os.O_WRONLY | os.O_CREAT | os.O_APPEND
                     | getattr(os, "O_BINARY", 0), mode)
        try:
            view = memoryview(raw)
            while view:
                view = view[os.write(fd, view):]
            os.fsync(fd)
        finally:
            os.close(fd)


def _replace_into(tmp: str, dst: str):
    """os.replace, waiting out a reader on Windows (6b317, from the
    Windows sweep): there a file can't be replaced while another thread
    has it open, so a save that met a read raised and was lost."""
    for n in range(20):
        try:
            os.replace(tmp, dst)
            return
        except PermissionError:
            if not IS_WIN or n == 19:
                raise
            time.sleep(0.05)


def _set_aside(name: str, base, suffix: str) -> str:
    """Rename a personal file that can't be read out of the way, bytes
    kept (_migrate_61's memory.json). The new name."""
    with _profile_write(base):
        src = _pfile(name, base)
        dst = src + suffix
        os.replace(src, dst)
        return os.path.basename(dst)


def stage_path(suffix: str = "") -> str:
    """A new name under run/ (nothing made yet) for a render, a download
    or an export to be made at; ctx.adopt moves it into the profile when
    it's whole. A crash's leftovers go at the next start
    (sweep_run_files)."""
    d = os.path.join(app_dir(), "run")
    os.makedirs(d, mode=0o700, exist_ok=True)
    return os.path.join(d, "stage-" + secrets.token_hex(12) + suffix)


def _hook_delay(name: str):
    """The `delay-<name>=<seconds>` test hook (1a 5.13, dev copies only):
    a slow writer, for the stale-write checks."""
    v = _hook_arg("delay-" + name)
    if v:
        try:
            time.sleep(min(float(v), 60.0))
        except ValueError:
            pass


# ------------------------------------------------ the context, captured
def current_ctx() -> ProfileCtx:
    """The active profile. Only a request's start, the boot, a switch and
    the test hooks ask (the gauntlet's AST check): everything else uses
    the ctx it was given or captured."""
    c = _PROFILE["ctx"]      # one read: no lock, so a request never
    if c is None:            # waits behind a write (review of 6b329)
        raise NoProfile("no profile is active yet")
    return c


def bound_ctx() -> ProfileCtx:
    """The ctx this thread works for: its request's, or the one its
    starter handed it (ctx_thread). Never "whatever is active now"."""
    c = getattr(_tl_ctx, "ctx", None)
    if c is None:
        raise NoProfile("this thread has no profile")
    return c


def bind_ctx(ctx):
    """Bind ctx to this thread (None unbinds); the previous binding."""
    old = getattr(_tl_ctx, "ctx", None)
    _tl_ctx.ctx = ctx
    return old


def _ctx_wrap(fn, ctx):
    # the starter's usage tap and stage ride along (6b528): a cloud seat's
    # thread, a server group's, the fact-check's all report into the page
    # that asked, as the request's own thread does
    tap = getattr(_tl_usage, "tap", None)
    role = getattr(_tl_usage, "role", "")

    @functools.wraps(fn)
    def run(*a, **k):
        prev = bind_ctx(ctx)
        _tl_usage.tap, _tl_usage.role = tap, role
        try:
            return fn(*a, **k)
        finally:
            bind_ctx(prev)
            _tl_usage.tap, _tl_usage.role = None, ""
    return run


def ctx_thread(target, ctx=None, bind=True, **kw):
    """threading.Thread(target=..., **kw) whose target runs on ctx, or on
    the starting thread's own ctx (none for machine work started at
    boot); bind=False: on none, for machine work that serves every
    profile (the usage writer). The only way this file starts a thread
    (the gauntlet's lint)."""
    c = ctx if ctx is not None else (
        getattr(_tl_ctx, "ctx", None) if bind else None)
    return threading.Thread(target=_ctx_wrap(target, c), **kw)


def ctx_executor(max_workers: int):
    """A thread pool whose workers run on the starting thread's ctx (the
    only pool this file makes; the gauntlet's lint)."""
    import concurrent.futures as _cf
    return _cf.ThreadPoolExecutor(
        max_workers=max_workers, initializer=bind_ctx,
        initargs=(getattr(_tl_ctx, "ctx", None),))


def ctx_timer(interval, fn, args=(), ctx=None):
    c = ctx if ctx is not None else getattr(_tl_ctx, "ctx", None)
    t = threading.Timer(interval, _ctx_wrap(fn, c), args)
    t.daemon = True
    return t


# ------------------------------------------- the settings split (1a 5.6)
# Section 3's table in three sets. SYNCED_SETTINGS describe the person and
# ride with an account (none spends money or acts on a server);
# PROFILE_LOCAL are this profile's own on this computer and never sync;
# MACHINE is the hardware's. "This computer" keeps all three in
# prefs.json, as before; an account keeps SYNCED_SETTINGS in personal.json
# and PROFILE_LOCAL in local.json, and reads MACHINE from prefs.json.
SYNCED_SETTINGS = frozenset((
    "user_name", "persona", "length", "home_area", "funnel_effort",
    "funnel_cloud", "polish", "suggest_own"))
PROFILE_LOCAL = frozenset((
    "turbo", "tier", "model", "council", "agent", "codeagent", "adv", "advon",
    "remote_autonomy", "workspace", "veo_day", "veo_count", "veo_daily_cap",
    "lend", "lend_pick", "studio_opts.*.neg", "mic_warm",
    "cloud_balance", "comps"))
MACHINE = frozenset((
    "app_models", "model_offers", "no_limits", "include_giants",
    "auto_cleanup", "studio_image", "studio_video", "studio_opts",
    "update_channel", "beta_updates", "auto_update_check", "last_ident",
    "last_version", "wizard_done", "seen_models", "remind_models_ts",
    "remind_models_off", "model_set", "model_set_had"))
# whole families of machine keys: studio_* (the negative prompt, which
# PROFILE_LOCAL names by path, apart), last_*, seen_*, remind_*, and the
# retired Contribute keys the boot sweep removes
MACHINE_PREFIXES = ("studio_", "last_", "seen_", "remind_", "contrib_",
                    "fleet_")
# the Studio's negative prompt: text the person typed, so it is theirs
STUDIO_NEG = "neg"
# profile-local keys that hold a real boolean and nothing else (6b429): a
# string "true" or a 1 from a stray client is ignored, not saved
LOCAL_BOOL = ("mic_warm",)


def comps_ok(v) -> bool:
    """"comps" (6b442): each mode's chosen compositor, {mode id: compositor id},
    both short strings, a few dozen at most. Anything else is ignored."""
    return (isinstance(v, dict) and len(v) <= 64
            and all(isinstance(k, str) and 0 < len(k) <= 80 and isinstance(x, str)
                    and 0 < len(x) <= 160 for k, x in v.items()))

# KEY-2: every value a synced key may hold. None of them turns on the
# cloud, cloud-only, the bench or the Remote agent, and no key here is a
# spending or action setting (the three-set test and KEY-2 check both).
SYNCED_ALLOWED = {
    "user_name": ("text", 80),
    "persona": ("text", 2000),
    "home_area": ("text", 200),
    "length": ("one of", (1, 2, 3, 4, 5)),
    "funnel_effort": ("one of", ("fast", "normal")),
    # "Include cloud models" (6b339): it can only keep the cloud OUT of a
    # funnel; cloud power and a key still decide whether any is asked
    "funnel_cloud": ("one of", (True, False)),
    "polish": ("one of", (True, False)),
    # "Personalise suggestions" (6b390): the starter chips follow the chats
    "suggest_own": ("one of", (True, False)),
}


def synced_value_ok(k: str, v) -> bool:
    rule = SYNCED_ALLOWED.get(k)
    if rule is None:
        return False
    kind, arg = rule
    if kind == "text":
        return isinstance(v, str) and len(v) <= arg
    return any(v == a and type(v) is type(a) for a in arg)


def pref_class(k: str):
    """"synced", "local", "machine", or None for a key no set names."""
    if not isinstance(k, str):
        return None
    if k in SYNCED_SETTINGS:
        return "synced"
    if k in PROFILE_LOCAL:
        return "local"
    if k in MACHINE or k.startswith(MACHINE_PREFIXES):
        return "machine"
    return None


class PrefScopeError(KeyError):
    """A settings key read through the wrong accessor: a sorting bug,
    loud rather than an empty value (6b329)."""


class _Scoped(dict):
    """One set's keys as a profile holds them. Reading a key of another
    set raises PrefScopeError, so a missorted reader can't quietly get
    None where "This computer" used to get a value. unread: the file
    couldn't be read (0b Q11: fine to read "off" from, never saved)."""
    cls = None
    unread = False

    def _ok(self, k):
        if pref_class(k) != self.cls:
            raise PrefScopeError("%s is not a %s setting" % (k, self.cls))

    def get(self, k, default=None):
        self._ok(k)
        return dict.get(self, k, default)

    def __getitem__(self, k):
        self._ok(k)
        return dict.__getitem__(self, k)

    def __contains__(self, k):
        self._ok(k)
        return dict.__contains__(self, k)


class _Unread(dict):
    """The {} a failed settings read hands to a caller that isn't strict:
    fine to read "off" from, never saved (review of 6b322)."""


def load_prefs(base, strict=False) -> dict:
    """prefs.json as it is. strict: an unreadable file raises
    StoreReadError; otherwise an empty _Unread, which store_prefs refuses
    to save. Only the accessors below call it (6b329): the rest of the
    app asks machine_prefs, user_prefs(ctx) or profile_local(ctx)."""
    try:
        return _read_json("prefs.json", base, dict) or {}
    except StoreReadError:
        if strict:
            raise
        return _Unread()


_prefs_lock = threading.RLock()


def store_prefs(d: dict, base):
    """Atomic, with a UNIQUE temp file per save (6b304). Callers that
    read-modify-write take _prefs_lock. A file on disk that can't be read
    is never written over (0b L1, 6b322): every caller read it first, so
    whatever it holds now was built on an empty read."""
    if isinstance(d, _Unread):
        raise StoreReadError("prefs.json")
    _read_json("prefs.json", base, dict)
    _write_json("prefs.json", d, base)


def _neg_of(opts) -> dict:
    """{studio key: its negative prompt} from a studio_opts value."""
    out = {}
    if isinstance(opts, dict):
        for k, v in opts.items():
            if isinstance(v, dict) and STUDIO_NEG in v:
                out[k] = v[STUDIO_NEG]
    return out


def _scope(cls: str, src: dict, unread=False) -> _Scoped:
    s = _Scoped()
    s.cls, s.unread = cls, unread
    for k, v in (src or {}).items():
        if pref_class(k) == cls:
            dict.__setitem__(s, k, v)
    if cls == "machine" and isinstance(s.get("studio_opts"), dict):
        dict.__setitem__(s, "studio_opts", {
            k: {f: x for f, x in v.items() if f != STUDIO_NEG}
            if isinstance(v, dict) else v
            for k, v in s["studio_opts"].items()})
    if cls == "local":
        neg = _neg_of((src or {}).get("studio_opts"))
        if neg:
            dict.__setitem__(s, "studio_opts.*.neg", neg)
    return s


def _pref_home(ctx, cls: str):
    """(base, file) where cls lives for ctx."""
    if cls == "machine" or ctx.root:
        return (MACHINE_ROOT if cls == "machine" else ctx), "prefs.json"
    return ctx, (PERSONAL_FILE if cls == "synced" else LOCAL_FILE)


def _pref_read(base, name: str, strict: bool):
    try:
        return _read_json(name, base, dict) or {}, False
    except StoreReadError:
        if strict:
            raise
        return {}, True


def machine_prefs(strict=False) -> _Scoped:
    """The machine's settings (MACHINE), from the data folder's
    prefs.json whatever profile is active."""
    d, bad = _pref_read(MACHINE_ROOT, "prefs.json", strict)
    return _scope("machine", d, bad)


def user_prefs(ctx, strict=False) -> _Scoped:
    """ctx's SYNCED_SETTINGS."""
    base, name = _pref_home(ctx, "synced")
    d, bad = _pref_read(base, name, strict)
    return _scope("synced", d, bad)


def profile_local(ctx, strict=False) -> _Scoped:
    """ctx's PROFILE_LOCAL settings; "studio_opts.*.neg" is {studio key:
    negative prompt}."""
    base, name = _pref_home(ctx, "local")
    d, bad = _pref_read(base, name, strict)
    return _scope("local", d, bad)


def _prefs_rmw(ctx, cls: str, fn):
    """Read-modify-write one set's keys where they live for ctx, under
    _prefs_lock (and, for a profile, the epoch check): fn gets a plain
    dict of that set's keys and changes it in place; only those keys
    change in the file, the others are written back as read. An
    unreadable file raises StoreReadError and is left alone."""
    base, name = _pref_home(ctx, cls)
    with _prefs_lock:
        if isinstance(base, ProfileCtx):
            base.check()
        cur = _read_json(name, base, dict) or {}
        view = dict(_scope(cls, cur))
        before = json.dumps(view, sort_keys=True, default=str)
        fn(view)
        if json.dumps(view, sort_keys=True, default=str) == before:
            return view
        neg = view.pop("studio_opts.*.neg", None) if cls == "local" else None
        out = {k: v for k, v in cur.items() if pref_class(k) != cls}
        for k, v in view.items():
            if pref_class(k) == cls:
                out[k] = v
        # studio_opts is shared by path (1a 5.6): the machine's fields and
        # the profile's negative prompt. "This computer" keeps both in one
        # value, so each side writes back the other's part as it was
        was = _neg_of(cur.get("studio_opts"))
        if cls == "machine" and was:
            so = out.get("studio_opts")
            so = {k: dict(v) if isinstance(v, dict) else {}
                  for k, v in so.items()} if isinstance(so, dict) else {}
            for k, v in was.items():
                so.setdefault(k, {})[STUDIO_NEG] = v
            out["studio_opts"] = so
        elif cls == "local" and (neg or was):
            so = out.get("studio_opts")
            so = {k: {f: x for f, x in v.items() if f != STUDIO_NEG}
                  if isinstance(v, dict) else {}
                  for k, v in so.items()} if isinstance(so, dict) else {}
            for k, v in (neg or {}).items():
                so.setdefault(k, {})[STUDIO_NEG] = v
            if so:
                out["studio_opts"] = so
            else:
                out.pop("studio_opts", None)
        # read strictly above, so nothing here was built on an empty read
        _write_json(name, out, base)
        return view


def machine_prefs_update(fn):
    """fn(dict of the MACHINE keys) changes them in place."""
    return _prefs_rmw(None, "machine", fn)


def user_prefs_update(ctx, fn):
    return _prefs_rmw(ctx, "synced", fn)


def profile_local_update(ctx, fn):
    return _prefs_rmw(ctx, "local", fn)


def prefs_view(ctx, strict=True) -> dict:
    """GET /api/prefs: what the page reads, for ctx. "This computer": the
    whole prefs.json, as before. An account: the machine's keys, then its
    own two files."""
    if ctx.root:
        return load_prefs(ctx, strict=strict)
    out = dict(machine_prefs(strict))
    out.update(user_prefs(ctx, strict))
    loc = dict(profile_local(ctx, strict))
    neg = loc.pop("studio_opts.*.neg", None)
    out.update(loc)
    if neg:
        so = dict(out.get("studio_opts") or {})
        for k, v in neg.items():
            so[k] = dict(so.get(k) or {}, **{STUDIO_NEG: v})
        out["studio_opts"] = so
    return out


def split_prefs(ctx, incoming: dict, old=None) -> dict:
    """POST /api/prefs (1a 5.6, 4.7): each key to its own place, as
    compare-and-set. Only keys whose value changes are written. With
    old ({key: the value the page last saw}), a key whose saved value is
    no longer that one is a conflict and isn't written. A key no set
    names, and a synced value outside its allowed set (KEY-2), is
    ignored. {"ok", "changed", "conflict", "ignored"}."""
    by = {"synced": {}, "local": {}, "machine": {}}
    ignored = []
    for k, v in (incoming or {}).items():
        c = pref_class(k)
        if c is None or k == "studio_opts.*.neg" or (
                c == "synced" and not synced_value_ok(k, v)) or (
                k in LOCAL_BOOL and not isinstance(v, bool)) or (
                k == "comps" and not comps_ok(v)):
            ignored.append(k)
        else:
            by[c][k] = v
    changed, conflict = [], {}

    def apply(want):
        def fn(view):
            for k, v in want.items():
                if isinstance(old, dict) and k in old \
                        and view.get(k) != old[k]:
                    conflict[k] = view.get(k)
                    continue
                if k not in view or view[k] != v:
                    view[k] = v
                    changed.append(k)
        return fn
    # the profile's own keys first, the machine's last: a switch landing
    # between them refuses the profile's write, and the 409 means nothing
    # changed (review of 6b329)
    if by["synced"]:
        user_prefs_update(ctx, apply(by["synced"]))
    if by["local"]:
        profile_local_update(ctx, apply(by["local"]))
    if by["machine"]:
        if isinstance(ctx, ProfileCtx):
            ctx.check()
        machine_prefs_update(apply(by["machine"]))
    return {"ok": True, "changed": sorted(changed), "conflict": conflict,
            "ignored": sorted(ignored)}


# ------------------------------------------------ boot and the switch
# profile.json (1a 5.1): {"active": "local"|"<dir>", "kept": null|{...},
# "epoch": "<64-bit hex>", "pending_import": bool, "legacy_base": {...}
# (0b, 6b324), "written": [...]} plus migrated_61 and webstore (6b324).
# 1a's fields are written here; M5's are left exactly as they are.
_INSTANCE_HELD = [False]      # this process holds run/instance.lock


def _profile_json_update(fn):
    """Read-modify-write root's profile.json (the machine's record of the
    active profile; not epoch-checked, since it is what a switch moves)."""
    with _profile_lock, _profile_flock():
        p = _read_json(PROFILE_FILE, MACHINE_ROOT, dict) or {}
        fn(p)
        _write_json(PROFILE_FILE, p, MACHINE_ROOT, indent=1)
        return p


def _profile_fields(p: dict, ctx) -> dict:
    if "active" not in p and ctx.root and _undecided():
        # a lost record with folders under accounts/ (see profile_resume):
        # "active" stays unwritten until a person decides, so no switch
        # makes them read as unnamed (M9)
        p["epoch"] = ctx.epoch
        return p
    p["active"] = "local" if ctx.root else ctx.name
    p.setdefault("kept", None)
    p["epoch"] = ctx.epoch
    p.setdefault("pending_import", False)
    return p


def _test_profile_ok(folder: str) -> bool:
    """A local test profile's folder, which only a dev copy with the
    profiles hook opens (1a 9: a build without the hook refuses a key
    file carrying test:true), and only when its .owner verifies (M9)."""
    return _account_openable(folder, os.path.basename(
        os.path.normpath(folder))) is not None


def profile_boot() -> ProfileCtx:
    """At every start, before anything is read: "This computer" becomes
    the active profile with a new epoch, so the boot order (_migrate_61,
    the downgrade import) runs through a root ctx (1a 5.1, I7). The copy
    holding the instance lock seeds `written` with the root files that
    exist (each has been written)."""
    ctx = ProfileCtx("local", app_dir())
    with _profile_lock:
        _PROFILE["ctx"] = ctx
    if _INSTANCE_HELD[0]:
        for n in _FIRST_WRITE:
            if os.path.exists(os.path.join(app_dir(), n)):
                _mark_written(n, MACHINE_ROOT)
    return ctx


def profile_resume() -> ProfileCtx:
    """After the boot order, before any route: the profile profile.json
    names. M8 opens only a local test profile, in a dev copy with the
    profiles hook; any other name (an account a later build made) is left
    in profile.json as it is and "This computer" runs. The lock holder
    records the epoch."""
    ctx = current_ctx()
    if not _INSTANCE_HELD[0]:
        return ctx
    try:
        p = _read_json(PROFILE_FILE, MACHINE_ROOT, dict) or {}
    except StoreReadError:
        p = {}
    act = p.get("active")
    if isinstance(act, str) and re.fullmatch(r"[0-9a-f]{32}", act):
        folder = os.path.join(app_dir(), ACCOUNTS_DIR, act)
        ok = _account_openable(folder, act)
        if ok:
            return profile_switch(ProfileCtx(ok[0], folder, act, ok[1]))
    try:
        def _f(q):
            und = _undecided() if "active" not in q else []
            if und:
                # THE RECORD WAS LOST (M9): profile.json went (or was never
                # this build's) while accounts/ holds folders. Nothing may
                # read as "not named" and be erased at the next start: one
                # account folder (with at most its own imports/<dir>) becomes
                # kept, which sign-in step 2 and Erase then offer; anything
                # else leaves "active" unwritten, so the invariant deletes
                # nothing of anyone's and sign-in refuses until a person
                # decides (M15's screen). This runs in every build, the
                # shipped app's included: it only ever keeps (review of
                # 6b330), and there accounts/ never exists
                q["epoch"] = ctx.epoch
                dirs = [x for x in und if _DIR_RX.fullmatch(x)]
                if (len(dirs) == 1 and not q.get("kept") and set(und)
                        <= {dirs[0], "imports/" + dirs[0]}):
                    q.update(active="local", pending_import=False, kept={
                        "dir": dirs[0], "reason": "signed-out",
                        "cause": "record-lost", "erase_after": None})
            elif q.get("active") not in (None, "local"):
                # a name this build can't open: left as it is
                q["epoch"] = ctx.epoch
                q.setdefault("kept", None)
                q.setdefault("pending_import", False)
            else:
                _profile_fields(q, ctx)
        _profile_json_update(_f)
    except (StoreReadError, OSError) as exc:
        print("  profile.json not updated: %s" % exc)
    return ctx


# one switch at a time (review of 6b329); re-entrant (M9): the switch
# protocol holds it across its bare switches
_switch_lock = threading.RLock()


def profile_switch(ctx_new, erase_old=False) -> ProfileCtx:
    """The bare switch (M8), which every step of M9's protocol that moves
    the epoch goes through: only the copy holding the instance lock, one
    at a time. Under the switch lock: the old profile's queued usage
    records are written to its ledger (any made after that are dropped),
    and its answers still streaming are kept as far as they got, as a
    quit keeps them (M9); then, holding read-aloud's lock and the chat
    store's across the epoch move, the speech stops, the old profile's
    finished deletes are made final, the old ctx is cancelled (streams
    and jobs watch it) and the epoch moves, so no speech, chat write or
    cache of the old profile lands after it (each profile cache starts
    empty for the new epoch). Then every account window but the one
    running the switch closes, and a switch to another folder cleans the
    web view's store. erase_old (a test profile only): its folder goes
    too, through the trash. The new ctx."""
    if not _INSTANCE_HELD[0]:
        raise NoProfile("profile changes need the instance lock")
    with _switch_lock:
        old = current_ctx()
        if old is ctx_new:
            return ctx_new
        try:
            usage_flush()
        except Exception:
            pass
        try:
            _turns_flush_ctx(old)
        except Exception:
            pass            # the answer is dropped, as before M9; the switch goes on
        try:
            know_stop(old)  # (6b530) no pass of the old profile is open past the epoch (ISO-7)
        except Exception:
            pass
        with _say_lock:
            try:
                _stop_speaking()
            except Exception:
                pass
            got = _chats_lock.acquire(timeout=30)
            try:
                if got:
                    try:
                        _chat_finalize_held(old, now=float("inf"))
                    except Exception:
                        pass
                with _profile_lock, _profile_flock():
                    old.cancel.set()
                    _PROFILE["ctx"] = ctx_new
                    _profile_caches_clear()
                    _written.clear()
                    _profile_json_update(lambda q: _profile_fields(q, ctx_new))
                    if erase_old and old.kind == "test":
                        try:
                            _erase_folder(old.dir, step="test")
                        except (OSError, ValueError) as exc:
                            print("  (the test profile goes at the next "
                                  "start: %s)" % exc)
            finally:
                if got:
                    _chats_lock.release()
        try:
            _after_switch(ctx_new, os.path.normcase(old.dir)
                          != os.path.normcase(ctx_new.dir))
        except NameError:
            pass            # the profile section alone (the gauntlet's)
        except Exception as exc:
            # the epoch has moved: the switch stands whatever the windows
            # or the web store do
            print("  (after the switch: %s)" % exc)
    return ctx_new


def test_profile_create() -> ProfileCtx:
    """The local-test-profile hook (1a 5.13): a folder under accounts/
    with an account.key holding random test values and test:true, its
    sync/state.json and media folders. Not active until switched to."""
    if "profiles" not in TEST_HOOKS:
        raise NoProfile("the profiles hook is off")
    if not _INSTANCE_HELD[0]:
        raise NoProfile("profile changes need the instance lock")
    name = secrets.token_hex(16)
    key = _test_key_new()
    with _profile_lock, _profile_flock():
        folder = os.path.join(_accounts_prepare(), name)
        _account_folder_make(folder, name, key)
    return ProfileCtx("test", folder, name, key["acct_id"])


# ------------------------------------ accounts/: the layout (1a 5.1, 5.8)
# (M9, 6b330) An account's folder is accounts/<32 hex>/: account.key
# (1c writes the real one; a local test profile's holds test values),
# .owner, its stores, sync/state.json and its media. Beside it only
# .new-* (a sign-in being built) and .trash-* (an erase under way).
# accounts/ is excluded from Time Machine, so root's originals an Add
# moved are staged OUTSIDE it (review of 6b330), in imports/<dir>/ under
# the data folder, which backups keep. The boot invariant keeps exactly
# what profile.json names. ONE RULE ABOVE ALL: a folder is only ever
# deleted by renaming it into a .trash-<rand> beside it first
# (_erase_folder), so no delete can land on a path it wasn't meant for,
# and an erase a crash cut short is finished by the next start. And
# staged units (root's own chats and facts) are erased only by a
# person's recorded choice ("Erase them", "Erase and continue"); a
# folder of them nobody names goes back into root.
ACCOUNT_KEY = "account.key"
OWNER_FILE = ".owner"
IMPORTED_UNITS = "units.json"
IMPORTS_DIR = "imports"
_DIR_RX = re.compile(r"[0-9a-f]{32}")
_ACCT_NAME_RX = re.compile(r"[0-9a-f]{32}|\.(?:new|trash)-[0-9a-f]{24}")
_IMP_NAME_RX = re.compile(r"[0-9a-f]{32}|\.trash-[0-9a-f]{24}")
# a media path as a chat or a unit map names it: never anything else
_MEDIA_REL_RX = re.compile(r"(?:images|videos|exports)/[\w-]+\.[a-z0-9]{1,5}")
KEPT_REASONS = ("signed-out", "removed", "deleted")
KEPT_ERASE_S = 7 * 86400          # removed or deleted: erased 7 days on
# what Add may move from name, persona and home area (1a 5.11 step 4)
ADD_SETTINGS = ("user_name", "persona", "home_area")
# every named step a crash can be injected at (the crash-at hook, 1a 5.13)
SWITCH_STEPS = (
    "signin.0", "signin.2.commit", "signin.2.key", "signin.2.renamed",
    "signin.2.imported.renamed", "signin.2", "signin.3", "signin.4",
    "signin.undo.key", "signin.undo.renamed", "signin.5.renamed", "signin.5",
    "signin.6.units", "signin.6.legacy", "signin.6.chats", "signin.6.memory",
    "signin.6.media", "signin.6", "signin.7",
    "signout.3", "signout.7", "signout.8.key", "signout.8.renamed",
    "signout.8.putback", "putback.chats", "putback.renamed",
    "signout.8.imported.renamed", "signout.8",
    "kept.1", "kept.4", "kept.keys", "kept.5",
    "kept-erase.commit", "kept-erase.key", "kept-erase.renamed",
    "kept-erase.imported.renamed", "kept-erase",
    "boot.key", "boot.renamed", "boot.step6")
_TM = {"done": None}               # accounts/ excluded from Time Machine this run


def _accounts_root() -> str:
    return os.path.join(app_dir(), ACCOUNTS_DIR)


def _imports_root() -> str:
    return os.path.join(app_dir(), IMPORTS_DIR)


def _tm_exclude(path: str):
    """A sticky Time Machine exclusion on accounts/ (1a 5.8), set before
    anything is written into it: synced data comes back from the server
    and the sign-out Export covers unsent work, so none of it belongs in
    a backup. macOS only, once per run, and a failure only logs: it never
    stands in the boot's way. A dev or test copy never runs tmutil (no
    test may exclude a real folder): it records the command it would run
    in run/tmutil.jsonl, with what accounts/ held at that moment.
    imports/ (root's staged originals) is never excluded."""
    if _TM["done"] == path:
        return
    _TM["done"] = path
    argv = ["tmutil", "addexclusion", path]
    if globals().get("DEFAULT_APP") is not True:
        try:
            d = os.path.join(app_dir(), "run")
            os.makedirs(d, mode=0o700, exist_ok=True)
            with open(os.path.join(d, "tmutil.jsonl"), "a", encoding="utf-8") as f:
                f.write(json.dumps({"argv": argv, "held": sorted(os.listdir(path))})
                        + "\n")
        except OSError:
            pass
        return
    if not globals().get("IS_MAC"):
        return
    try:
        r = subprocess.run(argv, capture_output=True, timeout=15)
        if r.returncode:
            print("  (Time Machine exclusion not set: exit %d)" % r.returncode)
    except Exception as exc:
        print("  (Time Machine exclusion not set: %s)" % exc)


def _accounts_prepare() -> str:
    """accounts/, made 0700 and excluded from Time Machine before its
    first file (1a 5.8). Everything that writes into accounts/ calls it
    first."""
    root = _accounts_root()
    if not os.path.isdir(root):
        os.makedirs(root, mode=0o700, exist_ok=True)
    _tm_exclude(root)
    return root


def _imports_prepare() -> str:
    """imports/, 0700, and in the backups like the rest of root."""
    root = _imports_root()
    if not os.path.isdir(root):
        os.makedirs(root, mode=0o700, exist_ok=True)
    return root


def _rename_retry(src: str, dst: str):
    """os.rename, waiting out a reader on Windows (an antivirus holding a
    file), as _replace_into does for files."""
    for n in range(100):             # up to 5 s: a virus scan of a new folder
        try:
            os.rename(src, dst)
            return
        except PermissionError:
            if not IS_WIN or n == 99:
                raise
            time.sleep(0.05)


def _fsync_dir(path: str):
    """A rename made durable before the commit that relies on it: the
    folder's own entry fsynced. Best effort; Windows has no such call."""
    if IS_WIN:
        return
    try:
        fd = os.open(path, os.O_RDONLY)
    except OSError:
        return
    try:
        os.fsync(fd)
    except OSError:
        pass
    finally:
        os.close(fd)


def _reparse(path: str) -> bool:
    """A link of any kind: a symlink, or on Windows a junction or any
    other reparse point (os.path.islink misses a junction)."""
    try:
        st = os.lstat(path)
    except OSError:
        return False
    if os.path.islink(path):
        return True
    return bool(getattr(st, "st_file_attributes", 0) & 0x400)


def _layout_child(path: str):
    """(parent, name) when path is a folder directly in accounts/ or
    imports/ with one of the layout's names and not a link, whose real
    path is exactly that; else ValueError."""
    name = os.path.basename(os.path.normpath(path))
    for parent, rx in ((_accounts_root(), _ACCT_NAME_RX),
                       (_imports_root(), _IMP_NAME_RX)):
        rp = os.path.realpath(parent)
        if (os.path.realpath(os.path.dirname(os.path.abspath(os.path.normpath(path))))
                == rp and rx.fullmatch(name)):
            if _reparse(path) or (os.path.lexists(path) and os.path.realpath(path)
                                  != os.path.join(rp, name)):
                break
            return rp, name
    raise ValueError("not an account folder: %r" % name)


def _erase_folder(path: str, step: str = "erase") -> bool:
    """THE ONLY WAY A FOLDER UNDER accounts/ OR imports/ IS DELETED (M9).
    Only a direct child with one of the layout's names, never a link or a
    junction, checked again just before each rename. account.key goes
    first (1a 5.11 step 8), renamed into a fresh .trash-<rand>/ beside the
    folder; then the folder is renamed in beside it; then the trash is
    removed. A crash leaves at most a .trash-* the next start removes; a
    file Windows holds stays in the trash until then. True when nothing
    is left."""
    root, name = _layout_child(path)
    path = os.path.join(root, name)
    with _profile_lock, _profile_flock():    # every delete under the lock
        if not os.path.lexists(path):
            return True
        if name.startswith(".trash-"):
            trash = path
        else:
            trash = os.path.join(root, ".trash-" + secrets.token_hex(12))
            os.mkdir(trash, 0o700)
            key = os.path.join(path, ACCOUNT_KEY)
            if os.path.lexists(key):
                _layout_child(path)             # nothing swapped in meanwhile
                _rename_retry(key, os.path.join(trash, ACCOUNT_KEY))
                _crash_point(step + ".key")
            _layout_child(path)
            _rename_retry(path, os.path.join(trash, name))
            _crash_point(step + ".renamed")
        shutil.rmtree(trash, ignore_errors=True)
        return not os.path.lexists(trash)


def _trash_file(path: str):
    """One file of an account folder that must go (a cloud.json that
    can't be read, so its synced keys can't be picked out): renamed into
    a .trash-* first, like a folder."""
    root = _accounts_prepare()
    trash = os.path.join(root, ".trash-" + secrets.token_hex(12))
    os.mkdir(trash, 0o700)
    _rename_retry(path, os.path.join(trash, os.path.basename(path)))
    shutil.rmtree(trash, ignore_errors=True)


def _crash_point(step: str):
    """The crash-at=<step> test hook (1a 5.13, dev copies only): the
    process dies here as a power cut would, with no finally and no
    atexit, so ISO-13 can prove a restart leaves no one's data with
    another. Every name is in SWITCH_STEPS. fail-at=<step> raises an
    OSError there instead (a disk that refuses), to reach the undo
    paths."""
    if _hook_arg("crash-at") == step:
        os._exit(86)
    if _hook_arg("fail-at") == step:
        raise OSError("fail-at hook: %s" % step)


# ------------------------------------------------ .owner (1a 5.1)
def _hkdf_sha256(ikm: bytes, info: bytes, n: int = 32, salt: bytes = b"") -> bytes:
    """RFC 5869 HKDF-SHA256, stdlib only (1a 7.2)."""
    import hmac as _hm
    prk = _hm.new(salt or b"\0" * 32, ikm, "sha256").digest()
    out, t, i = b"", b"", 1
    while len(out) < n:
        t = _hm.new(prk, t + info + bytes([i]), "sha256").digest()
        out += t
        i += 1
    return out[:n]


def _test_rid_key(acct_id: str) -> str:
    """A local test profile's stand-in rid_key (1a 9: random test values
    until 1c's keyring). It follows from acct_id so that signing in to
    the same test account again finds a folder whose .owner verifies
    (1a 5.11 sign-in step 2)."""
    return hashlib.sha256(("cai-test-rid|" + acct_id).encode("utf-8")).hexdigest()


def _read_key(folder: str):
    """(state, key) of a folder's account.key: ("missing", None),
    ("unreadable", None) (there, but not JSON this build reads: DPAPI, or
    a later build's), or ("ok", the dict)."""
    try:
        with open(os.path.join(folder, ACCOUNT_KEY), "rb") as f:
            raw = f.read()
    except FileNotFoundError:
        return "missing", None
    except OSError:
        return "unreadable", None
    try:
        k = json.loads(raw.decode("utf-8"))
    except Exception:
        return "unreadable", None
    return ("ok", k) if isinstance(k, dict) else ("unreadable", None)


def _owner_key(k):
    """K_owner = HKDF(rid_key, "cai2/owner") (1a 5.1). In this build only
    a local test profile's key gives one, and only in a dev copy with the
    profiles hook (M10's keyring brings the real one). None: this build
    can't tell."""
    if not (isinstance(k, dict) and k.get("test") is True
            and "profiles" in TEST_HOOKS):
        return None
    try:
        return _hkdf_sha256(bytes.fromhex(str(k.get("rid_key"))), b"cai2/owner")
    except ValueError:
        return None


def _owner_mac(K: bytes, acct_id: str, name: str) -> str:
    import hmac as _hm
    return _hm.new(K, ("%s|%s" % (acct_id, name)).encode("utf-8"),
                   "sha256").hexdigest()


def owner_check(folder: str, name: str = None):
    """.owner, checked every time a folder opens (1a 5.1): True (it
    verifies with this keyring), False (a well-formed one that doesn't,
    or none at all: a folder this account doesn't own), None (this build
    can't tell: no keyring it can read, one waiting on a re-key, which 1c
    resolves, or an .owner that isn't 64 hex: damaged, not another's)."""
    name = name or os.path.basename(os.path.normpath(folder))
    st, k = _read_key(folder)
    if st != "ok" or k.get("rekey_pending"):
        return None
    K = _owner_key(k)
    if K is None:
        return None
    try:
        with open(os.path.join(folder, OWNER_FILE), "rb") as f:
            have = f.read().decode("ascii").strip()
    except FileNotFoundError:
        return False
    except (OSError, UnicodeDecodeError):
        return None
    if not re.fullmatch(r"[0-9a-f]{64}", have):
        return None
    import hmac as _hm
    return _hm.compare_digest(have.encode("ascii"), _owner_mac(
        K, str(k.get("acct_id")), name).encode("ascii"))


def _write_file_raw(path: str, raw: bytes, mode=0o600):
    """A file in a folder that isn't a live profile (a sign-in's .new-*,
    an imports/<dir>): unique temp, fsync, replace."""
    fd, tmp = tempfile.mkstemp(dir=os.path.dirname(path), prefix=".w-",
                               suffix=".tmp")
    try:
        if not IS_WIN:
            os.fchmod(fd, mode)
        with os.fdopen(fd, "wb") as f:
            f.write(raw)
            f.flush()
            os.fsync(f.fileno())
        _replace_into(tmp, path)
    except BaseException:
        _unlink_quiet(tmp)
        raise


def _copy_stream_raw(path: str, rfile, n: int) -> int:
    """A file in a folder that isn't a live profile's store (an
    imports/<dir> upload, 6b529), streamed from a request body in 1 MB
    pieces: the bytes received. The caller checks the count against n
    and keeps the file's record."""
    got = 0
    with open(path, "wb") as f:
        while got < n:
            chunk = rfile.read(min(1 << 20, n - got))
            if not chunk:
                break
            f.write(chunk)
            got += len(chunk)
    return got


def _read_file_json(path: str, want=dict, default=None):
    """A JSON file outside any ctx (an imports/<dir> or a .new-*): default
    when absent, StoreReadError when it can't be read."""
    try:
        with open(path, "rb") as f:
            d = json.loads(f.read().decode("utf-8"))
    except FileNotFoundError:
        return default
    except Exception as exc:
        raise StoreReadError(os.path.basename(path)) from exc
    if not isinstance(d, want):
        raise StoreReadError(os.path.basename(path))
    return d


def _test_key_new(acct_id=None) -> dict:
    """A local test profile's account.key: random test values and
    test:true (1a 9). A key carrying test:true is never opened without
    the profiles hook."""
    a = acct_id if isinstance(acct_id, str) and _DIR_RX.fullmatch(acct_id) \
        else secrets.token_hex(16)
    return {"test": True, "acct_id": a, "device_id": secrets.token_hex(16),
            "origin": secrets.token_hex(16), "rid_key": _test_rid_key(a),
            "kit_saved": True}


def _account_folder_make(where: str, name: str, key: dict):
    """An account folder's skeleton in `where` (a .new-*, or a test
    profile's own): account.key 0600, .owner for `name`, sync/state.json
    and the media folders. Stores are made at their first write."""
    os.mkdir(where, 0o700)
    for sub in ("sync", "images", "videos", "exports"):
        os.mkdir(os.path.join(where, sub), 0o700)
    fd = os.open(os.path.join(where, ACCOUNT_KEY),
                 os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600)
    with os.fdopen(fd, "w") as f:
        json.dump(key, f)
        f.flush()
        os.fsync(f.fileno())
    K = _owner_key(key)
    if K is not None:
        _write_file_raw(os.path.join(where, OWNER_FILE), _owner_mac(
            K, key["acct_id"], name).encode("ascii"))
    _write_file_raw(os.path.join(where, STATE_FILE),
                    json.dumps({"written": []}).encode("utf-8"))


def _account_openable(folder: str, name: str):
    """(kind, acct_id) when this build may open the folder as a profile,
    else None: a local test profile (dev copy, profiles hook) whose
    .owner verifies. A real account waits for M10."""
    st, k = _read_key(folder)
    if st != "ok" or k.get("test") is not True or "profiles" not in TEST_HOOKS:
        return None
    if owner_check(folder, name) is not True:
        return None
    return "test", str(k.get("acct_id"))


# ------------------------------------------------ switching (1a 5.11)
_SWITCH = {"on": 0, "idle": threading.Event()}
_SWITCH["idle"].set()


def switch_wait(timeout: float = 60.0) -> bool:
    """A request's start waits out a switch under way (1a 5.11: from the
    lock for switching on nothing of the old profile is written, and the
    next request works for the new one). True when none runs."""
    ev = _SWITCH["idle"]
    return ev.is_set() or ev.wait(timeout)


def switch_ctx(timeout: float = 60.0):
    """The profile a request works for, taken while no switch runs: the
    wait and the read are made atomic by reading again when a switch
    began in between (review of 6b330). None: a switch outlasted the
    wait (the request is refused, never served under its hold)."""
    end = time.monotonic() + timeout
    while True:
        if not switch_wait(max(0.0, end - time.monotonic())):
            return None
        c = current_ctx()
        if _SWITCH["idle"].is_set():
            return c
        if time.monotonic() >= end:
            return None


@contextlib.contextmanager
def _switching():
    """One switch protocol at a time, with new requests held at their
    start until it ends."""
    with _switch_lock:
        _SWITCH["on"] += 1
        _SWITCH["idle"].clear()
        try:
            yield
        finally:
            _SWITCH["on"] = max(0, _SWITCH["on"] - 1)
            if not _SWITCH["on"]:
                _SWITCH["idle"].set()


def _hold(old):
    """Lock for switching (1a 5.11, sign-out step 3 and sign-in step 0):
    the same profile under a new epoch only the switch holds. The bare
    switch first keeps the old profile's live answers as far as they got
    and makes its deletes final (as a quit does), stops read-aloud and
    cancels the old ctx: from here every page write gets 409 and every
    background writer is refused."""
    return profile_switch(ProfileCtx(old.kind, old.dir, old.name, old.acct_id))


@contextlib.contextmanager
def _aside_root():
    """A root ctx for the switch alone while an account is still active
    (review of 6b330: a sign-out or a server sign-out finishes an Add's
    step 6 first, through root, instead of abandoning it). Only under the
    switch lock: requests are held, and the old root ctxs were cancelled,
    so nothing but the switch writes through it."""
    R0 = ProfileCtx("local", app_dir())
    with _profile_lock:
        _PROFILE["aside"] = R0
    prev = bind_ctx(R0)
    try:
        yield R0
    finally:
        bind_ctx(prev)
        with _profile_lock:
            _PROFILE["aside"] = None
        R0.cancel.set()


def _dirlist(p, key: str) -> list:
    v = p.get(key) if isinstance(p, dict) else None
    return [x for x in v if isinstance(x, str) and _DIR_RX.fullmatch(x)] \
        if isinstance(v, list) else []


def _named(p):
    """The folders profile.json names: {"active", "kept", "putback",
    "erase"}; putback lists the imports/<dir> whose units wait to go back
    into root, erase those a person chose to erase ("Erase them", "Erase
    and continue"). None when it can't be trusted (unreadable, missing,
    malformed, or with no "active" at all: a record lost and remade), in
    which case nothing but the trash and nobody's .new-* is deleted."""
    if not isinstance(p, dict) or "active" not in p:
        return None
    act, kept = p.get("active"), p.get("kept")
    if not (act == "local" or (isinstance(act, str) and _DIR_RX.fullmatch(act))):
        return None
    if kept is not None and not (
            isinstance(kept, dict) and isinstance(kept.get("dir"), str)
            and _DIR_RX.fullmatch(kept["dir"]) and kept.get("reason") in KEPT_REASONS):
        return None
    for key in ("putback", "erase"):
        v = p.get(key)
        if v is not None and not (isinstance(v, list) and len(_dirlist(p, key)) == len(v)):
            return None
    return {"active": None if act == "local" else act,
            "kept": kept["dir"] if kept else None,
            "putback": _dirlist(p, "putback"), "erase": _dirlist(p, "erase")}


def _list_add(q: dict, key: str, name: str):
    v = q.get(key) if isinstance(q.get(key), list) else []
    q[key] = v + ([name] if name not in v else [])


def _list_drop(q: dict, key: str, name: str):
    v = q.get(key) if isinstance(q.get(key), list) else []
    q[key] = [x for x in v if x != name]


def _pb_add(q: dict, name: str):
    """profile.json's putback list with name in it (once)."""
    _list_add(q, "putback", name)
    _list_drop(q, "erase", name)


def _pb_drop(q: dict, name: str):
    _list_drop(q, "putback", name)


def _er_add(q: dict, name: str):
    """profile.json's erase list: a person's recorded choice to erase
    imports/<name>, so a crash after it still finishes it, and nothing
    else ever erases staged units."""
    _list_add(q, "erase", name)
    _list_drop(q, "putback", name)


def _key_marked(folder: str) -> bool:
    """An unfinished sign-up or re-key 1c must resolve first (1c Q2):
    account.key marked signup "sent", or holding a rekey_pending keyring;
    or a key this build can't read at all (it might be one)."""
    st, k = _read_key(folder)
    if st == "unreadable":
        return True
    return st == "ok" and (k.get("signup") == "sent" or bool(k.get("rekey_pending")))


def _kept_keys_raw(folder: str, every: bool):
    """Entering the kept state: every synced key and the whole `account`
    section of the folder's cloud.json go at once (every key for a
    removal or a deletion). Written straight into the kept folder (it is
    no profile's now); a cloud.json that can't be read goes whole, into
    the trash, since its synced keys can't be picked out. Idempotent: a
    start does it again for a kept folder, in case a crash came between
    the commit and this. A removal or a deletion also takes servers.json's
    Access tokens and device keys (6b334), the addresses and names kept."""
    if every:
        _kept_servers_raw(folder)
    p = os.path.join(folder, "cloud.json")
    if not os.path.exists(p):
        return
    try:
        d = _read_file_json(p, dict, None)
    except StoreReadError:
        _trash_file(p)
        return
    if d is None:
        return
    pv = d.get("providers") if isinstance(d.get("providers"), dict) else {}
    keep = {} if every else {k: v for k, v in pv.items()
                             if not (isinstance(v, dict) and v.get("sync") is True)}
    if keep != pv or "account" in d or (every and d.get("active")):
        d["providers"] = keep
        d.pop("account", None)
        if every:
            d["active"] = ""
        _write_file_raw(p, json.dumps(d).encode("utf-8"))


def _kept_servers_raw(folder: str):
    """servers.json without its secrets (the Access token, the device key
    and what names it); one that can't be read goes whole, to the trash."""
    p = os.path.join(folder, "servers.json")
    if not os.path.exists(p):
        return
    try:
        d = _read_file_json(p, dict, None)
    except StoreReadError:
        _trash_file(p)
        return
    rows = d.get("servers") if isinstance(d, dict) else None
    if not isinstance(rows, list):
        _trash_file(p)
        return
    gone = ("access_id", "access_secret", "seed", "device_id", "public_key",
            "paired_at", "device_name", "relay", "relay_token")
    clean = [{k: v for k, v in r.items() if k not in gone}
             for r in rows if isinstance(r, dict)]
    if clean != rows:
        _write_file_raw(p, json.dumps({"v": 1, "servers": clean}).encode("utf-8"))


def _unit_total(name: str) -> int:
    """Every unit an imports/<name> holds (one that can't be read counts:
    it is kept, never erased for it)."""
    try:
        return len(_units(_imported_path(name))["units"])
    except StoreReadError:
        return 1


def boot_invariant(now: float = None) -> dict:
    """THE BOOT INVARIANT (1a 5.11), first in boot, by the copy holding
    the instance lock only, under run/profile.lock. Only the folders
    profile.json names (active or kept, never both) may be in accounts/,
    and only theirs and the put-back list's in imports/:
      * profile.json missing, unreadable, malformed or without "active":
        nothing is deleted but the trash and a .new-* holding nobody's
        data (review of 6b330: no one is left stuck); an imports/<dir>
        whose account folder is gone goes on the put-back list when the
        record can be written;
      * a named folder whose .owner fails is erased; one this build
        can't check (no keyring it reads, a re-key pending, a damaged
        .owner) is left; a kept folder past erase_after is erased; the
        active folder with no account.key becomes kept (sign-in step 2
        decides later). A folder that goes sends its Add's units back to
        root (putback in the same commit);
      * a kept folder's synced keys go, again, in case a crash came
        between the commit and that;
      * every other 32-hex folder and .new-* in accounts/ is erased,
        except a .new-* (or folder) holding an unfinished sign-up or
        re-key (1c Q2);
      * in imports/: a folder on the erase list (a person's choice) is
        erased; any other one nobody names goes on the put-back list if
        it holds a unit (I12: staged units are only ever erased by a
        person), and is erased if it holds none;
      * .trash-* is emptied; any other name is left alone.
    profile.json is always written before the erase it allows, so a
    crash between them is finished by the next start. {erased, kept,
    why}."""
    out = {"erased": [], "kept": [], "why": ""}
    if not _INSTANCE_HELD[0]:
        out["why"] = "no instance lock"
        return out
    root, iroot = _accounts_root(), _imports_root()
    now = time.time() if now is None else now

    def _gone(path, step="boot"):
        try:
            _erase_folder(path, step=step)
            out["erased"].append(os.path.relpath(path, app_dir()))
        except (OSError, ValueError) as exc:
            print("  (%s not erased: %s; next start)" % (os.path.basename(path), exc))
    with _profile_lock, _profile_flock():
        if not os.path.isdir(root) and not os.path.isdir(iroot):
            return out
        readable = True
        try:
            p = _read_json(PROFILE_FILE, MACHINE_ROOT, dict)
        except StoreReadError:
            p, readable = None, False
        n = _named(p)
        if n is None:
            out["why"] = "profile.json can't be trusted: nothing of anyone's deleted"
            for base, rx in ((root, _ACCT_NAME_RX), (iroot, _IMP_NAME_RX)):
                for name in sorted(os.listdir(base)) if os.path.isdir(base) else []:
                    path = os.path.join(base, name)
                    if not rx.fullmatch(name) or _reparse(path) or not os.path.isdir(path):
                        continue
                    if name.startswith(".trash-") or (
                            name.startswith(".new-") and not _key_marked(path)):
                        _gone(path)
                    else:
                        out["kept"].append(name)
            orphans = [x for x in (sorted(os.listdir(iroot)) if os.path.isdir(iroot) else [])
                       if _DIR_RX.fullmatch(x) and not os.path.isdir(os.path.join(root, x))
                       and not _reparse(os.path.join(iroot, x))]
            if orphans and readable:
                def _back(q):
                    for x in orphans:
                        if x not in _dirlist(q, "putback"):
                            _list_add(q, "putback", x)
                _profile_json_update(_back)
            return out

        def _lost(q, name):
            if _unit_total(name):
                _pb_add(q, name)
        drop = []
        act, kept = n["active"], n["kept"]
        if act:
            f = os.path.join(root, act)
            ok = owner_check(f, act) if os.path.isdir(f) else None
            if not os.path.isdir(f):
                _profile_json_update(lambda q: (q.update(
                    active="local", pending_import=False), _lost(q, act)))
                act = None
            elif ok is False:
                _profile_json_update(lambda q: (q.update(
                    active="local", pending_import=False), _lost(q, act)))
                drop.append(act)
                act = None
            elif _read_key(f)[0] == "missing" and not kept:
                # the key can't be read (1a 5.11): kept, never erased here
                _profile_json_update(lambda q: q.update(
                    active="local", kept={
                        "dir": act, "reason": "signed-out",
                        "cause": "key-missing", "erase_after": None}))
                kept, act = act, None
        if kept:
            f = os.path.join(root, kept)
            kd = (_read_json(PROFILE_FILE, MACHINE_ROOT, dict) or {}).get("kept") or {}
            ea = kd.get("erase_after")
            past = isinstance(ea, (int, float)) and now >= ea
            if not os.path.isdir(f):
                _profile_json_update(lambda q: (q.update(kept=None, pending_import=False),
                                                _lost(q, kept)))
                kept = None
            elif past or owner_check(f, kept) is False:
                _profile_json_update(lambda q: (q.update(kept=None, pending_import=False),
                                                _lost(q, kept)))
                drop.append(kept)
                kept = None
            else:
                try:
                    _kept_keys_raw(f, kd.get("reason") != "signed-out")
                except (OSError, StoreReadError) as exc:
                    print("  (a kept folder's keys wait: %s)" % exc)
        n = _named(_read_json(PROFILE_FILE, MACHINE_ROOT, dict)) or n
        keep_acc = {x for x in (n["active"], n["kept"]) if x}
        for name in sorted(os.listdir(root)) if os.path.isdir(root) else []:
            path = os.path.join(root, name)
            if name in keep_acc or not _ACCT_NAME_RX.fullmatch(name) \
                    or _reparse(path) or not os.path.isdir(path):
                if _ACCT_NAME_RX.fullmatch(name):
                    out["kept"].append(name)
                continue
            if name.startswith(".new-") and _key_marked(path):
                out["kept"].append(name)
                continue
            if _DIR_RX.fullmatch(name) and name not in drop \
                    and _read_key(path)[0] == "ok" and _key_marked(path):
                out["kept"].append(name)
                continue
            _gone(path)
        # imports/: the person's erase list, then anything nobody names
        for x in n["erase"]:
            if os.path.lexists(os.path.join(iroot, x)):
                _gone(os.path.join(iroot, x))
            if not os.path.lexists(os.path.join(iroot, x)):
                _profile_json_update(lambda q, x=x: _list_drop(q, "erase", x))
        keep_imp = keep_acc | set(n["putback"])
        back = []
        for name in sorted(os.listdir(iroot)) if os.path.isdir(iroot) else []:
            path = os.path.join(iroot, name)
            if not _IMP_NAME_RX.fullmatch(name) or _reparse(path) \
                    or not os.path.isdir(path) or name in n["erase"]:
                continue
            if name in keep_imp:
                out["kept"].append("imports/" + name)
            elif name.startswith(".trash-") or not _unit_total(name):
                _gone(path)
            else:
                back.append(name)
                out["kept"].append("imports/" + name)
        if back:
            _profile_json_update(lambda q: [_pb_add(q, x) for x in back])
    return out


def profile_boot_pending(root) -> dict:
    """At a start, after the invariant and before the downgrade import,
    through root's ctx (1a 9's boot order): a pending Add step 6 of the
    active or kept folder (only one this build can open: review of
    6b330), then every pending put-back (read even from a record that
    can't otherwise be trusted: putting back loses nothing).
    {"step6", "putback"}."""
    out = {"step6": False, "putback": False}
    if not _INSTANCE_HELD[0]:
        return out
    try:
        p = _read_json(PROFILE_FILE, MACHINE_ROOT, dict) or {}
    except StoreReadError:
        return out
    n = _named(p)
    prev = bind_ctx(root)
    try:
        tgt = (n["active"] or n["kept"]) if n else None
        if p.get("pending_import") is True and tgt:
            f = os.path.join(_accounts_root(), tgt)
            if os.path.isdir(f) and _account_openable(f, tgt):
                try:
                    _add_stage(root, tgt)
                    out["step6"] = True
                except (StoreReadError, OSError, ValueError) as exc:
                    print("  (the Add's last step waits: %s)" % exc)
                _crash_point("boot.step6")
        for pb in _dirlist(p, "putback"):
            try:
                out["putback"] = _putback_finish(root, pb) or out["putback"]
            except (StoreReadError, OSError, ValueError) as exc:
                print("  (putting the chats back waits: %s)" % exc)
    finally:
        bind_ctx(prev)
    return out


# ------------------------------------------------ Add (1a 5.11 step 4)
def _add_choice(a) -> dict:
    """What the Add sheet ticked; nothing by default (I7): chats "all" or
    a list of root ids, memory, and which of name, persona and home area."""
    a = a if isinstance(a, dict) else {}
    ch = a.get("chats")
    if ch != "all":
        ch = [x for x in ch if isinstance(x, str)][:5000] if isinstance(ch, list) else []
    st = a.get("settings")
    st = [k for k in ADD_SETTINGS if isinstance(st, list) and k in st]
    return {"chats": ch, "memory": a.get("memory") is True, "settings": st}


_MEDIA_IMG_RX = re.compile(r"/api/image/([\w-]+\.(?:png|jpg|webp))")
_MEDIA_BOX_RX = re.compile(r"\[\[(dl|vid):(\{.*?\})\]\]")


def _chat_media(c) -> list:
    """The media a chat's messages show: pictures, videos and the
    exports still offered for download, as paths in a profile folder."""
    out = set()
    for m in (c.get("messages") if isinstance(c, dict) else None) or []:
        t = m.get("content") if isinstance(m, dict) else None
        if not isinstance(t, str):
            continue
        out.update("images/" + x for x in _MEDIA_IMG_RX.findall(t))
        for kind, js in _MEDIA_BOX_RX.findall(t):
            try:
                i = str((json.loads(js) or {}).get("id") or "")
            except (ValueError, AttributeError):
                continue
            if kind == "vid" and re.fullmatch(r"[\w-]+\.(?:mp4|gif|webm)", i):
                out.add("videos/" + i)
            elif kind == "dl" and re.fullmatch(r"[A-Za-z0-9_-]{16,48}\.[a-z0-9]{1,5}", i):
                out.add("exports/" + i)
    return sorted(out)


def _media_ok(rel) -> bool:
    """A media path from data (a chat, a manifest, a unit map) names a
    file in images/, videos/ or exports/ and nothing else (review of
    6b330: `images/../prefs.json` passed a first-part check)."""
    return isinstance(rel, str) and bool(_MEDIA_REL_RX.fullmatch(rel))


def _mkey(rel: str) -> str:
    """How two media names compare on this disk: without case on a Mac
    and on Windows, where IMG.png and img.png are one file."""
    return rel.casefold() if (IS_WIN or globals().get("IS_MAC")) else rel


def _with_sidecar(rel: str) -> list:
    """A media file and what travels with it: a render's .render.json, an
    export's .meta."""
    stem = os.path.splitext(rel)[0]
    return [rel, stem + (".meta" if rel.startswith("exports/") else ".render.json")]


def _link_or_copy(src: str, dst: str):
    try:
        os.link(src, dst)
    except OSError:
        shutil.copyfile(src, dst)


def _add_build(H, newp: str, add: dict) -> dict:
    """Sign-in step 4 into the .new-* folder: the ticked chats with fresh
    ids (each records its root id), the media they show with their
    sidecars, the memory facts, and name, persona and home area as
    pending_settings in sync/state.json (never personal.json; 1d fills
    it). Root is only read here. The manifest step 6 stages from."""
    man = {"chats": [], "facts": [], "media": [], "settings": []}
    written = []
    if add["chats"]:
        out = []
        for c in load_chats(H):
            if not (isinstance(c, dict) and isinstance(c.get("id"), str)):
                continue
            if add["chats"] != "all" and c["id"] not in add["chats"]:
                continue
            nc = _jcopy(c)
            nc["id"] = _new_chat_id()
            nc["root_id"] = c["id"]
            out.append(nc)
            man["chats"].append(c["id"])
            for rel in _chat_media(c):
                if _media_ok(rel) and rel not in man["media"] \
                        and os.path.isfile(H.path(rel)):
                    man["media"].append(rel)
        _write_file_raw(os.path.join(newp, CHATS_FILE), json.dumps(
            {"v": 2, "chats": out, "gone": []}).encode("utf-8"))
        written.append(CHATS_FILE)
        # linked where step 6 moves root's copy away (no second copy on
        # disk); copied where a chat root keeps still shows it, so no two
        # live profiles share a file
        still = set()
        for c in load_chats(H):
            if isinstance(c, dict) and c.get("id") not in man["chats"]:
                still.update(_mkey(x) for x in _chat_media(c))
        for rel in man["media"]:
            for f in _with_sidecar(rel):
                if os.path.isfile(H.path(f)):
                    if _mkey(rel) in still:
                        shutil.copyfile(H.path(f), os.path.join(newp, f))
                    else:
                        _link_or_copy(H.path(f), os.path.join(newp, f))
    if add["memory"]:
        facts = [_jcopy(f) for f in _load_memory(H) if _fact_fp(f)]
        man["facts"] = [_fact_fp(f) for f in facts]
        _write_file_raw(os.path.join(newp, MEMORY_FILE),
                        json.dumps(facts, indent=1).encode("utf-8"))
        written.append(MEMORY_FILE)
    pend = {}
    if add["settings"]:
        up = user_prefs(H, strict=True)
        for k in add["settings"]:
            v = up.get(k)
            if isinstance(v, str) and v.strip() and synced_value_ok(k, v):
                pend[k] = v
                man["settings"].append(k)
    st = {"written": written, "add": man}
    if pend:
        st["pending_settings"] = pend
    _write_file_raw(os.path.join(newp, STATE_FILE), json.dumps(st).encode("utf-8"))
    return man


def _imported_path(name: str) -> str:
    """imports/<name>: root's originals an Add to account <name> moved,
    outside accounts/ so backups keep them (review of 6b330)."""
    return os.path.join(_imports_root(), name)


def _units(imp: str) -> dict:
    """The imports/<dir>/units.json unit map: {"v": 1, "units": {uid:
    {"kind", ...}}}. Kind-extensible: a kind this build doesn't know (1h's
    projects) is kept as it is and never put back or dropped by it."""
    d = _read_file_json(os.path.join(imp, IMPORTED_UNITS), dict, None) or {}
    if not isinstance(d.get("units"), dict):
        d["units"] = {}
    d.setdefault("v", 1)
    return d


def _units_write(imp: str, d: dict):
    _write_file_raw(os.path.join(imp, IMPORTED_UNITS),
                    json.dumps(d, indent=1).encode("utf-8"))


def _merge_file_list(path: str, items: list, key):
    """items added to the JSON list at path, one per key, nothing twice
    (a re-run after a crash adds nothing)."""
    have = _read_file_json(path, list, None) or []
    seen = {key(x) for x in have}
    add = [x for x in items if key(x) not in seen]
    if add or not os.path.exists(path):
        _write_file_raw(path, json.dumps(have + add, indent=1).encode("utf-8"))


def _add_stage(H, name: str):
    """Sign-in step 6, through a root ctx (the switch's hold, the boot's,
    or the aside one a sign-out finishes it with): the originals of what
    was added move into imports/<name>/, in units, each chat with the
    media only it showed, each memory fact. In this order (review of
    6b330): the units, the legacy entries (legacy/ first, then the
    rewrite, then legacy_base), root's chats rewritten without them, the
    facts the same way, and only THEN the media, once no chat root keeps
    can show them, so a step 6 cut short never leaves a chat in root
    with its pictures staged. Name, persona and home area are deleted
    from root, not staged. Then pending_import is cleared. Every part can
    run again after a crash: what is staged already is skipped, and
    nothing is ever re-imported."""
    folder = os.path.join(_accounts_root(), name)
    man = (_read_file_json(os.path.join(folder, STATE_FILE), dict, {}) or {}).get("add")
    man = man if isinstance(man, dict) else {}
    ids = [x for x in man.get("chats") or [] if isinstance(x, str)]
    fps = set(x for x in man.get("facts") or [] if isinstance(x, str))
    imp = _imported_path(name)
    _imports_prepare()
    for sub in ("", "units", "legacy", "media"):
        os.makedirs(os.path.join(imp, sub), mode=0o700, exist_ok=True)
    d = _units(imp)
    if ids:
        with _chats_lock:
            chats = load_chats(H)
            idset = set(ids)
            for c in chats:
                if isinstance(c, dict) and c.get("id") in idset:
                    uid = "chat-" + c["id"]
                    _write_file_raw(os.path.join(imp, "units", uid + ".json"),
                                    json.dumps(c).encode("utf-8"))
                    d["units"][uid] = {"kind": "chat", "root_id": c["id"],
                                       "media": [x for x in _chat_media(c) if _media_ok(x)]}
            _units_write(imp, d)
            _crash_point("signin.6.units")
            _stage_legacy_chats(H, imp, idset)
            _crash_point("signin.6.legacy")
            keep = _ChatList(c for c in chats
                             if not (isinstance(c, dict) and c.get("id") in idset))
            keep.doc = chats.doc
            keep.gone = list(chats.gone) + [i for i in ids if i not in chats.gone]
            if len(keep) != len(chats) or set(keep.gone) != set(chats.gone):
                store_chats(keep, H, legacy=True)
            _crash_point("signin.6.chats")
    if fps:
        with _memory_lock:
            facts = _load_memory(H)
            for f in facts:
                fp = _fact_fp(f)
                if fp in fps:
                    uid = "fact-" + fp[:32]
                    _write_file_raw(os.path.join(imp, "units", uid + ".json"),
                                    json.dumps(f).encode("utf-8"))
                    d["units"][uid] = {"kind": "memory", "fp": fp}
            _units_write(imp, d)
            _stage_legacy_memory(H, imp, fps)
            rest = [f for f in facts if _fact_fp(f) not in fps]
            if len(rest) != len(facts):
                _save_memory(rest, H, legacy=True)
            _crash_point("signin.6.memory")
    media = [x for x in man.get("media") or [] if _media_ok(x)]
    if media:
        with _chats_lock:
            still = set()
            for c in load_chats(H):
                if isinstance(c, dict):
                    still.update(_mkey(x) for x in _chat_media(c))
            moved = False
            for rel in media:
                if _mkey(rel) in still:
                    continue
                for f in _with_sidecar(rel):
                    if os.path.isfile(H.path(f)):
                        dst = os.path.join(imp, "media", f)
                        os.makedirs(os.path.dirname(dst), mode=0o700, exist_ok=True)
                        with _profile_write(H):
                            _rename_retry(H.path(f), dst)
                        moved = True
            if moved:
                for sub in ("images", "videos", "exports"):
                    _fsync_dir(H.path(sub))
                    _fsync_dir(os.path.join(imp, "media", sub))
        _crash_point("signin.6.media")
    sk = [k for k in man.get("settings") or [] if k in ADD_SETTINGS]
    if sk:
        user_prefs_update(H, lambda v: [v.pop(k, None) for k in sk])
    _profile_json_update(lambda q: q.__setitem__("pending_import", False))


def _stage_legacy_chats(H, imp: str, ids: set):
    """The legacy chats.json entries that map to the moved chats, copied
    into imports/<dir>/legacy/ with the root id each maps to, before
    the rewrite takes them out (1a 5.11 step 6)."""
    lb = (_read_json(PROFILE_FILE, H, dict) or {}).get("legacy_base")
    idmap = lb.get("ids") if isinstance(lb, dict) and isinstance(lb.get("ids"), dict) else {}
    legacy = _read_json(LEGACY_CHATS, H, list) or []
    take = []
    for e in legacy:
        lid = e.get("id") if isinstance(e, dict) else None
        m = idmap.get(lid) if isinstance(lid, str) else None
        tgt = m.get("id") if isinstance(m, dict) else None
        if tgt in ids:
            take.append({"entry": e, "maps_to": tgt})
    if take:
        _merge_file_list(os.path.join(imp, "legacy", "chats.json"), take,
                         lambda x: (x.get("entry") or {}).get("id"))


def _stage_legacy_memory(H, imp: str, fps: set):
    legacy = _read_json(LEGACY_MEMORY, H, list) or []
    take = [f for f in legacy if _fact_fp(f) in fps]
    if take:
        _merge_file_list(os.path.join(imp, "legacy", "memory.json"), take, _fact_fp)


# ------------------------------------ Put them back (1a 5.11 step 8)
def _fact_ts(f) -> float:
    t = f.get("ts") if isinstance(f, dict) else None
    return float(t) if isinstance(t, (int, float)) else 0.0


def _putback(R, name: str) -> bool:
    """Every unit left in imports/<name> back into root, whole: a chat
    under its own root id (out of `gone`), with its media; a memory fact;
    their legacy entries back into chats.json and memory.json, and
    legacy_base with them. The write evicts nothing (review of 6b330:
    the 1,000-chat cap took chats back out, root's own too), and the facts
    are merged by time, so root's newer ones are never the ones the cap
    trims. Runs again safely after a crash. False while a unit of a kind
    this build doesn't know is left (it stays for a build that does)."""
    imp = _imported_path(name)
    if not os.path.isdir(imp):
        return True
    d = _units(imp)
    units = sorted(d["units"].items())
    unknown = [u for u, v in units if (v or {}).get("kind") not in ("chat", "memory")]
    with _chats_lock:
        chats = load_chats(R)
        have = {c.get("id") for c in chats if isinstance(c, dict)}
        gone = list(chats.gone)
        changed = False
        for uid, u in units:
            if u.get("kind") != "chat":
                continue
            rid = u.get("root_id")
            c = _read_file_json(os.path.join(imp, "units", uid + ".json"), dict, None)
            if c is not None and rid not in have:
                chats.append(c)
                have.add(rid)
                changed = True
            if rid in gone:
                gone = [x for x in gone if x != rid]
                changed = True
            for rel in u.get("media") or []:
                if not _media_ok(rel):
                    continue
                for f in _with_sidecar(rel):
                    src = os.path.join(imp, "media", f)
                    if os.path.isfile(src) and not os.path.exists(R.path(f)):
                        with _profile_write(R):
                            _ensure_parent(R.path(f), R)
                            _rename_retry(src, R.path(f))
            _crash_point("signout.8.putback")
        if changed:
            chats.gone = gone
            store_chats(chats, R, evict=False)
        _putback_legacy_chats(R, imp)
    _crash_point("putback.chats")
    with _memory_lock:
        facts = _load_memory(R)
        haveh = {_fact_fp(f) for f in facts}
        add = []
        for uid, u in units:
            if u.get("kind") != "memory" or u.get("fp") in haveh:
                continue
            f = _read_file_json(os.path.join(imp, "units", uid + ".json"), dict, None)
            if f is not None:
                add.append(f)
                haveh.add(u.get("fp"))
        if add:
            _save_memory(sorted(facts + add, key=_fact_ts), R)
        _putback_legacy_memory(R, imp)
    return not unknown


def _putback_legacy_chats(R, imp: str):
    items = _read_file_json(os.path.join(imp, "legacy", "chats.json"), list, None) or []
    items = [x for x in items if isinstance(x, dict) and isinstance(x.get("entry"), dict)
             and isinstance(x["entry"].get("id"), str)]
    if not items:
        return
    with _profile_lock:
        for _try in range(4):
            lb = (_read_json(PROFILE_FILE, R, dict) or {}).get("legacy_base")
            if not (isinstance(lb, dict) and "ids" in lb):
                return          # root keeps no legacy record: nothing to restore into
            legacy, sha = _read_json_h(LEGACY_CHATS, R, list)
            legacy = legacy or []
            present = {e.get("id") for e in legacy if isinstance(e, dict)}
            add = [x["entry"] for x in items if x["entry"]["id"] not in present]
            nsha = _legacy_replace(LEGACY_CHATS, legacy + add, R, sha) if add else sha
            if nsha is None:
                continue        # an older build saved meanwhile: again
            ids = dict(lb.get("ids") or {}) if isinstance(lb.get("ids"), dict) else {}
            for x in items:
                ids[x["entry"]["id"]] = {"id": x.get("maps_to"),
                                         "h": _ent_hash(x["entry"])}
            _profile_legacy_set(R, chats=nsha, ids=ids)
            return


def _putback_legacy_memory(R, imp: str):
    items = [f for f in _read_file_json(os.path.join(imp, "legacy", "memory.json"),
                                        list, None) or [] if _fact_fp(f)]
    if not items:
        return
    with _profile_lock:
        for _try in range(4):
            lb = (_read_json(PROFILE_FILE, R, dict) or {}).get("legacy_base")
            if not (isinstance(lb, dict) and "facts" in lb):
                return
            legacy, sha = _read_json_h(LEGACY_MEMORY, R, list)
            legacy = legacy or []
            present = {_fact_fp(f) for f in legacy}
            add = [f for f in items if _fact_fp(f) not in present]
            nsha = _legacy_replace(LEGACY_MEMORY, legacy + add, R, sha, indent=1) \
                if add else sha
            if nsha is None:
                continue
            fps = [x for x in map(_fact_fp, legacy + add) if x]
            _profile_legacy_set(R, memory=nsha, facts=fps)
            return


def _putback_finish(R, name: str) -> bool:
    """Put back, then drop name from profile.json's putback list, then
    erase the emptied imports/<name> (commit first, erase after, as
    everywhere)."""
    if not _putback(R, name):
        return False
    _profile_json_update(lambda q: _pb_drop(q, name))
    _erase_folder(_imported_path(name), step="putback")
    return True


def _imported_erase(name: str, step: str):
    """A person's recorded "Erase them": imports/<name> goes, then leaves
    the erase list."""
    if os.path.lexists(_imported_path(name)):
        _erase_folder(_imported_path(name), step=step)
    _profile_json_update(lambda q: _list_drop(q, "erase", name))


def _imported_count(name: str) -> dict:
    """What an imports/<name> holds that root doesn't (the sign-out and
    Erase sheets' question, 1a 5.11 step 2), by kind. A unit whose chat or
    fact root still holds (a step 6 cut short) isn't counted: erasing it
    loses nothing (review of 6b330)."""
    imp = _imported_path(name)
    if not os.path.isdir(imp):
        return {"units": 0, "kinds": {}}
    try:
        u = _units(imp)["units"]
    except StoreReadError:
        return {"units": 1, "kinds": {"unreadable": 1}}
    try:
        rc = (_read_file_json(os.path.join(app_dir(), CHATS_FILE), dict, {}) or {}).get("chats")
        rids = {c.get("id") for c in rc if isinstance(c, dict)} if isinstance(rc, list) else set()
        rfps = {_fact_fp(f) for f in _read_file_json(os.path.join(app_dir(), MEMORY_FILE),
                                                    list, []) or []}
    except StoreReadError:
        rids, rfps = set(), set()
    k = {}
    n = 0
    for v in u.values():
        v = v if isinstance(v, dict) else {}
        if (v.get("kind") == "chat" and v.get("root_id") in rids) or (
                v.get("kind") == "memory" and v.get("fp") in rfps):
            continue
        kd = str(v.get("kind"))
        k[kd] = k.get(kd, 0) + 1
        n += 1
    return {"units": n, "kinds": k}


# ------------------------------------------------ sign-in (1a 5.11)
def _account_dirs() -> list:
    """The 32-hex folders under accounts/, named or not."""
    return [n for n in _undecided() if _DIR_RX.fullmatch(n)]


def _undecided() -> list:
    """What a lost record would leave with no one deciding: the 32-hex
    folders and .new-* in accounts/, and each imports/<dir> as
    "imports/<dir>"; never the trash."""
    out = []
    for base, rx, pre in ((_accounts_root(), _ACCT_NAME_RX, ""),
                          (_imports_root(), _IMP_NAME_RX, "imports/")):
        try:
            names = os.listdir(base)
        except OSError:
            continue
        out += [pre + n for n in names
                if rx.fullmatch(n) and not n.startswith(".trash-")
                and os.path.isdir(os.path.join(base, n))
                and not _reparse(os.path.join(base, n))]
    return sorted(out)


def _existing_folder(p):
    """(name, kept dict or None) of the account folder profile.json
    names, active or kept; None when there is none. Only a named folder
    is ever offered for erasing: one no record names is the invariant's,
    and folders a lost record left are nobody's to erase here."""
    n = _named(p)
    if n and n["active"]:
        return n["active"], None
    if n and n["kept"]:
        return n["kept"], p.get("kept")
    return None


def _cancelled(cancel) -> bool:
    """The account window the switch runs from was closed (review of
    6b330): before the commit, nothing goes ahead."""
    return cancel is not None and cancel.is_set()


def profile_signin(req_ctx, opts=None, cancel=None) -> dict:
    """Sign-in, steps 0-7 (1a 5.11). The 1b/1c/1d steps are no-ops until
    they exist; the keyring is a local test profile's (the profiles hook),
    so this runs only in a dev copy with it. opts: {"add": {chats,
    memory, settings} (nothing by default), "acct_id": (the same test
    account again), "erase_existing": (the answer to step 2's offer)}.
    cancel: the account window's closing, checked before the commit.
    A crash at any step leaves either "This computer" as it was, or the
    account committed and the rest finished at the next start."""
    if not _INSTANCE_HELD[0]:
        raise NoProfile("profile changes need the instance lock")
    if "profiles" not in TEST_HOOKS:
        raise NoProfile("accounts need 1c's keyring; this build signs in to "
                        "local test profiles only")
    opts = opts if isinstance(opts, dict) else {}
    add = _add_choice(opts.get("add"))
    with _switching():
        old = current_ctx()
        if req_ctx is not None and req_ctx is not old:
            raise StaleProfile("the profile changed")
        if not old.root:
            return {"err": "signed-in"}
        # 0. flush and lock: live answers kept, deletes final, speech
        # stopped, the old ctx cancelled (the page reloads on 409)
        H = _hold(old)
        _crash_point("signin.0")
        _hook_delay("switch")      # a slow switch, for the checks (dev copies only)
        prev = bind_ctx(H)
        newp = None
        try:
            # 1. unlock in memory [1c]: the test keyring
            key = _test_key_new(opts.get("acct_id"))
            # 2. an account folder already here, active or kept. With a
            # record that can't be trusted and folders under accounts/,
            # nothing goes ahead: no folder is offered or erased that the
            # record doesn't name (a lost record, see profile_resume)
            p0 = _read_json(PROFILE_FILE, MACHINE_ROOT, dict) or {}
            if _named(p0) is None and _undecided():
                return {"err": "undecided",
                        "folders": len([x for x in _undecided()
                                        if _DIR_RX.fullmatch(x)])}
            for _n in range(16):
                p = _read_json(PROFILE_FILE, MACHINE_ROOT, dict) or {}
                ex = _existing_folder(p)
                if not ex:
                    break
                xname, xkept = ex
                xf = os.path.join(_accounts_root(), xname)
                st, k0 = _read_key(xf)
                same = st == "ok" and k0.get("acct_id") == key["acct_id"]
                if same and xkept and xkept.get("reason") == "deleted":
                    return {"stop": "deleted"}
                if same and owner_check(xf, xname) is True:
                    _profile_json_update(lambda q: q.update(
                        active=xname, kept=None))
                    acct = ProfileCtx("test", xf, xname, key["acct_id"])
                    bind_ctx(prev)
                    prev = None
                    profile_switch(acct)
                    return {"ok": True, "resumed": True, "dir": xname,
                            "tag": acct.tag, "reload": True}
                # an Add of that folder's cut short is finished first,
                # through root, so what the offer counts is whole
                if p.get("pending_import") is True and os.path.isdir(xf) \
                        and _account_openable(xf, xname):
                    _add_stage(H, xname)
                if opts.get("erase_existing") is not True:
                    return {"need": "erase-existing",
                            "imported": _imported_count(xname)}
                # erased, key file first, with its staged units (the
                # person's choice, recorded first; those chats never come
                # back into root this way: ISO-23)
                def _forget(q, x=xname):
                    # only the folder being erased leaves the record
                    if q.get("active") == x:
                        q.update(active="local", pending_import=False)
                    if isinstance(q.get("kept"), dict) and q["kept"].get("dir") == x:
                        q.update(kept=None, pending_import=False)
                    if os.path.lexists(_imported_path(x)):
                        _er_add(q, x)
                    else:
                        _pb_drop(q, x)
                _profile_json_update(_forget)
                _crash_point("signin.2.commit")
                _erase_folder(xf, step="signin.2")
                _imported_erase(xname, "signin.2.imported")
            _crash_point("signin.2")
            # 3. the folder, built beside the others as .new-*
            aroot = _accounts_prepare()
            name = secrets.token_hex(16)
            newp = os.path.join(aroot, ".new-" + secrets.token_hex(12))
            _account_folder_make(newp, name, key)
            _crash_point("signin.3")
            # 4. Add: exactly what was ticked, copied in with fresh ids
            man = _add_build(H, newp, add)
            _crash_point("signin.4")
            if _cancelled(cancel):
                raise _Cancelled()
            # 5. commit: the rename (made durable), then profile.json (a
            # folder profile.json doesn't name is erased at the next start)
            final = os.path.join(aroot, name)
            _rename_retry(newp, final)
            newp = None
            _fsync_dir(aroot)
            _crash_point("signin.5.renamed")
            added = any(man[k] for k in ("chats", "facts", "media", "settings"))
            _profile_json_update(lambda q: q.update(
                active=name, kept=None, pending_import=added))
            _crash_point("signin.5")
        except (Exception, _Cancelled) as exc:
            if newp and os.path.lexists(newp):
                try:
                    _erase_folder(newp, step="signin.undo")
                except (OSError, ValueError):
                    pass
            if isinstance(exc, _Cancelled):
                return {"err": "cancelled"}
            raise
        finally:
            if prev is not None:
                bind_ctx(prev)
        # 6. root's originals staged (a failure here is finished at the
        # next start: pending_import stays true)
        if added:
            prev = bind_ctx(H)
            try:
                _add_stage(H, name)
            except (StoreReadError, OSError, ValueError) as exc:
                print("  (the Add's last step waits for the next start: %s)" % exc)
            finally:
                bind_ctx(prev)
        _crash_point("signin.6")
        # 7. start sync [1d]; the page reloads on the new profile
        acct = ProfileCtx("test", final, name, key["acct_id"])
        profile_switch(acct)
        _crash_point("signin.7")
        return {"ok": True, "dir": name, "tag": acct.tag, "reload": True,
                "added": {k: len(v) for k, v in man.items()}}


class _Cancelled(Exception):
    """The account window closed before the commit (review of 6b330)."""


# ------------------------------------------------ sign-out (1a 5.11)
def signout_info(ctx) -> dict:
    """The sign-out sheet's data (1a 5.11 step 2; the words are 1e's):
    unsent changes (none without 1d: a placeholder, and a blocker for
    offering sign-out in M15), answers still streaming, settings waiting
    in pending_settings, the media not in the account (all of it until
    Phase 2), an Add not finished uploading, and whether the Kit was
    saved."""
    if ctx.root:
        return {"signed_in": False}
    st = _read_file_json(os.path.join(ctx.dir, STATE_FILE), dict, {}) or {}
    ps = st.get("pending_settings")
    _k = _read_key(ctx.dir)[1] or {}

    def n(sub):
        try:
            return len([x for x in os.listdir(ctx.path(sub))
                        if not x.endswith((".render.json", ".meta"))])
        except OSError:
            return 0
    return {"signed_in": True, "unsent": 0,
            "streaming": turns_live_count(ctx),
            "pending_settings": sorted(ps) if isinstance(ps, dict) else [],
            "media": {"images": n("images"), "videos": n("videos")},
            "imported": _imported_count(ctx.name),
            "kit_saved": _k.get("kit_saved") is not False,
            "only_computer": None}


def _finish_step6_aside(name: str) -> bool:
    """An Add's step 6 the account being left still owes, finished through
    an aside root ctx (review of 6b330: never abandoned silently). True
    when nothing is owed now."""
    p = _read_json(PROFILE_FILE, MACHINE_ROOT, dict) or {}
    if p.get("pending_import") is not True:
        return True
    try:
        with _aside_root() as R0:
            _add_stage(R0, name)
        return True
    except (StoreReadError, OSError, ValueError) as exc:
        print("  (the Add's last step couldn't finish: %s)" % exc)
        return False


def profile_signout(req_ctx, opts=None, cancel=None) -> dict:
    """Sign-out chosen by the person, steps 1-9 (1a 5.11). opts:
    {"imported": "putback" | "erase"}, the answer the sheet needs when an
    Add hasn't finished uploading (no default: without it nothing
    happens), recorded in the commit. Steps 4-6 are 1b/1d's and no-ops
    until they exist. cancel: the account window's closing."""
    if not _INSTANCE_HELD[0]:
        raise NoProfile("profile changes need the instance lock")
    opts = opts if isinstance(opts, dict) else {}
    choice = opts.get("imported") if opts.get("imported") in ("putback", "erase") else None
    with _switching():
        old = current_ctx()
        if req_ctx is not None and req_ctx is not old:
            raise StaleProfile("the profile changed")
        if old.root:
            return {"err": "signed-out"}
        name = old.name
        # 2. the sheet's question: an Add not finished uploading
        info = signout_info(old)
        if info["imported"]["units"] and choice is None:
            return {"need": "imported", "info": info}
        # 1 and 3. flush the page and lock for switching
        H = _hold(old)
        _crash_point("signout.3")
        # an Add's step 6 cut short is finished first; failing that,
        # nothing happens (the sheet says why)
        if not _finish_step6_aside(name):
            return {"err": "add-unfinished"}
        if choice is None and _imported_count(name)["units"]:
            return {"need": "imported", "info": signout_info(H)}
        if _cancelled(cancel):
            return {"err": "cancelled"}
        # 4. final upload [1d]; 5. stop sync [1d] and lending [1g] (read-
        # aloud and the ctx were stopped by the hold); 6. /v2/logout [1b]
        # 7. commit, with the sheet's answer
        has_imp = os.path.lexists(_imported_path(name))

        def _commit(q):
            q.update(active="local", kept=None, pending_import=False)
            if choice == "putback":
                _pb_add(q, name)
            elif choice == "erase" and has_imp:
                _er_add(q, name)
        _profile_json_update(_commit)
        _crash_point("signout.7")
        R = profile_switch(ProfileCtx("local", app_dir()))
        # 8. erase, key file first; the browser store was cleaned by the
        # switch; the staged units as the sheet said
        try:
            _erase_folder(H.dir, step="signout.8")
        except (OSError, ValueError) as exc:
            print("  (the account folder goes at the next start: %s)" % exc)
        prev = bind_ctx(R)
        try:
            if choice == "putback":
                _putback_finish(R, name)
            elif choice == "erase" and has_imp:
                _imported_erase(name, "signout.8.imported")
        except (StoreReadError, OSError, ValueError) as exc:
            print("  (the rest of the sign-out waits for the next start: %s)" % exc)
        finally:
            bind_ctx(prev)
        _crash_point("signout.8")
        # 9. caches emptied by the switch; the page reloads
        return {"ok": True, "tag": R.tag, "reload": True}


# ------------------------------------ signed out by the server (1a 5.11)
def profile_keep(req_ctx, reason: str = "signed-out", cause: str = "") -> dict:
    """The kept state (1a 5.11): a sign-out by the server (reason
    "signed-out", cause saying why), a verified removal notice ("removed")
    or deletion proof ("deleted"); 1d drives it, the profiles hook until
    then. The folder, state.json and the push queue stay; it is never
    served or synced while kept. An Add's step 6 cut short is finished
    first, or stays owed (pending_import) for the next start."""
    if not _INSTANCE_HELD[0]:
        raise NoProfile("profile changes need the instance lock")
    if reason not in KEPT_REASONS:
        return {"err": "reason"}
    with _switching():
        old = current_ctx()
        if req_ctx is not None and req_ctx is not old:
            raise StaleProfile("the profile changed")
        if old.root:
            return {"err": "signed-out"}
        # 1. streams stopped with their partial text written through the
        # account's ctx, read-aloud stopped, lending [1g]; 2. sync [1d]
        H = _hold(old)
        _crash_point("kept.1")
        owed = not _finish_step6_aside(old.name)
        # 4. commit first (review of 6b330), then 3's key erasure: a crash
        # between them is finished by the next start
        kept = {"dir": old.name, "reason": reason, "cause": str(cause or "")[:60],
                "erase_after": (time.time() + KEPT_ERASE_S)
                if reason in ("removed", "deleted") else None}
        _profile_json_update(lambda q: q.update(active="local", kept=kept,
                                                pending_import=owed))
        _crash_point("kept.4")
        try:
            _kept_keys_raw(H.dir, reason != "signed-out")
        except (OSError, StoreReadError) as exc:
            print("  (the kept folder's keys go at the next start: %s)" % exc)
        _crash_point("kept.keys")
        R = profile_switch(ProfileCtx("local", app_dir()))
        _crash_point("kept.5")
        # 5. the page reloads
        return {"ok": True, "tag": R.tag, "kept": kept, "reload": True}


def profile_kept_erase(req_ctx, opts=None) -> dict:
    """[Erase] on a kept, removed or deleted folder: with a non-empty
    imports/<dir>, step 2's question first, the answer recorded in the
    commit. Commit, then erase."""
    if not _INSTANCE_HELD[0]:
        raise NoProfile("profile changes need the instance lock")
    opts = opts if isinstance(opts, dict) else {}
    choice = opts.get("imported") if opts.get("imported") in ("putback", "erase") else None
    with _switching():
        cur = current_ctx()
        if req_ctx is not None and req_ctx is not cur:
            raise StaleProfile("the profile changed")
        p = _read_json(PROFILE_FILE, MACHINE_ROOT, dict) or {}
        n = _named(p)
        if not (n and n["kept"] and cur.root):
            return {"err": "nothing kept"}
        name = n["kept"]
        f = os.path.join(_accounts_root(), name)
        if p.get("pending_import") is True and os.path.isdir(f) \
                and _account_openable(f, name):
            prev = bind_ctx(cur)
            try:
                _add_stage(cur, name)
            except (StoreReadError, OSError, ValueError):
                return {"err": "add-unfinished"}
            finally:
                bind_ctx(prev)
        imp = _imported_count(name)
        if imp["units"] and choice is None:
            return {"need": "imported", "imported": imp}
        has_imp = os.path.lexists(_imported_path(name))

        def _commit(q):
            q.update(kept=None, pending_import=False)
            if choice == "putback":
                _pb_add(q, name)
            elif has_imp:
                _er_add(q, name)
        _profile_json_update(_commit)
        _crash_point("kept-erase.commit")
        try:
            _erase_folder(f, step="kept-erase")
        except (OSError, ValueError) as exc:
            print("  (the kept folder goes at the next start: %s)" % exc)
        prev = bind_ctx(cur)
        try:
            if choice == "putback":
                _putback_finish(cur, name)
            elif has_imp:
                _imported_erase(name, "kept-erase.imported")
        finally:
            bind_ctx(prev)
        _crash_point("kept-erase")
        return {"ok": True}


# ------------------------------------------------ the test hooks (1a 5.13)
# `profiles` (dev copies only): make a local test profile, switch to it and
# back, and start the real writers late under the profile active now, so
# the gauntlet can prove a write after a switch lands nowhere (ISO-7) and
# a switch empties every cache (ISO-8). No route exists without the hook.
_TEST_LATE = {}     # id -> "pending", "ok" or the error's name


def _cache_dirty() -> list:
    """The profile caches not in their empty state (for ISO-8)."""
    out = []
    for name, obj in _PROFILE_CACHES.items():
        if isinstance(obj, threading.local):
            continue
        if obj._cur() != _CACHE_BLANK.get(name):
            out.append(name)
    return sorted(out)


def _cache_fill(tag: str):
    """A canary in every profile cache (for ISO-8)."""
    for name, obj in _PROFILE_CACHES.items():
        cur = obj if isinstance(obj, threading.local) else obj._cur()
        if isinstance(cur, threading.local):
            cur.canary = tag
        elif isinstance(cur, dict):
            cur["canary-" + tag] = tag
        elif isinstance(cur, list):
            cur.append(tag)
        elif isinstance(cur, set):
            cur.add(tag)


def test_profile_op(d: dict, req_ctx=None) -> dict:
    """POST /api/test/profile, with the profiles hook only. M9 adds the
    switch protocol's ops, on local test profiles (1a 5.13): signin
    (with its Add), signout, keep (the kept, removed and deleted states),
    kept-erase and info (the sign-out sheet's data)."""
    op = d.get("op")
    if op == "status":
        c = current_ctx()
        return {"tag": c.tag, "kind": c.kind, "stale": _PROFILE["stale"],
                "dirty": _cache_dirty(), "late": dict(_TEST_LATE),
                "dir": None if c.root else c.name, "acct_id": c.acct_id}
    if op == "signin":
        return profile_signin(req_ctx, d)
    if op == "signout":
        return profile_signout(req_ctx, d)
    if op == "keep":
        return profile_keep(req_ctx, str(d.get("reason") or "signed-out"),
                            str(d.get("cause") or "session"))
    if op == "kept-erase":
        return profile_kept_erase(req_ctx, d)
    if op == "info":
        return signout_info(current_ctx())
    if op == "create":
        return {"name": test_profile_create().name}
    if op == "switch":
        to = str(d.get("to") or "")
        if to == "local":
            new = ProfileCtx("local", app_dir())
        elif re.fullmatch(r"[0-9a-f]{32}", to) and _test_profile_ok(
                os.path.join(app_dir(), ACCOUNTS_DIR, to)):
            new = ProfileCtx("test", os.path.join(app_dir(), ACCOUNTS_DIR, to),
                             to)
        else:
            return {"err": "no such profile"}
        return {"tag": profile_switch(new, erase_old=bool(d.get("erase"))).tag}
    if op == "fill":
        _cache_fill(str(d.get("tag") or "x")[:40])
        return {"dirty": _cache_dirty()}
    if op == "late":
        ctx = current_ctx()
        kind, text = str(d.get("kind") or ""), str(d.get("text") or "")[:200]
        delay = min(float(d.get("delay") or 0), 30.0)
        jid = secrets.token_hex(6)
        _TEST_LATE[jid] = "pending"

        def run():
            time.sleep(delay)
            try:
                if kind == "memory":
                    with _memory_lock:
                        items = _load_memory(ctx)
                        _save_memory(items + [{"fact": text,
                                               "ts": time.time()}], ctx)
                elif kind == "chat":
                    chat_ops([{"op": "create", "id": _new_chat_id(),
                               "lane": "ai", "title": text}], ctx)
                elif kind == "export":
                    run_export(text, "md", "late", ctx)
                elif kind == "image":
                    _write_image_bytes(ctx, b"\x89PNG\r\n\x1a\n" + text.encode())
                elif kind == "video":
                    # the Veo download's landing, after its delay hook
                    _hook_delay("veo-download")
                    ctx.write_bytes(VIDEO_SUB + "/" + _media_id() + ".mp4",
                                    b"\x00\x00\x00\x18ftypmp42" + text.encode())
                elif kind == "cloud":
                    if not _cloud_save_state(ctx, "groq", {
                            "name": "Groq", "key": text, "status": "ok",
                            "base": "https://api.groq.com/openai/v1"}):
                        raise StaleProfile("not saved")
                elif kind == "prefs":
                    user_prefs_update(ctx, lambda v: v.__setitem__(
                        "persona", text))
                elif kind == "quality":
                    ctx.append(QUALITY_FILE, (text + "\n").encode())
                elif kind == "cache":
                    _cache_fill(text)
                elif kind == "remote":
                    if not _remote_save({"host": text, "user": "u"}):
                        raise StaleProfile("not saved")
                elif kind == "usage":
                    usage_put({"t": round(time.time(), 1), "m": text, "w": "local",
                               "n": 1, "i": 1, "o": 1})
                    usage_flush()
                    if not any(r.get("m") == text for r in usage_read(ctx)):
                        raise StaleProfile("not recorded")
                else:
                    raise ValueError(kind)
                _TEST_LATE[jid] = "ok"
            except BaseException as exc:
                _TEST_LATE[jid] = type(exc).__name__
        ctx_thread(target=run, ctx=ctx, daemon=True).start()
        return {"id": jid}
    return {"err": "unknown op"}


