def _sky_context():
    if _sky_tls["ctx"] is None:
        import ssl
        ctx = ssl.create_default_context()
        try:
            ctx.load_verify_locations(cadata=_APPLE_ROOT_CA)
        except Exception:
            pass
        _sky_tls["ctx"] = ctx
    return _sky_tls["ctx"]


def _sky_dir() -> str:
    return os.path.join(app_dir(), "sky")


def _sky_path(i: int) -> str:
    # keyed by URL hash, not list index — editing SKY_SOURCES must never
    # make a cached file impersonate a different clip
    h = hashlib.sha1(SKY_SOURCES[i].encode()).hexdigest()[:10]
    return os.path.join(_sky_dir(), "sky-%s.mov" % h)


def _atoms(fh, end):
    """Top-level QuickTime atoms as (type, offset, size)."""
    off = fh.tell()
    while off + 8 <= end:
        fh.seek(off)
        hdr = fh.read(8)
        if len(hdr) < 8:
            return
        size, typ = struct.unpack(">I4s", hdr)
        if size == 1:
            size = struct.unpack(">Q", fh.read(8))[0]
        elif size == 0:
            size = end - off
        if size < 8:
            return
        yield typ, off, size
        off += size


def _patch_moov(buf: bytearray, shift: int):
    """Shift every stco/co64 chunk offset inside a moov blob by `shift`.
    Recursive descent over the real container atoms — a naive byte scan
    for b'stco' can hit sample data and corrupt the file."""
    containers = {b"moov", b"trak", b"mdia", b"minf", b"stbl",
                  b"edts", b"udta"}

    def walk(start, end):
        off = start
        while off + 8 <= end:
            size, typ = struct.unpack(">I4s", buf[off:off + 8])
            hs = 8
            if size == 1:
                size = struct.unpack(">Q", buf[off + 8:off + 16])[0]
                hs = 16
            if size < hs or off + size > end:
                return
            if typ in containers:
                walk(off + hs, off + size)
            elif typ in (b"stco", b"co64"):
                n = struct.unpack(">I", buf[off + hs + 4:off + hs + 8])[0]
                base = off + hs + 8
                w = 4 if typ == b"stco" else 8
                fmt = ">I" if typ == b"stco" else ">Q"
                for k in range(n):
                    p = base + w * k
                    v = struct.unpack(fmt, buf[p:p + w])[0] + shift
                    buf[p:p + w] = struct.pack(fmt, v)
            off += size

    walk(8, len(buf))


def _faststart(src: str, dst: str):
    """qt-faststart: rewrite `src` so moov precedes mdat, into `dst`."""
    total = os.path.getsize(src)
    with open(src, "rb") as fh:
        atoms = list(_atoms(fh, total))
        moov = next(((o, s) for t, o, s in atoms if t == b"moov"), None)
        mdat = next(((o, s) for t, o, s in atoms if t == b"mdat"), None)
        if not moov or not mdat:
            raise ValueError("no moov/mdat atom")
        if moov[0] < mdat[0]:                     # already fast-start
            os.replace(src, dst)
            return
        fh.seek(moov[0])
        blob = bytearray(fh.read(moov[1]))
        if b"cmov" in blob[:256]:
            raise ValueError("compressed moov unsupported")
        # every atom after ftyp moves back by exactly len(moov)
        _patch_moov(blob, moov[1])
        with open(dst + ".part", "wb") as out:
            for typ, off, size in atoms:          # ftyp keeps pole position
                if typ == b"ftyp":
                    fh.seek(off)
                    out.write(fh.read(size))
            out.write(blob)
            for typ, off, size in atoms:
                if typ in (b"ftyp", b"moov"):
                    continue
                fh.seek(off)
                left = size
                while left:
                    chunk = fh.read(min(1 << 20, left))
                    if not chunk:
                        break
                    out.write(chunk)
                    left -= len(chunk)
    os.replace(dst + ".part", dst)
    os.remove(src)


def _sky_fetch(i: int):
    tmp = _sky_path(i) + ".dl"
    try:
        os.makedirs(_sky_dir(), exist_ok=True)
        have = os.path.getsize(tmp) if os.path.exists(tmp) else 0
        hdrs = {"User-Agent": "MillenAI"}
        if have:
            # PICK UP WHERE A CLOSED SESSION LEFT OFF (6b318, per Patrick:
            # the same backdrops "over and over"): a clip half downloaded
            # when the app quit started from zero next time, so a short
            # session rarely finished a fresh one and the cached clips came
            # round again
            hdrs["Range"] = "bytes=%d-" % have
        req = urllib.request.Request(SKY_SOURCES[i], headers=hdrs)
        with urllib.request.urlopen(req, timeout=60,
                                    context=_sky_context()) as r:
            if have and getattr(r, "status", 200) == 206:
                total = have + int(r.headers.get("Content-Length") or 0)
                mode = "ab"
            else:                     # no range: the whole file, afresh
                have, mode = 0, "wb"
                total = int(r.headers.get("Content-Length") or 0)
            with open(tmp, mode) as out:
                got = have
                while True:
                    chunk = r.read(1 << 20)
                    if not chunk:
                        break
                    out.write(chunk)
                    got += len(chunk)
                    with _sky_lock:
                        _sky_jobs[i] = {
                            "status": "downloading",
                            "pct": int(got * 92 / total) if total else 0}
        with _sky_lock:
            _sky_jobs[i] = {"status": "remuxing", "pct": 96}
        _faststart(tmp, _sky_path(i))
        with _sky_lock:
            _sky_jobs[i] = {"status": "ready", "pct": 100}
        # THE PANTRY (5.3.1, per Patrick: "preload more in the background
        # and cache them for the future" — the 3.8 no-stockpile rule is
        # rescinded): SKY_KEEP clips OF EACH KIND, day and night (6b323,
        # per Patrick: "still getting the same few"). One shelf of 8 let
        # an evening's night clips push out the daytime ones, and by day
        # two clips took turns. mtime is touched on serve, so the playing
        # clip is never the evictee. Orphans from old catalog hashes go.
        try:
            idx = {os.path.basename(_sky_path(n)): n
                   for n in range(len(SKY_SOURCES))}
            clips = sorted(glob.glob(os.path.join(_sky_dir(), "sky*.mov")),
                           key=os.path.getmtime)
            for p in clips:
                if os.path.basename(p) not in idx:
                    os.remove(p)
            dark = set(SKY_DARK)
            for kind in (True, False):
                mine = [p for p in clips if os.path.basename(p) in idx
                        and (idx[os.path.basename(p)] in dark) == kind]
                for old in mine[:-SKY_KEEP]:
                    os.remove(old)
            for part in glob.glob(os.path.join(_sky_dir(), "*.dl")):
                # three days to resume in (6b318)
                if time.time() - os.path.getmtime(part) > 3 * 86400:
                    os.remove(part)
        except Exception:
            pass
    except Exception as exc:
        with _sky_lock:
            _sky_jobs[i] = {"status": "error", "pct": 0, "t": time.time(),
                            "note": str(exc)[:120]}
        # a transfer cut short stays, to resume; a refused range, a dead
        # link or a file that won't remux starts over
        if isinstance(exc, (urllib.error.HTTPError, ValueError)):
            try:
                os.remove(tmp)
            except Exception:
                pass


SKY_KEEP = 8      # clips kept of each kind (6b323): about 4.5 GB in all


# WHICH CLIPS WERE SEEN, kept beside them (6b323): the page's own copy
# lives in the window's storage, which came back empty on Patrick's Mac,
# and with no history every clip on the shelf counts as new.
_sky_hist_lock = threading.Lock()


def sky_hist() -> list:
    try:
        with open(os.path.join(_sky_dir(), "hist.json"), encoding="utf-8") as f:
            h = json.load(f)
        return [x for x in h if isinstance(x, int)
                and 0 <= x < len(SKY_SOURCES)][:32]
    except (OSError, ValueError, TypeError):
        return []


def sky_seen(i: int):
    with _sky_hist_lock:
        h = [i] + [x for x in sky_hist() if x != i]
        os.makedirs(_sky_dir(), exist_ok=True)
        fd, tmp = tempfile.mkstemp(dir=_sky_dir(), prefix=".hist-",
                                   suffix=".tmp")
        with os.fdopen(fd, "w", encoding="utf-8") as f:
            json.dump(h[:32], f)
        _replace_into(tmp, os.path.join(_sky_dir(), "hist.json"))


def sky_status(i: int, warm: bool = False) -> dict:
    if not 0 <= i < len(SKY_SOURCES):
        return {"status": "error", "pct": 0, "note": "no such clip"}
    if os.path.exists(_sky_path(i)):
        return {"status": "ready", "pct": 100}
    with _sky_lock:
        job = _sky_jobs.get(i)
        if job and job.get("status") != "error":
            return dict(job)
        # A FAILED CLIP SAYS SO (6b317): the next poll restarted it at
        # once, so the page never saw "error" and never moved on; a clip
        # Apple retired (or, on Windows, one it couldn't verify) sat at
        # "Loading · 0%" for good. It may be tried again in ten minutes.
        if job and time.time() - job.get("t", 0) < 600:
            return {k: v for k, v in job.items() if k != "t"}
        # ONE download at a time: several launches/refreshes each kicking a
        # 400 MB prewarm saturated the line and made everything feel slow.
        # A background warm never starts while anything else is fetching;
        # only a clip the user is actually waiting on may jump the queue.
        busy = any(j.get("status") in ("downloading", "remuxing")
                   for j in _sky_jobs.values())
        if warm and busy:
            return {"status": "busy", "pct": 0}
        _sky_jobs[i] = {"status": "downloading", "pct": 0}
    ctx_thread(target=_sky_fetch, args=(i,), daemon=True).start()
    return {"status": "downloading", "pct": 0}


# ---------------------------------------------------------------- funnels
# A FUNNEL (6b228) is a guided narrowing: the user names a decision and
# its requirements, and the model proposes N options per stage. Each
# pick becomes context for the next stage, so the choices converge
# instead of restarting. Text mode is pure model; image mode attaches a
# real photo per option harvested from the web (nothing is generated).
FUNNEL_SYS = (
    "You run a decision funnel. Each stage offers the user a small set "
    "of CONCRETE, mutually distinct options that narrow the decision. "
    "Never repeat an option already chosen, never offer near-duplicates. "
    "Every stage's options are VALUES OF ONE DECISION AXIS (size, "
    "budget, vibe, effort), and each option must literally answer the "
    "question as worded — a heavy-or-light question cannot list dish "
    "names. An option is NEVER a complete final answer: no named "
    "products, menu items, model numbers or tickers — stages narrow, "
    "only the final recommendation names. Never re-open or contradict "
    "an axis a prior answer already settled. Respect the user's stated "
    "requirements absolutely.")

# SOME DECISIONS ARE NOT RESTAURANT PICKS (6b253, per Patrick's note on
# the funnel set): health, the end of a relationship, cutting back on
# drinking, whether to see a doctor. A funnel that treats those like
# choosing a laptop reads cold, and cold is the one thing that makes a
# person close the tab. Detected from the GOAL TEXT rather than from a
# tagged chip, so someone who TYPES "should I leave my marriage" gets
# the same care as someone who clicked a suggestion.
_TENDER_RX = re.compile(
    r"\b(end|leave|break\s*up|divorc\w*|separat\w*)\b[^.]{0,40}"
    r"\b(relationship|marriage|partner|him|her|them|wife|husband|"
    r"boyfriend|girlfriend|engagement)\b|"
    # both word orders: "should I SEE a specialist" and "which
    # SPECIALIST should I see" — the noun alone is enough, since a
    # clinician's title rarely appears in a non-medical decision
    r"\b(doctors?|therapists?|specialists?|psychiatrists?|"
    r"counsell?ors?|physio\w*|dermatologists?|cardiologists?|"
    r"oncologists?)\b|"
    r"\b(depress\w*|anxiet\w*|anxious|suicid\w*|self.?harm|grief|"
    r"grieving|mental\s+health|burn(ed|t)?\s*out|panic\s+attack|"
    # "stress" but never "stress test" — that is a server task, and the
    # Code lane shares this module
    r"stress(?!\s*test)|overwhelm\w*|therap\w*|"
    r"antidepressant\w*|medications?|\bmeds\b)\b|"
    r"\b(drinking|alcohol|sober|sobriety|smoking|vaping|addict\w*|"
    r"relapse)\b|"
    r"\b(diagnos\w*|symptom|chronic\s+pain|cancer|surgery|miscarr\w*)\b|"
    r"\b(dying|hospice|funeral|passed\s+away)\b",
    re.I)

FUNNEL_CARE = (
    "\n\nTHIS DECISION IS A TENDER ONE — it touches the person's health, "
    "their body, or someone they love. Shift from narrowing to "
    "SUPPORTING:\n"
    "- Open by acknowledging the weight of it in ONE short clause. Never "
    "gush, never perform sympathy, and never open with a heading.\n"
    "- Options are still concrete, but frame them as ways to think about "
    "it or next steps to take — never as verdicts on what they should "
    "feel or do about a person.\n"
    "- Include an option that is about gathering more information, "
    "taking time, or talking to someone qualified, where that honestly "
    "fits. Not every decision should be forced to a conclusion today.\n"
    "- For anything medical, be clear you are not a clinician and that "
    "a real one is the right call. Do not diagnose, and do not "
    "speculate about what a symptom means.\n"
    "- Keep the person's dignity in every word. They are deciding, not "
    "being processed.")


# THE VERDICT VOICE (6b260, per Patrick: the summary used to parrot the
# picks back — "something strawberry, frozen, with sprinkles" — because
# it was driven by FUNNEL_SYS, whose entire job is to OFFER OPTIONS).
# The summary is not a stage; it gets its own system prompt whose only
# job is a decision.
FUNNEL_SUMMARY_SYS = (
    "You are the decisive final step of a decision funnel. The "
    "narrowing is DONE — your only job is the verdict. Speak like a "
    "sharp, warm expert who has heard every answer and knows exactly "
    "what to suggest: one concrete, specific, real recommendation. "
    "Restating the user's own answers back to them is failure; so is "
    "offering a list of options — they came for a recommendation and "
    "you give exactly one, with the reason it fits and the next step. "
    # 6b265, judged: a trip verdict invented a B&B ("The Clam House")
    # and a ferry that does not run; a laptop verdict shipped a
    # discontinued 2022 config as current; another overrode the
    # user's clicked "14-inch" with a 15.6" machine and called it
    # "closest to your preference". Three hard rules:
    "Three hard rules.\n"
    "- REAL only: never invent or half-remember a business, product, "
    "route or service. A specific name you cannot vouch is real "
    "loses to a well-known one you can — recommend what you KNOW "
    "exists, current as of your knowledge, and put what to double-"
    "check in one clause.\n"
    "- Picks are binding, LITERALLY AND IN MEANING: the verdict must "
    "be an instance of the clicked option itself, not an adjacent "
    "category — if they clicked Handmade pasta over Gnocchi, a gnudi "
    "(a dumpling) is an override, however lovely; if they clicked "
    "Conservative, an all-equity fund is an override however you "
    "phrase it; a monthly budget is not met by a one-time fee. Never "
    "relabel the thing to fit the click. If a pick cannot be honored "
    "exactly, say so plainly and recommend the closest thing that "
    "DOES honor it — never rationalize a different spec as close "
    "enough.\n"
    "- Stated requirements (budget, no car, timeframe) bind the "
    "verdict; if the picks make one impossible, name the conflict "
    "and resolve it in the requirement's favor.\n"
    # 6b266, judged 2.8: told strawberry + frozen + "with sprinkles",
    # the verdict gave Nerds Gummy Clusters sprinkles they don't have
    "- No fake fits: if NO real option satisfies every answer, say so "
    "plainly, recommend the closest REAL one, and name which wish it "
    "misses — inventing an attribute to claim a perfect match is the "
    "worst possible verdict. FEASIBILITY IS AN ATTRIBUTE: a train "
    "that runs there, a ferry, a place being reachable car-free — "
    "never assert a route or service you cannot vouch exists. A "
    "transit claim needs a NAMED real line or operator you are sure "
    "of ('the NJ Transit 319 bus from Port Authority'); 'bus or "
    "regional rail' is a guess, and a guess gets 'check the actual "
    "route' instead.\n"
    # 6b281, judged: a $1,999 laptop against "under $1500", softened
    # to "sits just above that ceiling"; a typed "2 hours a day"
    # dropped by the verdict
    "- A stated NUMBER is a wall, not a hint: a budget, a time limit, "
    "a weight — the pick sits inside it or you say plainly nothing "
    "real does and name the closest that fits. 'Slightly above' is a "
    "miss. Every TYPED answer appears in the verdict — honored, or "
    "named and reconciled in one clause; never silently dropped.")


def funnel_summary_sys_for(goal: str) -> str:
    """Care mode applies to the verdict too — a tender decision gets a
    tender recommendation, same detection as the stages."""
    return FUNNEL_SUMMARY_SYS + (FUNNEL_CARE
                                 if _TENDER_RX.search(goal or "")
                                 else "")


def funnel_sys_for(goal: str) -> str:
    """The funnel's system prompt, softened when the decision deserves
    it (6b253). One place, so every funnel entry point agrees."""
    return FUNNEL_SYS + (FUNNEL_CARE if _TENDER_RX.search(goal or "") else "")


def _stage_ok(data, asked, opts) -> bool:
    """Is a generated stage actually a stage? (6b267, judged three
    cycles running: the local fallback writes malformed options
    ("High-engagement engagement"), options that don't answer their
    own question, and REPHRASED RE-ASKS of earlier stages.) The
    mechanical tells: too few options, a doubled word inside a label,
    or a question sharing most of its content words with one already
    asked. A failed gate costs one more walk up the cloud ladder."""
    q = str((data or {}).get("q", "")).lower()
    rows = [o for o in ((data or {}).get("options") or [])
            if isinstance(o, dict) and o.get("label")]
    if not q or len(rows) < min(2, opts):
        return False
    for o in rows:
        w = re.findall(r"[a-z]+", str(o["label"]).lower())
        if any(a == b for a, b in zip(w, w[1:])):
            return False               # "engagement engagement"
    stop = {"the", "a", "an", "of", "for", "your", "you", "to", "in",
            "what", "which", "how", "do", "does", "is", "are", "it",
            "on", "or", "and", "with", "much", "many", "kind", "type"}
    qw = set(re.findall(r"[a-z]+", q)) - stop
    for prev in (asked or []):
        pw = set(re.findall(r"[a-z]+", str(prev).lower())) - stop
        if qw and pw and len(qw & pw) / len(qw | pw) >= 0.6:
            return False               # a reworded repeat
    return True


def funnel_stage(goal, reqs, opts, stage, total, picks, want_img=False,
                 asked=None, effort="normal", cloud=True):
    """One stage: a question plus `opts` options, as structured data.

    `asked` is every question already put to the user. Without it the
    model re-asked the SAME question every stage — "city or nature?"
    four times running, ignoring a typed answer in between (6b260,
    caught by drill.py on its first batch). Knowing the ANSWERS is not
    enough; it has to know what it already ASKED."""
    asked = [a for a in (asked or []) if a]
    chosen = ("\n".join(
        "- stage %d: asked \"%s\" -> they answered \"%s\""
        % (i + 1, asked[i] if i < len(asked) else "(not recorded)", p)
        for i, p in enumerate(picks))
        if picks else "(nothing chosen yet)")
    prior = ("\n".join("- %s" % q for q in asked)
             if asked else "(none yet)")
    # the closer a funnel gets to done, the easier it is for the model
    # to coast — "Which direction?" as stage 5 of 5 was seen live
    # (6b260, per Patrick). The last stage is told it is last.
    final = (" This is the FINAL question before the recommendation "
             "— ask the one thing that would most change what you "
             "recommend." if stage == total else "")
    ask = (
        "DECISION: %s\nREQUIREMENTS: %s\nCHOICES SO FAR:\n%s\n\n"
        "QUESTIONS ALREADY ASKED — never repeat or rephrase any of "
        "these, and never ask what an answer above already "
        "settles. Rewording is repeating: texture asked once is "
        "texture asked, whatever the words. Each new question probes "
        "an AXIS no prior stage touched:\n%s\n\n"
        "This is stage %d of %d.%s Write ONE short question (under 12 "
        "words) that MATERIALLY narrows this decision, then exactly %d "
        "options that follow from the choices so far.\n"
        "Never a vague or rhetorical question ('Which direction?', "
        "'What matters most?'), and never one whose answer the "
        "choices already imply. When the big choice is settled, "
        "narrow the practical side that matters most next: budget, "
        "size, timing, or where to get it.\n"
        "Reply as STRICT JSON, nothing else:\n"
        '{"q":"the question","options":[{"label":"short name",'
        '"why":"one clause on the tradeoff"}]}'
        % (goal, reqs or "none stated", chosen, prior, stage, total,
           final, opts))
    label = next((l for l in ("Gemma 4 26B", "Gemma 4 12B", "Qwen 3.6 35B MoE",
                              "Gemma 4 E2B")
                  if model_cached(l) and model_fits_memory(l)), "")
    msgs = [{"role": "system", "content": funnel_sys_for(goal)},
            {"role": "user", "content": ask}]
    raw = ""
    engine = ""
    # THE ORDER (6b339, per Patrick: "keep cloud first in funnels, But under
    # the effort selection ... add a checkbox, include cloud models. And if
    # that's turned on, it'll use or prioritize the cloud models. If that's
    # turned off, then it just goes to server models first, followed by
    # local models."): cloud when the box is ticked AND cloud power is on,
    # then the person's server (the same chooser as the modes), then this
    # Mac. With the box unticked NO cloud model is asked here at all: not
    # the stage, not the retry.
    use_cloud = bool(cloud) and cloud_allowed()
    try:
        # a recovered server is used and a dead one skipped: asked again when
        # its last check is over a minute old, 5 s at most (6b339)
        server_refresh_modes(bound_ctx())
        srv = server_funnel_pick(bound_ctx(), effort)
    except (StaleProfile, BrokenPipeError, ConnectionResetError):
        raise
    except Exception:
        srv = None
    # THE LADDER, not the single active provider (6b261, measured):
    # cycle 2's funnels all ran while Groq — the "active" conf — was
    # quota-resting, so every stage silently fell to a 4-bit local
    # model that shrugged at the axis rules. One resting provider must
    # cost one rung, not the whole funnel.
    # THE USER PICKS THE EFFORT (6b308, per Patrick: "two radio buttons
    # where the user can click either fast or normal"). Fast: the quick
    # model (Haiku first), 1-2 s a stage; Normal: the work model (Opus
    # 5.5 at medium). Either way a stage that fails the gate below gets
    # one more pass on the work model.
    if use_cloud:
        for _conf in (fast_cloud_ladder(utility=True) if effort == "fast"
                      else work_ladder("work")):
            raw = cloud_text(_conf, msgs, timeout=60 if effort == "fast"
                             else 120)
            if raw:
                engine = str(_conf.get("model") or "cloud")
                break
    if not raw and srv:
        parts = []
        try:
            with server_first_deadline(30 if effort == "fast" else 60):
                run_model(srv["label"], msgs, parts.append)
            raw = strip_think("".join(parts))
            if raw:
                engine = "server:%s \u00b7 %s" % (srv["server"], srv["name"])
        except (StaleProfile, BrokenPipeError, ConnectionResetError):
            raise
        except Exception as exc:
            raw = ""      # a server that fails is skipped: this Mac next
            server_mark_down(bound_ctx(), srv["server"], str(exc))
    if not raw and label:
        parts = []
        try:
            run_model(label, msgs, parts.append)
            raw = strip_think("".join(parts))
            engine = "local:" + label
        except Exception:
            raw = ""
    m = re.search(r"\{[\s\S]*\}", raw or "")
    data = {}
    if m:
        try:
            data = json.loads(m.group(0))
        except Exception:
            data = {}
    out = []
    for o in (data.get("options") or [])[:opts]:
        if isinstance(o, dict) and o.get("label"):
            out.append({"label": str(o["label"])[:90],
                        "why": str(o.get("why", ""))[:160]})
    # A STAGE WITH NO OPTIONS IS NOT A STAGE (6b263, measured), and
    # a malformed or re-asked one is no better (6b267): the gate
    # covers both, and a failure earns exactly one more walk up the
    # ladder before we accept defeat.
    if ((not out or not _stage_ok(data, asked, opts))
            and use_cloud):
        out = []
        for _conf in work_ladder("work"):
            raw2 = cloud_text(_conf, msgs, timeout=120)
            m2 = re.search(r"\{[\s\S]*\}", raw2 or "")
            if not m2:
                continue
            try:
                d2 = json.loads(m2.group(0))
            except Exception:
                continue
            if not _stage_ok(d2, asked, opts):
                continue
            for o in (d2.get("options") or [])[:opts]:
                if isinstance(o, dict) and o.get("label"):
                    out.append({"label": str(o["label"])[:90],
                                "why": str(o.get("why", ""))[:160]})
            if out:
                engine = str(_conf.get("model") or "cloud") + ":retry"
                data = d2
                break
    elif (not out or not _stage_ok(data, asked, opts)) and \
            engine.startswith("server:") and label:
        # no cloud rung (unticked, off or none) and the server's stage
        # failed the gate: one more walk, onto this Mac (6b339)
        parts = []
        try:
            run_model(label, msgs, parts.append)
            raw3 = strip_think("".join(parts))
        except Exception:
            raw3 = ""
        m3 = re.search(r"\{[\s\S]*\}", raw3 or "")
        try:
            d3 = json.loads(m3.group(0)) if m3 else {}
        except Exception:
            d3 = {}
        if _stage_ok(d3, asked, opts):
            out = [{"label": str(o["label"])[:90],
                    "why": str(o.get("why", ""))[:160]}
                   for o in (d3.get("options") or [])[:opts]
                   if isinstance(o, dict) and o.get("label")]
            if out:
                engine, data = "local:" + label + ":retry", d3
    if want_img and out:
        # all of the stage's pictures at once, one each, never the same
        # one twice (6b340); a card left without one asks again itself
        for o, img in zip(out, funnel_images(goal, [o["label"] for o in out])):
            o["img"] = img
            if _fimg_blocked(goal, o["label"]):
                o["img_none"] = True       # the page doesn't ask again
    if not out:
        # every rung failed the gate: a plain, always-answerable
        # narrowing question beats a dead end (6b274)
        engine = engine + ":fallback" if engine else "fallback"
        _fq = "In the final call, what matters most?"
        if _fq in (asked or []):
            _fq = "Which of these would you give up last?"
        data = {"q": _fq}
        out = [{"label": "Lowest cost", "why": "spend the least"},
               {"label": "Best quality", "why": "the one that lasts"},
               {"label": "Easiest to get", "why": "available now, no hunting"},
               {"label": "Fastest result", "why": "sorted this week"}][:max(2, opts)]
    return {"engine": engine,
            "q": str(data.get("q", ""))[:120] or "In the final call, what matters most?",
            "options": out}


# ==== funnel images: begin ====
# FUNNEL PICTURES (6b340, per Patrick: "let's make the images a little
# bit bigger ... if an image isn't returned for any of them, then keep
# trying to fetch one because it's kind of useless without them"). His
# stage of six had two cards with no picture, two with the same aerial
# photo and one with a travel site's advert banner, because each card
# took the first og:image of the top three pages of ONE text search. Now
# it's an image search, three queries deep, every candidate vetted, one
# picture per card, the whole stage at once. Only the goal and the
# option's label go out, as before; the page loads the picture straight
# from its https URL, as before.
# ADULT PICTURES NEVER REACH A CARD (review of 6b340). ddgs's Bing image
# engine never sends its safesearch setting (checked live: "nude" gave 35
# results, 0 with Bing's own adlt=strict), and ddgs's automatic choice may
# pick it, so the search is only ever the two engines that enforce it:
# Bing with adlt=strict added, and DuckDuckGo images with safesearch
# "on". If neither answers, the card has no picture; nothing falls back
# to an unfiltered search, and so the old last resort (the og:image of a
# page a text search found; every text engine that honours safesearch
# was down) is gone too. A second guard is ours (_FIMG_ADULT): a short
# list of plain words and known hosts refused in a picture's address,
# title and host, and no search at all when the goal or the option names
# one. A filter can miss, so this is a limit, not a promise. And it
# fails closed: a Bing request that doesn't carry adlt=strict is never
# sent, and the DuckDuckGo leg is skipped unless ddgs still lists that
# engine under that name (a rename would let ddgs's automatic choice
# reach stock Bing); a ddgs upgrade can cost the pictures, not the filter.
_FIMG_BUDGET = 9.0                     # the whole stage's pictures, in s
_FIMG_MIN = (400, 240)                 # smaller is a thumbnail or an icon
# page furniture, adverts, drawings, charts and screenshots, by the
# words in the address (the first live run's "Suburban Edge" was a
# Screenshot-2025-04-22.png; two more were ChatGPT-Image-… pictures,
# and the funnel's pictures are real ones, never generated: 6b228)...
# (whole words only: "catalogo", "silicon" and "bannerman" are places)
_FIMG_BAD = re.compile(
    r"(?<![a-z])(?:logos?|icons?|ico|favicons?|sprites?|avatars?|badges?|"
    r"banners?|buttons?|emojis?|placeholders?|clip-?art|vectors?|"
    r"infographics?|charts?|diagrams?|screen-?shots?|chatgpt|dall-?e|"
    r"midjourney|sponsors?|sponsored|adverts?|advertisements?|promos?|"
    r"promotions?|coupons?|ads?)(?![a-z])", re.I)
# ...or the title the search gave it
_FIMG_BAD_TITLE = re.compile(
    r"(?<![a-z])(?:logos?|icons?|banners?|clip ?art|vectors?|"
    r"infographics?|charts?|diagrams?|screenshots?|adverts?|"
    r"advertisements?|sponsored|promos?|promotions?|coupons?)(?![a-z])",
    re.I)
# the second guard against adult pictures: plain words, whole words only
# ("Sussex" and "Essex" are places), and the sites that are only that
_FIMG_ADULT = re.compile(
    r"(?<![a-z0-9])(?:nudes?|nudity|naked|nsfw|porn\w*|xxx|erotic\w*|"
    r"sexy?|sexual|lingerie|topless|fetish|hentai|onlyfans)"
    r"(?![a-z0-9])", re.I)
# in a HOST the words run together ("hotnude", "freeporn"), so they are
# found inside it; not "sex" (Sussex, Essex), "naked" (a juice) or
# "escort" (a Ford), and not "nudel" or "pornic" (a noodle shop, a town)
_FIMG_ADULT_HOSTWORD = re.compile(
    r"nude(?!l)|porn(?!ic)|xxx|hentai|erotic|nsfw|fetish|lingerie|"
    r"topless|onlyfans|sexy", re.I)
# a host label that is the word itself ("sex.com", "free-sex.example")
_FIMG_ADULT_LABEL = re.compile(r"(?:^|[.-])sex(?:[.-]|$)", re.I)
# the sites that are only that, and their picture servers
_FIMG_ADULT_HOST = re.compile(
    r"pornhub|xvideos|xnxx|xhamster|redtube|youporn|spankbang|eporner|"
    r"chaturbate|stripchat|bongacams|livejasmin|fansly|phncdn|xhcdn|"
    r"xhpingcdn|rdtcdn|ypncdn|(?:^|\.)(?:erome|e621|rule34)\.", re.I)
# words of a goal that say nothing about what a picture shows
_FIMG_STOP = frozenset(
    "a an and are best buy can choose do does for get good how i in is it "
    "me my new of on or pick should the to we what where which who why "
    "will with you your".split())
# stock libraries serve their previews watermarked, social sites refuse
# a picture loaded from anywhere else, and a video's or a document's
# cover is mostly its title in big letters
_FIMG_BAD_HOST = re.compile(
    r"(^|\.)(shutterstock|istockphoto|gettyimages|dreamstime|alamy|123rf|"
    r"depositphotos|vecteezy|freepik|ftcdn|envatousercontent|fbsbx|"
    r"instagram|cdninstagram|tiktokcdn|ytimg|scribdassets)\.", re.I)
_fimg_cache = profile_cache("_fimg_cache", {})   # query -> (when, rows)
_fimg_cache_lock = threading.Lock()


def _fimg_keys(url: str) -> set:
    """What makes two picture URLs the same picture: the address without
    its query, and a long file name alone (a re-hosted copy, or
    WordPress's -800x533 size of it)."""
    p = urllib.parse.urlsplit(str(url))
    host = (p.hostname or "").lower()
    host = host[4:] if host.startswith("www.") else host
    path = urllib.parse.unquote(p.path).lower().rstrip("/")
    keys = {host + path}
    stem = re.sub(r"[-_]\d{2,4}x\d{2,4}$", "",
                  path.rsplit("/", 1)[-1].rsplit(".", 1)[0])
    if len(stem) >= 12:
        keys.add("f:" + stem)
    return keys


def _fimg_unq(s) -> str:
    """Percent-decoded up to three times ("n%2575de" is "nude" after two),
    lower-cased."""
    s = str(s)
    for _ in range(3):
        u = urllib.parse.unquote(s)
        if u == s:
            break
        s = u
    return s.lower()


def _fimg_adult_url(url) -> bool:
    """True when a URL's host, path or query names something adult. A
    URL that won't parse counts as one."""
    if not url:
        return False
    try:
        p = urllib.parse.urlsplit(str(url))
        host = (p.hostname or "").lower()
        text = _fimg_unq(p.path) + " " + _fimg_unq(p.query)
    except ValueError:
        return True
    return bool(_FIMG_ADULT_HOST.search(host)
                or _FIMG_ADULT_HOSTWORD.search(host)
                or _FIMG_ADULT_LABEL.search(host)
                or _FIMG_ADULT.search(text))


def _fimg_ok(row) -> str:
    """The row's picture URL when it can be a card's photo, else ""."""
    img = str(row.get("image") or "").strip()
    if not img.startswith("https://") or len(img) > 400:
        return ""        # https only (6b310), and nothing absurd
    try:
        p = urllib.parse.urlsplit(img)
    except ValueError:
        return ""
    path = _fimg_unq(p.path)
    host, title = p.hostname or "", str(row.get("title") or "")
    if (re.search(r"\.(svg|gif|ico|bmp)$", path)
            or _FIMG_BAD_HOST.search(host)
            or _FIMG_BAD.search(path)
            or _FIMG_BAD_TITLE.search(title)
            or _fimg_adult_url(img)
            or _fimg_adult_url(row.get("url"))      # the page it was on
            or _FIMG_ADULT.search(title)):
        return ""
    try:
        w, h = int(row.get("width") or 0), int(row.get("height") or 0)
    except (TypeError, ValueError):
        w = h = 0
    if w and h and (w < _FIMG_MIN[0] or h < _FIMG_MIN[1]
                    or not 0.5 <= w / h <= 2.6):
        return ""        # a thumbnail, or a strip: a banner or a tower
    return img


def _fimg_rank(rows, label: str = "") -> list:
    """The vetted URLs, best first: a title that names the option (its
    words, by their first five letters, so "Historic" is "Historical"),
    then a landscape shape, then a photo format (a PNG is usually a
    graphic); otherwise in the search's own order."""
    words = {w[:5] for w in re.findall(r"[a-z0-9]{3,}", str(label).lower())}
    scored = []
    for i, r in enumerate(rows or []):
        u = _fimg_ok(r) if isinstance(r, dict) else ""
        if not u:
            continue
        try:
            ratio = int(r.get("width") or 0) / int(r.get("height") or 0)
        except (TypeError, ValueError, ZeroDivisionError):
            ratio = 0
        tw = {w[:5] for w in re.findall(r"[a-z0-9]{3,}",
                                        str(r.get("title") or "").lower())}
        named = bool(words) and len(words & tw) * 2 >= len(words)
        png = urllib.parse.urlsplit(u).path.lower().endswith(".png")
        scored.append((-(2 * named + (1.2 <= ratio <= 2.2) + (not png)),
                       i, u))
    return [u for _s, _i, u in sorted(scored)]


def _fimg_queries(goal: str, label: str) -> list:
    """The label in the goal's context (its telling words), then the
    label alone, then the label as a photo: each a wider net."""
    lab = " ".join(str(label).split())[:90]
    g = " ".join([w for w in re.findall(r"[\w'-]+", str(goal))
                  if w.lower() not in _FIMG_STOP][:6])[:60]
    out = []
    for q in (lab + " " + g if g else lab, lab, lab + " photo"):
        if lab and q not in out:
            out.append(q)
    return out


def _fimg_strict_class():
    """ddgs's Bing images engine, asked for adlt=strict in the request it
    builds, and made to refuse any request that doesn't carry it (a ddgs
    that stops using build_payload, or sends the query another way, gets
    no answer from Bing rather than an unfiltered one)."""
    from ddgs.engines.bing_images import BingImages

    class _Strict(BingImages):
        def build_payload(self, *a, **k):
            p = super().build_payload(*a, **k)
            p["adlt"] = "strict"
            return p

        def request(self, *a, **k):
            if (k.get("params") or {}).get("adlt") != "strict":
                return None
            return super().request(*a, **k)
    return _Strict


def _fimg_bing(query: str, limit: int, proxy=None) -> list:
    """Bing's image search with its adult filter at strict."""
    rows = _fimg_strict_class()(proxy=proxy, timeout=8).search(
        query, safesearch="on", max_results=limit) or []
    return [{k: getattr(r, k, "") for k in
             ("image", "title", "width", "height", "url")} for r in rows]


def _fimg_ddg_ok() -> bool:
    """True only while ddgs still lists its DuckDuckGo images engine under
    that name. If an upgrade renames it, backend="duckduckgo" would fall
    back to ddgs's automatic choice, which includes Bing unfiltered."""
    try:
        import ddgs.engines as de
        return "duckduckgo" in (de.ENGINES.get("images") or {})
    except Exception:
        return False


def _ddg_images(query: str, limit: int = 25) -> list:
    """Image hits (image, title, width, height, url) from a safe-search
    engine, the first that answers. Never raises."""
    proxy = _search_proxy() if IS_WIN else None
    try:
        rows = _fimg_bing(query, limit, proxy)
        if rows:
            return rows
    except Exception:
        pass
    if not _fimg_ddg_ok():
        return []
    try:
        return (DDGS(proxy=proxy) if proxy else DDGS()).images(
            query, max_results=limit, backend="duckduckgo",
            safesearch="on") or []
    except Exception:
        return []


def _fimg_blocked(goal: str, label: str) -> bool:
    """True when the goal or the option names something adult: no
    picture is sought for it, and the page is told to stop asking."""
    return bool(_FIMG_ADULT.search(str(goal) + " " + str(label)))


# AT MOST TWO PICTURE SEARCHES AT ONCE (review of 6b340): six cards
# asking again together, each up to four searches, could trip the search
# engines' rate limits and starve the chat's own web search
_fimg_sem = threading.BoundedSemaphore(2)


def _fimg_search(query: str, deadline=None) -> list:
    """_ddg_images, remembered for 5 minutes when it found something, so
    a card asking again walks on down the same list. Waits its turn, but
    not past the deadline."""
    now = time.time()
    with _fimg_cache_lock:
        hit = _fimg_cache.get(query)
        if hit and now - hit[0] < _RESULTS_TTL:
            return hit[1]
    wait = 5.0 if deadline is None else max(0.0, deadline - time.monotonic())
    if not _fimg_sem.acquire(timeout=wait):
        return []
    try:
        rows = _ddg_images(query)
    finally:
        _fimg_sem.release()
    if rows:
        with _fimg_cache_lock:
            if len(_fimg_cache) > 60:
                _fimg_cache.clear()
            _fimg_cache[query] = (now, rows)
    return rows


def funnel_image(goal: str, label: str, taken=None, lock=None,
                 deadline=None) -> str:
    """One vetted photo for a funnel option, or "". `taken` holds the
    keys of every picture already spoken for (the stage's other cards,
    and any the page says failed to load); the one returned is claimed
    in it under `lock`, so options searched side by side never share."""
    if not HAS_SEARCH or not str(label).strip() or _fimg_blocked(goal, label):
        return ""
    taken = set() if taken is None else taken
    lock = lock or threading.Lock()

    def claim(urls):
        with lock:
            for u in urls:
                ks = _fimg_keys(u)
                if not ks & taken:
                    taken.update(ks)
                    return u
        return ""

    def late():
        return deadline is not None and time.monotonic() > deadline
    qs = _fimg_queries(goal, label)
    for q in qs:
        if late():
            return ""
        u = claim(_fimg_rank(_fimg_search(q, deadline), label))
        if u:
            return u
    return ""


def funnel_images(goal: str, labels: list, budget: float = _FIMG_BUDGET,
                  exclude=()) -> list:
    """A picture for each label, searched side by side within `budget`
    seconds ("" where none came in time), no two the same and none of
    `exclude`. Today's stage searched one card after another."""
    out = [""] * len(labels)
    taken = set()
    for u in exclude or ():
        taken.update(_fimg_keys(u))
    lock = threading.Lock()
    deadline = time.monotonic() + budget

    def one(i, lab):
        try:
            img = funnel_image(goal, lab, taken, lock, deadline)
            with lock:
                out[i] = img
        except Exception:
            pass
    threads = [ctx_thread(target=one, args=(i, lab), daemon=True)
               for i, lab in enumerate(labels)]
    for t in threads:
        t.start()
    for t in threads:
        t.join(timeout=max(0.0, deadline - time.monotonic()))
    with lock:
        return list(out)
# ==== funnel images: end ====


# ==== VERA RUBIN (6b519): begin ====
# Patrick (2026-10-24): "a feature to emulate a Vera Rubin ... I know it's going
# to take a lot of processing power, but where it just sits there and will show
# Vera Rubin and just goes and goes and goes." One question, every machine he
# has: this Mac's strongest MLX model and the paired server's best models that
# fit its card work on it round after round, and a console shows the work and
# both machines' load while they do. His rules: it runs until Stop, or until
# RUBIN_STALL_ROUNDS rounds in a row bring no improvement (a ceiling of
# RUBIN_CEILING_S is the safety net); the best answer so far is always the one
# on screen; never a cloud model, even with "Use cloud power" on (6b521).
#
# THE LOOP (run_rubin):
#   round 0  the question is planned (its parts and the evidence each needs) on
#            one machine while the other writes the first answer exactly as
#            Thinking does (6b515: one writer, a critic, the brief, the
#            fact-check) from the grounded search (6b514); a judge scores it.
#   round n  1. the weak points: a critic on each machine reads the best answer
#               (critic_prompt), and the plan's parts the answer doesn't
#               settle are found by their words (rubin_gaps);
#            2. targeted searches for exactly those (Grounding per gap, its
#               queries planned from the gap), new sources joined to the pack
#               under stable numbers, so every [n] keeps meaning one page;
#            3. competing revisions, one per writer: the Mac's model and the
#               server's two best, each where it lives, one job at a time per
#               machine (the gateway's one-job rule; one MLX engine here);
#               final_prompt with the best answer as material and the weak
#               points as the review notes;
#            4. two judges (one per machine, in parallel, blind letters in a
#               shuffled order) score every revision and the current best on
#               a fixed rubric (RUBIN_CRITERIA); a revision replaces the best
#               only when the judges' mean puts it RUBIN_MARGIN above the best
#               in the same judging and no judge picked the best (rubin_accept);
#            5. the new best is fact-checked against the evidence it cites
#               (verify_answer) and re-sent after a RESET.
#   A round with nothing new to work on (no new source, no open part, and the
#   critics' notes empty or the same as last round's) skips
#   the writers and counts as a stalled round; after a stalled round the next
#   one waits RUBIN_BACKOFF_S, so the machines aren't burned on rounds that
#   change nothing.
# Stop (the console's button, or the send button once) sets the request's
# hurry Event: every call under way is told to stop at its next token and the
# best answer is sent once more with its record, cleanly. The console reads the
# RUBIN frames (rubin_snapshot, rubin_load); the page saves the last answer
# sent, as for every answer, with the sources row and a one-line record.
RUBIN_TIER = "Vera Rubin"
RUBIN_STALL_ROUNDS = 3          # rounds in a row with no improvement end the run
RUBIN_CEILING_S = 4 * 3600.0    # the safety net
RUBIN_MARGIN = 0.25             # a revision must beat the best by this (1-10) in the same judging
RUBIN_BACKOFF_S = (0.0, 20.0, 60.0)   # the pause before a round, by stalled rounds so far
RUBIN_MAX_SOURCES = 24          # the pack's sources; new ones after this are not added
RUBIN_PACK_CHARS = 20000        # ~6K tokens: a 16K context keeps room for the answer and the notes
RUBIN_CHECK_PACK = 9000         # the fact-check's pack: the sources the answer cites first
RUBIN_CHECK_KEEP = 0.85         # a fact-check that would cut more of the answer than this keeps is refused
RUBIN_JUDGE_PACK = 12000
RUBIN_SEARCHES = 3              # targeted searches a round
RUBIN_LOAD_S = 4.0              # the machine panel's sample period (the gateway asks: every few seconds at most)
RUBIN_SRV_FIRST_S = 120.0       # a server call's first word (a model load, the gateway's queue)
RUBIN_CALL_S = {"plan": 90, "critic": 150, "write": 420, "judge": 240, "check": 120}
RUBIN_CRITERIA = (("grounded", 0.25), ("correct", 0.25), ("complete", 0.2),
                  ("clear", 0.15), ("fit", 0.15))
RUBIN_WRITERS_SRV = 2           # the server's best models that write each round
_RUBIN_NUM = re.compile(r"\[(\d{1,3}(?:\s*,\s*\d{1,3})*)\]")    # [3], [2, 4] (the page's own forms)

RUBIN_PLAN = (
    "Plan the research for the question below before anyone answers it. "
    "Today is {today}. Split it into the 2 to 5 parts a complete answer must "
    "settle. For each part say what evidence would settle it, and give 1 or 2 "
    "web search queries that would find that evidence: keyword queries, names "
    "copied exactly as written, the year when it is about now. Never answer "
    "the question.\n"
    "Reply with ONLY JSON, nothing before or after it: {{\"parts\": [{{\"q\": "
    "\"the part as a short question\", \"need\": \"the evidence that settles "
    "it\", \"search\": [\"query one\", \"query two\"]}}]}}\n\nQUESTION: ")

RUBIN_JUDGE = (
    "You judge a contest between answers to one question. Today is {today}. "
    "Score EVERY answer on five criteria, 1 to 10 each, against the numbered "
    "web evidence and today's date:\n"
    "- grounded: each fact about the present is backed by the evidence and "
    "marked with its source number like [3]; nothing is invented, and no [n] "
    "points at a source that doesn't say it.\n"
    "- correct: no wrong figure, date, name or version, no mixed-up units (a "
    "chip for a cluster, a list price for an hourly rate), no stale 'latest'.\n"
    "- complete: it settles every part of the question listed below, with the "
    "depth each part needs.\n"
    "- clear: it leads with the answer, each paragraph adds something new, no "
    "filler, no repetition, no talk about its own sources or process.\n"
    "- fit: it suits the reader described below, at the length they asked for.\n"
    "Be harsh. Length is not a virtue by itself, and a confident wrong claim "
    "costs more than a missing one. 10 means nothing at all could be improved, "
    "9 is what a domain expert would write with these sources, 6 to 7 is a "
    "good answer with real gaps, 5 is usable with clear flaws, 1 is wrong or "
    "useless. FIRST name each answer's three biggest weaknesses (a specific "
    "claim, a missing part, a sentence that wanders), THEN score it. The labels "
    "are in random order and say nothing about who wrote what.\n"
    "Reply with ONLY one JSON object, nothing before or after it: "
    "{{\"weak\": {{\"A\": [\"weakness\", \"weakness\", \"weakness\"], ... one "
    "entry per answer}}, \"scores\": {{\"A\": {{\"grounded\": 6, \"correct\": 7, "
    "\"complete\": 5, \"clear\": 7, \"fit\": 6}}, ... one entry per answer}}, "
    "\"best\": \"A\", \"why\": \"what the best answer does better than the rest, "
    "under 20 words, naming no letter\"}}")

RUBIN_FOCUS = {
    "grounded": "back every current fact with its source number, and drop what no source supports",
    "correct": "fix every figure, date, name and unit the notes question, from the evidence",
    "complete": "settle the parts of the question the answer leaves open",
    "clear": "lead with the answer, cut repetition and filler, make every paragraph earn its place",
    "fit": "write for the reader described: their role, what they need to decide, the length they set",
}


class RubinIO:
    """Everything the loop writes to the page, in one place and one lock:
    the RUBIN frames, the steps, the answer (after a RESET). A write that
    fails (the reader left, the profile changed) marks the run gone and
    never raises inside a worker; the loop re-raises it at the end."""

    def __init__(self, emit, status=None, step=None, stop=None):
        self._emit, self._status, self._step = emit, status, step
        self.lock = threading.Lock()
        self.gone = None
        self.stop = stop             # set when the reader leaves: every call stops at its next token

    def _w(self, x):
        if self.gone is not None:
            return
        with self.lock:
            try:
                self._emit(x)
            except Exception as exc:          # noqa: BLE001 — re-raised by the loop
                self.gone = exc
                if self.stop is not None:
                    self.stop.set()

    def frame(self, obj):
        self._w(Ctl(NUL + "RUBIN:" + json.dumps(obj, separators=(",", ":")) + NUL))

    def ctl(self, tag, obj):
        self._w(Ctl(NUL + tag + ":" + json.dumps(obj) + NUL))

    def answer(self, text):
        self._w(Ctl(NUL + "RESET" + NUL))
        self._w(str(text))

    def status(self, text):
        if self._status is not None and self.gone is None:
            try:
                self._status(text)
            except Exception as exc:          # noqa: BLE001
                self.gone = exc

    def step(self, sid, label, state="run", detail=""):
        if self._step is not None and self.gone is None:
            try:
                self._step(sid, label, state, detail)
            except Exception:
                pass


class RubinLane:
    """One machine's worker (this Mac or one paired server): its
    models run one at a time, because a server's card holds one job at a time
    (the gateway's rule) and this Mac one MLX engine. `models`: labels, the
    strongest first. The panel reads busy, model, tps and the live pace of
    the call under way."""

    def __init__(self, kind, name, models, run=None, sid=""):
        self.kind, self.name, self.sid = kind, name, sid
        self.models = list(models)
        self.lock = threading.Lock()
        self.busy, self.model, self.resident = "", "", ""
        self.tps, self.live_t0, self.live_chars = 0.0, 0.0, 0
        self.fails, self.calls, self.down = 0, 0, False
        self.rounds, self.wins, self.last_win = 0, 0, 0
        self._run = run or _rubin_run

    def label_of(self, m):
        return str(m.get("name") or "cloud") if isinstance(m, dict) else str(m)

    def order(self):
        """The writers, the one already resident first (one swap a round, not two)."""
        ms = list(self.models)
        for i, m in enumerate(ms):
            if self.label_of(m) == self.resident:
                return [m] + ms[:i] + ms[i + 1:]
        return ms

    def live_tps(self):
        if self.live_t0 and self.live_chars:
            s = time.time() - self.live_t0
            if s > 0.5:
                return round(self.live_chars / 4.0 / s, 1)
        return 0.0

    def call(self, model, messages, job, stop, budget, raw=False):
        """One model call on this machine: (text, "") or ("", why). Waits its
        turn; gives up past `budget` seconds or when `stop` is set, and the
        call's next token then ends its stream (an engine or the gateway stops
        generating)."""
        end = time.time() + max(5.0, float(budget))
        while not self.lock.acquire(timeout=0.5):
            if stop.is_set() or time.time() >= end:
                return "", "stopped" if stop.is_set() else "busy"
        label = self.label_of(model)
        parts, err, quit_ = [], [], threading.Event()
        try:
            self.busy, self.model, self.calls = job, label, self.calls + 1
            self.live_t0, self.live_chars = 0.0, 0

            def collect(chunk):
                if quit_.is_set() or stop.is_set():
                    raise _DraftAbandoned()
                if chunk and not self.live_t0:
                    self.live_t0 = time.time()
                parts.append(chunk)
                self.live_chars += len(chunk or "")

            def go():
                try:
                    self._run(self, model, messages, collect)
                except _DraftAbandoned:
                    pass
                except Exception as exc:      # noqa: BLE001 — returned as the why
                    err.append(exc)
            th = ctx_thread(target=go, daemon=True)
            th.start()
            while th.is_alive() and time.time() < end and not stop.is_set():
                th.join(timeout=0.5)
            if th.is_alive():
                quit_.set()
                return "", "stopped" if stop.is_set() else "too slow"
            self.resident = label
            if self.live_t0 and self.live_chars:
                s = time.time() - self.live_t0
                if s > 0.3:
                    self.tps = round(self.live_chars / 4.0 / s, 1)
            if err:
                e0 = err[0]
                if getattr(e0, "slow", False):
                    return "", "too slow"
                if getattr(e0, "transient", False):
                    return "", "busy"         # the server's hiccup, not a refusal: asked again next round
                if getattr(e0, "kind", "") in ("fit", "missing") and model in self.models \
                        and len(self.models) > 1:
                    self.models.remove(model)       # that model can't run there (6b516)
                return "", str(e0)[:160] or type(e0).__name__
            text = strip_think("".join(parts)).strip()
            if not text:
                return "", "empty"
            if not raw and _looks_degenerate(text):
                return "", "degenerate"
            return text, ""
        finally:
            self.busy, self.model = "", ""
            self.live_t0, self.live_chars = 0.0, 0
            self.lock.release()


def _rubin_run(lane, model, messages, collect):
    """A lane's model call: a server's model through the gateway (a model
    load gets RUBIN_SRV_FIRST_S), this Mac's through its engine."""
    if lane.kind == "server":
        with server_first_deadline(RUBIN_SRV_FIRST_S):
            run_model(model, messages, collect)
        return
    run_model(model, messages, collect)


def rubin_score(scores) -> float:
    """One answer's weighted mean of RUBIN_CRITERIA (1-10); 0.0 without scores."""
    if not isinstance(scores, dict):
        return 0.0
    tot = wsum = 0.0
    for k, w in RUBIN_CRITERIA:
        v = scores.get(k)
        if isinstance(v, (int, float)) and not isinstance(v, bool):
            tot += max(1.0, min(10.0, float(v))) * w
            wsum += w
    return round(tot / wsum, 2) if wsum else 0.0


def _rubin_json(text):
    """The first JSON object in a model's reply (through a fence, prose, a
    trailing comma), or None."""
    t = re.sub(r"^```(?:json)?\s*|\s*```$", "", (text or "").strip(), flags=re.S)
    i, j = t.find("{"), t.rfind("}")
    if i < 0 or j <= i:
        return None
    body = t[i:j + 1]
    for cand in (body, re.sub(r",\s*([\]}])", r"\1", body)):
        try:
            v = json.loads(cand)
        except ValueError:
            continue
        if isinstance(v, dict):
            return v
    return None


def rubin_judge_parse(text, letters):
    """{"scores": {letter: {criterion: n}}, "best": letter, "why": str} from
    one judge's reply, only for the letters asked about and only when every
    one of them was scored; None otherwise."""
    d = _rubin_json(text)
    if not d or not isinstance(d.get("scores"), dict):
        return None
    out = {}
    for L in letters:
        s = d["scores"].get(L)
        if not isinstance(s, dict):
            return None
        row = {}
        for k, _w in RUBIN_CRITERIA:
            v = s.get(k)
            try:
                row[k] = max(1.0, min(10.0, float(v)))
            except (TypeError, ValueError):
                pass
        if not row:
            return None
        out[L] = row
    best = str(d.get("best") or "").strip().upper()[:1]
    weak = d.get("weak") if isinstance(d.get("weak"), dict) else {}
    return {"scores": out, "best": best if best in letters else "",
            "why": re.sub(r"\s+", " ", str(d.get("why") or ""))[:160],
            "weak": {L: [re.sub(r"\s+", " ", str(w)).strip()[:200] for w in (weak.get(L) or [])
                         if isinstance(w, str) and w.strip()][:3] for L in letters}}


def rubin_combine(judged, letters):
    """The judges' verdicts averaged: {letter: {"score", "crit": {k: mean}}},
    plus each judge's own pick. A judge that didn't answer isn't counted."""
    judged = [j for j in judged if j]
    out = {}
    for L in letters:
        crit = {}
        for k, _w in RUBIN_CRITERIA:
            vs = [j["scores"][L][k] for j in judged if k in j["scores"].get(L, {})]
            if vs:
                crit[k] = round(sum(vs) / len(vs), 2)
        out[L] = {"score": rubin_score(crit), "crit": crit}
    for L in letters:
        out[L]["weak"] = [w for j in judged for w in (j.get("weak") or {}).get(L, [])]
    return out, [j.get("best", "") for j in judged], [j.get("why", "") for j in judged]


def rubin_cites(text, n_sources):
    """(the source numbers an answer cites, how many marks point past the
    pack's last source)."""
    nums = [int(x) for g in _RUBIN_NUM.findall(text or "") for x in re.split(r"\s*,\s*", g)]
    good = sorted({n for n in nums if 1 <= n <= n_sources})
    return good, sum(1 for n in nums if n < 1 or n > n_sources)


# THE MEASURABLE PART (6b519, seen live): a judge reading its own machine's
# answer scored it 10 of 10 in round 0, and nothing could ever beat it. So every
# answer, the best and the revisions alike, also loses points for what can be
# counted: figures and names with no source number (grounded), marks that point
# past the pack (grounded), talk about "the sources" (clear). It gives a
# lenient judge's ceiling room, and the writers a target they can see: the
# same counts go into their notes.
_RUBIN_META_RX = re.compile(
    r"\b(?:the |these |those )?(?:provided |available |listed |given )?(?:sources?|evidence|"
    r"search results|snippets)(?: provided| above| given| listed)? (?:do(?:es)? not|don['\u2019]t|"
    r"doesn['\u2019]t|say|says|show|shows|mention|mentions|name|names|list|lists|confirm|"
    r"confirms|indicate|indicates|suggest|suggests|state|states)\b"
    r"|\b(?:provided|available) (?:sources?|evidence|search results|snippets)\b"
    r"|\bas of my (?:training|knowledge)|\bmy (?:training data|knowledge cutoff)"
    r"|\bI (?:can(?:no|['\u2019])t|cannot|don['\u2019]t have (?:access|the ability)) "
    r"(?:browse|access|search|look up)", re.I)


def rubin_mech(text, n_sources):
    """({criterion: points off}, [what was counted, for the writers]): the
    share of claim-bearing sentences without a source mark (up to 3 off
    grounded, only when there is evidence to cite), marks past the pack (1
    each, up to 2), sentences about the sources or the model's own data (0.75
    each, up to 2 off clear)."""
    off, said = {}, []
    sents = [x for x in _SENT_RX.split(text or "") if len(x.strip()) >= 12]
    claims = [x for x in sents if _CLAIM_RX.search(x)]
    if n_sources and claims:
        bare = [x for x in claims if not _RUBIN_NUM.search(x)]
        if bare:
            off["grounded"] = round(3.0 * len(bare) / len(claims), 2)
            said.append("%d of %d sentences that state a figure, date or name carry no source "
                        "number: cite the source for each, or drop it if no source says it"
                        % (len(bare), len(claims)))
    bad = rubin_cites(text, n_sources)[1]
    if bad:
        off["grounded"] = off.get("grounded", 0.0) + min(2.0, float(bad))
        said.append("%d source mark%s point%s past the last source: cite only listed numbers"
                    % (bad, "" if bad == 1 else "s", "s" if bad == 1 else ""))
    meta = len(_RUBIN_META_RX.findall(text or ""))
    if meta:
        off["clear"] = min(2.0, 0.75 * meta)
        said.append("%d sentence%s talk%s about 'the sources' or your own data: state the facts "
                    "plainly instead" % (meta, "" if meta == 1 else "s", "s" if meta == 1 else ""))
    return off, said


def rubin_apply_mech(res, texts, n_sources):
    """The judges' scores with each answer's counted points off (rubin_mech)."""
    out = {}
    for i, t in enumerate(texts):
        r = res.get(i)
        if not r:
            continue
        off, _said = rubin_mech(t, n_sources)
        c = dict(r["crit"])
        for k, v in off.items():
            if k in c:
                c[k] = round(max(1.0, c[k] - v), 2)
        out[i] = dict(r, crit=c, score=rubin_score(c), judged=r["score"])
    return out


def rubin_yardstick(anchor_score, anchor_now, cand_now):
    """The score shown for a new best answer, on one yardstick for the whole
    run: where the judges put it between the first answer and a perfect 10 in
    the same judging, laid on the first answer's own score. Judged halfway from
    the first answer to 10, it shows halfway from the first answer's score to
    10. (A plain lead added to the first score ran past 10 by the third round,
    seen live: judged beside stronger answers the first one drops.) Without a
    first score, the judging's own."""
    if not anchor_score or anchor_now is None:
        return round(max(1.0, min(10.0, cand_now)), 2)
    room = 10.0 - anchor_now
    frac = (1.0 if cand_now >= anchor_now else 0.0) if room <= 0 else (cand_now - anchor_now) / room
    frac = max(0.0, min(1.0, frac))
    return round(max(1.0, min(10.0, anchor_score + frac * (10.0 - anchor_score))), 2)


def rubin_accept(best_now, cand, picks=(), margin=RUBIN_MARGIN):
    """Whether the strongest revision replaces the best answer: the judges'
    mean puts it at least `margin` above the best IN THE SAME JUDGING (scores
    from different judgings are not compared), and no judge picked the best
    answer as the best of the lot (a split verdict is not an improvement).
    picks: each judge's pick as an index of the answers judged, 0 the best."""
    if cand < best_now + margin:
        return False
    return not any(p == 0 for p in picks)


def rubin_should_stop(st, stop, now=None) -> str:
    """Why the loop ends now, or "": "stopped" (Stop), "gone" (the reader
    left), "ceiling" (the safety net), "settled" (RUBIN_STALL_ROUNDS rounds
    in a row brought no improvement)."""
    now = time.time() if now is None else now
    if st.io is not None and st.io.gone is not None:
        return "gone"
    if stop.is_set():
        return "stopped"
    if now - st.t0 >= st.ceiling_s:
        return "ceiling"
    if st.stalls >= st.stall_n:
        return "settled"
    return ""


class RubinState:
    """One Vera Rubin run: the question, its plan, the evidence (numbered once,
    for good), the best answer, the record of every round and the counters
    the console shows."""

    def __init__(self, question, sys_msg=None, history="", reader="", today=None,
                 ceiling_s=RUBIN_CEILING_S, stall_n=RUBIN_STALL_ROUNDS, io=None):
        self.question = str(question or "")
        self.sys_msg = sys_msg if isinstance(sys_msg, dict) else {"role": "system", "content": ""}
        self.history, self.reader = history, reader
        self.today = today or time.localtime()
        self.ceiling_s, self.stall_n, self.io = float(ceiling_s), int(stall_n), io
        self.t0 = time.time()
        self.plan = []                     # [{"q", "need", "search": [..]}]
        self.sources, self.terms = [], []
        self._keys, self.read_urls, self.searched = set(), set(), set()
        self.best = {"text": "", "score": 0.0, "crit": {}, "by": "", "round": 0}
        self.best_ever = 0.0
        self.round, self.stalls, self.phase = 0, 0, "planning"
        self.drafts = self.checked = self.fixed = self.searches = 0
        self.history_rows = []             # one per round: r, score, improved, by, why, new, drafts, secs
        self.changed, self.reason, self.done = "", "", False
        self.last_notes = ""
        self.weak = []                     # the judges' weaknesses of the best answer, for the next writers
        self.corrections = []              # this round's corrections the evidence settles (6b518's)
        self.anchor, self.anchor_score = "", 0.0   # the first answer and its score: every round's yardstick

    # ---- the evidence
    def add_sources(self, rows, terms=(), keep_all=False):
        """Join a search's sources to the pack under the next free numbers
        (a source already in it keeps its own); counts every page read. The
        number of sources added. keep_all: the handler's own pack, already
        numbered on the page, goes in whole and in order."""
        added = 0
        for s in rows or []:
            url = str(s.get("url") or "")
            if not url:
                continue
            if s.get("paras"):
                self.read_urls.add(_src_key(url))
            k = _src_key(url)
            if k in self._keys or len(self.sources) >= RUBIN_MAX_SOURCES:
                continue
            if not keep_all and not (s.get("paras") or s.get("body")):
                continue
            s = dict(s)
            s["_terms"] = list(terms or self.terms)
            self._keys.add(k)
            self.sources.append(s)
            added += 1
        for t in terms or ():
            if t.lower() not in [x.lower() for x in self.terms]:
                self.terms.append(t)
        return added

    def rows(self):
        """The SOURCES frame: the page's chips, in the pack's numbering."""
        return [{"t": (s.get("title") or s.get("host") or "")[:80],
                 "u": s.get("url") or "", "d": s.get("date") or ""} for s in self.sources]

    def elapsed(self):
        return time.time() - self.t0


def rubin_pack(st, only=None, budget=RUBIN_PACK_CHARS):
    """The evidence a model reads, in evidence_pack's own format and under
    the run's numbers: every source (or the numbers in `only` first, then the
    rest while the budget lasts), each source's passages picked with the
    words of the search that found it."""
    n_all = len(st.sources)
    if not n_all:
        return ""
    order = list(range(n_all))
    if only:
        first = [n - 1 for n in only if 1 <= n <= n_all]
        order = first + [i for i in order if i not in first]
    share = max(300, min(GROUND_SRC_CHARS, (budget - 220 * n_all) // max(1, n_all)))
    head = ("WEB EVIDENCE gathered %s, %d source%s, numbered for citing:"
            % (time.strftime("%Y-%m-%d", st.today), n_all, "" if n_all == 1 else "s"))
    out, used = [head], len(head)
    for i in order:
        s = st.sources[i]
        txt, _n = evidence_pack([s], s.get("_terms") or st.terms, st.today, budget=share + 400)
        body = txt.split("\n", 1)[1] if "\n" in txt else ""
        body = re.sub(r"^\[1\] ", "[%d] " % (i + 1), body, count=1)
        if used + len(body) > budget and len(out) > 1:
            break
        out.append(body)
        used += len(body) + 2
    return "\n\n".join(out)


def rubin_block(st, only=None, budget=RUBIN_PACK_CHARS):
    """The question block every model of the run reads: the conversation so
    far (when there is one), then the grounded turn with the run's pack."""
    pack = rubin_pack(st, only, budget)
    turn = grounded_turn(st.question, pack, st.today)
    return (st.history + "\n\n" + turn) if st.history else turn


def rubin_reader(sys_text) -> str:
    """Who the answer is for, from the chat's own system prompt: the name,
    the remembered facts and the standing instructions the person set."""
    t = str(sys_text or "")
    out = []
    m = re.search(r"The user's name is ([^\n]{1,80}?) —", t)
    if m:
        out.append("Name: " + m.group(1))
    m = re.search(r"you remember these facts about the user:\n(.*?)\nNever OPEN", t, re.S)
    if m:
        out.append("Known about them: " + re.sub(r"\s+", " ", m.group(1))[:900])
    m = re.search(r"standing instructions for how you should respond, in their own words:\n\"(.*?)\"\n", t, re.S)
    if m:
        out.append("Their standing instructions: " + re.sub(r"\s+", " ", m.group(1))[:600])
    m = re.search(r"\nLENGTH: ([^\n]{1,200})", t)
    if m:
        out.append("Length they set: " + m.group(1)[:200])
    return "\n".join(out) or "Nothing is known about the reader; judge fit for a smart general reader."


def rubin_persona(sys_text) -> str:
    """The standing instructions the person set, as the critic reads them (6b518)."""
    m = re.search(r'standing instructions for how you should respond, in their own words:\n"(.*?)"\n',
                  str(sys_text or ""), re.S)
    return m.group(1).strip() if m else ""


def rubin_history(messages) -> str:
    """The conversation before the question, briefly, for a follow-up: the
    last four turns, each cut."""
    turns = [m for m in (messages or [])[1:-1] if isinstance(m, dict)
             and m.get("role") in ("user", "assistant")][-4:]
    if not turns:
        return ""
    return "EARLIER IN THIS CONVERSATION (for context):\n" + "\n".join(
        "%s: %s" % ("Person" if m["role"] == "user" else "You",
                    re.sub(r"\s+", " ", str(m.get("content") or ""))[:1200]) for m in turns)


def rubin_plan_parse(text, question, today=None):
    """The plan's parts from the planner's reply; the rules' own parts (the
    question's sub-questions and their planned queries, plan_queries) when
    the reply has none."""
    d = _rubin_json(text)
    parts = []
    for p in (d or {}).get("parts") or []:
        if not isinstance(p, dict) or not str(p.get("q") or "").strip():
            continue
        qs = [re.sub(r"\s+", " ", str(x)).strip()[:120] for x in (p.get("search") or [])
              if isinstance(x, str) and str(x).strip()][:2]
        parts.append({"q": str(p["q"]).strip()[:200], "need": str(p.get("need") or "").strip()[:200],
                      "search": qs})
    if parts:
        return parts[:5]
    out = []
    for part in [x for x in _GQ_SPLIT_RX.split(str(question or "")) if x and len(x.split()) >= 3][:4] \
            or [str(question or "")]:
        out.append({"q": part.strip()[:200], "need": "", "search": plan_queries(part, today, limit=2)})
    return out


def rubin_gaps(st, text=None):
    """The plan's parts the answer doesn't settle yet: fewer than half of a
    part's own words (its names count twice) appear in the answer."""
    low = str(st.best["text"] if text is None else text).lower()
    gaps = []
    for p in st.plan:
        terms, ents = _gq_terms(p.get("q") or "")
        if not terms:
            continue
        w = sum(2 if t in ents else 1 for t in terms)
        hit = sum((2 if t in ents else 1) for t in terms if t.lower() in low)
        if hit < 0.5 * w:
            gaps.append(p)
    return gaps


def rubin_note_items(notes):
    """The critics' bullets, as (kind, text): WRONG, MIXED UP, STALE, MISSING."""
    out = []
    for ln in str(notes or "").splitlines():
        m = re.match(r"\s*(?:[-*•]|\d+[.)])?\s*\**\s*(WRONG|MIXED UP|STALE|MISSING)\**\s*[:—-]\s*(.+)",
                     ln, re.I)
        if m:
            out.append((m.group(1).upper(), m.group(2).strip()))
    return out


_RUBIN_NOTE_META = re.compile(
    r"\b(?:the |this |that )?(?:evidence|draft|answer|question|text|response|reviewer|material|"
    r"sources?|snippets?)(?: (?:asks?|says?|states?|claims?|lists?|mentions?|gives?|shows?|"
    r"provides?|offers?|cites?|calls? for|needs?))?\b|\b(?:unsupported|implausible|missing|"
    r"incorrect|not supported|no evidence)\b", re.I)


def rubin_queries(st, notes, gaps):
    """What this round searches for, at most RUBIN_SEARCHES: each a
    (sub-question, its planned queries). The open parts first (with the
    plan's own queries), then the critics' doubtful claims (a check of the
    claim) and missing angles, never a search the run already made."""
    items = []
    for p in gaps:
        qs = [q for q in p.get("search") or [] if q.lower() not in st.searched]
        items.append((p["q"], qs))
    for kind, txt in rubin_note_items(notes):
        t = re.sub(r"[\"“”']", "", txt)
        t = re.split(r"\s+(?:—|--|->|→)\s+|;\s|\s\(", t)[0][:160]
        # "the evidence says", "the question asks", "the draft claims": the
        # reviewer's words, not the subject (seen live as search queries)
        t = _RUBIN_NOTE_META.sub(" ", t)
        t = re.sub(r"\s+", " ", t).strip(" .,:;")
        if kind in ("WRONG", "STALE", "MIXED UP", "MISSING") and len(t.split()) >= 2:
            items.append((t, []))
    out, seen = [], set()
    for q, qs in items:
        k = _ground_key(q)
        if k in seen or k in st.searched:
            continue
        seen.add(k)
        out.append((q, qs))
        if len(out) >= RUBIN_SEARCHES:
            break
    return out


def rubin_search(st, items, start=None, wait_s=GROUND_TOTAL_S + 6):
    """The targeted searches (two at a time): each item a Grounding of its
    sub-question with the plan's queries added as the model's lines, so the
    grounded search's planning, filters, page reads and passages all apply.
    The number of new sources joined to the pack."""
    start = start or (lambda q, qs: ground_start(q, planner=(lambda _p, _qs=qs: "\n".join(_qs))
                                                 if qs else None))
    added = 0
    for i in range(0, len(items), 2):
        gs = []
        for q, qs in items[i:i + 2]:
            st.searched.add(_ground_key(q))
            for x in qs:
                st.searched.add(x.lower())
            st.searches += 1
            try:
                gs.append(start(q, qs))
            except Exception:
                pass
        for g in gs:
            try:
                g.wait(timeout=wait_s)
                srcs, _pack, _nr, _np = g.snapshot()
                added += st.add_sources(srcs, getattr(g, "terms", []) or [])
            except Exception:
                pass
    return added


def rubin_judge_messages(st, answers, letters):
    """The judge's messages: the rubric, the reader, the plan's parts, the
    evidence the answers cite, then the answers under their letters."""
    cited = []
    for t in answers:
        for n in rubin_cites(t, len(st.sources))[0]:
            if n not in cited:
                cited.append(n)
    today = strftime_np("%A, %B %-d, %Y", st.today)
    parts = "\n".join("- " + p["q"] for p in st.plan) or "- (the question as asked)"
    body = ("=== THE QUESTION ===\n" + st.question
            + ("\n\n" + st.history if st.history else "")
            + "\n\n=== ITS PARTS ===\n" + parts
            + "\n\n=== THE READER ===\n" + st.reader
            + "\n\n=== THE EVIDENCE ===\n" + (rubin_pack(st, cited, RUBIN_JUDGE_PACK) or "(no web evidence)")
            + "".join("\n\n=== ANSWER %s ===\n%s" % (L, str(t)[:7000]) for L, t in zip(letters, answers)))
    return [{"role": "system", "content": "You are a strict, fair judge. You answer with JSON only."},
            {"role": "user", "content": RUBIN_JUDGE.format(today=today) + "\n\n" + body}]


def rubin_focus(crit):
    """This round's focus: the best answer's weakest criterion."""
    if not crit:
        return "complete"
    return min(crit, key=lambda k: (crit[k], [c for c, _w in RUBIN_CRITERIA].index(k)))


def rubin_notes(st, critic_notes_list, gaps, new_n, focus):
    """The review notes the writers carry this round."""
    lines = ["FOCUS THIS ROUND: %s." % RUBIN_FOCUS.get(focus, RUBIN_FOCUS["complete"])]
    if gaps:
        lines.append("PARTS THE ANSWER DOESN'T SETTLE YET:")
        lines += ["- %s%s" % (p["q"], (" (needs: %s)" % p["need"]) if p.get("need") else "") for p in gaps]
    seen = set()
    merged = []
    for n in critic_notes_list:
        for ln in str(n or "").splitlines():
            k = re.sub(r"\W+", " ", ln.lower()).strip()
            if k and k not in seen:
                seen.add(k)
                merged.append(ln.rstrip())
    if merged:
        lines.append("REVIEWERS' NOTES:")
        lines += merged[:14]
    weak = list(dict.fromkeys(st.weak or []))[:6]
    _off, counted = rubin_mech(st.best["text"], len(st.sources))
    if weak or counted:
        lines.append("WHAT THE JUDGES MARKED DOWN:")
        lines += ["- " + w for w in weak + counted]
    if new_n:
        a = len(st.sources) - new_n + 1
        lines.append("NEW EVIDENCE: sources [%d] to [%d] were added this round; use what bears "
                     "on the question, with its number." % (a, len(st.sources)))
    lines.append("Keep every part of the current answer that is right, its [n] marks included; "
                 "cite only the numbers listed in the evidence. Write the whole improved answer, "
                 "not a list of changes.")
    return "\n".join(lines)


def rubin_footer(st, final=False):
    """The answer's one-line record, saved with it."""
    n = len(st.history_rows)          # round 0 and every round that finished
    m = int(st.elapsed() // 60)
    bits = ["Vera Rubin", "%d round%s" % (n, "" if n == 1 else "s"),
            "%d source%s read" % (len(st.read_urls), "" if len(st.read_urls) == 1 else "s"),
            "%d draft%s" % (st.drafts, "" if st.drafts == 1 else "s")]
    if st.checked:
        bits.append("%d claim%s checked, %d fixed" % (st.checked, "" if st.checked == 1 else "s", st.fixed))
    if st.best["score"]:
        bits.append("score %.1f/10" % st.best["score"])
    bits.append(("%d min" % m) if m else "%d s" % int(st.elapsed()))
    if final and st.reason:
        bits.append({"stopped": "stopped by you", "settled": "no further improvement",
                     "ceiling": "time limit reached"}.get(st.reason, st.reason))
    return "\n\n*" + " · ".join(bits) + "*"


def rubin_snapshot(st, lanes):
    """The console's state frame."""
    return {"k": "state", "round": st.round, "phase": st.phase, "el": round(st.elapsed(), 1),
            "sources": len(st.sources), "read": len(st.read_urls), "searches": st.searches,
            "drafts": st.drafts, "checked": st.checked, "fixed": st.fixed,
            "score": st.best["score"], "crit": st.best["crit"], "by": st.best["by"],
            "spark": [r["score"] for r in st.history_rows][-40:], "stalls": st.stalls,
            "stall_n": st.stall_n, "ceiling": st.ceiling_s, "changed": st.changed[:240],
            "reason": st.reason, "done": st.done,
            "plan": [p["q"][:90] for p in st.plan][:5],
            "lanes": [{"n": l.name, "k": l.kind, "busy": l.busy, "m": l.model,
                       "down": l.down} for l in lanes]}


# ---- the machine panel
def rubin_mac_load() -> dict:
    """This Mac now: GPU and CPU busy, memory used and its pressure, the
    thermal state macOS tells apps (nominal, fair, serious, critical; it
    gives no temperature without admin rights)."""
    out = {"gpu": None, "cpu": None, "mem_used": None, "mem_total": None,
           "pressure": None, "thermal": None}
    try:
        out["gpu"] = gpu_utilization()
    except Exception:
        pass
    if HAS_PSUTIL:
        try:
            out["cpu"] = psutil.cpu_percent(interval=None)
            vm = psutil.virtual_memory()
            out["mem_used"], out["mem_total"] = vm.total - vm.available, vm.total
        except Exception:
            pass
    try:
        out["pressure"] = mem_pressure()
    except Exception:
        pass
    if IS_MAC:
        try:
            from Foundation import NSProcessInfo      # pyobjc, with pywebview
            out["thermal"] = ("nominal", "fair", "serious", "critical")[
                int(NSProcessInfo.processInfo().thermalState())]
        except Exception:
            pass
    return out


def rubin_server_load(e) -> dict:
    """One server's card now, from the gateway's /v1/usage (one signed GET;
    it loads nothing and never keeps the server awake): busy, VRAM, its
    memory; a temperature and power draw only if the kit reports them (the
    kit of 2026-10 doesn't: the panel says so)."""
    out = {"ok": False, "gpu": None, "vram_used": None, "vram_total": None,
           "ram_used": None, "ram_total": None, "temp": None, "power": None}
    try:
        code, js = _srv_json(e, "GET", "/v1/usage", timeout=SRV_USAGE_S)
    except Exception:
        return out
    if code != 200 or not isinstance(js, dict):
        return out
    g, r = _srv_usage_gpu(js), _srv_usage_ram(js)
    raw = js.get("gpu") if isinstance(js.get("gpu"), dict) else {}

    def num(v, hi):
        return v if isinstance(v, (int, float)) and not isinstance(v, bool) and 0 <= v <= hi else None
    if g["vram_total_bytes"] and isinstance(e, dict) and e.get("id"):
        _rubin_vram[e["id"]] = g["vram_total_bytes"]
    out.update(ok=True, gpu=g["busy_pct"], vram_used=g["vram_used_bytes"],
               vram_total=g["vram_total_bytes"], ram_used=r["used_bytes"], ram_total=r["total_bytes"],
               temp=num(raw.get("temp_c"), 150), power=num(raw.get("power_w"), 2000))
    return out


def rubin_load(lanes, servers, mac=None, srv=None) -> dict:
    """The panel's load frame: this Mac and each server lane, with each
    machine's tokens a second (the call under way, else its last)."""
    mac = mac or rubin_mac_load
    srv = srv or rubin_server_load
    rows = []
    m = dict(mac())
    ml = next((l for l in lanes if l.kind == "mac"), None)
    m.update(name="This Mac", model=ml.model if ml else "", busy=ml.busy if ml else "",
             tps=(ml.live_tps() or ml.tps) if ml else 0.0, kind="mac")
    rows.append(m)
    for l in lanes:
        if l.kind != "server":
            continue
        e = servers.get(l.sid)
        u = dict(srv(e)) if e is not None else {"ok": False}
        u.update(name=l.name, model=l.model, busy=l.busy, tps=l.live_tps() or l.tps, kind="server")
        rows.append(u)
    return {"k": "load", "m": rows}


def rubin_sampler(io, lanes, servers, stop, period=RUBIN_LOAD_S):
    """The panel's sampler thread: a load frame every `period` seconds
    until the run ends."""
    def run():
        while not stop.wait(period):
            if io.gone is not None:
                return
            try:
                io.frame(rubin_load(lanes, servers))
            except Exception:
                pass
    t = ctx_thread(target=run, daemon=True)
    t.start()
    return t


# ---- who works
_rubin_vram = profile_cache("_rubin_vram", {})     # server id -> its card's bytes, read from /v1/usage


def rubin_server_lanes(ctx, probe=True):
    """[(lane, entry)] for each paired server the person lets the modes use
    (its "Use for Fast, Thinking and Pro" switch on) that answered its last
    check: its models for a thinking seat (srv_role_ok "think") that run
    whole on its card, strongest first, RUBIN_WRITERS_SRV of them. A card
    whose size the gateway's /v1/info doesn't report is read from /v1/usage
    (its vram_total_bytes), so a model too big for it is never sent: weights
    plus the gateway's margin must fit (_srv_fits), and a model the card
    refused lately is out (srv_is_nofit, 6b516). probe=False (the menu's
    row): no network read; a card of unknown size lists its "gpu" models."""
    out = []
    try:
        entries = _srv_read(ctx)
    except Exception:
        return out
    speeds = None
    for e in entries:
        if not _srv_paired(e) or e.get("prefer") is False:
            continue
        s = _srv_seen.get(e["id"]) or {}
        if not s.get("at") or s.get("err") or not s.get("reachable") or not s.get("auth"):
            continue
        vram = (s.get("gpu") or {}).get("vram_bytes") or _rubin_vram.get(e["id"])
        if not vram and probe:
            try:
                vram = rubin_server_load(e).get("vram_total")
            except Exception:
                vram = None
            if vram:
                _rubin_vram[e["id"]] = vram
        if not vram and probe:
            continue          # a card of unknown size gets nothing sent unasked (6b339's rule)
        cands = []
        for m in s.get("models") or []:
            if not isinstance(m, dict) or not m.get("name") or m.get("nofit"):
                continue
            if srv_is_nofit(e["id"], m["name"], m.get("size") or 0):
                continue
            if vram and (not isinstance(m.get("size"), int) or m["size"] <= 0):
                continue      # a size it doesn't say can't be checked against the card
            if _srv_fits(m, vram, bool(probe)):
                cands.append(dict(m, label=e["name"] + SERVER_SEP + m["name"], server=e["name"],
                                  sid=e["id"], params=_srv_params(m["name"])))
        if speeds is None:
            speeds = server_speeds(ctx)
        ranked = srv_rank(cands, "think", "normal", speeds)
        if ranked:
            out.append((RubinLane("server", e["name"], [m["label"] for m in ranked[:RUBIN_WRITERS_SRV]],
                                  sid=e["id"]), e))
    return out


def rubin_mac_model():
    """This Mac's strongest model that fits now (Fast's ladder), or ""."""
    try:
        r = resolve_tier("Fast")
    except Exception:
        r = []
    return r[0] if r else ""


def rubin_lanes(ctx, mac_label=None, probe=True):
    """Every machine that works on the question: this Mac and the servers.
    Never the cloud (6b521, per Patrick: local only, even with cloud power
    on, so it can run for hours and cost nothing)."""
    lanes, servers = [], {}
    mac_label = rubin_mac_model() if mac_label is None else mac_label
    if mac_label:
        lanes.append(RubinLane("mac", "This Mac", [mac_label]))
    for lane, e in rubin_server_lanes(ctx, probe):
        lanes.append(lane)
        servers[lane.sid] = e
    return lanes, servers


def rubin_tier_row(ctx) -> dict:
    """/api/tiers' row for Vera Rubin: what works on it, whether anything can."""
    try:
        lanes, _s = rubin_lanes(ctx, probe=False)
    except Exception:
        lanes = []
    models = [l.label_of(m) for l in lanes for m in l.models]
    n = len(models)
    return {"desc": TIERS[RUBIN_TIER]["desc"], "models": models, "cloud": [], "skipped": [],
            "available": bool(n), "count": n,
            "why": "" if n else ("Nothing can run it: download a model under Settings › Models "
                                 "or pair a server."),
            "note": ("It stops when you press Stop, or when %d rounds in a row bring nothing "
                     "better, and keeps this Mac%s busy the whole time." % (RUBIN_STALL_ROUNDS, " and your server" if any(
                         l.kind == "server" for l in lanes) else ""))
            + " Nothing is sent to the cloud."}


# ---- one round
def _rubin_par(jobs):
    """Run (fn, args) jobs side by side; their results in order."""
    res = [None] * len(jobs)

    def one(i, fn, a):
        try:
            res[i] = fn(*a)
        except Exception:
            res[i] = None
    ths = [ctx_thread(target=one, args=(i, fn, a), daemon=True) for i, (fn, a) in enumerate(jobs)]
    for t in ths:
        t.start()
    for t in ths:
        t.join()
    return res


def _rubin_budget(st, kind):
    left = st.ceiling_s - st.elapsed()
    return max(5.0, min(float(RUBIN_CALL_S[kind]), left))


def rubin_judge(st, lanes, answers, stop, seed=0):
    """The judges (one per machine, side by side) on `answers` (the current
    best first): ({index: {"score", "crit"}}, picks as indexes or -1, whys).
    The letters are shuffled per round, so a position isn't a verdict."""
    rnd = random.Random(seed)
    idx = list(range(len(answers)))
    rnd.shuffle(idx)
    letters = [chr(65 + i) for i in range(len(answers))]
    shown = [answers[i] for i in idx]           # letter k shows answers[idx[k]]
    msgs = rubin_judge_messages(st, shown, letters)
    judges = [l for l in lanes if l.kind in ("mac", "server") and not l.down][:2] or \
        [l for l in lanes if not l.down][:1]

    def one(lane):
        m = lane.order()[0]            # the model resident there now: no load to judge
        txt, _why = lane.call(m, msgs, "judging", stop, _rubin_budget(st, "judge"), raw=True)
        return rubin_judge_parse(txt, letters) if txt else None
    got = _rubin_par([(one, (l,)) for l in judges])
    comb, picks, whys = rubin_combine(got, letters)
    # "Answer B is clearer than A" means nothing on the console: the letters become names
    names = {L: ("the current answer" if idx[k] == 0 else "a revision") for k, L in enumerate(letters)}
    whys = [re.sub(r"\b[Aa]nswer ([A-Z])\b|\b([A-Z])\b(?= (?:is|has|does|covers|gives|adds|cites))",
                   lambda m: names.get(m.group(1) or m.group(2), m.group(0)), w) for w in whys]
    by_idx = {idx[k]: comb[L] for k, L in enumerate(letters)}
    pick_idx = [idx[letters.index(p)] if p in letters else -1 for p in picks]
    return by_idx, pick_idx, [w for w in whys if w], sum(1 for g in got if g)


def rubin_check(st, lanes, text, writer_lane, stop):
    """The fact-check of a new best answer against the evidence it cites
    (quality-1's verify_answer): on a machine that didn't write it when
    there is one. (text, checked, fixed)."""
    # a server first (its quick models answer the checker's JSON; this Mac's
    # big model sent nothing usable twice in the live runs), one that didn't
    # write the answer before one that did, this Mac last
    ok = [l for l in lanes if l.kind in ("mac", "server") and not l.down]
    ok.sort(key=lambda l: (l.kind != "server", l is writer_lane))
    lane = (ok or [None])[0]
    if lane is None or len(text) < VERIFY_MIN_CHARS or claim_count(text) < 2:
        return text, 0, 0
    cited = rubin_cites(text, len(st.sources))[0]
    block = rubin_block(st, cited, RUBIN_CHECK_PACK)
    m = lane.order()[0]

    why_ = []

    def run(_l, msgs, emit):
        txt, why = lane.call(m, msgs, "fact-checking", stop, _rubin_budget(st, "check"), raw=True)
        if not txt:
            why_.append(why)
            raise RuntimeError(why or "no check")
        emit(txt)
    res = verify_answer(run, "", block, [], text, budget_s=_rubin_budget(st, "check") + 30,
                        known=corrections_stuck(text, st.corrections))
    if DEV_HOME:
        print("rubin: check on %s: %s" % (lane.name, ("nothing usable (%s)" % (why_[0] if why_ else
                                                                             "no claims list"))
                                          if not res else
                                          "%d checked, %d fixed" % (res["checked"], res["fixed"])),
              file=sys.stderr, flush=True)
    if not res:
        return text, 0, 0
    new = (res["text"] or "").strip()
    # THE CHECK MAY CORRECT, NOT GUT (seen live, the Mac alone): the judged
    # winner's GB300 NVL72 sentences were deleted as "unsupported" and the
    # answer shipped as a hollow lead line. The check's text is never judged,
    # so it may cost at most RUBIN_CHECK_KEEP of the answer; past that the
    # judged text stands
    if res["fixed"] and new and len(new) >= RUBIN_CHECK_KEEP * len(text):
        return new, res["checked"], res["fixed"]
    return text, res["checked"], 0


def _rubin_notes_key(notes_list):
    return " ".join(sorted(re.sub(r"\W+", " ", str(n).lower()).strip() for n in notes_list))[:4000]


def rubin_round(st, lanes, stop, io, search=None):
    """One round after the first answer (see the section's head): weak
    points, targeted searches, competing revisions, the judges, the check.
    True when the best answer improved. A round the Stop button (or the
    reader leaving) cut short is not recorded and changes nothing."""
    t0 = time.time()
    st.round += 1
    n = st.round

    def phase(p, line=None):
        st.phase = p
        io.frame(rubin_snapshot(st, lanes))
        io.status("Vera Rubin · round %d · %s" % (n, line or p))

    def stalled(why, **row):
        st.stalls += 1
        st.changed = why
        r = {"r": n, "score": st.best["score"], "improved": False, "by": "", "why": "",
             "new": 0, "drafts": 0, "secs": round(time.time() - t0)}
        r.update(row)
        st.history_rows.append(r)
        return False

    # 1. the weak points: a critic on each machine, and the plan's open parts
    phase("finding the weak points")
    block = rubin_block(st)
    writers = [l for l in lanes if l.kind in ("mac", "server") and not l.down]

    persona = rubin_persona(st.sys_msg.get("content"))
    corrections = []

    def critic(lane):
        txt, _why = lane.call(lane.order()[0], critic_prompt(block, [st.best["text"]], persona=persona),
                              "reviewing", stop, _rubin_budget(st, "critic"))
        notes = critic_notes(txt) if txt else ""
        # quality-2's checks (6b518): a line bringing a number or a name from
        # nowhere goes; a WRONG the evidence settles becomes a correction
        try:
            notes, _dropped = critic_filter(notes, [block, st.best["text"]], time.strftime("%Y"))
            corrections.extend(critic_corrections(notes, block, [st.best["text"]]))
        except Exception:
            pass
        return notes
    notes_list = [x for x in _rubin_par([(critic, (l,)) for l in writers[:2]]) if x]
    st.corrections = list({c.get("quote"): c for c in corrections if c.get("quote")}.values())
    gaps = rubin_gaps(st)
    if rubin_should_stop(st, stop) in ("stopped", "gone"):
        return False
    # 2. targeted searches for exactly those
    items = rubin_queries(st, "\n".join(notes_list), gaps)
    new_n = 0
    if items:
        phase("searching for %d weak point%s" % (len(items), "" if len(items) == 1 else "s"))
        new_n = rubin_search(st, items, start=search)
        if new_n:
            io.ctl("SOURCES", st.rows())
    if rubin_should_stop(st, stop) in ("stopped", "gone"):
        return False
    nkey = _rubin_notes_key(notes_list)
    if not new_n and not gaps and (not notes_list or nkey == st.last_notes) \
            and not rubin_mech(st.best["text"], len(st.sources))[1]:
        # NOTHING NEW TO WORK ON (budget sanity): the same notes as last round,
        # no open part, no new source. No writer runs; the round is stalled.
        return stalled("Round %d: nothing new to work on (%s), so no machine rewrote it." % (
            n, "the reviewers repeated themselves" if notes_list else "the reviewers found nothing to fix"))
    st.last_notes = nkey
    # 3. competing revisions, one per writer, each on its own machine
    focus = rubin_focus(st.best["crit"])
    notes = rubin_notes(st, notes_list, gaps, new_n, focus)
    phase("writing revisions", "writing revisions (focus: %s)" % focus)
    msgs = final_prompt(st.sys_msg, rubin_block(st), [st.best["text"]], notes, cut=8000,
                        corrections=st.corrections)

    def write(lane):
        got = []
        for m in lane.order():
            if stop.is_set():
                break
            txt, why = lane.call(m, msgs, "writing a revision", stop, _rubin_budget(st, "write"))
            if txt:
                try:
                    txt = trim_recap(txt)        # the closing recap the persona forbids (6b518)
                except Exception:
                    pass
            if txt and len(txt) > 200 and len(txt) >= 0.4 * len(st.best["text"]):
                got.append((lane, lane.label_of(m), txt))
            elif why and why not in ("stopped", "too slow", "empty", "degenerate", "busy"):
                lane.fails += 1
                if lane.fails >= 3:
                    lane.down = True          # three refusals in a row: it sits the rest out
        if got:
            lane.fails = 0
        return got
    cands = []
    for g in _rubin_par([(write, (l,)) for l in lanes if not l.down]):
        cands += g or []
    if rubin_should_stop(st, stop) in ("stopped", "gone"):
        return False
    st.drafts += len(cands)
    if not cands:
        return stalled("Round %d: no revision came back in time." % n, new=new_n)
    # 4. the judges, blind, the current best among the revisions
    phase("judging %d revision%s" % (len(cands), "" if len(cands) == 1 else "s"))
    texts = [st.best["text"]] + [c[2] for c in cands]
    a_i = None
    if st.anchor and st.anchor != st.best["text"]:
        a_i = len(texts)                 # the first answer rides along as the yardstick
        texts.append(st.anchor)
    res, picks, whys, n_j = rubin_judge(st, lanes, texts, stop, seed=n)
    if rubin_should_stop(st, stop) in ("stopped", "gone"):
        return False
    if not n_j:
        return stalled("Round %d: the judges didn't answer, so the answer stands." % n,
                       new=new_n, drafts=len(cands))
    res = rubin_apply_mech(res, texts, len(st.sources))       # the counted points off
    best_now = (res.get(0) or {}).get("score", 0.0)
    win = max(range(1, len(cands) + 1), key=lambda i: (res.get(i) or {}).get("score", 0.0))
    w_score = (res.get(win) or {}).get("score", 0.0)
    if not rubin_accept(best_now, w_score, [p for p in picks if p != a_i]):
        # the score shown stays the one the answer won with: a judging of an
        # unchanged answer moves by noise alone, and the line would wander
        st.weak = (res.get(0) or {}).get("weak") or st.weak
        return stalled("Round %d: no revision beat the answer (the strongest scored %.1f, the "
                       "answer %.1f in the same judging)." % (n, w_score, best_now),
                       new=new_n, drafts=len(cands), score=st.best["score"])
    w_lane, w_lbl, w_text = cands[win - 1]
    w_lane.wins = getattr(w_lane, "wins", 0) + 1
    w_lane.last_win = n
    # 5. the new best, fact-checked against the evidence it cites
    if not stop.is_set():
        phase("fact-checking the new answer", "fact-checking")
        try:
            w_text, ck, fx = rubin_check(st, lanes, w_text, w_lane, stop)
        except Exception:
            ck = fx = 0
        st.checked += ck
        st.fixed += fx
    gain = w_score - best_now
    a_now = (res.get(a_i) or {}).get("score") if a_i is not None else best_now
    # never below the score it replaced (seen live: one judge put the first
    # answer above the old best, and an improvement drew a falling line)
    shown = max(st.best["score"], rubin_yardstick(st.anchor_score, a_now, w_score))
    st.best = {"text": w_text, "score": shown, "crit": (res.get(win) or {}).get("crit", {}),
               "by": w_lbl, "round": n, "judged": round(w_score, 2)}
    st.weak = (res.get(win) or {}).get("weak") or []
    st.best_ever = max(st.best_ever, w_score)
    st.stalls = 0
    why = whys[0] if whys else ""
    st.changed = "Round %d: %s's revision won, +%.1f%s%s." % (
        n, w_lbl, gain, (" · " + why.rstrip(".")) if why else "",
        (" · %d new source%s" % (new_n, "" if new_n == 1 else "s")) if new_n else "")
    st.history_rows.append({"r": n, "score": st.best["score"], "improved": True, "by": w_lbl,
                            "why": why, "new": new_n, "drafts": len(cands),
                            "secs": round(time.time() - t0), "judged": round(w_score, 2),
                            "best_now": round(best_now, 2),
                            "first_now": round(a_now, 2) if a_now is not None else None})
    io.answer(w_text + rubin_footer(st))
    return True


def rubin_first(st, lanes, messages, stop, io, council=None):
    """Round 0: the first answer, written as Thinking writes it (6b515's
    craft through run_council: one writer, a critic, the brief, the
    fact-check) on the server when there is one, else on this Mac; shown as
    it streams. The text on screen afterwards, or ""."""
    srv = next((l for l in lanes if l.kind == "server" and not l.down), None)
    mac = next((l for l in lanes if l.kind == "mac"), None)
    shown, counts = [], {"drafts": 0, "checked": 0, "fixed": 0}

    def tap(c):
        if isinstance(c, Ctl):
            s = str(c)
            if s == NUL + "RESET" + NUL:
                del shown[:]
            elif s.startswith(NUL + "DRAFT:") and "(no answer" not in s and "(review)" not in s:
                counts["drafts"] += 1
            elif s.startswith(NUL + "STEP:") and '"verify"' in s:
                m = re.search(r"Checked (\d+) claims?(?:, fixed (\d+))?", s)
                if m:
                    counts["checked"], counts["fixed"] = int(m.group(1)), int(m.group(2) or 0)
        elif c:
            shown.append(str(c))
        io._w(c)
        if io.gone is not None:
            raise BrokenPipeError("the reader left")
    council = council or run_council
    plans = []
    if srv is not None:
        plans.append((srv, list(srv.models[:2]) if len(srv.models) > 1 else [srv.models[0], srv.models[0]],
                      dict(srv_only=True, srv_merge=True)))
    if mac is not None:
        plans.append((mac, [mac.models[0], mac.models[0]], {}))
    for lane, labels, kw in plans:
        if stop.is_set():
            break
        del shown[:]
        with lane.lock:
            lane.busy, lane.model = "writing the first answer", lane.label_of(labels[0])
            try:
                council(labels, messages, tap, io.status, hurry=stop, craft=True, **kw)
            except (StaleProfile, BrokenPipeError, ConnectionResetError):
                raise
            except Exception:
                pass
            finally:
                lane.busy, lane.model = "", ""
                lane.resident = lane.label_of(labels[-1])
        text = "".join(shown).strip()
        if text and not text.startswith("⚠️"):
            st.best.update(text=text, by=lane.label_of(labels[0]), round=0)
            st.drafts += max(1, counts["drafts"])
            st.checked += counts["checked"]
            st.fixed += counts["fixed"]
            return text
    return ""


def _rubin_log(st):
    """A dev copy's log says how each round went (the NOTES measurements read it)."""
    if DEV_HOME and st.history_rows:
        r = st.history_rows[-1]
        print("rubin: round %d score=%.2f improved=%s by=%s new=%s drafts=%s secs=%s el=%ds "
              "judged=%s best_now=%s first_now=%s | %s" % (
                  r["r"], r["score"], r["improved"], r.get("by") or "-", r.get("new"), r.get("drafts"),
                  r.get("secs"), st.elapsed(), r.get("judged"), r.get("best_now"), r.get("first_now"),
                  st.changed[:200]), file=sys.stderr, flush=True)


def rubin_plan(st, lanes, stop, prefer=None):
    """The question's plan, on `prefer` (the machine the first answer isn't
    using), else the rules' own."""
    txt = ""
    if prefer is not None:
        m = prefer.order()[0] if prefer.kind == "server" else prefer.models[0]
        today = strftime_np("%A, %B %-d, %Y", st.today)
        txt, _w = prefer.call(m, [{"role": "user", "content": RUBIN_PLAN.format(today=today)
                                   + st.question[:1500]}], "planning", stop, RUBIN_CALL_S["plan"],
                              raw=True)
    st.plan = rubin_plan_parse(txt, st.question, st.today)
    return st.plan


def run_rubin(question, messages, emit, status, step, stop, ctx=None, ground=None,
              lanes=None, servers=None, search=None, council=None, web=True,
              ceiling_s=RUBIN_CEILING_S, stall_n=RUBIN_STALL_ROUNDS, sample=True):
    """VERA RUBIN (6b519): see the section's head. `ground`: the handler's
    grounded search of the question (6b514), when it ran; `stop`: the
    request's hurry Event (Stop). Writes through emit; returns the state."""
    io = RubinIO(emit, status, step, stop)
    sys_msg = messages[0] if messages and messages[0].get("role") == "system" else {"role": "system", "content": ""}
    st = RubinState(question, sys_msg, rubin_history(messages), rubin_reader(sys_msg.get("content")),
                    ceiling_s=ceiling_s, stall_n=stall_n, io=io)
    if lanes is None:
        lanes, servers = rubin_lanes(ctx)
    servers = servers or {}
    if not [l for l in lanes if l.kind in ("mac", "server")]:
        io._w(AppText("⚠️ Vera Rubin needs a model on this Mac or a paired server, and "
                      "neither can answer right now."))
        return st
    io.frame({"k": "start", "tier": RUBIN_TIER, "stall_n": st.stall_n, "ceiling": st.ceiling_s,
              "lanes": [{"n": l.name, "k": l.kind, "models": [l.label_of(m) for m in l.models]}
                        for l in lanes]})
    sampler = None
    done_ev = threading.Event()
    if sample:
        io.frame(rubin_load(lanes, servers))
        sampler = rubin_sampler(io, lanes, servers, done_ev)
    try:
        # the evidence the handler already gathered keeps its numbers
        if ground is not None:
            srcs, _p, _r, _n = ground.snapshot()
            st.add_sources(srcs, getattr(ground, "terms", []) or [], keep_all=True)
            st.searches += 1
        elif web:
            st.phase = "searching the web"
            io.frame(rubin_snapshot(st, lanes))
            g = (search or (lambda q, qs: ground_start(q)))(question, [])
            try:
                g.wait(timeout=GROUND_TOTAL_S)
                srcs, _p, _r, _n = g.snapshot()
                st.add_sources(srcs, getattr(g, "terms", []) or [])
            except Exception:
                pass
            st.searches += 1
            if st.sources:
                io.ctl("SOURCES", st.rows())
        first_msgs = [dict(m) for m in messages]
        if ground is None and st.sources:
            first_msgs[-1]["content"] = grounded_turn(question, rubin_pack(st, budget=GROUND_PACK_CHARS))
            first_msgs[0] = dict(first_msgs[0], content=str(first_msgs[0].get("content") or "") + GROUND_SYSTEM)
            st.sys_msg = first_msgs[0]
        # round 0: the plan beside the first answer (on the other machine), then the first answer judged
        srv = next((l for l in lanes if l.kind == "server"), None)
        mac = next((l for l in lanes if l.kind == "mac"), None)
        other = mac if srv is not None else None
        st.phase = "writing the first answer"
        io.frame(rubin_snapshot(st, lanes))
        if other is None:
            rubin_plan(st, lanes, stop, srv or mac)
            first = rubin_first(st, lanes, first_msgs, stop, io, council)
        else:
            res = _rubin_par([(rubin_first, (st, lanes, first_msgs, stop, io, council)),
                              (rubin_plan, (st, lanes, stop, other))])
            first = res[0] or ""
        if not st.plan:
            st.plan = rubin_plan_parse("", question, st.today)
        if not first:
            st.reason = "gone" if io.gone is not None else ("stopped" if stop.is_set() else "failed")
            if io.gone is None and not stop.is_set():
                io._w(AppText("⚠️ Vera Rubin couldn’t write a first answer: none of "
                              "its models answered."))
            return st
        if web and st.plan and not stop.is_set():
            # the plan's parts the first answer leaves open are searched now
            items = [(p["q"], p.get("search") or []) for p in rubin_gaps(st)][:RUBIN_SEARCHES]
            if items:
                st.phase = "searching for the plan's open parts"
                io.frame(rubin_snapshot(st, lanes))
                if rubin_search(st, items, start=search):
                    io.ctl("SOURCES", st.rows())
        if not stop.is_set():
            st.phase = "judging the first answer"
            io.frame(rubin_snapshot(st, lanes))
            res, _p, _w, n_j = rubin_judge(st, lanes, [st.best["text"]], stop, seed=0)
            res = rubin_apply_mech(res, [st.best["text"]], len(st.sources))
            if n_j and res.get(0):
                st.best.update(score=res[0]["score"], crit=res[0]["crit"])
                st.best_ever = res[0]["score"]
                st.weak = res[0].get("weak") or []
            st.anchor, st.anchor_score = st.best["text"], st.best["score"]
        st.history_rows.append({"r": 0, "score": st.best["score"], "improved": True,
                                "by": st.best["by"], "why": "the first answer", "new": len(st.sources),
                                "drafts": st.drafts, "secs": round(st.elapsed())})
        st.changed = "Round 0: %s wrote the first answer%s." % (
            st.best["by"] or "the writer",
            (", scored %.1f" % st.best["score"]) if st.best["score"] else "")
        _rubin_log(st)
        while True:
            why = rubin_should_stop(st, stop)
            if why:
                st.reason = why
                break
            wait = RUBIN_BACKOFF_S[min(st.stalls, len(RUBIN_BACKOFF_S) - 1)]
            if wait:
                st.phase = "pausing %ds before the next round" % int(wait)
                io.frame(rubin_snapshot(st, lanes))
                if stop.wait(min(wait, max(0.0, st.ceiling_s - st.elapsed()))):
                    continue
            _n_rows = len(st.history_rows)
            rubin_round(st, lanes, stop, io, search)
            io.frame(rubin_snapshot(st, lanes))
            if len(st.history_rows) > _n_rows:
                _rubin_log(st)
        return st
    finally:
        done_ev.set()
        st.done = True
        st.phase = "done"
        if not st.reason:
            st.reason = "gone" if io.gone is not None else "stopped"
        if st.best["text"] and io.gone is None:
            io.answer(st.best["text"] + rubin_footer(st, final=True))
        try:
            io.frame(rubin_snapshot(st, lanes))
            if sample:
                io.frame(rubin_load(lanes, servers))
        except Exception:
            pass
        if io.gone is not None and isinstance(io.gone, (StaleProfile, BrokenPipeError,
                                                       ConnectionResetError)):
            raise io.gone
# ==== VERA RUBIN (6b519): end ====



# ------------------------------------------ the turn writer (0b 5.4)
# The server saves each question when it arrives and each answer as it
# ends, from the bytes the stream actually carried (6b322). The page no
# longer saves turns, so an answer that finishes into a chat nobody is
# looking at is kept, and a stopped one keeps what was shown.
_TURN_TAGS = ("RUN|STATUS|DRAFT|SOURCES|PHOTOS|MAP|CTX|PLACEHINT|PLACES2"
              "|STEP|APPROVE|RATE"      # RATE: the writer's pace (6b515), the page's twin
              "|USAGE|DONE"             # a model call's tokens; the run's clock (6b528)
              "|OFFER"                  # the way on when a server didn't answer (6b570)
              "|RUBIN")                 # Vera Rubin's console (6b519)
# the page's rules, character for character: JS "." stops at a line
# break, and JS "$" (unlike Python's) only at the very end
_TURN_FRAME = re.compile("\x00(" + _TURN_TAGS
                         + "):([^\n\r\u2028\u2029]*?)\x00")
_TURN_PART = re.compile("\x00(?:" + _TURN_TAGS + "):[^\x00]*\\Z")
_TURN_RESET = "\x00RESET\x00"
_TURN_BOLD_SKIP = re.compile(
    r"^(open|closed|note|heads|tip|hours|today|tonight|monday|tuesday|"
    r"wednesday|thursday|friday|saturday|sunday|yes|no)\b", re.I)
_turns_live = profile_cache("_turns_live", {})
_turns_lock = threading.Lock()


def turn_text(raw: str) -> str:
    """The answer text exactly as the page shows it (0b L5, R-2-22):
    every frame lifted out, then only what follows the last RESET. The
    page's parseStream() does the same; one corpus checks both."""
    t = _TURN_PART.sub("", _TURN_FRAME.sub("", raw))
    cut = t.rfind(_TURN_RESET)
    return t[cut + len(_TURN_RESET):] if cut >= 0 else t


def _places_worth_showing(places, loc=""):
    """The places a message may keep (6b437, per Patrick: stray black
    boxes under an answer). A place with a description, hours or
    coordinates is worth a card. A bare name is only worth keeping when
    there is a location to pin it in (the page geocodes it into a map);
    a bare name with no location is a bold phrase, not a place."""
    if not isinstance(places, list):
        return []
    ps = [p for p in places if isinstance(p, dict) and p.get("n")]
    if any(p.get("d") or p.get("h") or p.get("lat") is not None
           or p.get("lon") is not None for p in ps):
        return ps
    return ps if (loc or "").strip() else []


def turn_record(raw: str, searched: bool = False, aborted: bool = False):
    """The assistant message the page builds at the end of a stream
    (content, and drafts, sources, photos, map, places and loc when
    present), or None: nothing to keep, or an error line (the question
    stays unanswered, for Try again; 0b Q12). A stopped stream's empty
    answer isn't rescued from a draft: the page doesn't either."""
    drafts, got = [], {}
    for tag, body in _TURN_FRAME.findall(raw):
        try:
            d = json.loads(body)
        except ValueError:
            continue
        if tag == "DRAFT":
            if isinstance(d, dict) and not any(x.get("m") == d.get("m")
                                               for x in drafts):
                drafts.append(d)
        elif tag in ("SOURCES", "PHOTOS", "MAP", "PLACEHINT", "PLACES2"):
            got[tag] = d
        elif tag == "CTX" and isinstance(d, dict):
            got["CTX"] = d.get("loc") or ""
        # the run's own numbers (6b528): every model call's tokens, the
        # clock, and each step's last state, so a reopened chat shows the
        # same token line and "How it got there" the live answer did
        elif tag == "USAGE" and isinstance(d, dict):
            got.setdefault("USAGE", []).append(d)
        elif tag == "DONE" and isinstance(d, dict):
            got["DONE"] = d
        elif tag == "RATE" and isinstance(d, dict):
            got["RATE"] = d
        elif tag == "OFFER" and isinstance(d, dict):
            got["OFFER"] = dict({"server": str(d.get("server") or "")[:60]},
                                **({"asleep": 1} if d.get("asleep") else {}))
        elif tag == "STEP" and isinstance(d, dict) and d.get("id"):
            st = got.setdefault("STEP", {})
            _prev = st.get(d["id"]) or {}
            st[d["id"]] = {k: d[k] for k in ("id", "l", "s", "d") if k in d}
            # A CODE RUN KEEPS ITS RISK AND ITS SIZE (6b622): a command's
            # first frame says reading / changes / irreversible (and "· N
            # steps" for a batch); its last says the result. The reopened
            # chat draws the risk tag from r, the batch from n.
            # (inline, so the gauntlet's lifted copy of this function
            # needs no other name)
            if re.match(r"(conn|cmd\d+(?:_\d+)?|reboot\d+)$", str(d["id"])):
                _dd = str(d.get("d") or "")
                _rk = ("read" if re.match(r"reading\b", _dd) else "write"
                       if re.match(r"changes\b", _dd) else "danger"
                       if re.match(r"irreversible\b", _dd) else "")
                _bn = re.search(r"\u00b7\s*(\d+) steps", _dd)
                if _rk or _prev.get("r"):
                    st[d["id"]]["r"] = _rk or _prev["r"]
                if _bn or _prev.get("n"):
                    st[d["id"]]["n"] = int(_bn.group(1)) if _bn else _prev["n"]
    full = turn_text(raw)
    if not full and not aborted:
        good = [x for x in drafts if not str(x.get("t", "")).startswith(
            "(no answer")]
        full = str(good[0].get("t", "")) if good else ""
    places = got.get("PLACES2")
    pm = re.search(r"\[\[PLACES\]\]\s*(\[[\s\S]*?\])\s*\Z", full)
    if pm:
        try:
            places = json.loads(pm.group(1))[:4]
        except ValueError:
            places = None
    full = re.sub(r"\n?\[\[PLACES\]\][\s\S]*\Z", "", full).strip()
    # bold phrases are venue names only when the server said the question
    # was a place lookup (PLACEHINT); a searched answer's bold lead-ins
    # are not places (6b437, per Patrick)
    if not places and got.get("PLACEHINT"):
        bold = [m.strip() for m in re.findall(r"\*\*([^*\n]{3,42})\*\*",
                                              full)]
        bold = [re.sub(r"[.,;:!?]+$", "", b) for b in bold]
        bold = [b for b in bold
                if re.match(r"[A-Z\u00c0-\u017f]", b)
                and not b.startswith("$")
                and not re.search(r"\d\s*(am|pm)", b, re.I)
                and not _TURN_BOLD_SKIP.match(b)
                and len(b.split()) <= 5]
        uniq = list(dict.fromkeys(bold))[:4]
        places = [{"n": b, "d": "", "h": ""} for b in uniq] or None
    if not full or full.startswith("\u26a0\ufe0f") or "\n\u26a0\ufe0f" in full:
        return None
    rec = {"role": "assistant", "content": full}
    if drafts:
        rec["drafts"] = drafts
    if got.get("SOURCES"):
        rec["sources"] = got["SOURCES"]
    if got.get("PHOTOS"):
        rec["photos"] = got["PHOTOS"]
    if got.get("MAP"):
        rec["map"] = got["MAP"]
    places = _places_worth_showing(places, got.get("CTX", ""))
    if places:
        rec["places"] = places
        rec["loc"] = got.get("CTX", "")
    if got.get("USAGE"):
        rec["usage"] = got["USAGE"][:40]
    if got.get("DONE"):
        rec["run"] = got["DONE"]
    if got.get("RATE"):
        rec["rate"] = got["RATE"]
    if got.get("OFFER"):
        rec["offer"] = got["OFFER"]          # the buttons come back with the chat (6b570)
    if aborted and full:
        rec["stopped"] = True                # a Stop keeps what was shown, and says so (6b570)
    if got.get("STEP"):
        _sv = list(got["STEP"].values())
        # a Code run is every command it ran, up to REMOTE_CAP and its
        # batches' lines (6b622); any other answer, its first 24 steps
        rec["steps"] = _sv[:160] if any(
            re.match(r"(conn|cmd\d+(?:_\d+)?|reboot\d+)$", str(x.get("id")))
            for x in _sv) else _sv[:24]
    return rec


def _turn_rec(t):
    return turn_record(b"".join(t["wire"]).decode("utf-8", "replace"),
                       t.get("searched", False), t.get("aborted", False))


def _turn_finish(t):
    """Save a turn's answer once: at the stream's end, at a quit
    mid-stream (_turns_flush), or when the chat's next question arrives
    (_turns_settle), whichever comes first."""
    with _turns_lock:
        if t.get("done"):
            return
        t["done"] = True
        _turns_live.pop(id(t), None)
    try:
        rec = _turn_rec(t)
        if rec:
            chat_append_late(t["id"], t["n"], t["h"], rec, t["base"])
    except Exception:
        pass


def _turns_settle(chats, cid, keep=True) -> bool:
    """Called under _chats_lock with the list in hand: every answer still
    streaming into cid is settled now, kept (a Stop the server hasn't
    noticed yet, before the chat's next question) or thrown away (Try
    again, Edit & resend). True when the list changed."""
    with _turns_lock:
        live = [t for t in _turns_live.values()
                if t.get("id") == cid and not t.get("done")]
        for t in live:
            t["done"] = True
            _turns_live.pop(id(t), None)
    changed = False
    for t in live:
        if keep:
            t["aborted"] = True
            rec = _turn_rec(t)
            if rec:
                changed = bool(_chat_late(chats, t["id"], t["n"], t["h"],
                                          rec, _bk(t["base"]))) or changed
    return changed


_turns_flushing = [False]


def _turns_flush():
    """At a quit: keep every answer still streaming, as far as it got.
    Once only: a signal arriving during the atexit flush would otherwise
    wait on the chat lock its own thread holds (review of 6b322)."""
    if _turns_flushing[0]:
        return
    _turns_flushing[0] = True
    with _turns_lock:
        live = list(_turns_live.values())
    for t in live:
        _turn_finish(t)
    # a delete inside its undo window is final at a quit (0b 5.6): its id
    # joins gone and chats.json loses it now (the next start would too),
    # in the profile active at the quit (6b329)
    try:
        _chat_finalize(current_ctx(), now=float("inf"))
    except Exception:
        pass


atexit.register(_turns_flush)


def _turns_flush_ctx(ctx):
    """At a switch (M9, from the review of 6b329): the answers still
    streaming for the profile being left are kept as far as they got,
    through its own ctx, before the epoch moves, as a quit keeps them.
    The streams themselves then stop (emit sees ctx.cancel)."""
    with _turns_lock:
        live = [t for t in _turns_live.values() if isinstance(t, dict)
                and t.get("base") is ctx and not t.get("done")]
    for t in live:
        try:
            _turn_finish(t)
        except Exception:
            pass


def turns_live_count(ctx) -> int:
    """How many answers are streaming for ctx (the sign-out sheet)."""
    with _turns_lock:
        return len([t for t in _turns_live.values() if isinstance(t, dict)
                    and t.get("base") is ctx and not t.get("done")])


# the headers a proxy or tunnel adds to what it forwards (see _gate)
_PROXY_HEADERS = ("X-Forwarded-For", "X-Forwarded-Host", "Forwarded",
                  "X-Real-IP", "Cf-Connecting-Ip", "True-Client-IP")


class StudioHandler(http.server.BaseHTTPRequestHandler):
    protocol_version = "HTTP/1.0"  # lets us stream then close, no chunking

    def log_message(self, *args):
        pass

    # NOTHING IS KEPT BY THE WEB VIEW (0b 5.11, 6b322): every response,
    # the page, JSON, pictures, videos, downloads and errors, is no-store
    # (it was no-cache, private max-age or public for a week here and
    # there). Any Cache-Control a route sets is replaced.
    def send_header(self, keyword, value):
        if keyword.lower() == "cache-control":
            return
        super().send_header(keyword, value)

    def end_headers(self):
        super().send_header("Cache-Control", "no-store")
        self._head_sent = True
        super().end_headers()

    # ONE WRAPPER PER REQUEST (6b322): the thread's leftovers from the
    # last request are cleared first (0b 5.11: a search's rows or a cloud
    # answer's provider must never reach the next request on this
    # thread); a store that can't be read answers 503 with its line
    # (0b L1); and a chat turn in flight is saved however the request
    # ends. THE PROFILE IS TAKEN ONCE, HERE (1a 5.2, 6b329): the request
    # and every thread it starts work for this ctx to the end, and a
    # write after a switch is refused (409 when nothing was sent yet).
    def _run(self, fn):
        _tl_search.__dict__.clear()
        _answered.pop(threading.get_ident(), None)
        self._turn = None
        self._head_sent = False
        self._bench_held = False       # an /api/chat counted (6b331)
        self._bench_srv_held = False   # a server-only /api/chat counted (6b341)
        # a switch under way (M9): wait for it, then work for the profile
        # it leaves active (the page's old X-Profile then gets 409). One
        # that outlasts the wait is not served under the switch's hold
        self.ctx = switch_ctx()
        if self.ctx is None:
            self._send_json({"err": "The profile is changing. Try again in "
                             "a moment."}, code=503)
            return
        bind_ctx(self.ctx)
        try:
            fn()
        except StoreReadError as exc:
            if not self._head_sent:
                self._send_json({"err": READ_FAIL.get(str(exc),
                                 "Couldn’t read that. Nothing changed."),
                                 "unreadable": str(exc)}, code=503)
        except StaleProfile:
            if not self._head_sent:
                self._profile_changed(drain=False)
        finally:
            t, self._turn = self._turn, None
            if t:
                _turn_finish(t)
            if self._bench_held:
                self._bench_held = False
                bench_release()
            if self._bench_srv_held:
                self._bench_srv_held = False
                bench_release_remote()
            bind_ctx(None)

    def do_GET(self):
        self._run(self._do_GET)

    def do_POST(self):
        self._run(self._do_POST)

    def _gate(self):
        """True = let the request through; False = already answered it.

        ONLY THIS APP'S OWN WINDOW GETS IN (6b310; the web version's door
        page is gone with the web version). On every request:
          * addressed to this server's own loopback name and port. A
            DNS-rebinding page arrives under its own hostname, so it
            fails here before anything else is read.
          * no proxy header (6b320).
          * carrying this launch's ACCESS_KEY as a cookie. The window
            collects it once through /?boot=<one-time code> (6b321);
            another account's process on this computer, or a page on a
            stray port, never has it.
          * and X-Api-Token (6b321) on everything but the page itself and
            the public clips under /static/ (_COOKIE_ONLY). Allow-listed,
            not prefix-checked, so a route added outside /api can't skip
            it and '//api' or absolute-form paths can't slip past.
        The cookie is named for the port because browsers share cookies
        across the ports of one host: a dev instance's key must not
        overwrite the app's."""
        host = (self.headers.get("Host") or "").strip().lower()
        if host not in ("127.0.0.1:%d" % PORT, "localhost:%d" % PORT):
            return self._deny()
        # NOTHING THROUGH A PROXY (6b320, ISO-14). The window talks to us
        # directly; a request a proxy or tunnel forwarded carries one of
        # these, and with the web version gone nobody may reach the app
        # that way, key or no key.
        if any(self.headers.get(h) for h in _PROXY_HEADERS):
            return self._deny()
        keyed = self._keyed()
        if self.command == "GET" and self.path.startswith("/?boot="):
            # the window's first load trades the one-time code for the
            # cookie (6b321). Already keyed (a reload of that URL): just
            # go home, and leave the code alone.
            if keyed or _take_boot_code(urllib.parse.unquote(
                    self.path[len("/?boot="):])):
                self.send_response(302)
                if not keyed:
                    self.send_header(
                        "Set-Cookie", "millen_key_%d=%s; Path=/; HttpOnly; "
                        "SameSite=Strict" % (PORT, ACCESS_KEY))
                self.send_header("Location", "/")
                self.send_header("Cache-Control", "no-store")
                self.send_header("Content-Length", "0")
                self.end_headers()
            else:
                self._deny()
            return False
        if ACCOUNTS and self.command == "GET" and self.path.startswith(
                "/account?boot="):
            # the account window's first load trades its own one-time code
            # (M9, 1a 5.9); the cookie is the same launch key
            if keyed or _take_acct_boot(urllib.parse.unquote(
                    self.path[len("/account?boot="):])):
                self.send_response(302)
                if not keyed:
                    self.send_header(
                        "Set-Cookie", "millen_key_%d=%s; Path=/; HttpOnly; "
                        "SameSite=Strict" % (PORT, ACCESS_KEY))
                self.send_header("Location", "/account")
                self.send_header("Cache-Control", "no-store")
                self.send_header("Content-Length", "0")
                self.end_headers()
            else:
                self._deny()
            return False
        if not keyed:
            return self._deny()
        if self.command == "GET" and _COOKIE_ONLY.fullmatch(self.path):
            return True
        if self.command == "GET" and (
                hz_debug_spec(self.path, bool(DEV_HOME)) is not None
                or _HZ_FONT_RX.fullmatch(self.path)):
            # the Horizon's bundled fonts (6b526), fetched by @font-face with
            # no way to add a header; and a dev copy's frozen page
            return True
        if ACCOUNTS and self.command == "GET" and self.path in ACCOUNT_STATIC:
            # the account window's page and its two static files: nothing
            # personal, and a <script src> can't send a header
            return True
        if self.path.startswith("/api/account/"):
            # ONLY THE ACCOUNT WINDOW'S TOKEN (1a 5.9): the main window's
            # is refused here, and this one is refused everywhere else (it
            # isn't API_TOKEN); bound to the profile it was opened for
            tok = _ACCT["token"]
            if not (ACCOUNTS and tok and secrets.compare_digest(
                    (self.headers.get("X-Api-Token") or "").encode("utf-8"),
                    tok.encode("utf-8"))):
                return self._deny()
            xp = self.headers.get("X-Profile") or ""
            tag = _ACCT["tag"] or ""
            if not (secrets.compare_digest(xp.encode("utf-8", "replace"),
                                           tag.encode("utf-8"))
                    and tag == self.ctx.tag):
                # a moved epoch: 409, and the window closes (1a 5.9)
                account_close(keep_running=True)
                return self._profile_changed()
            _ACCT["calls"] += 1
            return True
        # compare_digest on BYTES, as for the cookie
        if not secrets.compare_digest(
                (self.headers.get("X-Api-Token") or "").encode("utf-8"),
                API_TOKEN.encode("utf-8")):
            return self._deny()
        # X-PROFILE (1a 5.2, 4.5; 6b329): the page names the profile it
        # was drawn for. After a switch its calls get 409 and change
        # nothing, and the page reloads. Native callers (the gauntlet,
        # ci_smoke) send none and act on the profile active at their
        # start, like any request.
        xp = self.headers.get("X-Profile")
        if xp is not None and not secrets.compare_digest(
                xp.encode("utf-8", "replace"),
                self.ctx.tag.encode("utf-8")):
            return self._profile_changed()
        return True

    def _profile_changed(self, drain=True) -> bool:
        """409 profile-changed (1a 5.2): nothing was done. At the gate a
        POST's body is drained first (see _refuse); a route that already
        read it passes drain=False. The page reloads on it."""
        try:
            n = int(self.headers.get("Content-Length", 0) or 0)
            while drain and n > 0 and self.command == "POST":
                chunk = self.rfile.read(min(n, 65536))
                if not chunk:
                    break
                n -= len(chunk)
        except Exception:
            pass
        body = json.dumps({"err": "profile-changed"}).encode()
        try:
            self.send_response(409)
            self.send_header("Content-Type", "application/json")
            self.send_header("X-Profile", "changed")
            self.send_header("Content-Length", str(len(body)))
            self.end_headers()
            self.wfile.write(body)
        except Exception:
            pass
        return False

    def _keyed(self) -> bool:
        # EVERY cookie of that name: a stray one with a longer Path sorts
        # first and must not shadow the real key. compare_digest on
        # BYTES: a str with a non-ASCII character raises TypeError.
        for v in re.findall(r"(?:^|;)\s*millen_key_%d=([^;\s]+)" % PORT,
                            self.headers.get("Cookie", "") or ""):
            if secrets.compare_digest(v.encode("utf-8"),
                                      ACCESS_KEY.encode("utf-8")):
                return True
        return False

    def _deny(self) -> bool:
        if self.command == "POST":
            return self._refuse(403, "open the app from its own window")
        body = brand("MillenAI: open the app from its own window."
                     ).encode("utf-8")
        try:
            self.send_response(403)
            self.send_header("Content-Type", "text/plain; charset=utf-8")
            self.send_header("Content-Length", str(len(body)))
            self.end_headers()
            self.wfile.write(body)
        except Exception:
            pass
        return False

    # the three content types a cross-site HTML form can post. Nothing
    # here speaks them, so their presence on a write IS the forgery.
    FORM_CT = ("application/x-www-form-urlencoded", "multipart/form-data",
               "text/plain")

    def _csrf_ok(self) -> bool:
        """Cross-site write protection (6b257). The owner's window holds
        the launch-key cookie, which _gate checks first (6b310); this is
        the wall behind it. A browser counts every port of 127.0.0.1 as
        one site, so SameSite alone would let a page on another local
        port POST here with the cookie riding along and erase a chat
        history or delete multi-GB weights. Two doors, both closed on
        writes only:

          * ORIGIN, when the browser sends one, must be this same
            server. Browsers attach Origin to every cross-site POST
            (forms included), so a mismatch is a forgery by definition.
          * The three FORM content types are refused outright — they
            are the one way a cross-site form reaches a JSON endpoint
            without a preflight.

        Native callers — curl, urllib, the gauntlet — send no Origin
        and a JSON content type, so they sail through.
        Every write must also arrive addressed to localhost, which is
        what closes DNS rebinding (_gate checks the same, first)."""
        ct = (self.headers.get("Content-Type") or "").split(";")[0]
        if ct.strip().lower() in self.FORM_CT:
            return False
        host = (self.headers.get("Host") or "").strip().lower()
        origin = (self.headers.get("Origin") or "").strip()
        if origin and origin.lower() != "null":
            try:
                oh = urllib.parse.urlsplit(origin).netloc.lower()
            except Exception:
                return False
            if not self._same_host(oh, host):
                return False
        # a request addressed to anything but this machine is a
        # rebinding attempt, not the app (unconditional since the web
        # version went, 6b320: there is no other kind of caller)
        hn = host.rsplit(":", 1)[0] if ":" in host else host
        if host and hn not in ("127.0.0.1", "localhost", "[::1]"):
            return False
        return True

    @staticmethod
    def _same_host(oh: str, host: str) -> bool:
        if oh == host:
            return True
        oa, _, op = oh.partition(":")
        ha, _, hp = host.partition(":")
        local = ("127.0.0.1", "localhost", "[::1]")
        return op == hp and oa in local and ha in local

    def _refuse(self, code: int, err: str) -> bool:
        """Turn a POST away CLEANLY. Two details that look optional and
        are not (6b257): the request body must be DRAINED — refusing
        without reading it leaves bytes in the socket, and the close
        that follows becomes a TCP reset, which the caller sees as
        'Connection reset by peer' instead of our tidy 403 (it made the
        gauntlet's own lockdown probe flaky, twice) — and the response
        needs a Content-Length, or an HTTP/1.1 reader waits for a close
        to know the body ended. Always returns False, so gates can
        `return self._refuse(...)`."""
        try:
            n = int(self.headers.get("Content-Length", 0) or 0)
            while n > 0:                      # bounded, chunk at a time
                chunk = self.rfile.read(min(n, 65536))
                if not chunk:
                    break
                n -= len(chunk)
        except Exception:
            pass
        body = json.dumps({"ok": False, "err": err}).encode()
        try:
            self.send_response(code)
            self.send_header("Content-Type", "application/json")
            self.send_header("Content-Length", str(len(body)))
            self.end_headers()
            self.wfile.write(body)
        except Exception:
            pass
        return False

    # ------------------------------------------------------------------ GET
    def _do_GET(self):
        if not self._gate():
            return
        if self.path == "/api/test/local" and "local-record" in TEST_HOOKS:
            self._send_json({"calls": [list(c) for c in _LOCAL_CALLS]})
            return
        if self.path == "/api/test/suggest" and _suggest_hooked():
            # what the starter-chip pass last asked, and how often (6b390)
            self._send_json({"asks": int(_suggest_state.get("asks", 0)),
                             "prompt": _suggest_state.get("prompt", ""),
                             "running": bool(_suggest_state.get("running"))})
            return
        _hz_spec = hz_debug_spec(self.path, bool(DEV_HOME))
        if self.path == "/" or _hz_spec is not None:
            # exactly "/" (6b321): "/?anything" is no longer the page, so
            # "/?key=" gets the gate's 403 even with the cookie. The page
            # carries nothing personal: the name and town for the hero
            # come from /api/prefs, behind the token. A dev copy also
            # serves "/?hz=<spec>", the same page in a frozen state (6b526).
            _hz_spec = _hz_spec or _hook_arg("hz") or None
            html = (HTML_CONTENT
                    .replace("__HZ_DEBUG__", json.dumps(_hz_spec))
                    .replace("__HZ_PLACE__", json.dumps(hz_place()))
                    .replace("__HZ_FONTS__", hz_font_css())
                    .replace("__HZ_SEEN__", json.dumps(hz_seen(self.ctx)))
                    .replace("__SKY_ORBIT__", json.dumps(
                        [i for i, u in enumerate(SKY_SOURCES) if "GMT" in u]))
                    .replace("__SKY_HZ__", json.dumps(sky_hz_clips()))
                    .replace("__AGENT_ROWS__", build_agent_rows())
                    .replace("__CODE_ROWS__", build_code_rows())
                    .replace("__TIER_META__", json.dumps(
                        {n: {"icon": t["icon"], "desc": t["desc"]}
                         for n, t in TIERS.items()}))
                    .replace("__AGENT_META__", json.dumps(
                        {n: {"icon": a["icon"], "desc": a["desc"],
                             "picks": a.get("picks", [])[:3]}
                         for n, a in AGENTS.items()}))
                    .replace("__APP_BETA__",
                             'VERSION <b class="vnum">%s</b>' % short_version())
                    .replace("__CHIP__", chip_name())
                    .replace("__IS_PC__", json.dumps(IS_WIN))
                    .replace("__DICT_TRACE__",
                             json.dumps("dict-trace" in TEST_HOOKS))
                    .replace("__GIANT_LABEL__", _html_escape(giant_blurb()[0]))
                    .replace("__GIANT_TIP__", _html_escape(giant_blurb()[1]))
                    .replace("__MEM_LABEL__", mem_label())
                    .replace("__WIN_WIPE__",
                             # the wipe needs pywebview's transparent
                             # NSWindow; the shell paints its own night
                             # (6b532)
                             "1" if (HAS_WEBVIEW and IS_MAC and not SHELL)
                             else "0")
                    .replace("__CHANNEL_DEFAULT__", _channel_default())
                    .replace("__SHELL_TL__",
                             # the Mac shell seats the traffic lights on the
                             # header row; the page keeps their zone clear
                             "1" if (SHELL and IS_MAC) else "0")
                    .replace("__SKY_N__", str(len(SKY_SOURCES)))
                    .replace("__SKY_DARK__", json.dumps(SKY_DARK))
                    .replace("__SKY_NIGHT__", json.dumps(sky_is_night()))
                    .replace("__PROFILE__", self.ctx.tag)
                    # a dev copy's imp-demo=<path> hook (6b529): the import
                    # sheet opens on load and brings that export in; "" otherwise
                    .replace("__IMP_DEMO__", json.dumps(_hook_arg("imp-demo")))
                    .replace("__JUST_UPDATED__", json.dumps(_JUST_UPDATED[0]))
                    .replace("__APP_VER_SPEC__", spec_version())
                    .replace("__APP_VER__", short_version()
                             + (" \u00b7 test build" if os.environ.get(
                                 "MILLENAI_TESTBUILD") else "")))
            # THE PAGE CAN NEVER GO STALE AGAIN (6b248, per Patrick:
            # "the hosted web ui is not up to date" — the server was
            # current, his BROWSER was serving a heuristically-cached
            # copy: this page shipped with no cache headers at all).
            # ETag = build number + source mtime, no-cache =
            # revalidate every load: a fresh build turns the next
            # reload into a full fetch, an unchanged one into an
            # instant tiny 304. The mtime is load-bearing (6b264,
            # seen live): between releases APP_BUILD holds still by
            # rule, so a build-only ETag told WKWebView "unchanged"
            # while the page had changed for days — Patrick's test
            # window kept re-serving a cached weeks-old UI off 304s.
            # (6b329) and the profile: a page drawn for another profile
            # is never "unchanged", or a reload after a switch would get
            # a 304 and the old __PROFILE__, and reload again
            etag = '"b%d-%d-%s"' % (APP_BUILD, _SRC_MTIME, self.ctx.tag)
            if _hz_spec is None and self.headers.get("If-None-Match") == etag:
                self.send_response(304)
                self.send_header("ETag", etag)
                self.send_header("Cache-Control", "no-cache")
                self.end_headers()
                return
            body = brand(html).encode("utf-8")
            self.send_response(200)
            self.send_header("Content-Type", "text/html; charset=utf-8")
            self.send_header("Content-Length", str(len(body)))
            self.send_header("ETag", etag)
            self.send_header("Cache-Control", "no-cache")
            self.send_header("Content-Security-Policy", PAGE_CSP)
            self.end_headers()
            self.wfile.write(body)
        elif ACCOUNTS and self.path in ACCOUNT_STATIC:
            self._send_account_static()
        elif self.path == "/api/account/session":
            # the account window's first call (the gate took its token
            # and profile): what it opened for, and which profile
            ok, why = accounts_gate()
            c = self.ctx
            self._send_json({"task": _ACCT["task"], "tag": c.tag,
                             "profile": {"kind": c.kind, "signed_in": not c.root},
                             "accounts": {"on": ok, "note": ACCOUNT_OFF[why][1]
                                          if why else ""}})
        elif self.path.startswith("/api/workspace"):
            # WORKSPACE: point MillenAI at a folder and ask about the
            # code in it. READ-ONLY: nothing here writes or executes
            # anything
            if (self.path.startswith("/api/workspace/set")
                    or self.path.startswith("/api/workspace/off")):
                # choosing or dropping the folder writes prefs, so it is a
                # POST (6b320); a GET here changes nothing
                self.send_error(405, "use POST")
                return
            root = (profile_local(self.ctx).get("workspace") or "")
            self._send_json({"ok": bool(root), "root": root,
                             "files": len(_ws_files(root)) if root else 0})
            return
        elif self.path.startswith("/api/geo"):
            # pin lookups for the places module — proxied so the browser
            # never talks to Nominatim (no CORS, shared cache, one UA)
            q = urllib.parse.parse_qs(
                urllib.parse.urlparse(self.path).query).get("q", [""])[0]
            self._send_json(_geocode(q[:120]) or {})
        elif self.path == "/api/sky/cached":
            # night rides along: the hourly change needs it NOW, not as it
            # was when the page loaded (6b318)
            # (6b323) the history of what was seen, and the clips half
            # downloaded, which the shelf finishes before starting another
            self._send_json({"cached": [
                i for i in range(len(SKY_SOURCES))
                if os.path.exists(_sky_path(i))], "night": sky_is_night(),
                "partial": [i for i in range(len(SKY_SOURCES))
                            if os.path.exists(_sky_path(i) + ".dl")],
                "hist": sky_hist()})
        elif self.path.startswith("/api/sky/status"):
            m = re.search(r"[?&]i=(\d+)", self.path)
            self._send_json(sky_status(int(m.group(1)) if m else 0,
                                       warm="warm=1" in self.path))
        elif self.path == "/static/vfx/hdr-beacon.mp4":
            # THE LIGHT SOURCE (6b261, per Patrick: "make AI HDR too").
            # A PQ/BT.2020 clip is the only thing a WKWebView page can
            # paint brighter than SDR white — same 6.7KB asset and same
            # trick as ConcordeVPN's beacon ("measured: display headroom
            # 1.0 -> 8.7x, +0.1% CPU — hardware HEVC decode"). WebKit
            # asks for Ranges, so answer them.
            try:
                _vp = os.path.join(os.path.dirname(
                    os.path.abspath(__file__)), "vfx", "hdr-beacon.mp4")
                with open(_vp, "rb") as f:
                    _blob = f.read()
            except Exception:
                self.send_error(404)
                return
            _m = re.match(r"bytes=(\d+)-(\d*)",
                          self.headers.get("Range", "") or "")
            _a, _b = 0, len(_blob) - 1
            if _m:
                _a = int(_m.group(1))
                if _m.group(2):
                    _b = min(int(_m.group(2)), _b)
            _chunk = _blob[_a:_b + 1]
            self.send_response(206 if _m else 200)
            self.send_header("Content-Type", "video/mp4")
            self.send_header("Accept-Ranges", "bytes")
            if _m:
                self.send_header("Content-Range", "bytes %d-%d/%d"
                                 % (_a, _b, len(_blob)))
            self.send_header("Content-Length", str(len(_chunk)))
            self.end_headers()
            try:
                self.wfile.write(_chunk)
            except Exception:
                pass
        elif self.path.startswith("/static/sky/"):
            # under /static/ (6b321): a <video src> can't carry the token,
            # and these are Apple's public clips, streamed by Range
            self._send_sky()
        elif _HZ_FONT_RX.fullmatch(self.path):
            # the Horizon's bundled faces (6b526): fixed public bytes from
            # fonts/, by name, nothing else from that folder
            _fn = _HZ_FONT_RX.fullmatch(self.path).group(1)
            _fp = resource("fonts", _fn)
            if not os.path.isfile(_fp):
                self.send_error(404)
                return
            with open(_fp, "rb") as f:
                _fb = f.read()
            self.send_response(200)
            self.send_header("Content-Type", {
                "ttf": "font/ttf", "otf": "font/otf", "woff": "font/woff",
                "woff2": "font/woff2"}[_fn.rsplit(".", 1)[1]])
            self.send_header("Content-Length", str(len(_fb)))
            self.send_header("Cache-Control", "max-age=86400")
            self.end_headers()
            try:
                self.wfile.write(_fb)
            except Exception:
                pass
        elif self.path == "/api/home":
            # the Horizon home's status line (6b526): the day's cloud calls
            self._send_json(home_facts(self.ctx))
        elif self.path.startswith("/api/remote/classify"):
            # read-only introspection of the safety classifier (6b249):
            # the UI uses it to preview a command's risk, and the gauntlet
            # to guard the classifier over the wire. No side effects — it
            # never touches the server.
            q = urllib.parse.urlparse(self.path).query
            cmd = urllib.parse.parse_qs(q).get("cmd", [""])[0]
            self._send_json({"risk": classify_cmd(cmd)})
        elif self.path == "/api/remote/config":
            # the SSH connection never leaves the host
            c = remote_conf()
            self._send_json({"host": c.get("host", ""),
                             "user": c.get("user", ""),
                             "port": c.get("port", "22"),
                             "key": c.get("key", ""),
                             "jump": c.get("jump", ""),
                             "configured": bool(c.get("host"))})
        elif urllib.parse.urlparse(self.path).path == "/api/servers":
            # Settings › Your servers (6b334): this profile's servers,
            # never a token or a key; ?refresh=1 checks each one first
            _sq = urllib.parse.parse_qs(urllib.parse.urlparse(self.path).query)
            srv_lan_touch_boot(self.ctx)        # the Mac's Local Network prompt, once (6b430)
            self._send_json(servers_view(
                self.ctx, (_sq.get("refresh") or [""])[0] == "1"))
        elif urllib.parse.urlparse(self.path).path == "/api/servers/sleep":
            # Settings › Your servers (6b346): this server's auto sleep setting
            _sq = urllib.parse.parse_qs(urllib.parse.urlparse(self.path).query)
            _sid = (_sq.get("id") or [""])[0]
            self._send_json(server_sleep_get(self.ctx, _sid)
                            if _SRV_ID_RX.fullmatch(_sid) else {"ok": False, "kind": "gone", "err": SRV_GONE})
        elif urllib.parse.urlparse(self.path).path == "/api/servers/models":
            # Settings › Your servers (6b407): its models and the three sets
            _sq = urllib.parse.parse_qs(urllib.parse.urlparse(self.path).query)
            _sid = (_sq.get("id") or [""])[0]
            self._send_json(server_models_get(self.ctx, _sid)
                            if _SRV_ID_RX.fullmatch(_sid) else {"ok": False, "kind": "gone", "err": SRV_GONE})
        elif urllib.parse.urlparse(self.path).path == "/api/servers/usage":
            # the sidebar meters' read of one server's card (6b342): while
            # a benchmark runs nothing is asked of any server
            _sq = urllib.parse.parse_qs(urllib.parse.urlparse(self.path).query)
            _sid = (_sq.get("id") or [""])[0]
            if _bench["running"]:
                self._send_json({"ok": True, "paused": True})
            elif not _SRV_ID_RX.fullmatch(_sid):
                self._send_json({"ok": False})
            else:
                self._send_json(server_usage(self.ctx, _sid))
        elif self.path == "/api/cloud":
            c = cloud_conf()
            d = _cloud_all()
            _now = time.time()

            def _cool_left(v):
                try:
                    return max(0, int(float(v.get("cool") or 0) - _now))
                except (TypeError, ValueError):
                    return 0
            provs = {k: {"status": v.get("status", ""),
                         "note": (v.get("note") or "")[:80],
                         # model rests count too (6b307): a provider
                         # whose every model is resting isn't "in use"
                         "cool": max(_cool_left(v), cloud_rest_left(k, v)),
                         # real money where the provider will say (Kimi);
                         # '' where it won't — never invented
                         "balance": (cloud_balance(k, v)
                                     if v.get("status") == "ok" else "")}
                     for k, v in (d.get("providers") or {}).items()}
            self._send_json({"configured": bool(c),
                             "name": (c or {}).get("name", ""),
                             "model": (c or {}).get("model", ""),
                             "active": d.get("active", ""),
                             "turbo": bool(profile_local(self.ctx).get("turbo")),
                             "bench": [lbl for lbl, _c in cloud_bench()],
                             "providers": provs,
                             # ESTIMATED balances (6b441): only a provider
                             # the person set one for; never a key
                             "balance": cloud_balance_est(self.ctx)})
        elif self.path == "/api/stats":
            self._send_stats()
        elif urllib.parse.urlparse(self.path).path == "/api/usage":
            # Settings › Usage (6b325): ?range=1h|1d|1w|1m|1y|all&model=
            # A ledger that can't be read answers 503 (StoreReadError)
            _uq = urllib.parse.parse_qs(urllib.parse.urlparse(self.path).query)
            _ur = (_uq.get("range") or ["all"])[0]
            if _ur not in USAGE_RANGES:
                self._send_json({"err": "unknown range"}, code=400)
            else:
                self._send_json(usage_query(
                    usage_read(self.ctx), _ur,
                    (_uq.get("model") or [""])[0][:120]))
        elif self.path == "/api/bench/running":
            # the composer asks before it clears itself (review of 6b331)
            self._send_json({"running": bool(_bench["running"]),
                             "err": BENCH_BUSY if _bench["running"] else ""})
        elif self.path == "/api/bench":
            # the hardware benchmark (6b331): the run and the saved runs
            # (6b341: this profile's, and a run of its own server or cloud)
            self._send_json(bench_status(self.ctx))
        elif self.path.split("?")[0] == "/api/bench/targets":
            # what a run can test (6b341): this profile's paired servers
            # and cloud models; ?refresh=<server id> checks that server first
            _bq = urllib.parse.parse_qs(urllib.parse.urlparse(self.path).query)
            _bs = (_bq.get("refresh") or [""])[0]
            self._send_json(bench_targets(
                self.ctx, _bs if _SRV_ID_RX.fullmatch(_bs) else ""))
        elif self.path == "/api/engines":
            self._send_engines()
        elif self.path == "/api/setup":
            self._send_json(setup_status())
        elif self.path == "/api/setup/busy":
            self._send_json(setup_busy())
        elif self.path == "/api/models/offer":
            # what the More-models card will change (6b335)
            self._send_json(model_offer_plan())
        elif self.path.startswith("/api/model/update"):
            st = model_update_status()
            if "plan=1" in self.path:
                # the post-update card: after the startup sweep
                _SWEEP_DONE.wait(15)
                st["plan"] = _cleanup_stat()
                # and the person's awake servers (6b445); none is woken
                st["servers"] = servers_updates(self.ctx)
            self._send_json(st)
        elif self.path.startswith("/api/update/check"):
            force = urllib.parse.parse_qs(
                urllib.parse.urlparse(self.path).query
            ).get("force", [""])[0] == "1"
            self._send_json(check_update(force=force))
        elif self.path == "/api/update/status":
            self._send_json(dict(_update))
        elif self.path == "/api/update/whatsnew":
            self._send_json(whats_new(_JUST_UPDATED[0]))
        elif self.path.startswith("/api/export/"):
            # EVERY export is octet-stream with an attachment disposition,
            # never the format's real MIME (6b295). Model-authored HTML
            # served as text/html from our own origin would be stored XSS
            # against the app itself; this closes it and costs nothing.
            iid = urllib.parse.unquote(self.path[len("/api/export/"):]
                                       .split("?")[0])
            base = self.ctx
            pth = os.path.join(export_dir(base), iid)
            if not _X_ID_RX.match(iid) or not os.path.exists(pth):
                self.send_error(404)
                return
            try:
                with open(os.path.join(export_dir(base),
                                       os.path.splitext(iid)[0] + ".meta")) as mf:
                    nm = (json.load(mf) or {}).get("name") or iid
            except Exception:
                nm = iid
            with open(pth, "rb") as f:
                data = f.read()
            self.send_response(200)
            self.send_header("Content-Type", "application/octet-stream")
            self.send_header("X-Content-Type-Options", "nosniff")
            self.send_header("Content-Disposition", _x_disposition(nm))
            self.send_header("Content-Length", str(len(data)))
            self.send_header("Cache-Control", "private, max-age=3600")
            self.end_headers()
            self.wfile.write(data)
        elif self.path.startswith("/api/video/") and self.path.endswith(
                (".mp4", ".gif", ".webm")):
            vid = self.path[len("/api/video/"):]
            pth = os.path.join(video_dir(self.ctx), vid)
            if not re.fullmatch(r"[\w-]+\.(mp4|gif|webm)", vid) \
                    or not os.path.exists(pth):
                self.send_error(404)
                return
            # Range matters here: a WKWebView <video> asks for one
            rng = self.headers.get("Range", "")
            total = os.path.getsize(pth)
            a, b = 0, total - 1
            m = re.match(r"bytes=(\d*)-(\d*)", rng or "")
            partial = bool(m and (m.group(1) or m.group(2)))
            if partial:
                a = int(m.group(1) or 0)
                b = int(m.group(2) or (total - 1))
                b = min(b, total - 1)
            with open(pth, "rb") as f:
                f.seek(a)
                data = f.read(b - a + 1)
            self.send_response(206 if partial else 200)
            self.send_header("Content-Type", {
                "mp4": "video/mp4", "webm": "video/webm",
                "gif": "image/gif"}[vid.rsplit(".", 1)[1]])
            self.send_header("Accept-Ranges", "bytes")
            if partial:
                self.send_header("Content-Range",
                                 "bytes %d-%d/%d" % (a, b, total))
            self.send_header("Content-Length", str(len(data)))
            self.send_header("Cache-Control", "private, max-age=86400")
            self.end_headers()
            self.wfile.write(data)
        elif self.path.startswith("/api/image/") and self.path.endswith(
                (".png", ".jpg", ".webp")):
            iid = self.path[len("/api/image/"):]
            pth = os.path.join(image_dir(self.ctx), iid)
            if not re.fullmatch(r"[\w-]+\.(png|jpg|webp)", iid) or not os.path.exists(pth):
                self.send_error(404)
                return
            with open(pth, "rb") as f:
                data = f.read()
            self.send_response(200)
            self.send_header("Content-Type", {"png": "image/png", "jpg": "image/jpeg",
                                              "webp": "image/webp"}[iid.rsplit(".", 1)[1]])
            self.send_header("Content-Length", str(len(data)))
            self.send_header("Cache-Control", "private, max-age=86400")
            self.end_headers()
            self.wfile.write(data)
        elif self.path == "/api/tiers":
            pulled = ollama_pulled_tags() or set()
            bench = [lbl for lbl, _c in cloud_bench()]
            out = {}
            for name, t in TIERS.items():
                if t.get("cloud_only"):
                    # its line-up is the key bench, and with no keys the
                    # tier is unusable — the UI greys it out on this flag
                    out[name] = {"desc": t["desc"], "models": bench,
                                 "skipped": [], "available": bool(bench)}
                    if len(bench) > 1:          # who writes the blend (6b440)
                        _lad = compositor_ladder()
                        out[name]["blend"] = blend_text(_lad[0]["name"] if _lad else "")
                    continue
                if t.get("max"):
                    # every model there is (6b440): its own row
                    out[name] = max_tier_row(self.ctx)
                    continue
                if t.get("rubin"):
                    # Vera Rubin (6b519): this Mac, the servers, the cloud only when on
                    out[name] = rubin_tier_row(self.ctx)
                    continue
                try:
                    chosen = [x["label"] for x in resolve_tier_seats(name, self.ctx)]
                except (StoreReadError, NoProfile):
                    chosen = resolve_tier(name)
                # installed models this tier can't use right now
                skipped = [l for l in MODEL_INFO
                           if SUPPORTED.get(l) and model_cached(l, pulled)
                           and l not in chosen
                           and not model_fits_memory(l)]
                out[name] = {"desc": t["desc"], "models": chosen,
                             "skipped": skipped, "available": True}
                # Fast's bubble names the rung that will actually answer
                # (6b246) — "Cloud Enabled" alone didn't say WHO
                if name == "Fast" and cloud_allowed():
                    _fl = fast_cloud_ladder()
                    if _fl:
                        out[name]["fastcloud"] = _fl[0].get("name", "")
                # a mode with more server models than seats says how many
                # sit (6b339, final review)
                try:
                    _cap = tier_server_cap(name, self.ctx)
                except (StoreReadError, NoProfile):
                    _cap = None
                if _cap:
                    out[name]["srvcap"] = {"seated": _cap[0], "of": _cap[1]}
                # who writes the blend of Thinking and Pro (6b440), from the rules the
                # merge itself follows; Fast has no blend
                if name in ("Thinking", "Pro"):
                    try:
                        out[name]["blend"] = mode_blend(self.ctx, chosen, len(bench))
                    except Exception:
                        pass
                    # who writes it, and who else could (6b442)
                    try:
                        out[name]["comp"] = mode_comp_choices(self.ctx, chosen, len(bench))
                    except Exception:
                        pass
            # "<server> Only" (6b337): one row per paired server, from its
            # last check; greyed on the page while it can't answer
            try:
                out.update(server_only_tiers(self.ctx))
            except (StoreReadError, NoProfile):
                pass
            # Cloud Only's modes and one pick per provider (6b440): their
            # availability and the reason each one that is off is off
            try:
                out.update(cloud_mode_tiers())
            except Exception:
                pass
            self._send_json(out)
        elif self.path == "/api/prefs":
            self._send_json(prefs_view(self.ctx))
        elif self.path == "/api/suggest":
            # the starter chips from the person's chats (6b390): what is
            # kept, at once; a pass that is due runs behind it
            self._send_json(suggest_view(self.ctx))
        elif self.path.startswith("/api/import/"):
            self._import_get()               # bring your chats (6b529)
        elif self.path == "/api/chats":
            # an unreadable store answers 503, never an empty list (0b L1)
            with _chats_lock:
                _cs = load_chats(self.ctx)
                _rev = _data_rev[0]
            self._send_json({"chats": _cs, "data_rev": _rev})
        elif self.path.startswith("/api/chats/one?"):
            # one chat, as saved: the page adopts it after each answer
            # (6b322), so the two never hold different turns
            _id = (urllib.parse.parse_qs(urllib.parse.urlparse(
                self.path).query).get("id", [""])[0] or "")
            with _chats_lock:
                _, _c = _chat_find(load_chats(self.ctx), _id)
                _rev = _data_rev[0]
            self._send_json({"chat": _c, "data_rev": _rev})
        elif self.path.startswith("/api/chats/search"):
            # full-text over the user's own chats (6b269, per Patrick:
            # "search through existing conversations") — titles match
            # instantly client-side; this covers message CONTENT. Since
            # 6b480 each hit also carries where it matched and a line of
            # the text around it (chat_search)
            _q = (urllib.parse.parse_qs(urllib.parse.urlparse(
                self.path).query).get("q", [""])[0] or "")
            _ids, _hits = [], []
            if _q.strip():
                with _chats_lock:
                    _cs = load_chats(self.ctx)
                _ids, _hits = chat_search(_cs, _q)
            self._send_json({"ids": _ids, "hits": _hits})
        elif self.path == "/api/know":
            # YOUR STUFF (6b530): the index's status in plain words; asking
            # also makes sure the indexer runs for this profile
            know_kick(self.ctx)
            self._send_json(know_status(self.ctx))
        elif self.path.startswith("/api/know/search"):
            # the search itself, for the page's preview and the eval: hits
            # with their passages, nothing else changed
            _kq = urllib.parse.parse_qs(urllib.parse.urlparse(self.path).query)
            _kqs = _kq.get("q", [""])[0][:2000]
            try:
                _kn = max(1, min(20, int(_kq.get("n", ["5"])[0])))
            except ValueError:
                _kn = 5
            _kh = know_search(self.ctx, _kqs, top=_kn,
                              embed=_kq.get("embed", ["1"])[0] != "0") if _kqs else []
            self._send_json({"hits": [dict(
                {k: h.get(k) for k in ("chunk", "src", "key", "title", "head", "ts",
                                       "score", "cos", "lanes")},
                body=str(h.get("body") or "")[:600], label=know_label(h)) for h in _kh]})
        elif self.path == "/api/memory":
            self._send_json({"facts": _load_memory(self.ctx)})
        elif self.path == "/api/me":
            # WHO AM I (6b257, the Account pane). One kind since the web
            # version's visitor, PIN and Google profiles went (6b320): this
            # computer's owner. The shape stays for the signed-in account.
            # `accounts` (6b327): on only in a build with the account
            # screens and with PyNaCl ready; the note says why not (CRY-4)
            _aon, _awhy = accounts_gate()
            _acc = {"on": _aon, "note": ACCOUNT_OFF[_awhy][1] if _awhy else ""}
            if ACCOUNTS:
                # (M9) a build with the account window says so; the
                # shipped app's reply is unchanged
                _acc["window"] = True
            self._send_json({"kind": "owner", "accounts": _acc})
        elif self.path == "/api/voice/status":
            with _setup_lock:
                job = dict(_setup_jobs.get(VOICE_ROW, {}))
            pct = job.get("pct", 0)
            if job.get("status") == "downloading":
                repo = _whisper_repo()
                est = (1_600_000_000 if repo == WHISPER_REPO
                       else 490_000_000)
                pct = min(99, round(     # bytes once (6b335)
                    _dir_bytes_real(_hf_model_dir(repo)) / est * 100))
            self._send_json({"supported": _voice_supported(),
                             "ready": _voice_supported() and _voice_ready(),
                             "engine": _dict_engine_name(),      # 6b543
                             "downloading": job.get("status") == "downloading",
                             "pct": pct,
                             "note": job.get("note", "")})
        else:
            self.send_error(404)

    def _send_sky(self):
        """Stream a cached skyline clip with Range support — Safari asks
        for dozens of byte ranges while scrubbing a video into playback,
        and a plain 200 would make it re-pull the whole file each time."""
        m = re.fullmatch(r"/static/sky/(\d{1,3})\.mov", self.path)
        # a number past the list 404s (it raised IndexError and dropped
        # the connection, 6b321)
        p = (_sky_path(int(m.group(1)))
             if m and int(m.group(1)) < len(SKY_SOURCES) else None)
        if not (p and os.path.exists(p)):
            self.send_error(404)
            return
        try:
            os.utime(p, None)   # LRU keys on mtime = "recently played"
        except OSError:
            pass
        size = os.path.getsize(p)
        start, end = 0, size - 1
        rng = self.headers.get("Range", "")
        partial = rng.startswith("bytes=")
        if partial:
            try:
                a, b = rng[6:].split(",")[0].split("-")[:2]
                start = int(a) if a else max(0, size - int(b))
                if a:
                    end = min(int(b), size - 1) if b else size - 1
            except ValueError:
                partial = False
                start, end = 0, size - 1
        if start > end or start >= size:
            self.send_error(416)
            return
        self.send_response(206 if partial else 200)
        self.send_header("Content-Type", "video/quicktime")
        self.send_header("Accept-Ranges", "bytes")
        self.send_header("Content-Length", str(end - start + 1))
        if partial:
            self.send_header("Content-Range",
                             "bytes %d-%d/%d" % (start, end, size))
        self.send_header("Cache-Control", "public, max-age=604800")
        self.end_headers()
        try:
            with open(p, "rb") as fh:
                fh.seek(start)
                left = end - start + 1
                while left:
                    chunk = fh.read(min(1 << 20, left))
                    if not chunk:
                        break
                    self.wfile.write(chunk)
                    left -= len(chunk)
        except Exception:
            pass          # client hung up mid-stream — normal for video

    def _send_account_static(self):
        """/account, /account.css and /account.js (1a 5.9), each under the
        account window's strict CSP: nothing inline runs, nothing is
        framed, no form can post, no <base>, no plugin."""
        if self.path == "/account":
            body = brand(ACCOUNT_HTML.replace("__APP__", APP_NAME).replace(
                "__TAG__", _html_escape(_ACCT["tag"] or ""))).encode("utf-8")
            ctype = "text/html; charset=utf-8"
        elif self.path == "/account.css":
            body, ctype = ACCOUNT_CSS.encode("utf-8"), "text/css; charset=utf-8"
        else:
            body = ACCOUNT_JS.encode("utf-8")
            ctype = "text/javascript; charset=utf-8"
        self.send_response(200)
        self.send_header("Content-Type", ctype)
        self.send_header("Content-Length", str(len(body)))
        self.send_header("X-Content-Type-Options", "nosniff")
        self.send_header("Content-Security-Policy", ACCOUNT_CSP)
        self.end_headers()
        self.wfile.write(body)

    # ==== bring your chats (6b529): routes begin ====
    # Every route sits behind _gate (the cookie and the API token) like
    # the rest of /api/. Errors the person can act on come back as 400
    # with a plain line; an unreadable store is _run's 503.
    def _import_get(self):
        u = urllib.parse.urlparse(self.path)
        q = urllib.parse.parse_qs(u.query)
        one = lambda k, d="": (q.get(k, [d])[0] or d)
        try:
            if u.path == "/api/import/status":
                self._send_json(import_status(self.ctx, one("run"), one("since", "0")))
            elif u.path == "/api/import/sources":
                self._send_json(import_sources(self.ctx))
            elif u.path == "/api/import/apps":
                self._send_json({"apps": IMPORT_APPS,
                                 "watch": _imp_watch_status(_IMPORT_WATCH)})
            else:
                self.send_error(404)
        except ImportError_ as exc:
            self._send_json({"err": str(exc), "detail": exc.detail}, code=400)

    def _import_post(self):
        u = urllib.parse.urlparse(self.path)
        try:
            if u.path == "/api/import/upload":
                q = urllib.parse.parse_qs(u.query)
                n = int(self.headers.get("Content-Length", 0) or 0)
                self._send_json(import_upload(self.ctx, q.get("run", [""])[0],
                                              self.rfile, n))
                return
            d = self._json_body()
            if u.path == "/api/import/begin":
                self._send_json(import_begin(self.ctx, d.get("app"), d.get("name"),
                                             d.get("size"), d.get("path")))
            elif u.path == "/api/import/start":
                self._send_json(import_start(self.ctx, d.get("run"), d.get("app")))
            elif u.path == "/api/import/cancel":
                self._send_json(import_cancel(self.ctx, d.get("run")))
            elif u.path == "/api/import/remove":
                self._send_json(import_remove(self.ctx, d.get("app")))
            elif u.path == "/api/import/remember":
                self._send_json(import_remember(self.ctx, d.get("run")))
            elif u.path == "/api/import/open":
                self._send_json(import_open(d.get("app")))
            elif u.path == "/api/import/watch":
                self._send_json(import_watch(self.ctx, bool(d.get("on")), d.get("app")))
            else:
                self.send_error(404)
        except ImportError_ as exc:
            self._send_json({"err": str(exc), "detail": exc.detail}, code=400)
    # ==== bring your chats (6b529): routes end ====

    def _json_body(self) -> dict:
        """The request's JSON object; {} for anything else."""
        n = int(self.headers.get("Content-Length", 0) or 0)
        try:
            d = json.loads(self.rfile.read(n)) if n else {}
        except (ValueError, json.JSONDecodeError):
            d = {}
        return d if isinstance(d, dict) else {}

    def _send_json(self, obj, code=200):
        body = json.dumps(obj).encode("utf-8")
        self.send_response(code)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def _send_engines(self):
        """Probe every backend so the UI can show live status dots."""
        status = {}

        # Ollama: one call tells us it's up AND which models are pulled
        pulled = None
        try:
            with urllib.request.urlopen(
                ollama_url("/api/tags"), timeout=1.5
            ) as r:
                tags = json.loads(r.read().decode("utf-8")).get("models", [])
                pulled = {m.get("name", "") for m in tags
                          if isinstance(m, dict) and not ollama_internal(m)}
                pulled |= {n[:-len(":latest")] for n in pulled
                           if n.endswith(":latest")}
        except Exception:
            pulled = None  # ollama down

        for label, (kind, target) in MODEL_ROUTES.items():
            if kind == "ollama":
                if pulled is None:
                    status[label] = {"up": False, "note": "ollama offline",
                                     "cmd": "ollama serve"}
                elif target in pulled:
                    status[label] = {"up": True, "note": "ready"}
                else:
                    status[label] = {"up": False,
                                     "note": f"not pulled — ollama pull {target}",
                                     "cmd": f"ollama pull {target}"}
            else:
                repo = MLX_REPOS.get(label, "<model-repo>")
                if _engine_up(target):
                    status[label] = {"up": True, "note": f"loaded · port {target}"}
                elif mlx_model_cached(repo):
                    # downloaded but idle — starts on demand, so it IS usable
                    status[label] = {"up": True, "note": "ready · loads on use"}
                else:
                    status[label] = {
                        "up": False,
                        "note": "not downloaded",
                        "cmd": (f"mlx_lm.server --model {repo} "
                                f"--port {target}"),
                    }

        for label, st in status.items():
            st["mem_ok"] = model_fits_memory(label)
            st["supported"] = SUPPORTED.get(label, True)
            st["downloadable"] = not st.get("up") and st["supported"]
            st["mem"] = MODEL_MEM_BYTES.get(label, 0)  # strength proxy
            with _setup_lock:
                job = dict(_setup_jobs.get(label, {}))
            if job.get("status") in ("downloading", "queued"):
                st["dl"] = job.get("status")
                pct = job.get("pct", 0)
                # MLX downloads report no progress of their own — measure
                # the growing cache directory instead (ollama streams pct)
                if MODEL_ROUTES.get(label, ("",))[0] == "mlx":
                    est = MLX_EST_BYTES.get(label) or 1
                    # bytes once, not blobs + snapshot links (6b335)
                    grown = _dir_bytes_real(_hf_model_dir(MLX_REPOS[label]))
                    pct = min(99, round(grown / est * 100))
                st["pct"] = pct

        # models this Mac can't run never appear as "up"
        for label, ok in SUPPORTED.items():
            if not ok:
                status.setdefault(label, {})
                status[label].update(up=False, supported=False,
                                     note="needs Apple silicon")

        body = json.dumps(status).encode("utf-8")
        self.send_response(200)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def _send_stats(self):
        gpu = gpu_utilization()
        if HAS_PSUTIL:
            vm = psutil.virtual_memory()
            stats = {
                "real": True,
                # GB as memory is sold, 2^30 (review of 6b331): the rail
                # read 52 GB beside the benchmark's 48 on a 48 GB Mac
                "mem_used_gb": round(vm.used / 2 ** 30, 1),
                "mem_total_gb": round(vm.total / 2 ** 30, 1),
                "mem_pct": vm.percent,
                "mem_pressure": mem_pressure(),
                "gpu_pct": gpu,  # None when ioreg has no accelerator stats
            }
        else:
            stats = {"real": False, "gpu_pct": gpu,
                     "mem_pressure": mem_pressure()}
        # the chat store's change counter rides the 2 s poll (0b 5.6)
        stats["data_rev"] = _data_rev[0]
        # PyNaCl's state (6b327): accounts need it, CI asserts it
        stats["crypto"] = crypto_status()
        body = json.dumps(stats).encode("utf-8")
        self.send_response(200)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    # ----------------------------------------------------------------- POST
    # ---------------------------------------------- a document turn (6b522)
    def _chat_doc(self, req_json, messages, tier, model_name, images, docs):
        """A chat turn that carries a .md or .txt file (6b522, per Patrick):
        ONE model of this Mac reads it and nothing else runs. The chat
        handler calls this once the question is saved and the hold on this
        computer's engines is taken (server_only_request is False for a
        document turn), before anything of the tier is resolved; everything
        after is here. No cloud call (no draft, critic, compositor, query
        plan or title), no server (the person's own included), no web
        search, no council, no memory pass; the chat's title is written on
        this Mac too (/api/title reads _doc_chats). NOTES 6b522 lists every
        side path and why each is safe."""
        user_base = self.ctx
        _cid = str((self._turn or {}).get("id") or "")
        for _k in [k for k, v in list(_doc_chats.items()) if time.time() - v > 300]:
            _doc_chats.pop(_k, None)
        if _cid:
            _doc_chats[(user_base.name, _cid)] = time.time()
        last = messages[-1] if messages and isinstance(messages[-1], dict) else {}
        question = str(last.get("content") or "").strip()
        history = [{"role": m["role"], "content": str(m.get("content") or "")}
                   for m in messages[:-1][-DOC_HISTORY:]
                   if isinstance(m, dict) and m.get("role") in ("user", "assistant")]
        agent = str(req_json.get("agent") or "")
        models = req_json.get("models") if isinstance(req_json.get("models"), list) else None
        label, why = doc_local_pick(tier, model_name, models, agent, bool(images))
        # a picture with the document is read by the picture model here, in
        # the same turn; with none installed the pictures are left out, said
        b64s = ([u.split(",", 1)[1] if u.startswith("data:") else u for u in images]
                if images and label == DOC_VISION else None)
        system = doc_system_text(user_prefs(user_base),
                                 (AGENTS.get(agent) or {}).get("system", "")
                                 if why == "agent" else "")
        kind = MODEL_ROUTES.get(label, ("",))[0] if label else ""

        self.send_response(200)
        self.send_header("Content-Type", "text/plain; charset=utf-8")
        self.send_header("Cache-Control", "no-cache")
        self.send_header("X-Accel-Buffering", "no")
        self.send_header("X-Web-Search", "0")
        if self._turn:
            self._turn["searched"] = False
            self.send_header("X-Chat-Id", self._turn["id"])
        self.send_header("X-Models", header_text(label))
        self.end_headers()

        # the stream's own plumbing, as the chat handler's: writes under a
        # lock, kept for the saved turn, a heartbeat while a model loads or
        # a part is summarised (it re-sends the last status: nothing leaves)
        wlock = threading.Lock()
        last_write = [time.time()]
        last_status = ["reading the document"]
        hb_stop = threading.Event()

        def _write(data: bytes):
            with wlock:
                try:
                    self.wfile.write(data)
                    self.wfile.flush()
                except OSError:
                    if self._turn is not None:
                        self._turn["aborted"] = True
                    raise
                last_write[0] = time.time()
                if self._turn is not None:
                    self._turn["wire"].append(data)

        def _heartbeat():
            while not hb_stop.wait(5):
                if time.time() - last_write[0] > 20:
                    try:
                        _write(f"{NUL}STATUS:{last_status[0]}{NUL}".encode("utf-8"))
                    except Exception:
                        return
        ctx_thread(target=_heartbeat, daemon=True).start()
        sent = [0]
        said = [False]

        def emit(chunk: str):
            if user_base.cancel.is_set():
                raise StaleProfile("the profile changed")
            if not isinstance(chunk, Ctl):
                chunk = strip_special(chunk).replace(NUL, "")
            if not chunk:
                return
            sent[0] += len(chunk)
            _write(chunk.encode("utf-8"))

        def memit(chunk: str):
            if (chunk and not isinstance(chunk, (Ctl, AppText))
                    and str(chunk).strip()):
                said[0] = True
            emit(chunk)

        def step(sid: str, lbl: str, state: str = "run", detail: str = ""):
            try:
                _write((NUL + "STEP:" + json.dumps(
                    {"id": sid, "l": lbl, "s": state, "d": str(detail)[:70]})
                    + NUL).encode("utf-8"))
            except Exception:
                pass

        def status(text: str):
            text = str(text).replace(NUL, "")
            last_status[0] = text
            _write(f"{NUL}STATUS:{text}{NUL}".encode("utf-8"))

        try:
            if not label:
                step("read", "No model on " + DOC_HERE, "done", "Nothing sent")
                emit(AppText(DOC_NO_MODEL))
                return
            status("Read on " + DOC_HERE + ": " + label)
            step("read", "Read on " + DOC_HERE + ": " + label, "run",
                 "Stays on " + DOC_HERE)
            if images and not b64s:
                status("Pictures left out. No picture model on " + DOC_HERE + ".")
            doc_answer(label, docs, question, history, system, memit, step, status,
                       gone=lambda: _client_gone(self.connection), images=b64s)
            if sent[0]:
                step("draft", "Answer written", "done", "%d chars" % sent[0])
        except (DocStopped, BrokenPipeError, ConnectionResetError):
            pass                     # Stop: the page hung up
        except StaleProfile:
            raise
        except Exception as exc:
            try:
                emit("\n" + offline_hint(kind, exc))
            except (BrokenPipeError, ConnectionResetError, StaleProfile):
                pass
        finally:
            hb_stop.set()
            # the local ledgers, as any answer's: the quality line and the
            # usage count. No memory pass (6b522): a document's words never
            # become remembered facts, and no other model reads them
            if not user_base.cancel.is_set():
                try:
                    qpath = user_base.path(QUALITY_FILE)
                    if os.path.exists(qpath) and os.path.getsize(qpath) > 2_000_000:
                        user_base.remove(QUALITY_FILE)
                    user_base.append(QUALITY_FILE, (json.dumps({
                        "ts": int(time.time()), "tier": tier, "model": label,
                        "searched": False, "chars": sent[0],
                    }) + "\n").encode("utf-8"), mode=0o644)
                except StaleProfile:
                    pass            # a stale line lands nowhere, as it should
                except Exception:
                    pass
                if said[0]:
                    try:
                        usage_put({"t": round(time.time(), 1), "a": 1, "m": label[:80]})
                    except StaleProfile:
                        pass
                    except Exception:
                        pass

    def _do_POST(self):
        if not self._gate():
            return
        if not self._csrf_ok():
            self._refuse(403, "cross-site")
            return
        if self.path == "/api/test/trace" and "dict-trace" in TEST_HOOKS:
            # one dictation's timings (6b345), dev copies only: a line in
            # the log, nothing kept
            d = self._json_body()
            print("[dict-trace] %s" % str(d.get("line", ""))[:200], flush=True)
            self._send_json({"ok": True})
            return
        if self.path == "/api/test/profile" and "profiles" in TEST_HOOKS:
            # the local-test-profile hook (1a 5.13), dev copies only
            n = int(self.headers.get("Content-Length", 0) or 0)
            try:
                d = json.loads(self.rfile.read(n)) if n else {}
            except (ValueError, json.JSONDecodeError):
                d = {}
            try:
                self._send_json(test_profile_op(d if isinstance(d, dict)
                                                else {}, self.ctx))
            except NoProfile as exc:
                self._send_json({"err": str(exc)}, code=409)
            return
        if self.path == "/api/test/account" and "account-headless" in TEST_HOOKS:
            # A HEADLESS ACCOUNT-WINDOW SESSION (1a 5.13, 1e (c)), dev
            # copies only: a token bound to the epoch exactly as a real
            # window's, so the 409, the refusal of the main token and the
            # closing at a switch apply to it unchanged
            d = self._json_body()
            op = d.get("op")
            if op == "open":
                self._send_json(account_open(str(d.get("task") or ""),
                                             headless=True))
            elif op == "close":
                self._send_json({"closed": account_close()})
            else:
                self._send_json({"open": bool(_ACCT["token"]),
                                 "token": _ACCT["token"], "tag": _ACCT["tag"],
                                 "task": _ACCT["task"], "calls": _ACCT["calls"],
                                 "window": _ACCT["window"] is not None})
            return
        if self.path.startswith("/api/account/"):
            # the account window's calls (its token and profile checked
            # by the gate). The screens are 1e's; the switch runs here
            # only for local test profiles (the profiles hook)
            d = self._json_body()
            if self.path == "/api/account/close" or self.path == "/api/account/cancel":
                # Esc, Enter on a sheet with no default, the close box:
                # nothing that wasn't committed moves (ISO-11)
                account_close()
                self._send_json({"ok": True, "closed": True})
                return
            if self.path in ("/api/account/signin", "/api/account/signout"):
                with _ACCT_LOCK:
                    _ACCT["running"] = True
                    _cancel = _ACCT["cancel"]
                try:
                    try:
                        out = (profile_signin if self.path.endswith("signin")
                               else profile_signout)(self.ctx, d, _cancel)
                    except (NoProfile, ValueError) as exc:
                        out = {"err": str(exc)[:160]}
                    except StaleProfile:
                        raise
                    except OSError as exc:
                        # the window gets an answer (a Windows rename that
                        # failed, a disk that refused); the protocol's own
                        # order left nothing half done that a start can't finish
                        out = {"err": "couldn't finish: %s" % (
                            exc.strerror or exc.__class__.__name__)}
                finally:
                    with _ACCT_LOCK:
                        _ACCT["running"] = False
                out["account_tag"] = _ACCT["tag"]
                self._send_json(out)
                return
            self._send_json({"err": "unknown"}, code=404)
            return
        if self.path == "/api/window/focus":
            # a second launch asks this copy to come forward (6b310). It
            # only ever brings the window forward (6b320): reopening
            # /?key= in the default browser put the key in its history
            # and the cookie on every 127.0.0.1 port
            try:
                self.rfile.read(int(self.headers.get("Content-Length", 0)
                                    or 0))
                if HAS_WEBVIEW and webview.windows:
                    _w = webview.windows[0]
                    # on Windows restore() un-maximizes too (6b317, from
                    # the sweep): only a minimized window is restored
                    if not IS_WIN or _WIN_STATE["min"]:
                        _was_max = _WIN_STATE["max"]
                        _w.restore()
                        if IS_WIN and _was_max:
                            _w.maximize()   # it was maximized before
                    _w.show()
                    if IS_MAC:
                        from AppKit import NSApp
                        from PyObjCTools import AppHelper
                        AppHelper.callAfter(
                            lambda: NSApp.activateIgnoringOtherApps_(True))
            except Exception:
                pass
            self._send_json({"ok": True})
            return
        if self.path.startswith("/api/servers/"):
            # Settings › Your servers (6b334): add, pair, test, a new
            # Access token, remove. A reply carries the server's public
            # view only, never the token or the key
            d = self._json_body()
            sid, op = str(d.get("id") or ""), self.path[len("/api/servers/"):]
            if op == "add":
                out = server_add(self.ctx, d)
            elif op == "sleep":
                # auto sleep (6b346): this server's setting, in the active profile
                out = (server_sleep_set(self.ctx, sid, {k: d[k] for k in ("enabled", "minutes") if k in d})
                       if _SRV_ID_RX.fullmatch(sid) else {"ok": False, "kind": "gone", "err": SRV_GONE})
            elif op == "wake-test":
                # Wake up server (6b430): the packets, none waited for
                out = (server_wake_test(self.ctx, sid, d.get("relay_only") is True)
                       if _SRV_ID_RX.fullmatch(sid) else {"ok": False, "kind": "gone", "err": SRV_GONE})
            elif op == "autoclean":
                # auto-clean on your servers (6b445): the page asks once a
                # launch and every six hours; only what this app brought there
                out = {"ok": True, "servers": servers_autoclean(self.ctx)}
            elif op == "lan-settings":
                # the Local Network pane, a fixed argument list (6b430)
                if IS_MAC:
                    subprocess.Popen(["open", LAN_SETTINGS_URL])
                out = {"ok": bool(IS_MAC)}
            elif op == "models":
                # a set for this server, as the sheet showed it (6b407)
                out = (server_models_apply(self.ctx, sid, d)
                       if _SRV_ID_RX.fullmatch(sid) else {"ok": False, "kind": "gone", "err": SRV_GONE})
            elif op == "relay":
                # the wake relay (6b431): its address and token, set or cleared;
                # the token is write-only
                out = (server_set_relay(self.ctx, sid, d)
                       if _SRV_ID_RX.fullmatch(sid) else {"err": SRV_GONE})
            elif op not in ("pair", "test", "access", "remove", "prefer"):
                self.send_error(404)
                return
            elif not _SRV_ID_RX.fullmatch(sid):
                out = {"err": SRV_GONE}
            elif op == "pair":
                out = server_pair(self.ctx, sid, d.get("code"))
            elif op == "access":
                out = server_set_access(self.ctx, sid, d)
            elif op == "remove":
                out = server_remove(self.ctx, sid)
            elif op == "prefer":
                out = server_set_prefer(self.ctx, sid, d.get("on"))
            else:
                _se = _srv_find(_srv_read(self.ctx), sid)
                out = {"err": SRV_GONE}
                if _se is not None:
                    server_check(_se)
                    if (_srv_seen.get(_se["id"]) or {}).get("auth"):
                        server_gen_refresh(_se)
                    out = {"ok": True, "server": _srv_public(_se)}
            if op == "sleep" and IS_MAC and d.get("enabled") is True and out.get("ok"):
                srv_lan_touch_bg(self.ctx, [sid])    # the switch is the moment to ask (6b430)
            self._send_json(out)
            return
        if self.path == "/api/cloud/balance":
            # THE TYPED BALANCE (6b441): {provider, amount} sets it, now;
            # {provider, clear: true} forgets it. Not a secret, but never
            # a key either way.
            n2 = int(self.headers.get("Content-Length", 0) or 0)
            try:
                d = json.loads(self.rfile.read(n2)) if n2 else {}
            except (ValueError, json.JSONDecodeError):
                d = {}
            if not isinstance(d, dict):
                d = {}
            which = str(d.get("provider", "")).strip().lower()
            if which not in BALANCE_PROVIDERS:
                self._send_json({"ok": False,
                                 "err": "no balance estimate for that provider"})
                return
            profile_local(self.ctx, strict=True)
            if d.get("clear") is True:
                def _clr(p):
                    cur = p.get("cloud_balance")
                    if isinstance(cur, dict):
                        cur = {k: v for k, v in cur.items() if k != which}
                        p["cloud_balance"] = cur
                profile_local_update(self.ctx, _clr)
                self._send_json({"ok": True, "balance": cloud_balance_est(self.ctx)})
                return
            amt = balance_valid(d.get("amount"))
            if amt is None:
                self._send_json({"ok": False,
                                 "err": "Enter an amount from 0 to %d." % BALANCE_MAX_USD})
                return
            now = round(time.time(), 1)

            def _set(p):
                cur = p.get("cloud_balance")
                cur = dict(cur) if isinstance(cur, dict) else {}
                cur[which] = {"amount_usd": amt, "set_at": now}
                p["cloud_balance"] = cur
            profile_local_update(self.ctx, _set)
            self._send_json({"ok": True, "balance": cloud_balance_est(self.ctx)})
            return
        if self.path == "/api/cloud/set":
            # KEY SETUP IN-APP, per Patrick ("no extra user effort"):
            # the owner pastes a key into their own running app; it is
            # written 0600 next to the other config and never echoed back.
            n2 = int(self.headers.get("Content-Length", 0) or 0)
            try:
                d = json.loads(self.rfile.read(n2)) if n2 else {}
            except (ValueError, json.JSONDecodeError):
                d = {}
            key = str(d.get("key", "")).strip()
            which = str(d.get("provider", "gemini")).strip().lower()
            # every branch below saves settings too: settings it can't
            # read refuse the request before a key is touched (review of
            # 6b322), so "Nothing was changed" stays true
            profile_local(self.ctx, strict=True)
            if which == "off":
                # inside the cloud lock (6b326): a writer that had read the
                # file first would otherwise write every key back
                with _cloud_txn():
                    try:
                        self.ctx.remove(CLOUD_NAME)
                    except StaleProfile:
                        raise
                    except OSError:
                        pass
                _set_turbo(self.ctx, False)
                self._send_json({"ok": True, "off": True})
                return
            spec = {
                # defaults only matter when discovery fails (6b307):
                # gemini-2.5-flash is closed to new users, and the
                # claude-sonnet-4-5 snapshot retires from 2026-09-29
                "gemini": ("Gemini", PROVIDER_BASES["gemini"],
                           "gemini-3.8-flash"),
                # the name is the provider, not a model: the seat is
                # Qwen when Groq lets it, gpt-oss otherwise (6b307)
                "groq": ("Groq", PROVIDER_BASES["groq"],
                         "openai/gpt-oss-120b"),
                "claude": ("Claude", PROVIDER_BASES["claude"],
                           "claude-opus-5-5"),
                # Moonshot's Kimi K3 (6b245, per Patrick): 2.8T-param MoE,
                # open weights but ~64 H100s to self-host — so it joins as
                # a provider, not a local row. OpenAI-compatible API; the
                # default id is a guess the discovery call corrects.
                "kimi": ("Kimi K3", PROVIDER_BASES["kimi"], "kimi-k3"),
            }.get(which)
            if not spec or len(key) < 12:
                self._send_json({"ok": False, "err": "Paste the whole key."})
                return
            name, base, model = spec
            # CAUGHT BEFORE THE NETWORK: a key whose prefix identifies the
            # vendor but whose length is short is a truncated paste, full
            # stop — no round trip needed, and the message says so instead
            # of relaying the provider's ambiguous "Invalid API Key".
            _pre, _want, _exact = KEY_SHAPE.get(which, ("", 0, False))
            if _pre and _want and key.startswith(_pre) and len(key) < _want:
                self._send_json({
                    "ok": False,
                    "err": "The key looks cut off: %d characters, not %s%d. Copy it again." % (len(key), which.title(),
                                       "" if _exact else "at least ",
                                       _want)})
                return
            # DISCOVER models with the key first (6b213): one call
            # checks auth AND returns the real inventory, so a retired
            # default (gemini-2.5-flash, seen live) can never brick the
            # save. The chat probe below then verifies the pick.
            found = []
            try:
                # a bare Python-urllib UA gets 403'd at Groq's edge, which
                # silently saved a stale default (6b307)
                if "anthropic" in base:
                    lq = urllib.request.Request(
                        base + "/models?limit=1000",
                        headers={"x-api-key": key,
                                 "anthropic-version": "2023-06-01",
                                 "User-Agent": "MillenAI/%s" % APP_VERSION})
                else:
                    lq = urllib.request.Request(
                        base + "/models",
                        headers={"Authorization": "Bearer " + key,
                                 "User-Agent": "MillenAI/%s" % APP_VERSION})
                raw = json.loads(urllib.request.urlopen(
                    lq, timeout=20).read().decode("utf-8", "replace"))
                found = [str(m.get("id", "")).replace("models/", "")
                         for m in (raw.get("data") or [])
                         if m.get("id")]
            except Exception:
                pass                      # discovery is best-effort
            cands = []
            if found:
                # chat-capable only, then the ranked best — the policy
                # lives in CLOUD_SKIP_IDS/cloud_candidates, shared with
                # the boot refresh (6b247, ranked since 6b307)
                chat = [i for i in found
                        if not any(k in i.lower() for k in CLOUD_SKIP_IDS)]
                cands = cloud_candidates(which, chat, "seat")
                if cands:
                    model = cands[0]
                elif chat:
                    model = chat[0]
                found = chat or found[:6]
            # live-test before saving: a bad key must fail HERE, not
            # silently on the user's next question. A pick the provider
            # says is gone hands over to the next ranked one (6b307).
            # A BUSY OR THROTTLED PICK IS NOT A BAD KEY (6b307, found in
            # review): a 503 "high demand" on gemini-3.8-flash, or Qwen's
            # per-model token cap on Groq, saved a working key as failed
            # and called it revoked. Those hand over too, and when every
            # candidate is merely busy the key is saved with a note.
            _next = [m for m in cands if m != model][:3]
            _busy = False
            try:
                while True:
                    try:
                        _probe_model(base, key, model)
                        break
                    except urllib.error.HTTPError as _pe:
                        _pb = _http_body(_pe)
                        _gone = (_pe.code in (400, 404)
                                 and _MODEL_GONE_RX.search(_pb))
                        _mbusy = (_pe.code in (500, 502, 503, 504, 529)
                                  or (_pe.code == 429
                                      and model.lower() in _pb.lower()
                                      and not _NO_CREDIT_RX.search(_pb)))
                        if _next and (_gone or _mbusy):
                            model = _next.pop(0)
                            continue
                        if _mbusy:
                            _busy = True
                            break
                        raise
            except urllib.error.HTTPError as exc:
                # the provider's OWN words beat "HTTP Error 400": Google
                # answers 400 "Please pass a valid API key" for a bad key
                # (verified live) — surface that, plus the shape hint
                raw = _http_body(exc)
                detail = ""
                try:
                    body = json.loads(raw)
                    if isinstance(body, list):
                        body = body[0] if body else {}
                    detail = ((body.get("error") or {}).get("message")
                              or "")[:160]
                except Exception:
                    pass
                # A THROTTLED KEY IS A GOOD KEY. The probe spends real
                # quota, so on a free tier it is entirely normal for it to
                # come back 429 — and refusing the save there marked a
                # working Gemini key permanently failed while /models
                # still answered 200 (found live, 6b235). Accept it, rest
                # it, and say so.
                if cloud_failure_kind(exc.code, raw or detail) == "quota":
                    # an account with no money is saved too, but says so
                    # and sits out an hour, not ten minutes (6b307)
                    _broke = bool(_NO_CREDIT_RX.search(raw or detail))
                    _saved = _cloud_save_state(self.ctx, which, {"name": name, "base": base,
                                              "key": key, "model": model,
                                              "models": found,
                                              "status": "ok",
                                              "cool": time.time()
                                              + (3600.0 if _broke
                                                 else QUOTA_COOLDOWN),
                                              "note": ("out of credit \u2014 "
                                                       "top up the account"
                                                       if _broke else
                                                       "rate limited — "
                                                       "resting")},
                                      make_active=True)
                    if not _saved:
                        self._send_json({"ok": False, "err": _KEY_NOT_SAVED})
                        return
                    _set_turbo(self.ctx, True)
                    self._send_json({
                        "ok": True, "name": name, "model": model,
                        "models": found,
                        "warn": ("Key saved. The %s account is out of credit, so it sits out for now." % which.title()) if _broke else
                                ("key saved — %s is rate limited right now, "
                                 "so it sits out for a few minutes and comes "
                                 "back on its own." % which.title())})
                    return
                # the provider says "Invalid API Key" for a REVOKED key and
                # for a MANGLED one alike, so say which this looks like.
                # The prefix is the tell: right shape and right length is a
                # dead key (get a new one); anything else is the paste.
                hint = ""
                _pre, _want, _exact = KEY_SHAPE.get(which, ("", 0, False))
                if _pre and not key.startswith(_pre):
                    hint = (" This doesn’t look like a %s key; they start with %s."
                            % (which.title(), _pre))
                elif _want and _exact and len(key) != _want:
                    hint = (" The key is %d characters; a %s key is %d."
                            % (len(key), which.title(), _want))
                elif _want:
                    # right prefix, plausible length: the paste is fine, so
                    # the key itself is the problem — say so plainly rather
                    # than leaving "Invalid API Key" to be argued with
                    hint = (" The key looks right, so it was revoked or replaced. Issue a new one.")
                _kept = _cloud_save_failed(which, {
                    "name": name, "base": base, "key": key, "model": model,
                    "status": "fail",
                    "note": (detail or ("HTTP %s" % exc.code))[:120]},
                    # a key /models answered for isn't rejected (review)
                    auth=(cloud_failure_kind(exc.code, raw or detail) == "auth"
                          and not found))
                # the hints end in a full stop and the kept note starts with
                # one, so the stop is the note's when there is a note
                _kn = _kept_note(name, _kept)
                self._send_json({"ok": False,
                                 "err": "That key didn’t work: %s%s%s"
                                        % (detail or ("HTTP %s"
                                           % exc.code),
                                           hint.rstrip(".") if _kn else hint,
                                           _kn)})
                return
            except Exception as exc:
                _kept = _cloud_save_failed(which, {
                    "name": name, "base": base, "key": key, "model": model,
                    "status": "fail", "note": str(exc)[:80]})
                self._send_json({"ok": False,
                                 "err": "that key didn't work (%s)%s"
                                        % (str(exc)[:60],
                                           _kept_note(name, _kept))})
                return
            if _busy and not found:
                # every model answered 5xx and discovery found nothing:
                # the key was never checked (from review), so it is saved
                # only where it replaces nothing that works
                _kept = _cloud_save_failed(which, {
                    "name": name, "base": base, "key": key, "model": model,
                    "status": "fail",
                    "note": "%s was busy; the key wasn't checked" % name})
                self._send_json({"ok": False,
                                 "err": "Couldn’t check the key: %s is busy. Try again in a minute%s."
                                        % (name, _kept_note(name, _kept))})
                return
            try:
                # the entry is written fresh, so the persisted retirement
                # list goes with it — re-saving a key IS the retry, and
                # the in-memory set has to forget too or the freshly
                # discovered models stay benched. AFTER the write (6b326):
                # a failure of the old key landing before it could rest or
                # retire the new key's models again
                if not _cloud_save_state(self.ctx, which, {"name": name, "base": base,
                                                 "key": key, "model": model,
                                                 "models": found,
                                                 "status": "ok"},
                                         make_active=True):
                    self._send_json({"ok": False, "err": _KEY_NOT_SAVED})
                    return
                cloud_revive(found + [model])
            except StaleProfile:
                raise
            except Exception as exc:
                self._send_json({"ok": False, "err": str(exc)[:80]})
                return
            _set_turbo(self.ctx, True)
            _ok = {"ok": True, "name": name, "model": model,
                   "models": found}
            if _busy:
                _ok["warn"] = ("key saved — %s is busy right now and joins "
                               "as soon as it answers." % which.title())
            self._send_json(_ok)
            return
        if self.path in ("/api/workspace/set", "/api/workspace/off"):
            # the Workspace folder is a pref, so choosing or dropping it
            # is a POST (6b320; it was a GET, and a GET must change
            # nothing). The folder is only ever READ.
            n = int(self.headers.get("Content-Length", 0) or 0)
            try:
                d = json.loads(self.rfile.read(n)) if n else {}
            except (ValueError, json.JSONDecodeError):
                d = {}
            if not isinstance(d, dict):
                d = {}
            if self.path == "/api/workspace/off":
                profile_local_update(self.ctx,
                                     lambda p: p.pop("workspace", None))
                self._send_json({"ok": True})
                return
            # Explorer's "Copy as path" wraps it in quotes (6b317)
            root = os.path.expanduser(
                str(d.get("root") or "").strip().strip('"'))
            if not root or not os.path.isdir(root):
                self._send_json({"ok": False,
                                 "err": "That folder doesn’t exist."})
                return
            root = os.path.realpath(root)
            profile_local_update(self.ctx,
                                 lambda p: p.__setitem__("workspace", root))
            self._send_json({"ok": True, "root": root,
                             "files": len(_ws_files(root))})
            return
        if self.path.startswith("/api/remote/"):
            # SSH connection + the live approval channel (6b249)
            n = int(self.headers.get("Content-Length", 0) or 0)
            try:
                d = json.loads(self.rfile.read(n)) if n else {}
            except (ValueError, json.JSONDecodeError):
                d = {}
            if self.path == "/api/remote/approve":
                jid = str(d.get("jid", ""))
                with _remote_lock:
                    job = _remote_jobs.get(jid)
                    if job:
                        job["ok"] = bool(d.get("ok"))
                        job["gate"].set()
                self._send_json({"ok": bool(job)})
                return
            if self.path == "/api/remote/config":
                host = str(d.get("host", "")).strip()[:200]
                if not host:
                    try:
                        self.ctx.remove(REMOTE_NAME)
                    except StaleProfile:
                        raise
                    except Exception:
                        pass
                    self._send_json({"ok": True, "cleared": True})
                    return
                posted = {"host": host,
                          "user": str(d.get("user", "root")).strip()[:80]
                          or "root",
                          "port": str(d.get("port", "22")).strip()[:6]
                          or "22",
                          "key": str(d.get("key", "")).strip()[:300],
                          # an optional jump host (6b326): -F means ssh
                          # no longer reads a ProxyJump from ~/.ssh/config
                          "jump": str(d.get("jump", "")).strip()[:300]}
                conf = _remote_merge(remote_conf(), posted)
                if conf is not None and not _remote_save(conf):
                    self._send_json({"ok": False, "err": "Couldn’t save the connection. Check that the ConcordeAI folder isn’t read-only."})
                    return
                self._send_json({"ok": True})
                return
            if self.path == "/api/remote/forget":
                # the entry ssh said changed (or the server's and its jump
                # hosts') in the app's own host-key list (6b326)
                try:
                    _n = ssh_forget_host(remote_conf(), _SSH_CHANGED[0])
                    _SSH_CHANGED[0] = None
                    self._send_json({"ok": True, "removed": _n})
                except StaleProfile:
                    raise
                except Exception as exc:
                    self._send_json({"ok": False, "err": "Couldn’t update the host list: %s"
                                     % str(exc)[:120]})
                return
            if self.path == "/api/remote/test":
                conf = remote_conf()
                if not conf.get("host"):
                    self._send_json({"ok": False,
                                     "err": "No connection saved."})
                    return
                rc, out = ssh_run(conf, "echo __ok__ && whoami && uname -sr",
                                  timeout=20)
                ok = rc == 0 and "__ok__" in out
                # the useful line is ssh's last (6b326): keep the tail
                self._send_json({
                    "ok": ok,
                    "changed": bool(not ok and _SSH_HOSTKEY_RX.search(out)),
                    "detail": out.replace("__ok__", "").strip()[:300]
                    if ok else out.strip()[-500:]})
                return
            self.send_error(404)
            return
        if self.path == "/api/setup/install":
            # warm one backdrop alongside the models, so the very first
            # launch already opens onto a moving city
            try:
                sky_status(random.randrange(len(SKY_SOURCES)))
            except Exception:
                pass
            n = int(self.headers.get("Content-Length", 0) or 0)
            try:
                _d = json.loads(self.rfile.read(n)) if n else {}
            except (ValueError, json.JSONDecodeError):
                _d = {}
            # ONE OF THE THREE SETS (6b405), by name or by an old plan's
            # (basic/min -> light, pro/rec -> recommended, max/full/all ->
            # everything). It ADDS what is missing and deletes nothing: an
            # outdated version stays auto-clean's job. The pick is kept, so
            # the status and the More-models card follow the person's set
            _key = model_set_key((_d if isinstance(_d, dict) else {}).get("plan"))
            if not _key:
                self._send_json({"err": "Pick Light, Recommended or Everything."},
                                code=400)
                return
            _want = model_sets()[_key]
            _started = start_model_downloads(_want)
            model_set_choose(_key)
            self._send_json({"set": _key, "started": _started, "n": len(_want),
                             "already": len(_want) - len(_started),
                             "gb": round(sum(MODEL_INFO[l]["gb"]
                                             for l in _started), 1)})
            return
        if self.path == "/api/models/offer":
            # THE CARD'S BUTTON (6b335): carried out only if a plan made
            # now is still the one the card listed. Otherwise nothing
            # changes and the card gets the new plan to show instead.
            n = int(self.headers.get("Content-Length", 0) or 0)
            try:
                asked = json.loads(self.rfile.read(n)) if n else {}
            except (ValueError, json.JSONDecodeError):
                asked = {}
            plan = model_offer_plan()
            if not offer_matches(plan, asked):
                self._send_json({"changed": True, "plan": plan}, code=409)
                return
            self._send_json(apply_model_offer(plan))
            return
        if self.path == "/api/update/install":
            if _update["state"] in ("idle", "error"):
                ctx_thread(target=_do_update, daemon=True).start()
            self._send_json({"ok": True})
            return
        if self.path == "/api/update/download":
            # a PC's update: its release file, in the browser. Only the
            # URL the update check found is ever opened.
            url = str(_update.get("manual") or "")
            ok = url.startswith("https://github.com/")
            if ok:
                try:
                    webbrowser.open(url)
                except Exception:
                    ok = False
            self._send_json({"ok": ok})
            return
        if self.path == "/api/funnel/image":
            # ONE MORE PICTURE (6b340): for a card the stage sent without
            # one, or whose picture wouldn't load in the page. Only the
            # goal and the option's label go out, as the stage's own
            # search sends; `exclude` is every picture already on the
            # stage and each one that failed
            n = int(self.headers.get("Content-Length", 0) or 0)
            try:
                d = json.loads(self.rfile.read(n)) if n else {}
            except (ValueError, json.JSONDecodeError):
                d = {}
            d = d if isinstance(d, dict) else {}
            label = str(d.get("label", "")).strip()[:90]
            if not label:
                self._send_json({"img": "", "err": "no option named"})
                return
            goal = str(d.get("goal", "")).strip()[:300]
            if not HAS_SEARCH or _fimg_blocked(goal, label):
                # nothing to ask, or nothing to show: the page stops
                # trying at once
                self._send_json({"img": "", "none": True})
                return
            ex = [str(u)[:400] for u in (d.get("exclude") or [])
                  if isinstance(u, str)][:40]
            self._send_json({"img": funnel_images(
                goal, [label], budget=12.0, exclude=ex)[0]})
            return
        if self.path == "/api/funnel":
            n = int(self.headers.get("Content-Length", 0) or 0)
            try:
                d = json.loads(self.rfile.read(n)) if n else {}
            except (ValueError, json.JSONDecodeError):
                d = {}
            # held like a chat (review of 6b331): no benchmark starts mid-
            # stage, and none refuses its model call halfway through
            if not bench_hold():
                self._send_json({"err": BENCH_BUSY, "bench": True}, code=409)
                return
            self._bench_held = True
            goal = str(d.get("goal", "")).strip()[:300]
            if not goal:
                self._send_json({"err": "Name the decision first."})
                return
            reqs = str(d.get("reqs", "")).strip()[:400]
            picks = [str(x)[:90] for x in (d.get("picks") or [])][:20]
            opts = max(2, min(6, int(d.get("opts", 3) or 3)))
            total = max(1, min(20, int(d.get("stages", 5) or 5)))
            want_img = bool(d.get("images"))
            asked = [str(x)[:160] for x in (d.get("asked") or [])][:20]
            effort = "fast" if d.get("effort") == "fast" else "normal"
            # "Include cloud models" (6b339): read at every stage, so an open
            # funnel respects a change at the next one; ticked unless the
            # page says otherwise, and never without cloud power and a key
            # the saved choice counts too (rules review of 6b339): a request
            # that omits the field, or a page that hadn't read the setting,
            # can't turn cloud on against a saved OFF
            try:
                _saved_cloud = (user_prefs(self.ctx).get("funnel_cloud", True)
                                is not False)
            except (StaleProfile, BrokenPipeError, ConnectionResetError):
                raise
            except Exception:
                _saved_cloud = False
            use_cloud = (d.get("cloud") is not False and _saved_cloud
                         and cloud_allowed())
            stage = len(picks) + 1
            # FUNNEL TURNS ARE SAVED HERE (0b 5.5, gap G4; 6b322): the goal
            # or the latest pick when the request arrives, the summary
            # when it's done; the page only ever saved them itself, and
            # never the summary. Each reply carries the chat as saved.
            _fc = str(d.get("chat_id") or "")
            _ft = None
            _fbase = self.ctx
            if _fc and _CHAT_ID.fullmatch(_fc):
                if picks:
                    _fq = asked[len(picks) - 1] if len(asked) >= len(picks) else ""
                    _arrive = {"role": "assistant", "content":
                               (_fq + " \u2192 " if _fq else "") + picks[-1]}
                else:
                    _arrive = {"role": "user", "content": "Funnel: " + goal}
                _ft = list(chat_append_turn(
                    _fc, d.get("after_len"), d.get("after_hash"), [_arrive],
                    _fbase, lane="funnel", title=("Funnel: " + goal)[:48]))

            def _fsend(reply):
                if _ft:
                    if reply.get("done") and reply.get("summary"):
                        # a late write: a funnel deleted or erased
                        # meanwhile doesn't come back as a new chat
                        _late = chat_append_late(
                            _ft[0], _ft[1], _ft[2],
                            {"role": "assistant",
                             "content": str(reply["summary"])}, _fbase)
                        if _late:
                            _ft[:] = _late
                    with _chats_lock:
                        _, _fcc = _chat_find(load_chats(_fbase), _ft[0])
                    if _fcc:
                        reply["chat"] = {"id": _ft[0], "title": _fcc.get("title"),
                                         "messages": _fcc.get("messages", [])}
                self._send_json(reply)
            if stage > total:
                # the funnel is spent — summarise the path taken
                msgs = [{"role": "system",
                         "content": funnel_summary_sys_for(goal)},
                        {"role": "user", "content":
                         "DECISION: %s\nREQUIREMENTS: %s\nThe user "
                         "answered each narrowing question, in order: "
                         "%s\n(the questions asked were: %s)\n\n"
                         "Give your recommendation:\n"
                         "- NAME the specific thing in the first "
                         "sentence — a real, concrete pick (a breed, a "
                         "product, a place, a plan), never a category, "
                         "never a restatement of their answers, and "
                         "never a string that appears verbatim in the "
                         "picks list: the stages narrowed, YOU name. "
                         "If the last pick is already fully specific, "
                         "go one level deeper (exact model or config, "
                         "where to get it, what to order).\n"
                         "- When you refer to their preferences, use "
                         "ONLY their exact words from the answers — "
                         "never invent a budget, timeline or living "
                         "situation they didn't state, and never "
                         "SHRINK a stated one (picked 'up to $2000' "
                         "can't become 'a $1500 budget'). A fact they "
                         "didn't give is YOUR suggestion — say 'worth "
                         "checking', never 'since you want'. If a "
                         "typed answer skipped a question's axis, or "
                         "two answers conflict, say so in one plain "
                         "clause and resolve it — never silently "
                         "default.\n"
                         "- No invented logistics: never assert a "
                         "shuttle, opening status, travel time or "
                         "bookable venue you have no data for — "
                         "recommend the THING, and mark the logistics "
                         "as to-verify.\n"
                         "- The thing you name must be word-for-word "
                         "identical in the verdict and the next step.\n"
                         "- Then two or three sentences on why it fits "
                         "THESE answers and the requirements — woven "
                         "in, not listed back. Paraphrase their picks "
                         "into natural sentences; never paste an "
                         "option label as a clause ('since you are "
                         "traveling no car' is pasted; 'since you're "
                         "going car-free' is written).\n"
                         "- End with the single most useful next step, "
                         "as a plain instruction.\n"
                         "- If two picks genuinely tie, lead with your "
                         "winner and give the runner-up one clause.\n"
                         "Under 160 words. No preamble."
                         % (goal, reqs or "none", "; ".join(picks),
                            "; ".join(asked) or "not recorded")}]
                out = ""
                _eng = ""
                # the verdict is a draft the audit below checks, so it
                # writes at the work effort; the audit is the final word
                if use_cloud:
                    for _conf in work_ladder("work"):
                        out = cloud_text(_conf, msgs, timeout=120)
                        if out:
                            _eng = str(_conf.get("model") or "cloud")
                            break
                if not out:
                    # then the person's server (6b339), the strongest general
                    # model that fits its card, same chooser as the stages
                    try:
                        server_refresh_modes(self.ctx)
                        _sp = server_funnel_pick(self.ctx, "normal")
                    except (StaleProfile, BrokenPipeError,
                            ConnectionResetError):
                        raise
                    except Exception:
                        _sp = None
                    if _sp:
                        try:
                            _sparts = []
                            with server_first_deadline(60):
                                run_model(_sp["label"], msgs, _sparts.append)
                            out = strip_think("".join(_sparts))
                            if out:
                                _eng = "server:%s \u00b7 %s" % (_sp["server"], _sp["name"])
                        except (StaleProfile, BrokenPipeError,
                                ConnectionResetError):
                            raise
                        except Exception as _exc:
                            out = ""
                            server_mark_down(self.ctx, _sp["server"], str(_exc))
                if not out:
                    # ANY strong cached model beats none (6b260): the
                    # old three-label ladder meant a Mac without those
                    # exact models fell through to parroting the picks
                    lbl = next((l for l in MERGE_RANK
                                if l not in BLEND_EXCLUDE
                                and not slow_giant(l)
                                and model_cached(l)
                                and model_fits_memory(l)), "")
                    if lbl:
                        parts = []
                        try:
                            run_model(lbl, msgs, parts.append)
                            out = strip_think("".join(parts))
                            if out:
                                _eng = "local:" + lbl
                        except Exception:
                            out = ""
                # THE VERIFY PASS (6b271, judged three cycles running:
                # "Conservative" -> an all-equity fund, "social
                # companion" -> a solitary hamster, an invented NJ
                # Transit line). Rules alone did not hold, so a second
                # call audits the verdict against every pick and
                # requirement and rewrites what fails. Cloud only —
                # a 4-bit local auditor would rubber-stamp.
                try:
                  if out and use_cloud:
                    _audit = [
                        {"role": "system", "content":
                         "You audit a recommendation against what the "
                         "user actually chose. Be literal and "
                         "unforgiving."},
                        {"role": "user", "content":
                         "DECISION: %s\nREQUIREMENTS: %s\nTHE USER'S "
                         "PICKS, in order: %s\n\nVERDICT UNDER AUDIT:\n"
                         "%s\n\nDo this in order. FIRST, for each pick, "
                         "write one line in your own words stating what "
                         "the recommended thing ACTUALLY is on that axis "
                         "from what you know of it — not what the "
                         "verdict claims (e.g. 'Syrian hamster: solitary, "
                         "nocturnal, 2-3 yr lifespan'; 'VTSAX: 100%% "
                         "equities'; 'Bordentown: ~1.5 h from Penn'). "
                         "Then, for each named venue, product, route or "
                         "service, one line: real and exactly named, or "
                         "not vouchable. SECOND, judge: does each real "
                         "attribute match the pick in plain meaning (an "
                         "all-equity fund is not 'conservative'; a "
                         "solitary animal is not a 'social companion'; "
                         "a one-time fee does not meet a monthly budget; "
                         "a 90-minute town does not honor '4+ hours')? "
                         "Does every requirement hold — a stated number "
                         "(budget, hours) is a hard wall, and a price "
                         "above it fails even by a little? Does every "
                         "TYPED answer appear, honored or reconciled? "
                         "The verdict's "
                         "own assurances count for nothing. Identifiers "
                         "must be EXACT — a ticker, model number or "
                         "product name you are not certain of is a "
                         "fail; the correction names the thing "
                         "descriptively without the identifier. THIRD: "
                         "if everything holds, end with exactly: OK. "
                         "Otherwise end with a corrected verdict, "
                         "beginning on a line that says VERDICT:, in "
                         "the same shape and length — the real closest "
                         "thing, plainly naming which pick it misses, "
                         "and 'check the actual route' in place of any "
                         "logistics you could not vouch for. The "
                         "corrected verdict must read as a fresh "
                         "recommendation to the user — never mention "
                         "the audit, a wrong name, or that anything "
                         "was invented."
                         % (goal, reqs or "none", "; ".join(picks), out)}]
                    _fix = ""
                    for _conf in (compositor_ladder() or []):
                        _fix = cloud_text(_conf, _audit, timeout=120)
                        if _fix:
                            break
                        _rc = claude_refusal_conf(_conf)
                        if _rc:
                            _fix = cloud_text(_rc, _audit, timeout=120)
                            if _fix:
                                break
                    _fix = (_fix or "").strip()
                    # the audit's working lines stay private: only a
                    # VERDICT: block replaces the answer; a bare OK
                    # (or an audit with no verdict) leaves it alone
                    if _fix and not _fix.rstrip().endswith("OK"):
                        _m = re.search(r"VERDICT:\s*([\s\S]{40,})$", _fix)
                        if _m:
                            out = _m.group(1).strip()
                except Exception:
                    # an auditor that crashes forfeits its say; the
                    # verdict ships un-audited rather than not at all
                    # (6b277 — the bare-% crash closed the socket)
                    pass
                # NEVER hand the picks back as if they were an answer
                # (6b260, per Patrick) — if no model can weigh in, say
                # so honestly and point at the fix
                _fsend({"done": True, "stage": total,
                                 "total": total, "engine": _eng,
                                 "summary": out or (
                                     "I couldn't reach a model to weigh "
                                     "these, so no recommendation yet — "
                                     "your path was: "
                                     + " \u2192 ".join(picks)
                                     + ". Add a local model in Settings "
                                     "\u2192 Models (or a cloud key) and "
                                     "finish the funnel again.")})
                return
            st = funnel_stage(goal, reqs, opts, stage, total, picks,
                              want_img, asked, effort=effort,
                              cloud=use_cloud)
            _fsend({"done": False, "stage": stage,
                             "total": total, "q": st["q"],
                             "options": st["options"],
                             "engine": st.get("engine", "")})
            return
        if self.path == "/api/prefs":
            n = int(self.headers.get("Content-Length", 0))
            try:
                d = json.loads(self.rfile.read(n))
            except (ValueError, json.JSONDecodeError):
                d = None
            if not isinstance(d, dict):
                self._send_json({"ok": False})
                return
            # each key to its own place, compare-and-set (1a 5.6, 6b329):
            # the machine's to prefs.json, the person's and this
            # profile's to the active profile's files (prefs.json for
            # "This computer", as before). The read, the check and the
            # write of each under ONE lock (6b304: every toggle posts on
            # change, so two quick flips raced). A file it can't read
            # answers 503 and is left as it is (6b322). "_old" (optional)
            # holds the values the page last saw.
            old = d.pop("_old", None)
            out = split_prefs(self.ctx, d, old)
            if "no_limits" in d:
                _no_limits["v"] = bool(d.get("no_limits"))
            if "include_giants" in d:
                _giants["v"] = bool(d.get("include_giants"))
            self._send_json(out)
            return
        if self.path in ("/api/prefs/adopt", "/api/webstore/clean"):
            # the page's first-run move of its six per-person keys into
            # prefs.json, and the web view's clean-up (0b 5.10, 6b324)
            n = int(self.headers.get("Content-Length", 0) or 0)
            try:
                d = json.loads(self.rfile.read(n)) if n else {}
            except (ValueError, json.JSONDecodeError):
                d = None
            if not isinstance(d, dict):
                self._send_json({"err": "not an object"}, code=400)
            elif self.path == "/api/prefs/adopt":
                self._send_json(prefs_adopt(d, self.ctx))
            else:
                self._send_json(webstore_clean(d.get("local") is True))
            return
        if self.path == "/api/chats":
            # GONE (0b 5.3, 6b322): the whole-list save let an outdated
            # page replace everything; a page this old must reload
            self._send_json({"err": "This page is out of date. Reload."},
                            code=410)
            return
        if self.path == "/api/chats/ops":
            n = int(self.headers.get("Content-Length", 0) or 0)
            try:
                d = json.loads(self.rfile.read(n)) if n else {}
            except (ValueError, json.JSONDecodeError):
                d = {}
            ops = d.get("ops") if isinstance(d, dict) else None
            if not isinstance(ops, list):
                self._send_json({"err": "no ops"}, code=400)
                return
            self._send_json(chat_ops(ops, self.ctx))
            return
        if self.path == "/api/sky/seen":
            # the backdrop now showing, for the history beside the clips
            n = int(self.headers.get("Content-Length", 0) or 0)
            try:
                i = int(json.loads(self.rfile.read(n)).get("i"))
            except (ValueError, TypeError, AttributeError):
                i = -1
            ok = 0 <= i < len(SKY_SOURCES)
            if ok:
                sky_seen(i)
            self._send_json({"ok": ok})
            return
        if self.path == "/api/feedback":
            # GOOD / BAD ON AN ANSWER (6b528): one line in the quality
            # ledger ("make it better" has numbers instead of vibes), keyed
            # by the chat and the answer's place in it. 1 good, -1 bad, 0
            # takes it back. Nothing else is read or changed.
            _fb = self._json_body()
            try:
                vote = int(_fb.get("vote", 0))
            except (TypeError, ValueError):
                vote = 0
            cid = str(_fb.get("chat_id") or "")[:40]
            try:
                n = int(_fb.get("n", -1))
            except (TypeError, ValueError):
                n = -1
            if vote not in (-1, 0, 1) or not _CHAT_ID.fullmatch(cid) or n < 0:
                self._send_json({"ok": False, "err": "not a vote"}, code=400)
                return
            try:
                self.ctx.append(QUALITY_FILE, (json.dumps({
                    "ts": int(time.time()), "fb": vote, "chat": cid, "n": n})
                    + "\n").encode("utf-8"), mode=0o644)
            except StaleProfile:
                raise
            except Exception:
                self._send_json({"ok": False, "err": "couldn’t save it"},
                                code=500)
                return
            self._send_json({"ok": True})
            return
        if self.path == "/api/chat/hurry":
            # ANSWER NOW (6b257): flips the per-request Event minted in
            # /api/chat. The unguessable id is the whole authorization,
            # exactly like the Remote agent's APPROVE jid.
            n = int(self.headers.get("Content-Length", 0) or 0)
            _hb = {}
            try:
                _hb = json.loads(self.rfile.read(n)) if n else {}
                hid = str(_hb.get("hid", "")) if isinstance(_hb, dict) else ""
            except (ValueError, json.JSONDecodeError):
                hid = ""
            with _hurry_lock:
                ev = (_skip_jobs if isinstance(_hb, dict) and _hb.get("skip")
                      else _hurry_jobs).get(hid)
            if ev:
                ev.set()
            self._send_json({"ok": bool(ev)})
            return
        if self.path == "/api/suggest/refresh":
            # "Refresh" in Settings (6b390): a pass now, unless an answer, a
            # download or a benchmark is running
            self._send_json(suggest_view(self.ctx, refresh=True))
            return
        if self.path == "/api/title":
            n = int(self.headers.get("Content-Length", 0))
            try:
                _tb = json.loads(self.rfile.read(n))
                txt = str(_tb.get("text", ""))
                _tcid = str(_tb.get("chat_id") or "")
            except (ValueError, json.JSONDecodeError, AttributeError):
                txt, _tcid = "", ""
            # a chat the cloud just answered is named by that provider's
            # quick model (6b308); anything else stays on this Mac. The
            # ticket is THIS chat's (6b326), and make_title re-reads its
            # key under the lock
            _lc = (_last_cloud.get((self.ctx.name, _tcid))
                   if _tcid else None)
            _conf = (_lc[0] if _lc and time.time() - _lc[1] < 300
                     and cloud_allowed() else None)
            # a chat "<server> Only" just answered is named by that
            # server's model or not at all (6b337): never a local one
            # a chat a document was read in (6b522) is named on this Mac,
            # never by a server or a provider
            _dc = _doc_chats.get((self.ctx.name, _tcid)) if _tcid else None
            if _dc and time.time() - _dc < 300:
                self._send_json({"title": make_title(txt, ask_server=False)
                                 if txt else ""})
                return
            _so = (_srv_only_chats.get((self.ctx.name, _tcid))
                   if _tcid else None)
            _co = bool(_tcid and time.time() - _cloud_only_chats.get(
                (self.ctx.name, _tcid), 0) < 300)
            if _so and time.time() - _so[1] < 300:
                self._send_json({"title": make_title(txt, server=_so[0])
                                 if txt else ""})
                return
            self._send_json({"title": make_title(txt, conf=_conf, ask_server=not _co)
                             if txt else ""})
            return
        if self.path == "/api/open-logs":
            subprocess.Popen(
                ["open", log_dir()])
            self._send_json({"ok": True})
            return
        if self.path in ("/api/know", "/api/know/forget", "/api/know/open",
                         "/api/know/reindex"):
            # YOUR STUFF (6b530): the settings (chats on or off, a folder
            # added, sharing), Forget this folder, open a cited file, read
            # everything again. Folders are only ever read.
            n = int(self.headers.get("Content-Length", 0) or 0)
            try:
                d = json.loads(self.rfile.read(n)) if n else {}
            except (ValueError, json.JSONDecodeError):
                d = {}
            if not isinstance(d, dict):
                d = {}
            err = ""
            if self.path == "/api/know":
                root = ""
                if d.get("add") is not None:
                    root = os.path.realpath(os.path.expanduser(
                        str(d.get("add") or "").strip().strip('"')))
                    home = os.path.realpath(os.path.expanduser("~"))
                    own = os.path.realpath(app_dir())
                    if not root or not os.path.isdir(root):
                        err, root = "That folder doesn\u2019t exist.", ""
                    elif root in ("/", home) or root == own or root.startswith(own + os.sep):
                        err, root = ("Pick a folder inside your home, like Documents, "
                                     "not your whole home or the app\u2019s own data."), ""

                def _upd(sx):
                    if "chats" in d:
                        sx["chats"] = d["chats"] is True
                    if "share" in d:
                        sx["share"] = d["share"] is True
                    if root and root not in sx["folders"]:
                        sx["folders"] = sx["folders"] + [root]
                know_settings_update(self.ctx, _upd)
                know_kick(self.ctx, now=True)
            elif self.path == "/api/know/forget":
                if d.get("all") is True:
                    know_settings_update(self.ctx, lambda sx: sx.update(chats=False, folders=[]))
                    know_forget_all(self.ctx)
                else:
                    know_forget_folder(self.ctx, str(d.get("folder") or ""))
            elif self.path == "/api/know/reindex":
                know_forget_all(self.ctx)
                know_kick(self.ctx, now=True)
            elif self.path == "/api/know/open":
                # only a file the index holds (never an arbitrary path)
                u = str(d.get("u") or "")
                p = u[10:] if u.startswith("know:file:") else ""
                ok = False
                if p:
                    c = _know_conn(self.ctx)
                    try:
                        ok = bool(c.execute("SELECT 1 FROM docs WHERE key=?",
                                            ("file:" + p,)).fetchone())
                    finally:
                        c.close()
                if ok and os.path.exists(p):
                    if IS_MAC:
                        subprocess.Popen(["open", "-R", p])
                    elif IS_WIN:
                        subprocess.Popen(["explorer", "/select,", p])
                    else:
                        subprocess.Popen(["xdg-open", os.path.dirname(p)])
                else:
                    err = "That file isn\u2019t in your stuff any more."
                self._send_json({"ok": ok, "err": err})
                return
            out = know_status(self.ctx)
            out["ok"] = not err
            out["err"] = err
            self._send_json(out)
            return
        if self.path == "/api/memory/clear":
            # memory.json empties too (0b 5.8, L7): an older build must not
            # go on using a fact cleared here
            with _memory_lock:
                _load_memory(self.ctx)
                _save_memory([], self.ctx, erase=True)
            self._send_json({"ok": True})
            return
        if self.path == "/api/logout":
            # THE DESKTOP SIGN-OUT (M9, 1a 5.11). It signed a browser out of
            # the web version once (6b320: it touches no cookie, and never
            # the launch key's). In a build without accounts, or on "This
            # computer", it does nothing, as before. Signed in, it opens the
            # account window at the sign-out sheet: the main window may ask
            # for that window, never sign out itself (1a 5.9); the sheet's
            # answers and the sign-out run there (/api/account/signout).
            # A windowless copy gets the headless session instead.
            if not ACCOUNTS or self.ctx.root:
                self._send_json({"ok": True})
                return
            _r = account_open("signout", headless=NOWINDOW or SHELL)
            self._send_json({"ok": "err" not in _r, "account_window": "signout",
                             **({"err": _r["err"]} if "err" in _r else {})})
            return
        if self.path == "/api/forget":
            # FORGET ME, scoped (6b257, per Patrick: the droplet-destroy
            # treatment). The client asks WHAT dies, then demands FORGET
            # ME typed in caps; this end only deletes. The owner PIN and
            # the web profiles' whole-folder erase went with the web
            # version (6b320): each store is emptied in place and no
            # folder is ever removed.
            n = int(self.headers.get("Content-Length", 0) or 0)
            try:
                d = json.loads(self.rfile.read(n)) if n else {}
            except (ValueError, json.JSONDecodeError):
                d = {}
            if not isinstance(d, dict):
                d = {}          # valid JSON is not always an object
            scopes = set(d.get("scopes") or ["memory"])
            base = self.ctx
            # a store it can't read refuses the whole request before
            # anything is erased (review of 6b322, 0b L1)
            if "prefs" in scopes:
                user_prefs(base, strict=True)
            if "memory" in scopes:
                _load_memory(base)
            if "chats" in scopes:
                load_chats(base)
            # each store is emptied with its legacy file (0b 5.8, L7): an
            # older build started afterwards shows none of it either
            if "memory" in scopes:
                with _memory_lock:
                    _save_memory([], base, erase=True)
            if "chats" in scopes:
                with _chats_lock:
                    # the undo window's copies go too, and their ids stay
                    # dead, so a late answer can't bring one back
                    _chat_gone.update(_chat_stubs)
                    _chat_stubs.clear()
                    _chat_finals.pop(_bk(base), None)
                    with _turns_lock:
                        for _t in _turns_live.values():
                            _t["done"] = True
                        _turns_live.clear()
                    # nothing of the chats is left: not even the ids of
                    # the deleted ones
                    _cs = load_chats(base)
                    del _cs[:]
                    _cs.gone = []
                    store_chats(_cs, base, erase=True)
                suggest_forget(base)    # the summary of them goes too (6b390)
            if "prefs" in scopes:
                # personal keys only — machine config (turbo, update
                # channel) is not "about the user" and must survive
                def _forget(p):
                    for k in ("persona", "length", "user_name"):
                        p.pop(k, None)
                user_prefs_update(base, _forget)
            self._send_json({"ok": True})
            return
        if self.path == "/api/voice/prepare":
            if _voice_supported() and not _voice_ready():
                _prepare_voice()
            self._send_json({"ok": True})
            return
        if self.path.startswith("/api/dictate/"):
            # LIVE DICTATION (6b543): start, audio (as it is captured, raw
            # PCM int16 16 kHz mono; the reply carries the partial so far),
            # end (the tail, the reply is the final text), cancel, warm.
            _route, _, _q = self.path.partition("?")
            _sid = urllib.parse.parse_qs(_q).get("sid", [""])[0]
            n = int(self.headers.get("Content-Length", 0) or 0)
            body = self.rfile.read(n) if n else b""
            if _route == "/api/dictate/warm":
                _dict_warm()
                self._send_json({"ok": True, "engine": _dict_engine_name()})
                return
            if _route == "/api/dictate/start":
                if not (_voice_supported() and _voice_ready()):
                    self._send_json({"ok": False, "ready": False})
                    return
                s = _dict_start()
                if s is None:
                    self._send_json({"ok": False, "ready": False})
                    return
                self._send_json({"ok": True, "sid": s.sid, "engine": s.engine,
                                 "partials": s.partials})
                return
            s = _dict_get(_sid)
            if s is None:
                self._send_json({"ok": False, "err": "no session"}, code=404)
                return
            if _route == "/api/dictate/audio":
                s.feed(body)
                self._send_json({"ok": True, "partial": s.partial,
                                 "secs": round(s.secs(), 2)})
                return
            if _route == "/api/dictate/end":
                _dict_drop(s)
                try:
                    text = s.end(body)
                except Exception as exc:
                    self.send_error(500, str(exc)[:100])
                    return
                self._send_json({"ok": True, "text": text, "engine": s.engine})
                return
            if _route == "/api/dictate/cancel":
                _dict_drop(s)
                s.cancel()
                self._send_json({"ok": True})
                return
            self.send_error(404)
            return
        if self.path == "/api/transcribe":
            n = int(self.headers.get("Content-Length", 0))
            wav = self.rfile.read(n)
            if not (_voice_supported() and _voice_ready()):
                self.send_error(503, "Dictation isn’t ready")
                return
            try:
                self._send_json({"text": _dict_oneshot(_wav_to_f32(wav))})
            except Exception as exc:
                self.send_error(500, str(exc)[:100])
            return
        if self.path == "/api/speak":
            n = int(self.headers.get("Content-Length", 0))
            try:
                req = json.loads(self.rfile.read(n))
            except (ValueError, json.JSONDecodeError):
                req = {}
            if req.get("stop"):
                _stop_speaking()
            elif req.get("text"):
                _speak(req["text"])
            self._send_json({"ok": True})
            return
        if self.path == "/api/annotate/save":
            # the page's flattened picture (6b355): saved like an export,
            # then shown in Finder; a browser downloads it by id instead
            n = int(self.headers.get("Content-Length", 0) or 0)
            if n <= 0 or n > ANNOTATE_SAVE_MAX * 4 // 3 + 4096:
                self._send_json({"ok": False, "err": "Too big"}, code=413)
                return
            try:
                d = json.loads(self.rfile.read(n)) or {}
                r = save_annotated_png(self.ctx, d.get("png"))
            except (ValueError, json.JSONDecodeError, TypeError):
                self._send_json({"ok": False, "err": "not a PNG"}, code=400)
                return
            except StaleProfile:
                raise
            except (NotLanded, OSError):
                self._send_json({"ok": False, "err": "Couldn’t save. Try again."},
                                code=500)
                return
            r["ok"] = True
            # only when the page asks (the Save button does): a test or
            # a script that saves must not open a Finder window
            r["shown"] = bool(d.get("reveal")) and reveal_in_finder(
                os.path.join(export_dir(self.ctx), r["id"]))
            self._send_json(r)
            return
        if self.path == "/api/export/reveal":
            n = int(self.headers.get("Content-Length", 0) or 0)
            try:
                iid = (json.loads(self.rfile.read(n)) or {}).get("id", "")
            except (ValueError, json.JSONDecodeError):
                iid = ""
            pth = os.path.join(export_dir(self.ctx), str(iid))
            ok = bool(_X_ID_RX.match(str(iid))) and os.path.exists(pth) \
                and reveal_in_finder(pth)
            self._send_json({"ok": ok})
            return
        if self.path == "/api/studio/opts":
            n = int(self.headers.get("Content-Length", 0) or 0)
            try:
                d = json.loads(self.rfile.read(n)) if n else {}
            except (ValueError, json.JSONDecodeError):
                d = {}
            k = str(d.get("key") or "")
            if k not in STUDIOS:
                self._send_json({"ok": False})
                return
            self._send_json({"ok": True,
                             "opts": studio_save_opts(k, d.get("set") or {}),
                             "saved": studio_prefs(k)})
            return
        if self.path in ("/api/studio/install", "/api/studio/remove",
                         "/api/image/install", "/api/image/remove"):
            n = int(self.headers.get("Content-Length", 0) or 0)
            try:
                d = json.loads(self.rfile.read(n)) if n else {}
            except (ValueError, json.JSONDecodeError):
                d = {}
            key = str(d.get("key") or "image")
            if key not in STUDIOS:
                self._send_json({"ok": False, "error": "no such studio"})
                return
            if self.path.endswith("remove"):
                self._send_json(studio_remove(key))
            else:
                started = start_studio_install(key, str(d.get("tier") or ""))
                self._send_json({"started": started,
                                 "studio": studio_status(key)})
            return
        if self.path == "/api/model/download":
            n = int(self.headers.get("Content-Length", 0))
            try:
                want = json.loads(self.rfile.read(n)).get("labels", [])
            except (ValueError, json.JSONDecodeError):
                want = []
            self._send_json({"started": start_model_downloads(want)})
            return
        if self.path == "/api/model/update":
            # Update models (6b306): replacements download, each old
            # model goes once its replacement is complete; with servers
            # (6b445), each server the card listed gets what it listed
            _n = int(self.headers.get("Content-Length", 0) or 0)
            try:
                _b = json.loads(self.rfile.read(_n)) if _n else {}
            except (ValueError, json.JSONDecodeError):
                _b = {}
            _out = start_model_update()
            _sv = _b.get("servers") if isinstance(_b, dict) else None
            if isinstance(_sv, list):
                _out["servers"] = [
                    dict(server_update_apply(self.ctx, str(x.get("id") or ""), x.get("offer")),
                         id=str(x.get("id") or ""))
                    for x in _sv[:SERVER_MAX] if isinstance(x, dict)]
            self._send_json(_out)
            return
        if self.path == "/api/model/cleanup":
            # run the auto-clean sweep NOW — the checkbox's first act
            # (6b265); the janitor repeats it every 6 hours. force
            # (6b268, the Clean-now button) skips only the pref gate.
            _n = int(self.headers.get("Content-Length", 0) or 0)
            try:
                _b = json.loads(self.rfile.read(_n)) if _n else {}
            except Exception:
                _b = {}
            removed = _auto_cleanup_pass(
                manual=bool(isinstance(_b, dict) and _b.get("force")))
            self._send_json({"removed": removed,
                             "freed_gb": round(sum(
                                 _gb_of(l) for l in removed), 1),
                             "errors": dict(_CLEANUP_LAST_ERRORS)})
            return
        if self.path == "/api/model/remove":
            # REMOVE A MODEL (6b257, per Patrick's Manage flow). Ready
            # models only — a downloading one has a live writer thread
            # and no cancel machinery, and rmtree under it resurrects
            # partial state. MLX: stop the engine, then delete EXACTLY
            # the label's own HF cache dir pair, derived from the
            # vetted MLX_REPOS constant — never a glob, never the
            # shared hub/ parent (it may hold models we don't own).
            # Ollama: NEVER touch ~/.ollama on disk — blobs are
            # content-addressed and shared across tags; ask the daemon.
            n = int(self.headers.get("Content-Length", 0) or 0)
            try:
                _b = json.loads(self.rfile.read(n)) if n else {}
                want = (_b.get("labels", [])
                        if isinstance(_b, dict) else [])
            except (ValueError, json.JSONDecodeError):
                want = []
            removed, errors = _remove_models(
                [str(x) for x in want][:20])
            self._send_json({"removed": removed,
                             "freed_gb": round(sum(
                                 _gb_of(l) for l in removed), 1),
                             "errors": errors})
            return
        if self.path in ("/api/bench/start", "/api/bench/stop",
                         "/api/bench/skip", "/api/bench/cloud-plan"):
            # the hardware benchmark (6b331). A start is refused (409)
            # while an answer is being written or a run is going
            n = int(self.headers.get("Content-Length", 0) or 0)
            try:
                _bd = json.loads(self.rfile.read(n)) if n else {}
            except (ValueError, json.JSONDecodeError):
                _bd = {}
            _bd = _bd if isinstance(_bd, dict) else {}
            if self.path == "/api/bench/stop":
                self._send_json({"ok": True, "stopped": bench_stop()})
                return
            if self.path == "/api/bench/skip":
                self._send_json({"ok": True, "skipped": bench_skip()})
                return
            if self.path == "/api/bench/cloud-plan":
                # (6b341) what a cloud run would call, and the one-use
                # confirmation for it: nothing is sent to a provider here
                _bp = bench_cloud_plan(self.ctx, _bd.get("models"))
                self._send_json(_bp, code=200 if _bp.get("ok") else 400)
                return
            ok, got = bench_start(_bd, self.ctx)
            if ok:
                self._send_json({"ok": True, "id": got["id"]})
            else:
                self._send_json({"err": got}, code=(
                    409 if got in BENCH_BUSY_REASONS + (BENCH_ANSWERING,
                                                         BENCH_DOWNLOADING)
                    else 400))
            return
        if self.path.startswith("/api/import/"):
            self._import_post()              # bring your chats (6b529)
        if self.path == "/api/doc/pdf":
            # A PDF'S TEXT, READ ON THIS COMPUTER (6b546): the page posts the
            # file's bytes, the PDFKit helper reads them page by page, and the
            # text comes back to ride the .md/.txt path (6b522). No name is
            # sent (the page keeps it), nothing is kept, nothing leaves.
            n = int(self.headers.get("Content-Length", 0) or 0)
            if n > DOC_PDF_MAX_BYTES:
                self.close_connection = True       # the body is left unread
                self._send_json({"ok": False, "err": DOC_PDF_BIG}, code=413)
                return
            self._send_json(pdf_extract(self.rfile.read(n) if n > 0 else b""))
            return
        if self.path == "/api/doc/measure":
            # A FILE'S TOKENS AND THE MODEL'S CONTEXT (6b522): what the chip
            # and the warning bar show, for the model of this Mac the turn
            # would run on (doc_local_pick, from the page's own pick). Reads
            # the tokenizer and config from the cache and asks Ollama's
            # /api/show; no engine is loaded and nothing leaves the computer.
            d = self._json_body()
            raw = d.get("docs") if isinstance(d.get("docs"), list) else [d]
            mdocs = [{"name": str(x.get("name") or "file")[:200],
                      "text": x["text"][:DOC_MAX_CHARS]}
                     for x in raw if isinstance(x, dict)
                     and isinstance(x.get("text"), str)][:DOC_MAX_DOCS]
            if not mdocs:
                self._send_json({"err": "Nothing to measure."}, code=400)
                return
            _ms = d.get("models") if isinstance(d.get("models"), list) else None
            _ma = str(d.get("agent") or "")
            label, why = doc_local_pick(str(d.get("tier") or ""), str(d.get("model") or ""),
                                        _ms, _ma, bool(d.get("images")))
            if not label:
                self._send_json({"err": DOC_NO_MODEL, "label": "", "exact": False,
                                 "tokens": sum(-(-len(x["text"]) // DOC_CHARS_PER_TOK)
                                               for x in mdocs)})
                return
            _mh = [{"role": h["role"], "content": str(h.get("content") or "")}
                   for h in (d.get("history") if isinstance(d.get("history"), list) else [])
                   if isinstance(h, dict) and h.get("role") in ("user", "assistant")][-DOC_HISTORY:]
            m = doc_measure(label, mdocs, str(d.get("question") or ""),
                            doc_system_text(user_prefs(self.ctx),
                                            (AGENTS.get(_ma) or {}).get("system", "")
                                            if why == "agent" else ""), _mh)
            m["why"] = why
            self._send_json(m)
            return
        if self.path != "/api/chat":
            self.send_error(404)
            return

        length = int(self.headers.get("Content-Length", 0))
        try:
            req_json = json.loads(self.rfile.read(length))
        except (ValueError, json.JSONDecodeError):
            self.send_error(400)
            return
        # A BENCHMARK OWNS THE ENGINES (6b331): the question is refused
        # before anything is saved, and the page shows the line. Counted
        # from here to the end of the request (_run), so no benchmark
        # starts while this answer is being written. A chat on one model
        # of your own server (6b334) uses none of this computer's engines,
        # so a run of this computer neither turns it away nor waits for it
        # (a run of a server or of the cloud does both, 6b341).
        if not server_only_request(req_json, self.ctx):
            if not bench_hold():
                self._send_json({"err": BENCH_BUSY, "bench": True}, code=409)
                return
            self._bench_held = True
        else:
            # (6b341) a run of a server or of the cloud refuses it too, and
            # counts it so that no such run starts while it is written
            if not bench_hold_remote():
                self._send_json({"err": BENCH_BUSY, "bench": True}, code=409)
                return
            self._bench_srv_held = True

        messages = list(req_json.get("messages", []))
        # THE QUESTION IS SAVED ON ARRIVAL (0b 5.4, 6b322), when the page
        # names its chat: onto the page's own prefix, or into a copy (or
        # a fresh chat, for a deleted one) whose id goes back in
        # X-Chat-Id. The answer follows at the stream's end (_run's
        # finally), or at a quit. Drills and tests name no chat and save
        # nothing (0b Q12).
        _cid = str(req_json.get("chat_id") or "")
        # A TRY AGAIN OR EDIT & RESEND REWINDS HERE, after the benchmark's
        # hold (review of 6b331): the page sent the rewind first, and a
        # question then refused left the saved chat one turn short
        _rw = req_json.get("rewind")
        if (_cid and isinstance(_rw, dict) and _rw.get("op") == "truncate"
                and _rw.get("id") == _cid):
            chat_ops([{"op": "truncate", "id": _cid,
                       "to_len": _rw.get("to_len"),
                       "prefix_hash": _rw.get("prefix_hash")}], self.ctx)
        if _cid:
            _q = messages[-1] if messages else None
            if (not _CHAT_ID.fullmatch(_cid) or not isinstance(_q, dict)
                    or _q.get("role") != "user"):
                self._send_json({"err": "bad chat"}, code=400)
                return
            _al = req_json.get("after_len")
            _ah = req_json.get("after_hash")
            if _al is None:
                _al = len(messages) - 1
                _ah = chat_prefix_hash(messages, _al)
            _landed, _n, _h = chat_append_turn(
                _cid, _al, _ah, [_q], self.ctx,
                prefix=messages[:-1], lane=req_json.get("lane"),
                title=str(_q.get("content") or "")[:48])
            self._turn = {"id": _landed, "n": _n, "h": _h, "wire": [],
                          "base": self.ctx, "searched": False}
            with _turns_lock:
                _turns_live[id(self._turn)] = self._turn
        # pasted images ride beside the text; vision always routes to
        # LLaVA on Ollama (native /api/chat takes raw base64 per message)
        images = [i for i in (req_json.get("images") or [])
                  if isinstance(i, str) and len(i) < 8_000_000][:3]
        # DRAW ON THE PICTURE (6b355): the gate is the request's words and
        # nothing else. When it fires the model reads the page's gridded
        # COPY (same size, same model, same route as the original would
        # have taken) and is told to answer with shapes. A follow-up to
        # marks already drawn ("make the red box bigger") has no picture
        # of its own, so the page's newest one rides as prev_image and is
        # used only if the gate fires; otherwise it is ignored
        _ann = _ann_grid = False
        _ann_q = (str(messages[-1].get("content") or "")
                  if messages and isinstance(messages[-1], dict) else "")
        if images and annotate_wants(_ann_q):
            _ann = True
            _gs = [g for g in (req_json.get("grid_images") or [])
                   if isinstance(g, str) and len(g) < 8_000_000][:3]
            if len(_gs) == len(images):
                images, _ann_grid = _gs, True
        elif (not images and annotate_prev(messages)
              and annotate_edit_wants(_ann_q)):
            _pg, _po = req_json.get("prev_grid"), req_json.get("prev_image")
            _pi = (_pg if isinstance(_pg, str) and len(_pg) < 8_000_000
                   else _po if isinstance(_po, str) and len(_po) < 8_000_000
                   else "")
            if _pi:
                images, _ann, _ann_grid = [_pi], True, _pi is _pg
        if _ann:
            req_json["images"] = images
        model_name = req_json.get("model", "")
        auto_web = req_json.get("auto_web", True)
        # a tier resolves to its own line-up; otherwise honour explicit picks
        tier = req_json.get("tier") or ""
        req_tier = tier               # before a picture resets it (6b308)
        # the effort the person set (6b534); anything else is no effort at all.
        # A server model's reasoning level follows it on this thread (_run
        # clears it for the next request)
        _effort = req_json.get("effort")
        _effort = _effort if _effort in EFFORT_LEVELS else None
        _srv_think.level = effort_think(_effort)
        _srv_think.effort = _effort    # run_council reads it for its reviews
        _srv_think.brief = False       # a greeting's one pass (6b570), settled with the council
        _t_req = time.time()          # the run's clock starts here (6b528)
        _t_first = [0.0]              # when the first word reached the page
        # the usage tap goes in NOW (6b528), before the search and pre-warm
        # threads start, so the query plan's call is counted with the rest;
        # its frames wait in a list until the headers are out
        _tap_q = []
        _tap_sink = [_tap_q.append]
        usage_tap(lambda d: _tap_sink[0](d))
        usage_role("")
        _answered.pop(threading.get_ident(), None)
        # a new question voids the last one's "who answered": the title
        # of a chat answered on this Mac must never go to the cloud. Per
        # chat (6b326, from review): it was per user, so a funnel or a
        # second chat could be titled by another chat's provider
        _title_cid = str((self._turn or {}).get("id") or "")
        _last_cloud.pop((self.ctx.name, _title_cid), None)
        _srv_only_chats.pop((self.ctx.name, _title_cid), None)   # 6b337
        _cloud_only_chats.pop((self.ctx.name, _title_cid), None)  # 6b357
        _doc_chats.pop((self.ctx.name, _title_cid), None)         # 6b522
        for _k in [k for k, v in list(_last_cloud.items())
                   if time.time() - v[1] > 300]:
            _last_cloud.pop(_k, None)
        for _k in [k for k, v in list(_srv_only_chats.items())
                   if time.time() - v[1] > 300]:
            _srv_only_chats.pop(_k, None)
        for _k in [k for k, v in list(_cloud_only_chats.items())
                   if time.time() - v > 300]:
            _cloud_only_chats.pop(_k, None)
        if tier == "Smart":
            tier = "Fast"   # merged tiers (1.20) — old clients still send Smart
        if tier == "Best":
            tier = "Fast"   # Best retired (5.3) — it was Fast in a crown
        if tier == "Power":
            tier = "Pro"    # Pro absorbed Power (5.3)
        # THE MODES' SHOWN NAMES (6b526, 6b534, 6b544 per Patrick): the page says
        # Deep for Vera Rubin, and older pages sent the Greek and the 6b526
        # names; the tiers keep their keys, and a client that sends the name is understood
        if isinstance(tier, str) and tier in MODE_ALIASES \
                and MODE_ALIASES[tier] in TIERS:
            tier = MODE_ALIASES[tier]
        # ANSWER ON THIS MAC INSTEAD (6b570): the key under a server pick that
        # couldn't answer (server_offer) asks the same question once more with
        # here: true. It runs on this computer's strongest model that fits
        # (Fast's own pick, resolve_tier) as a hand pick, and with no cloud
        # (cloud: [], the Advanced "none at all"): the person chose this Mac.
        if req_json.get("here") is True and srv_only_tier(tier):
            _here = resolve_tier("Fast")[:1]
            tier = ""
            model_name = _here[0] if _here else ""
            req_json["models"] = list(_here)
            req_json["cloud"] = []
        # A .MD OR .TXT FILE IS READ ON THIS MAC (6b522, per Patrick): the turn
        # leaves here, after the mode's brand name is read (6b534) and before the tier, the server, the cloud or the web
        # search is looked at, and runs on one local model (_chat_doc)
        _ldocs = doc_request_docs(req_json)
        if _ldocs is not None:
            self._chat_doc(req_json, messages, tier, model_name, images, _ldocs)
            return
        # Cloud Only, or one of its modes or picks (6b440): "cloud:fast",
        # ":think", ":pro", "cloud:m:<provider>"
        _cl_mode, _cl_pid = cloud_tier_parse(tier)
        cloud_only = cloud_only_tier(tier)
        # MAX (6b440): every model; choosing it opens the cloud as Cloud Only does
        _max = bool(TIERS.get(tier, {}).get("max")) if isinstance(tier, str) else False
        _max_bench = cloud_bench() if _max else []
        # VERA RUBIN (6b519): its own loop (run_rubin), dispatched below
        _rubin = bool(TIERS.get(tier, {}).get("rubin")) if isinstance(tier, str) else False
        if cloud_only and _title_cid:
            _cloud_only_chats[(self.ctx.name, _title_cid)] = time.time()
        # ADVANCED overrides (6b248, per Patrick): a custom run names its
        # own cloud voices and its own compositor. cloud=None means "no
        # opinion" (tier rules apply); cloud=[] means explicitly none.
        req_cloud = req_json.get("cloud")
        if isinstance(req_cloud, list):
            req_cloud = [str(x)[:16] for x in req_cloud][:8]
        else:
            req_cloud = None
        req_comp = str(req_json.get("compositor") or "")[:40]
        # A MODE'S OWN COMPOSITOR (6b442): the person's pick in the model menu's
        # pop-out, for a tier only (Advanced names its own, above); run_council
        # checks it at answer time and falls back to the default, saying so
        mode_pen = req_json.get("mode_comp")
        mode_pen = mode_pen[:160] if isinstance(mode_pen, str) and tier else ""
        if server_label(req_comp):
            # run_council has no server compositor (6b337): a server's model
            # drafts, and the merge is this computer's or the cloud's
            req_comp = ""
        # "<SERVER> ONLY" (6b337, per Patrick: "Under the cloud models only,
        # can we add a Olama one only or whatever the server name is in a
        # user's case?"; "single makes more sense"): tier "srv:<id>" is ONE
        # model of that server, the strongest that fits its card, found
        # from this profile's own servers. With nothing to run on, the
        # council is a placeholder label and `_so_fail` says why: no other
        # model ever answers in its place.
        _so_c0, _so_fail, _so_wake = "", "", ""
        _ag_wake = []     # servers asleep that the agent lane wakes after the headers (6b461)
        _ch_wake = []     # the same for Fast, Thinking, Pro and Max (6b465)
        _ch_council0 = None
        # Fast, Thinking or Pro on that server alone (6b426): the mode, and
        # the seats it found there (every one that server's)
        _so_mode, _so_seats = srv_only_mode(tier), []
        server_take_wake_notes()           # none left from an earlier request on this thread (6b346)
        server_take_wake_pending()
        server_quiet_reset()               # nor a quiet-hours note (6b600)
        # a mode's server seats -> what answers in their place (6b339), and
        # how the turn's one seat went ("server", "fallback", "failed")
        _seat_fb = {}
        _seat_res = [""]
        _page_model = model_name       # what the page last had picked by hand
        if tier in TIERS:
            try:
                # Cloud Only never contacts the server (6b339, rules review)
                if not cloud_only:
                    # a sleeping server is woken after the headers, with the step the
                    # page shows, ten seconds and a Skip (6b465); the pictures and the
                    # agents that run their own flow keep the old wake
                    _ag0 = str(req_json.get("agent") or "")
                    if req_json.get("images") or (_ag0 and _ag0 not in _AGENT_ROLE):
                        server_refresh_modes(self.ctx)
                    else:
                        server_refresh_modes(self.ctx, wake=False)
                        if not _ag0:
                            _ch_wake = server_sleepers(self.ctx)
            except (StaleProfile, BrokenPipeError, ConnectionResetError):
                raise
            except Exception:
                pass
            # Max (6b440): every server model, then this computer's that fit and
            # have no server copy; its cloud models are added to the roster below
            _seats = (max_tier_seats(self.ctx) if _max
                      else resolve_tier_seats(tier, self.ctx))
            council = [x["label"] for x in _seats]
            _seat_fb = {x["label"]: x["fb"] for x in _seats if server_label(x["label"])}
            # THE PAGE'S `model` IS NOT THE MODE'S (6b339, final review: the page
            # always sends the model last picked by hand, "Gemma 4 E2B" on a
            # fresh install, beside a tier). Routing on it ran Fast on that model
            # whatever the seats said, never reached a server seat, and warmed
            # its engine on a Mac that should stay quiet. A mode answers from its
            # own seats; the stale pick is the last resort of an empty roster.
            model_name = ""
        elif srv_only_tier(tier):
            try:
                # a sleeping server is woken after the headers, with a status the
                # page shows (6b369); here only the check is made
                _so_lbl, _so_name, _so_why = server_only_resolve(
                    srv_only_id(tier), self.ctx, defer=True)
                _so_wake = server_take_wake_pending()
                _so_seats = (server_mode_resolve(srv_only_id(tier), _so_mode, self.ctx)
                             if _so_lbl and _so_mode else [])
            except (StaleProfile, BrokenPipeError, ConnectionResetError):
                raise
            except Exception:
                _so_lbl, _so_name, _so_why = "", "", (
                    "Couldn\u2019t check your servers.")
                _so_seats = []
            _so_c0 = _so_lbl or ((_so_name or "Your server") + SERVER_SEP
                                 + "unavailable")
            _so_fail = "" if _so_lbl else (
                _so_why or "That server can\u2019t answer right now.")
            council = [_so_c0]
            model_name = _so_c0
            if _so_seats:
                # the mode's seats, all on that server; a picture goes to its
                # reader alone, as in "<name> Only"
                council = _so_seats = _so_seats[:1] if images else _so_seats
                _so_c0 = model_name = council[0]
        else:
            council = [m for m in req_json.get("models", [])
                       if (m in MODEL_ROUTES and SUPPORTED.get(m))
                       or server_pick(m, self.ctx)[0] is not None]
            # a giant on Ollama picked WITH others answers alone (6b314):
            # a council gives each drafter 120 s, and a cold 400 GB load
            # alone takes minutes, so its draft was always abandoned
            # while the load went on holding the machine
            _sg = [m for m in council if slow_giant(m)]
            if _sg and len(council) > 1:
                council = _sg[:1]
        if cloud_only:
            # the line-up IS the bench — and it may legitimately be empty
            # (no keys), which run_cloud_only answers with instructions
            # rather than by quietly falling back to local silicon
            # a mode or a pick seats what its plan says (6b440); plain Cloud
            # Only the whole bench, as always
            _cplan = cloud_mode_plan(_cl_mode, _cl_pid) if _cl_mode else None
            council = [lbl for lbl, _c in cloud_bench()]
            if _cplan is not None:
                council = [lbl for lbl, _c in _cplan["seats"]]
            model_name = council[0] if council else ""
        elif not council and not (_max and _max_bench):   # Max with only cloud keys has none here
            council = [model_name or _page_model]
        # THE MERGER DRAFTS LAST (6b243). The council's local loop leaves
        # the LAST engine resident, and the merge stage wants the biggest
        # Gemma — when Gemma drafted mid-roster the next model's swap
        # evicted it, and the merge RELOADED it from disk: a full engine
        # swap spent purely on ordering. Same models, same merger, same
        # answers — one fewer multi-GB load per council.
        if len(council) > 1 and not model_name:
            council = council_merger_last(council, req_comp, mode_pen)
        _ch_council0 = list(council)    # the roster as the mode resolved it, to tell a hijack (6b465)
        # a tier request has model_name "" here (the page's own is set aside
        # above, 6b339) — the router matches on model_name, and an empty one
        # fell through to the smallest-cached fallback: the header said Gemma
        # while Llama 1B answered (seen live). The resolved council leader IS
        # the model.
        model_name = model_name or (council[0] if council[0:] else "")
        prompt = messages[-1]["content"] if messages else ""
        # TRIAGE FIRST (6b570, per Patrick: "Tests like this should be much more
        # fluent instead of hitting a breaking point"). "hi" on Thinking · Ollama1
        # alone ran the full craft: a 30 s draft, a review and a final writer, 44
        # to 67 s before the first word. A "chat" or "short" turn (turn_triage)
        # goes to the mode's first seat alone, streamed, with no drafts to
        # compare, no review and no merge; a "chat" one is also asked not to
        # reason (_srv_think.brief). Pictures, files, agents, Cloud Only, Max and
        # Deep keep their own runs.
        _triage = turn_triage(prompt)
        _plain_turn = (not images and not req_json.get("docs")
                       and not str(req_json.get("agent") or ""))
        _brief_turn = bool(
            len(council) > 1 and _triage != "full" and _plain_turn
            and not cloud_only and not _max and not _rubin
            and (tier in TIERS or (srv_only_tier(tier) and _so_seats)))
        _srv_think.brief = bool(_triage == "chat" and _plain_turn)
        if _brief_turn:
            council = council[:1]
            model_name = council[0]
            if _so_seats:
                _so_seats = list(council)
                _so_c0 = council[0]
            _ch_council0 = list(council)
        # A PICTURE, NOT PROSE (6b294): "generate an image of a cat" used
        # to get four paragraphs describing a cat. The intent is settled
        # here, before the web search, and answered below with a real image.
        # A FILE, NOT PROSE (6b295). Settled BEFORE the web search, and
        # before the painter: "export this chart as a png" is an export,
        # "draw me a cat" is not. A weak export score always yields to
        # image_intent, so today's painting behaviour is untouched.
        _prior = [m for m in messages[:-1]
                  if m.get("role") == "assistant"
                  and len(str(m.get("content") or "").strip()) > 40]
        export_req = None if images else export_intent(prompt, bool(_prior))
        if export_req and export_req.get("score", 0) < 3:
            export_req = None
        # the picture just made, if there was one — its alt text is the
        # subject, which is what a refinement refines
        _prev_img = _prev_imgf = _prev_vid = _prev_vidf = ""
        for _m in reversed(messages[:-1]):
            if _m.get("role") != "assistant":
                continue
            _c = str(_m.get("content") or "")
            _am = re.search(r"!\[([^\]]*)\]\(/api/image/"
                            r"([\w-]+\.(?:png|jpg|webp))\)", _c)
            if _am:
                _prev_img, _prev_imgf = _am.group(1), _am.group(2)
            _vm = re.search(r"\[\[vid:\{[^}]*\"id\":\"([\w.-]+)\"[^}]*"
                            r"\"t\":\"([^\"]*)\"", _c)
            if _vm:
                _prev_vidf, _prev_vid = _vm.group(1), _vm.group(2)
            break
        # ONE-SHOT OVERRIDES (6b303). Parsed BEFORE any intent runs, and
        # the matched phrases are REMOVED, so "at 4K" never reaches the
        # painter as content and the refinement path sees clean text.
        _skey = "video" if (_prev_vid and not _prev_img) else "image"
        _loose = bool(_prev_img or _prev_vid)
        _pnote = render_note(_skey, _prev_vidf if _skey == "video"
                             else _prev_imgf)
        _ovr, _pclean, _onotes = gen_overrides(prompt, _skey, _loose, _pnote)
        _ptext = _pclean if _ovr else prompt
        vid_subject = video_intent(_ptext) if not images else None
        # A FRESH VIDEO ASKED "AS A GIF" (6b356 gauntlet): the overrides above were
        # read for a picture (nothing earlier to say otherwise), and a picture has
        # no GIF, so the format was dropped and the server filmed an MP4 the person
        # hadn't asked for. A video's own words are read for a video, as the
        # follow-up branch below does
        if vid_subject and _skey != "video":
            _skey = "video"
            _ovr, _pclean, _onotes = gen_overrides(prompt, "video", _loose, {})
            _pnote = {}
        img_subject = (image_intent(_ptext)
                       if not images and not vid_subject else None)
        # a picture that already exists is a search, not a commission
        if img_subject and image_wants_fetch(prompt):
            img_subject = None
        # a short follow-up after a picture renders it again; an override
        # on its own ("double the resolution") IS the whole instruction,
        # so the same subject stands
        if not img_subject and not vid_subject and not images:
            if _prev_img and _TO_MOTION.search(prompt):
                # a still asked to MOVE: film the same subject, and redo
                # the overrides for the video studio ("as a gif" is a real
                # video format; it was rejected as an image one)
                vid_subject = _prev_img
                _skey = "video"
                _ovr, _pclean, _onotes = gen_overrides(prompt, "video",
                                                       True, {})
                _pnote = {}
            elif _prev_img or _prev_vid:
                _prev = _prev_img or _prev_vid
                # 6b304: a message that is ONLY settings ("double the
                # resolution", "make the video longer") carries no content
                # change, so the subject stands exactly. It used to be
                # passed to the refinement surgery AS the user's words,
                # which turned "a dog on a beach" into "a dog on a beach,
                # on a beach".
                if _ovr and not _residual(_pclean):
                    _fu = _prev
                else:
                    _fu = (image_followup(_pclean, _prev,
                                          refine=not srv_only_tier(tier),
                                          server=not cloud_only)
                           if _pclean else None) or (_prev if _ovr else None)
                if _fu:
                    if _prev_img:
                        img_subject = _fu
                    else:
                        vid_subject = _fu
        if export_req and img_subject and export_req["score"] < 5 \
                and export_req["ext"] in ("png", "svg", ""):
            export_req = None            # the painter wins a weak tie
        if export_req:
            img_subject = vid_subject = None
            auto_web = False
        if vid_subject:
            auto_web = False
        if img_subject:
            auto_web = False
        # EDIT THIS PICTURE (6b472): a photo attached to THIS message and a
        # request to change it. Never a marked-up copy (6b355's own lane)
        edit_req = (photo_edit_intent(_ann_q) if images and not _ann
                    and not export_req else None)
        if edit_req:
            auto_web = False

        # a selected AGENT owns the request: its best installed model, its
        # specialist system prompt; Research routes to the research flow
        agent_name = req_json.get("agent") or ""
        if agent_name and srv_only_tier(tier):
            # "<name> Only" runs its one model and nothing else (6b339,
            # per the rules review): an agent is refused, never run here or
            # in the cloud. The page turns the pick off when an agent is
            # chosen, so this is the door for a stale or hand-made request
            _so_fail = ("%s Only can’t run the %s agent. Nothing ran." % (_so_c0.split(SERVER_SEP, 1)[0]
                                      or "Your server", agent_name[:40]))
            agent_name = ""
        ag_system, ag_research, ag_remote = "", False, False
        # NO AUTO WEB SEARCH ON THE AGENT LANES (6b309): search snippets
        # were pasted into the Remote agent's task, where a web page could
        # steer a root shell. An explicit /search still searches.
        if agent_name == "Remote" or (
                agent_name in ("Coding", "Workspace", "Research")
                and not str(prompt).lower().startswith("/search")):
            auto_web = False
        if agent_name and not req_json.get("images"):
            try:
                # only the agents that may use a server ask it (Research and
                # Remote run their own flows, Cloud Only never asks, 6b339)
                if agent_name in _AGENT_ROLE and not cloud_only:
                    # a sleeping server is woken after the headers, with a step
                    # the page shows, ten seconds and a Skip (6b461)
                    server_refresh_modes(self.ctx, wake=False)
                    _ag_wake = server_sleepers(self.ctx)
            except (StaleProfile, BrokenPipeError, ConnectionResetError):
                raise
            except Exception:
                pass
            ag_label, ag, _ag_fb = resolve_agent_seat(agent_name, self.ctx)
            if ag:
                ag_research = bool(ag.get("research"))
                ag_remote = bool(ag.get("remote"))
                ag_system = ag.get("system", "")
                # the guided-task voice rides along on the Code lane
                # (6b250) — that's where the task library lives
                if agent_name in CODE_AGENTS and ag_system:
                    ag_system += TASK_GUIDE
                if ag_label:
                    council = [ag_label]
                    model_name = ag_label
                    _seat_fb = ({ag_label: _ag_fb} if server_label(ag_label)
                                else {})
                    tier = "Research" if ag_research else ""
        # the Remote agent (6b249) resolves its own driver — even with no
        # local model installed, a cloud key can drive it — so it must
        # not fall through the "no council" guard below
        if ag_remote:
            tier = ""

        docs = [d for d in (req_json.get("docs") or [])
                if isinstance(d, dict) and d.get("text")][:2]
        if docs:
            # attached files ARE the context: fold them into the message,
            # keep the search out of the way
            auto_web = False
            block = "\n\n".join(
                "--- FILE: %s ---\n%s" % (str(d.get("name", "file"))[:120],
                                           str(d["text"])[:50000])
                for d in docs)
            vm = dict(messages[-1]) if messages else {"role": "user",
                                                      "content": ""}
            base = str(vm.get("content", "")).strip() \
                or "Summarize the attached file(s) and note anything notable."
            # files first, question last, and an explicit "this is real
            # data" frame: without it the 35B read ZEBRA-42 and then
            # DENIED it existed, treating "secret launch code" as a prank
            vm["content"] = (
                "The user attached the following file(s). Their contents "
                "are real data provided by the user — read them and "
                "answer from them directly and factually.\n\n"
                "ATTACHED FILES:\n" + block +
                "\n\nQUESTION: " + base)
            messages = messages[:-1] + [vm] if messages else [vm]
            prompt = base

        # a picture in a mode, read by the person's server (6b357)
        _vis_srv = None
        if images:
            # vision answers come from the pixels: no web search, no tier
            # council — LLaVA takes the whole request
            _mode_pic = tier in TIERS and not cloud_only
            auto_web = False
            tier = ""
            b64s = [u.split(",", 1)[1] if u.startswith("data:") else u
                    for u in images]
            vm = dict(messages[-1]) if messages else {"role": "user",
                                                      "content": ""}
            if not str(vm.get("content", "")).strip():
                vm["content"] = "Describe this image in useful detail."
            if _ann:
                vm["content"] = annotate_instruction(vm["content"], _ann_grid)
            vm["images"] = b64s
            vm["image_urls"] = images     # media types, for the cloud (6b308)
            messages = messages[:-1] + [vm] if messages else [vm]
            # A PICTURE IN A MODE GOES TO THE SERVER (6b357, Patrick: "only
            # send it to the Mac if the server doesn't have a model that can
            # handle it"): a model of the person's server that fits its card
            # and says it reads pictures takes it as a mode's seat, this
            # computer's vision model behind it until its first word. The
            # cloud still reads it first when cloud power is on, as before;
            # Cloud Only, a pick of the person's and an Advanced council are
            # untouched. The annotate grid (6b355) is already in `images`.
            if _mode_pic:
                try:
                    _vis_srv = server_vision_pick(self.ctx)
                except (StaleProfile, BrokenPipeError, ConnectionResetError):
                    raise
                except Exception:
                    _vis_srv = None
            if _vis_srv is not None:
                _vfb = ("Qwen 3.5 Vision 9B" if model_cached(
                    "Qwen 3.5 Vision 9B", ollama_pulled_tags() or set()) else "")
                council = [_vis_srv["label"]]
                model_name = _vis_srv["label"]
                _seat_fb = {_vis_srv["label"]: _vfb}
            elif _seat_fb:
                # a mode's server seat doesn't read it (6b339): the vision
                # takeover below does, as it always did
                council, model_name, _seat_fb = (
                    ["Qwen 3.5 Vision 9B"], "Qwen 3.5 Vision 9B", {})
            # a picture sent to your own server's model stays on that
            # server (review of 6b334): server_answer finds its reader
            if not (len(council) == 1 and not cloud_only
                    and server_label(council[0])):
                council = ["Qwen 3.5 Vision 9B"]
                model_name = "Qwen 3.5 Vision 9B"
            prompt = vm["content"]

        # the model routing is settled by here — resolve it NOW, before
        # the search, so the engine can warm while the network works
        route, route_label = None, None
        # ONE MODEL OF YOUR OWN SERVER (6b334): it answers, whatever Use
        # cloud power says, and a failure is said, never covered by a
        # local or cloud model. A label of a server removed since lands
        # here too, and says so.
        # still "<server> Only" only if nothing (an agent) took the council
        _srv_only = bool(_so_c0) and council == (_so_seats or [_so_c0])
        if not _srv_only:
            _so_fail = ""
        _srv_lbl = (council[0] if len(council) == 1 and not cloud_only
                    and server_label(council[0]) else "")
        if _max and _max_bench:     # Max with cloud models is a council, never one server model (6b440)
            _srv_lbl = ""
        # a mode's own server seat is not an explicit pick (6b339): it may
        # fall back to this computer's copy, and Fast asks the cloud first
        _srv_seat = bool(_srv_lbl) and _srv_lbl in _seat_fb
        if _srv_seat:
            _srv_lbl = ""
        def _resolve_route():
            nonlocal route, route_label
            route, route_label = None, None
            if _srv_lbl:
                route, route_label = (None, None), _srv_lbl
            elif server_label(model_name):
                # a council led by a server model warms its first local one,
                # never a catalog label found inside the server's name
                route_label = next((l for l in council if l in MODEL_ROUTES), None)
                route = MODEL_ROUTES.get(route_label) if route_label else None
            for label, target in ({} if server_label(model_name)
                                  else MODEL_ROUTES).items():
                if label in model_name:
                    route, route_label = target, label
                    break
            if (route is None and not cloud_only
                    and not all(server_label(l) for l in council)):
                # smallest cached model, never a 40 GB bomb (see run_model)
                pulled = ollama_pulled_tags() or set()
                route_label = next((l for l in reversed(MERGE_RANK)
                                    if model_cached(l, pulled)), None)
                route = MODEL_ROUTES.get(route_label, (None, None))
            if route is None:
                route = (None, None)     # Cloud Only: there is no local route
        _resolve_route()      # (again after a server woke, 6b465)

        # PRE-WARM IN PARALLEL WITH THE SEARCH (6b243). This used to run
        # serially AFTER the search and BEFORE the headers: search 5-20s
        # of network, then up to 180s of engine load, then the first
        # byte. The two waits are on different resources — disk and
        # network — so they now overlap, and the headers go out
        # immediately, which matters twice over: the heartbeat that
        # keeps Cloudflare from dropping a silent stream only starts
        # AFTER the headers, so the old blocking load sat in exactly
        # the silent window the heartbeat exists to cover. run_model
        # takes _engine_lock before its own ensure, so if the warm-up
        # is still in flight the first draft simply waits on the lock —
        # the same wait as before, minus everything it used to shadow.
        # 6b304: only warm a text model for a chat that will USE one. An
        # export of the previous answer, a picture, a video, or a cloud-
        # only tier never calls run_model — so the engine loaded, sat
        # beside FLUX or Wan in unified memory, and, because run_model is
        # the only thing that stamps _mlx_last_use, the janitor (which
        # skips a zero stamp) never released it. The warm-up now stamps
        # the clock itself, so anything it loads is reclaimable.
        _no_text_model = (cloud_only or img_subject or vid_subject or edit_req
                          or (export_req and export_req.get("lane")
                              == "retro"))
        def _start_prewarm():
            if route[0] == "mlx" and route_label and not _no_text_model:
                def _prewarm(_lbl=route_label):
                    global _mlx_last_use
                    with _engine_lock:
                        ensure_mlx_engine(_lbl)
                        _mlx_last_use = time.time()
                ctx_thread(target=_prewarm, daemon=True).start()
        # a server being woken for this question may answer it: this computer's
        # engine is warmed only when that fails (6b461)
        # (the same for a mode: only a roster the mode resolved itself is
        # re-seated after a wake, so a picture, a pick or an agent that took
        # the council leaves the sleeper alone, 6b465)
        # (and a picture or a video wakes only a server that can make it, in
        # server_make, 6b482)
        if _ch_wake and (tier not in TIERS or cloud_only or _srv_only or _ag_wake
                         or _ch_council0 is None or council != _ch_council0
                         or img_subject or vid_subject):
            _ch_wake = []
        if not (_ag_wake or _ch_wake):
            _start_prewarm()

        # LINKS PASTED INTO THE MESSAGE ARE READ, NOT SEARCHED (6b423, per
        # Patrick: "I just sent a request to review some Airbnbs that I
        # found in Brazil. It came back with a whole bunch of random ones in
        # Colorado"). The pages themselves are the source, so the web search
        # of the message's words is skipped (it is what found the junk).
        # Never for the Remote agent (6b309: no web text in its task) nor
        # where the web is off (the agent lanes, files, pictures, exports);
        # an explicit /search still searches.
        _lk_urls = (pasted_links(str(prompt))
                    if (auto_web and not ag_remote
                        and not str(prompt).lower().startswith("/search"))
                    else [])
        _links, _links_n = [], 0
        # "/search …" forces a lookup; otherwise auto-search decides.
        bookish = False
        placey = False
        _ground = None           # the grounded search (6b514), finished after the headers
        try:
            _oai_note = other_ai_note(strip_greeting(prompt)) if auto_web else ""
        except Exception:
            _oai_note = ""
        _think_tail, _clock_line = "", ""
        # the Remote agent never gets web text in its task, not even on
        # /search: a page could steer a root shell (6b309, review)
        query, forced = None, (prompt.lower().startswith("/search")
                               and not ag_remote)
        if forced:
            query = prompt[7:].strip()
        elif _lk_urls:
            pass                     # read below, after the search block
        elif (auto_web and needs_search(prompt)
              and not TIERS.get(tier, {}).get("research")):
            # the greeting is chat, not query — "Yo is abes open" once
            # produced an answer about a place called "Yo is Abe's"
            query = strip_greeting(prompt) or prompt.strip()
            # "i meant whats a good spot…" — the correction is for the
            # reader, not the search engine, and it dragged the results
            # off to Virginia Beach and Bodrum (measured, 6b240)
            query = _PREAMBLE_RX.sub("", query, count=1).strip() or query
            # FOLLOW-UP THREADING: "is it open tomorrow" names no place —
            # borrow the entity from the previous searched turn so the
            # conversation keeps its thread. A PLACE question threads too
            # even when it isn't "thin": "any bars or clubs open" names
            # venues, so _entity_thin says it has a subject — but it has
            # no LOCATION, and a place search without one is worthless.
            if _entity_thin(query) or _VENUE_RX.search(query):
                prev = _thread_terms(messages, avoid=query)
                if prev:
                    query = prev + " " + query
        elif (auto_web and not TIERS.get(tier, {}).get("research")):
            # didn't trigger search on its own — but a short lean-on-the-
            # last-turn message ("what about saturday?") inherits the
            # previous entity and searches WITH it
            p2 = strip_greeting(prompt)
            p2 = _PREAMBLE_RX.sub("", p2, count=1).strip() or p2
            if p2 and len(p2.split()) <= 10 and _FOLLOWUP_RX.search(p2):
                prev = _thread_terms(messages, avoid=p2)
                if prev:
                    query = prev + " " + p2
        # A FOLLOW-UP CARRIES ITS EVIDENCE (6b518, per Patrick). Round 1's
        # follow-ups scored 1.7: "explain more" and "pick one and price it"
        # ran with no sources at all, and the writer invented what Claude had
        # said. When the person's previous turn was grounded, this turn reads
        # that evidence (numbered as before) and searches only for what it
        # adds; a follow-up that adds nothing searches nothing.
        _g_prior, _g_reuse = None, False
        if (auto_web and not forced and not _lk_urls and not ag_remote
                and not TIERS.get(tier, {}).get("research")):
            try:
                _g_prior = ground_prior(messages)
            except Exception:
                _g_prior = None
            if _g_prior is not None:
                p3 = strip_greeting(prompt)
                p3 = _PREAMBLE_RX.sub("", p3, count=1).strip() or p3
                _fu_new = followup_new_terms(p3)
                if not query:
                    # the earlier question's words ride this one's parts
                    # (Grounding.topic), so the query is the follow-up itself
                    query = p3 or prompt.strip()
                    _g_reuse = not _fu_new
                elif not _fu_new:
                    _g_reuse = True

        if query:
            _tl_search.rows = []   # keep-alive reuses threads — no stale rows
            _tl_search.osm = []    # ditto: last question's venues must go
            _tl_search.photos = []
            _tl_search.geo = None
            _tl_search.locq = ""
            # the clock for this request: the home area's for any
            # local-intent ask (6b275), the venue's once one geocodes,
            # the host's otherwise
            # the home area's clock frames EVERY request when it is
            # set (6b281): "today" and "tonight" belong to the user's
            # life, not the host machine's — a geocoded venue still
            # overrides it below
            _tl_search.tz, _tl_search.tz_place = _home_tz()
            snippets = None
            is_weather = bool(re.search(
                r"\bweather\b|\bforecast\b|\btemperature\b", query, re.I))
            if is_weather:
                _tl_search.weather_src = None
                snippets = weather_snippets(query)
                # the feed is a SOURCE (6b270): the chip shows, the
                # drill logs sources_n=1, and a stale reading is
                # traceable instead of "zero sources, 87°F"
                if snippets is not None and getattr(
                        _tl_search, "weather_src", None):
                    _tl_search.rows = [_tl_search.weather_src]
            if snippets is not None:
                # data answers need the DATA: a 3B given real degrees once
                # replied "warm the cockles" with no numbers at all
                messages[-1] = {
                    "role": "user",
                    "content": (
                        "Answer using ONLY the live data below. Begin "
                        "your reply with the current temperature and "
                        "conditions (e.g. \'It\'s 74\u00b0F and clear "
                        "right now\'), then wind and the forecast days. "
                        "Never omit the temperature. Use the data's own "
                        "sky word — never 'sunny' between dusk and dawn "
                        "— and never call a number 'sticky', 'dry' or "
                        "'unusual' unless the data says so.\n"
                        f"{snippets}\n\nQUESTION: {query}"
                    ),
                }
            else:
                # the venue words count too (6b237): asking for "late
                # night restaurants in 11221" wants the map and the pins
                # just as much as asking whether one is "open" does —
                # gating only on hours/open/address sent exactly the
                # queries the places module exists for down the plain
                # web-search path instead
                # A VENUE LOOKUP IS SHORT (6b260, seen live): a sixty-word
                # message about a friend, money and maybe-booking a hotel
                # contains "hotel" and "book" — and got shredded into a
                # fake venue name ("Challenging Tokyo-Haneda Airport
                # Should Be Grabbing Wifi Needed Sitting Down in Som")
                # and answered with the not-found script. Real lookups
                # ("is lucali open tonight", "late night restaurants in
                # 11221") are short; long prose goes to plain search,
                # which handles it fine.
                placey = (len(query.split()) <= 14
                          and bool(re.search(
                    r"\bhours\b|\bopen\b|\bclosed?\b|\bphone\b|"
                    r"\baddress\b|\bmenu\b|\breservation", query, re.I)
                    or _VENUE_RX.search(query)))
                matched = True
                bookish = bool(_BOOKING_RX.search(query.lower())
                               or _ASKY_RX.search(query))
                # the body override: "is wine good FOR YOU" is a health
                # question that happens to name a consumable — no venue
                # search, no [[PLACES]], no map (6b247, seen live)
                if _NOT_PLACEY_RX.search(query):
                    placey = bookish = False
                if placey:
                    snippets, matched = place_search(query)
                    pt_ = _place_terms(query).split()
                    _tl_search.locq = pt_[-1] if len(pt_) > 1 else ""
                    # REAL HOURS, ON TOP OF THE SNIPPETS (6b242). Overpass
                    # knows what is open right now; snippets almost never
                    # do. Placed FIRST in the context and labelled as the
                    # authority, because a blog post's stale hours must
                    # not outrank a structured tag. Additive only — an
                    # empty result changes nothing.
                    # THE LOCALITY IS WHAT'S LEFT AFTER THE CATEGORY
                    # (6b244). This took the last two words, which for a
                    # short question is the category itself: "whats some
                    # good bbq in bushwick?" reduces to "bbq bushwick",
                    # and geocoding THAT returns None — so no venues, no
                    # pins and no map, on a question that names a
                    # neighbourhood outright. Strip the venue words and
                    # the relative-time words; the remainder is the place.
                    _terms = _place_terms(query)
                    _loc = " ".join(w for w in _terms.split()
                                    if not _VENUE_RX.search(w)
                                    and w not in _REL_WORDS)[:60]
                    _osm = osm_places(_terms, _loc) if _loc else []
                    if _osm:
                        _tl_search.osm = _osm
                        _open = [p for p in _osm if p.get("open")]
                        if len(_osm) <= 3 and not _open:
                            _tl_search.thin_closed = len(_osm)
                        else:
                            _tl_search.thin_closed = 0
                        _lines = "\n".join(
                            "- %s%s — %s%s" % (
                                p["n"], (" (" + p["d"] + ")") if p["d"] else "",
                                p["h"] or "hours not published",
                                "  [OPEN NOW]" if p.get("open") else "")
                            for p in _osm)
                        snippets = (
                            "VENUE DATA (OpenStreetMap, authoritative for "
                            "hours — prefer these over any hours mentioned "
                            "in the web snippets below; %d of %d are open "
                            "right now):\n%s\n"
                            "This list covers NEARBY venues, not the "
                            "whole neighbourhood: a nothing-is-open "
                            "verdict must say it covers the listed "
                            "spots and add ONE call-ahead clause.\n"
                            "NAME VENUES ONLY FROM THIS VENUE DATA. The "
                            "web snippets below may describe same-named "
                            "places in OTHER CITIES (a Williamsburg "
                            "cafe in Virginia answered a Brooklyn "
                            "question — seen live); snippets give "
                            "colour and context, never venue names.\n\n%s"
                            % (len(_open), len(_osm), _lines, snippets or ""))
                        matched = True
                    # closure evidence rides above the venue data, once
                    # the OSM rows and web sources are both known (6b278)
                    snippets = closure_notices(query) + (snippets or "")
                    if matched:
                        # a pin only counts when the geocoder actually
                        # landed in the right neighborhood — "food
                        # bushwick" once pinned Edinburgh (seen live)
                        # geocode the LOCALITY, not the whole phrase —
                        # "bbq bushwick" resolves to nothing, which is
                        # why the map card vanished too (6b244)
                        g_ = _geocode(_loc or _place_terms(query))
                        lt_ = _tl_search.locq.lower()
                        if g_ and (not lt_ or lt_ in
                                   (g_.get("full") or "").lower()):
                            _tl_search.geo = g_
                elif bookish:
                    pt_ = _place_terms(query).split()
                    _tl_search.locq = pt_[-1] if len(pt_) > 1 else ""
                    # search the SENTENCE with the ask, not the whole
                    # message — "I'm chronically burned out. can you
                    # arrange a retreat in southeast asia" searched whole
                    # surfaced burnout clinics in Switzerland, not Bali
                    srch = next((s for s in re.split(r"(?<=[.?!])\s+", query)
                                 if _BOOKING_RX.search(s.lower())
                                 or _ASKY_RX.search(s)), query)
                    snippets = run_search_deep(srch, pages=3)
                elif _LISTINGS_RX.search(query):
                    # the listing beats the open web (6b278): a
                    # site-restricted pass first, the general pass
                    # for colour
                    snippets = (run_search(
                        query + " site:rottentomatoes.com OR "
                        "site:fandango.com OR site:boxofficemojo.com")
                        + "\n" + run_search(query))
                else:
                    # GROUNDED SEARCH (6b514, per Patrick): planned queries,
                    # filtered sources, pages read, numbered evidence. It
                    # runs beside the engine pre-warm and finishes after the
                    # headers (below, where step() exists), so the page sees
                    # each phase; the turn holds a placeholder until then.
                    def _ground_planner(ask_text, _lbl=route_label, _co=cloud_only,
                                        _ctx=self.ctx, _cn=tuple(council or ())):
                        """The fastest free model's query plan: a model of
                        this council's own server first (6b518), then the
                        person's server for the modes (6b357), a cloud
                        utility model when cloud power is on, this
                        computer's engine when it is already up and idle;
                        '' when none answers in time."""
                        ask = [{"role": "user", "content": ask_text}]
                        usage_role("search")     # the page's ledger row (6b528)
                        if not _co:
                            # THE PLAN NEVER LANDED (6b518): 28 of 28 bench
                            # plans had model=[]. Not the deadline: the
                            # server pick came back None at once, because a
                            # mode on one server alone ("Ollama1 Only, Thinking",
                            # the owner's setup) seats that server's models
                            # outside the modes' candidates, so
                            # server_side_pick had nothing to choose from. The
                            # plan now runs on the council's own non-reasoning
                            # seat (the critic's model: the one the last fact-
                            # check left on the card, so nothing new loads);
                            # a reasoning model would spend its 160 tokens
                            # thinking and write no query.
                            _seat = ground_plan_seat(_cn)
                            if _seat:
                                _t0, parts, _err = time.time(), [], ""
                                try:
                                    with server_first_deadline(GROUND_PLAN_S + 4), \
                                            server_ctx_sticky():
                                        server_stream(_seat, ask, parts.append, 160)
                                except (StaleProfile, BrokenPipeError, ConnectionResetError):
                                    raise
                                except Exception as _e:
                                    _err = repr(_e)[:160]
                                out = strip_think("".join(parts))
                                if DEV_HOME:
                                    print("ground-plan: seat=%r secs=%.2f out=%r%s" % (
                                        _seat, time.time() - _t0, out[:200],
                                        (" err=" + _err) if _err else ""),
                                        file=sys.stderr, flush=True)
                                if out:
                                    return out
                            try:
                                out = server_side_text(ask, _ctx, max_tokens=120)
                            except Exception:
                                out = None
                            if out:
                                return out
                        try:
                            for _c in gate_ladder(fast_cloud_ladder(utility=True),
                                                  None, _co):
                                out = cloud_text(_c, ask, timeout=6,
                                                 max_tokens=120, quiet=True)
                                if out:
                                    return out
                        except Exception:
                            pass
                        try:
                            _k, _p = MODEL_ROUTES.get(_lbl, (None, None))
                            if (_k == "mlx" and not _co and _engine_up(_p)
                                    and _engine_lock.acquire(blocking=False)):
                                _engine_lock.release()   # nobody is loading
                                parts = []
                                run_model(_lbl, ask, parts.append)
                                return "".join(parts)
                        except Exception:
                            pass
                        return ""
                    _ground = ground_start(
                        query, planner=_ground_planner,
                        want_photos=bool(_WANTS_IMAGES.search(prompt)),
                        prior=_g_prior, search=not _g_reuse,
                        turn_key=_ground_key(prompt))
                    snippets = GROUND_PENDING
                # ASKED FOR PICTURES, SO FETCH SOME (6b244, per Patrick).
                # Photos were only ever harvested on the PLACE path —
                # run_search reads snippets and never opens a page, so a
                # question like "do you have any photos?" got sources
                # from pexels and an answer apologising that it cannot
                # show images. Gated on actually asking, because opening
                # pages costs seconds and most questions don't want them.
                # NB: no step() here — the search phase runs BEFORE the
                # response opens (the X-Web-Search header depends on it),
                # and step() is defined further down with the writer. It
                # is an UnboundLocalError up here, and a hard 500 on
                # every image question until it was caught.
                if _WANTS_IMAGES.search(prompt) and not getattr(
                        _tl_search, "photos", None):
                    _ph = []
                    # _stash_sources rewrites rows as {"t","u"} — reading
                    # "href" here gave None every time, so the harvest
                    # ran with an empty URL list and quietly found
                    # nothing. The mechanism was never at fault.
                    _urls = [(r.get("u") or "")
                             for r in (getattr(_tl_search, "rows", []) or [])
                             if (r.get("u") or "").startswith("http")][:3]
                    try:
                        _fetch_pages(_urls, meta=_ph)
                    except Exception:
                        pass
                    _tl_search.photos = _ph
                    if _ph:
                        # and TELL the model, or it apologises for not
                        # being able to show what is already on screen
                        messages[-1] = dict(messages[-1])
                        messages[-1]["content"] = (
                            str(messages[-1].get("content", ""))
                            + "\n\n[The interface is displaying %d relevant "
                              "photo(s) from the sources directly beneath "
                              "your answer. Do NOT say you cannot show "
                              "images — describe what they show and carry "
                              "on.]" % len(_ph))
                if placey and matched:
                    # the closed-day check is MECHANICAL, not left to the
                    # model: whether "Closed on Tuesday" survives into a
                    # given run's snippets — and whether a 4-bit model
                    # notices it — is a coin flip (Lucali came back "open
                    # tonight 5-11pm" on a Tuesday, twice in three runs)
                    wd = time.strftime("%A", _venue_now())
                    closed_hit = re.search(
                        r"(close[sd]?[^.\n]{0,40}\b%s|\b%s[^.\n]{0,15}"
                        r"close[sd]?)" % (wd[:3], wd[:3]), snippets, re.I)
                    warn = ("READ FIRST: today is %s, and a source above "
                            "says it is CLOSED on %ss. Unless a source "
                            "clearly contradicts that, your first "
                            "sentence must be exactly: \"Closed tonight "
                            "— it's %s, and they're closed %ss.\" Then "
                            "continue the shape below.\n"
                            % (wd, wd, wd, wd)) if closed_hit else (
                            "Today is %s — never name any other weekday "
                            "as today.\n" % wd)
                    strictness = warn + (
                        "The data above is your ONLY source for hours, "
                        "phone numbers, addresses and prices — never "
                        "estimate or invent one. Write ENTIRELY in your "
                        "own words: pasting any line, menu or form text "
                        "from the data is a failure.\n"
                        "ANSWER SHAPE, exactly:\n"
                        "1. First sentence = the verdict, and it must NAME "
                        "today's weekday ('Closed tonight — it's Tuesday, "
                        "and they close Tuesdays' / 'Open tonight, Friday "
                        "hours are 5-11pm'). Before writing it, check "
                        "every source for a closed-day that matches "
                        "today's weekday — a listed 'Closed Monday and "
                        "Tuesday' beats a generic hours range.\n"
                        "2. Then at most three options as short bold-name "
                        "lines: **Name** — what it is — tonight's hours.\n"
                        # 6b304: this '+' was missing since 6b281, so the
                        # literal above was CALLED with the tuple below and
                        # every venue-hours question raised TypeError before
                        # headers were sent — the client saw a dropped line
                        + (("THIN LIST: only %d venue(s) could be checked "
                          "and none is open — say 'of the %d I could "
                          "check' in those words, never 'nothing is "
                          "open', and name the late-night or early "
                          "category (24-hour pharmacy chain, diner, "
                          "bodega) as the honest move.\n"
                          % (getattr(_tl_search, "thin_closed", 0),
                             getattr(_tl_search, "thin_closed", 0)))
                         if getattr(_tl_search, "thin_closed", 0) else "") +
                        "CLOSED MEANS CLOSED: if any source marks a "
                        "place permanently closed, it is closed — its "
                        "own website is the LAST source to trust, "
                        "never the reason to recommend it. Hours or "
                        "prices that come ONLY from a venue's own "
                        "website are 'listed, unverified' — say so in "
                        "those words, never 'open now' or 'opens at "
                        "noon today' on that alone (6b278: a site "
                        "from 2015 was quoted as today's hours). And "
                        "the data is a sample, not the town: never say "
                        "'nothing is open' from a handful of rows — "
                        "say what's open among what was found and "
                        "name the late-night or early category that "
                        "usually is (a 24-hour pharmacy chain, a "
                        "diner, a bodega) as the honest fallback.\n"
                        "3. When everything named is CLOSED at this "
                        "hour, still commit: name ONE real place "
                        "likely open right now (a 24-hour spot from "
                        "the data or one you know is long-standing, "
                        "flagged honestly) or state the earliest "
                        "reopening time — 'try a delivery app' or "
                        "'a 24-hour bodega' with no name is a "
                        "non-answer. A 'best X' ask still gets a "
                        "best (and one runner-up) even when the "
                        "verdict is 'closed until noon'.\n"
                        "4. One practical heads-up if the data supports one. "
                        "Nothing else: no 'best bet is to check', no filler, "
                        "under 120 words. If the data truly lacks the answer, "
                        "say that in ONE sentence and stop.\n"
                        "When you state hours, a price or a phone number, "
                        "credit the source — 'per their site', 'per "
                        "OpenStreetMap' — ONCE, at its first use; "
                        "stamping every line reads as pipeline residue.\n"
                        "THEN, as the very last line, write [[PLACES]] "
                        "followed by a compact JSON array of the real "
                        "places you named — like [[PLACES]] [{\"n\":"
                        "\"Lucali\",\"d\":\"thin-crust pizza, BYOB\","
                        "\"h\":\"5-11pm\"}] — max 4, only places from "
                        "the data, nothing after it.\n")
                elif placey:
                    # nothing in any engine mentions the place — a flat
                    # "couldn't find any information" is a dead end for the
                    # user; be a local who's honest AND still helpful.
                    # The first sentence is DICTATED (the code knows the
                    # entity) — asked politely, the model opened with
                    # "Two familiar ones:" on a compliance coin-flip.
                    # last term is the locality, the rest is the name:
                    # "qzxvbn cafe bushwick" -> "Qzxvbn Cafe" in "Bushwick"
                    pt = _place_terms(query).split()
                    _existence = re.match(
                        r"\s*(is|are)\s+there\b|\s*any\b", query, re.I)
                    if _existence or len(pt) > 4:
                        # "is there a supermarket that sells X" is a
                        # CATEGORY question, not a venue named
                        # "Supermarket Sells X" (6b261, the drill
                        # caught the script firing at exactly the old
                        # 6-term boundary) — and no venue is named by
                        # five-plus words of leftover prose either.
                        # Answer it as a question, honestly.
                        strictness = (
                            "The searches found nothing directly "
                            "relevant. Answer from your own knowledge, "
                            "be plain about what you're unsure of, and "
                            "never invent a venue, price or hour. Do "
                            "NOT claim you searched for a place by "
                            "name.\n")
                        pt = []
                    ent = (" ".join(pt[:-1]) or pt[0]).title() if pt \
                        else "that"
                    loc = (" in " + pt[-1].title()) if len(pt) > 1 else ""
                    if pt: strictness = (
                        "IMPORTANT: nothing you found actually mentions "
                        "the place the user asked about. Do not pretend "
                        "it does, and never present other places as if "
                        "they were the answer.\n"
                        "Write EXACTLY this reply:\n"
                        "First sentence, word for word: \"I can't find a "
                        "spot called %s%s — it might go by a different "
                        "name or only live on Instagram or Google "
                        "Maps.\"\n" % (ent, loc) +
                        "Middle, ONLY if one or two genuinely similar "
                        "real places appear in what you found: each as "
                        "'**Name** — what it is'. Otherwise skip the "
                        "middle. Never invent hours, phone numbers or "
                        "addresses.\n"
                        "Last sentence, word for word: \"Got the exact "
                        "spelling or a cross street? I'll take another "
                        "look.\"\n")
                elif bookish:
                    # thin snippets + an eager 4-bit model = invented
                    # sub-programs, participant caps and price tables
                    # dressed as fact (seen live, twice)
                    strictness = (
                        "Name ONLY businesses, programs, prices and "
                        "dates that appear in what you found — never "
                        "add one it doesn't contain, and never invent "
                        "details like group sizes or start dates. Where "
                        "what you found is thin, recommend the honest "
                        "CATEGORY and the listing site to browse (one "
                        "you actually found). Speak as yourself — 'I "
                        "found', 'I can see' — never 'the results', "
                        "'the snippets' or 'the excerpt you shared'; "
                        "the reader never sees those.\n"
                        "Shape: open with ONE human sentence to the "
                        "person in their own register — if they shared "
                        "something personal (burned out, heartbroken), "
                        "meet it in a clause; never open with a heading "
                        "or a listing. Then the real options, honestly "
                        "labeled. Close by asking for the one or two "
                        "details you'd need to narrow it down.\n"
                        "If you named real venues, add as the very last "
                        "line [[PLACES]] followed by compact JSON — "
                        "[{\"n\":\"name\",\"d\":\"five words\","
                        "\"h\":\"hours or ''\"}] — max 4, data only, "
                        "nothing after it.\n")
                elif is_weather:
                    # both weather rungs came back empty — live numbers
                    # exist NOWHERE in this context (6b266, judged: a
                    # sunny 71°F "right now" at 10:30 PM, invented).
                    strictness = (
                        "No live weather data reached you. Do NOT "
                        "state any current temperature, sky condition, "
                        "wind or forecast number — a made-up 'right "
                        "now' is the worst possible answer. One clause "
                        "says the live numbers didn't come through and "
                        "where to glance (a weather app, weather.gov); "
                        "then give only what you truly know — the "
                        "area's seasonal pattern and any planning "
                        "advice the question implies.\n")
                elif _LISTINGS_RX.search(query):
                    # "what movies are playing this week" once answered
                    # with ZERO titles and a homework list of other
                    # websites (6b265, judged 2.2/5). Listings retrieval
                    # is often thin, but the model KNOWS what's in wide
                    # release — the punt is a choice, and it's banned.
                    strictness = (
                        "This is a what's-on question. Sending the "
                        "reader to other sites is failure: never open "
                        "with what you can't see, never hand over a "
                        "list of places to go look instead of an "
                        "answer. Commit — name the actual current "
                        "wide releases or major events you know of "
                        "this month, plus anything the data adds, "
                        "each with a few honest words on what it is "
                        "and who it's for. NAMES ONLY: an item is "
                        "reported under its real proper title or not "
                        "at all — a description the data left in "
                        "place of a title ('the zombie sequel', 'the "
                        "Pacino true-crime project') is not a title; "
                        "drop it and name one you can vouch for. One "
                        "closing clause may say where to confirm local "
                        "times — after the real answer, never instead "
                        "of it.\n")
                else:
                    strictness = ""
                # data FIRST, instructions LAST — an instruction buried
                # before 4KB of scraped pages gets forgotten, and the
                # model answers by pasting the menu (seen live)
                # vocabulary matters: when this block said "results" and
                # "snippets", answers said "the snippets show…" — the
                # model parrots whatever the scaffolding calls things.
                # "What you just found" echoes back as "I found", which
                # is exactly the voice we want.
                messages[-1] = {
                    "role": "user",
                    "content": (
                        "What you just found on the web about "
                        f"'{query}' — the reader can NEVER see this "
                        "block, so restate anything you use:\n"
                        f"{snippets}\n\n"
                        # every searched answer gets today pinned — a
                        # generic search reply opened "Mondays can be
                        # challenging" on a Tuesday (seen live)
                        f"Today is {time.strftime('%A')}.\n"
                        # a burnout-retreat answer once NARRATED the junk
                        # the engine happened to return ("Mental Floss
                        # mentions Generation Beta") — junk is invisible
                        "Any result that does not help answer is noise: "
                        "never mention, summarize or apologize for an "
                        "off-topic result. The reader must never learn "
                        "what the search happened to return.\n"
                        # 6b266, judged 3.2: the L-train answer OPENED
                        # with "I can't pull live MTA service data from
                        # here" and spent 200 words on how-to-check
                        "Never describe your own data access — 'I "
                        "can't pull live data', 'the data I have', "
                        "'from here' are banned, and so are the "
                        "softened forms: 'I can't confirm', 'nothing "
                        "I found verifies', 'no hours were listed in "
                        "what I found'. When something live is "
                        "missing, ONE clause says what to check "
                        "and where; the rest answers from what you "
                        "actually know. Never claim lived experience "
                        "or memories of a place ('I've seen it in "
                        "enough corner stores') — you have none.\n"
                        # 6b275, judged: eggs "$3-4 right now" from
                        # memory against a BLS $2.28 released two days
                        # earlier; a movie slate from memory with
                        # "(announced date)" hedges
                        "A CURRENT PRICE, CURRENT LINEUP or WHAT'S-"
                        "PLAYING fact comes from the data WITH its "
                        "date and source in the same sentence ('$2.28 "
                        "a dozen — BLS, August'); if the data holds no "
                        "dated figure, say so in one clause and label "
                        "anything from memory with the month it was "
                        "true — never 'right now' from memory.\n"
                        f"{strictness}"
                        f"PROMPT: {query}"
                    ),
                }

        # THE PASTED PAGES (6b423): read side by side, each labelled Listing
        # N with its link, and the model told to keep to them. This is the
        # message every mode drafts from (Fast, Thinking, Pro, a server
        # seat, the cloud). The sources row is the links themselves, the
        # photos each page's own og:image; none read at all is answered
        # after the headers without a model.
        if _lk_urls:
            _links = read_links(_lk_urls)
            _links_n = sum(1 for r in _links if r.get("ok"))
            _tl_search.rows = [{"t": (r.get("title") or r["url"])[:80],
                                "u": r["url"]} for r in _links]
            _tl_search.photos = [r["image"] for r in _links
                                 if r.get("ok") and r.get("image")]
            _tl_search.osm, _tl_search.geo, _tl_search.locq = [], None, ""
            if _links_n and messages:
                messages[-1] = dict(messages[-1])
                messages[-1]["content"] = links_context(_links, str(prompt))

        # local models have no clock — without this "today" is meaningless
        today = strftime_np("%A, %B %-d, %Y")
        dated_system = dict(SYSTEM_PROMPT)
        if export_req and export_req["lane"] == "draft":
            _xk = EXPORT_KIND.get(export_req["ext"] or "md", ("text", "file"))
            dated_system = dict(dated_system)
            dated_system["content"] = dated_system.get("content", "") + (
                "\n\nTHIS ANSWER BECOMES A %s. Write the CONTENT of that "
                "file and nothing else \u2014 no preamble, no 'here is', no "
                "closing offer. %s"
                % (_xk[1].upper(),
                   {"table": "Put the data in ONE markdown pipe table with a "
                             "header row. Numbers bare, no currency symbols "
                             "inside the cells. A running total may be an "
                             "Excel formula like =SUM(B2:B13).",
                    "doc": "Use markdown headings, short paragraphs and "
                           "tables. It will be typeset, so structure it.",
                    "slides": "One '## Heading' per slide, then 3 to 6 "
                              "bullet lines under it.",
                    "calendar": "One line per event, each starting with an "
                                "ISO date (2026-03-14) and a 24-hour time "
                                "where there is one.",
                    "cards": "One 'Q: ...' line then an 'A: ...' line per "
                             "card, nothing else.",
                    "text": "Put the whole file in ONE fenced code block "
                            "tagged with its language.",
                    "archive": "One fenced code block per file, each with a "
                               "filename on the line directly above it.",
                    "image": ""}.get(_xk[0], "")))
        if ag_system:
            dated_system["content"] = ag_system
        # THE HOUR, NOT THE MINUTE (6b531, per Patrick: "faster feels
        # smarter"). The engine's prompt cache reuses a prompt only from
        # its first token: measured on Gemma 4 26B, a 5.5K-token chat whose
        # system prompt differed by one minute re-read everything (8.3 s to
        # the first token, 0 cached) where the same system prompt re-read
        # only the new turn (2.3 s, 4,096 cached). A minute stamp here made
        # every turn after the first a cold read. The hour keeps the rule
        # below (weekday, date, hour) and changes the prompt once an hour;
        # the exact minute still rides the question for searched answers
        # (6b264's clock line), the one place no model ignores.
        _now_local = _venue_stamp("%A, %B %-d, %Y, around %-I%p")
        dated_system["content"] += (
            "\n\nRIGHT NOW for the user it is " + _now_local +
            " (their local time). Every 'today', 'tonight' and 'right "
            "now' in your answer means THIS moment — never assert a "
            "different weekday, date or hour, even if your own clock "
            "disagrees: yours may be in another timezone; the user's "
            "is not.")
        if tier == "Thinking" and messages:
            messages[-1] = dict(messages[-1])
            _think_tail = "\n\n" + THINK_HINT
            messages[-1]["content"] += _think_tail
        # WORKSPACE: the chosen agent reads the user's own folder — the
        # files ride under the question so they can't be mistaken for
        # instructions
        if (agent_name and AGENTS.get(agent_name, {}).get("workspace")
                and messages):
            wsx = workspace_context(prompt)
            if wsx:
                messages[-1] = dict(messages[-1])
                messages[-1]["content"] = (
                    wsx + "\n\nQUESTION: " + str(messages[-1]["content"]))
        user_base = self.ctx      # whose memory/persona this is
        mem = memory_text(user_base)
        if mem:
            dated_system["content"] += (
                "\n\nFrom earlier conversations you remember these facts "
                "about the user:\n" + mem +
                "\nNever OPEN an answer with a remembered fact — "
                "even a load-bearing one enters after the substance "
                "starts, or it reads as surveillance. "
                "Use a remembered fact ONLY when it changes the "
                "advice — a protein target doesn't care what borough "
                "they live in. Never decorate an answer with their "
                "job, kids, dog or neighbourhood to show you know "
                "them, never build the answer on an ASSUMED situation "
                "(give both branches plainly instead), and never use "
                "a remembered fact in a closing line. A remembered "
                "fact is either KNOWN — state it plainly, once, when "
                "it changes the advice — or it is left out entirely; "
                "never hedge one into a guess ('if you're at a desk "
                "job', 'you're likely hunched over a laptop'), and "
                "never guess a job, habit or household the facts "
                "don't contain. At most ONE remembered fact per "
                "answer, and only when it changes the advice; a "
                "framing the user states in the question ('like I'm "
                "not an engineer') overrides anything remembered.")
        # standing preferences the user wrote themselves (About panel) — they
        # outrank remembered facts, which are extracted guesses
        _prefs = user_prefs(user_base)
        user_name = str(_prefs.get("user_name") or "").strip()[:80]
        if user_name:
            dated_system["content"] += (
                "\n\nThe user's name is " + user_name + " — they told "
                "you so themselves (Settings). Address them by name "
                "when it feels natural, never in every reply. If a "
                "remembered fact suggests a different name, this one "
                "wins.")
        persona = (_prefs.get("persona") or "").strip()[:2000]
        if persona:
            dated_system["content"] += (
                "\n\nThe user has set standing instructions for how you "
                "should respond, in their own words:\n\"" + persona + "\"\n"
                "Follow them in every reply without restating them. If the "
                "current message conflicts with them, the message wins.")
        # RESPONSE LENGTH (6b227, per Patrick): a 1-5 dial the user
        # owns. Each rung names a concrete SHAPE — sentences, not
        # adjectives — because "be brief" drifts but "two or three
        # sentences" doesn't. The top rungs authorise depth while
        # explicitly forbidding padding, so nothing rambles to fill
        # space.
        _LEN = {
            1: ("Answer in two or three sentences. Give the direct "
                "answer and the single most useful detail, nothing "
                "more. No headings, no lists, no preamble."),
            2: ("Keep it short — one or two tight paragraphs. Lead "
                "with the answer, add only what genuinely helps."),
            # the default rung carries the SHAPE law (6b271, judged:
            # tables in 5/6 simple answers, H2s in 4/6): a chat answer
            # is prose with bold lead-ins and a list where one earns
            # it — headings, tables and diagram blocks only when the
            # person asked for a document, a comparison or a plan
            3: ("Shape: prose, with bold lead-ins and a numbered or "
                "bulleted list only where steps or options genuinely "
                "need one. No headings, no tables, no code-fenced "
                "diagrams unless the person asked for a document, a "
                "side-by-side comparison or a plan. Say each thing "
                "once — a table that restates the paragraphs above "
                "it is padding. When you commit to durations, counts "
                "or ratios, re-add them before you send: the parts "
                "must sum to the total that was asked for, and one "
                "figure per fact — never 'a few drops' and '1 part "
                "to 2' for the same thing. If you show a formula, "
                "the headline number must satisfy it. A statistic or "
                "ranking is real stable knowledge or it is phrased as "
                "a rough expectation — never invent 'most people "
                "under-eat by 30 g' or 'the #2 mistake'. An 'every', "
                "'only' or 'always' over a product family or a "
                "single test result is narrowed to the cases it is "
                "true for, or hedged in one clause ('every 2015 "
                "MacBook' — the 12-inch stopped a version earlier). "
                "An explain-me ask is still prose: a numbered list is "
                "the ceiling, and a diagram that restates a list is "
                "padding."),
            4: ("Go deep when the question earns it: several "
                "developed paragraphs, with headings or a list where "
                "they genuinely organise the material. Cover the "
                "obvious follow-up. Never pad — every paragraph must "
                "carry new information."),
            5: ("Write a thorough, well-structured treatment — as "
                "long as the material honestly supports, up to "
                "several pages. Use headings and lists to organise "
                "it, work through the angles and the edge cases, and "
                "include concrete examples. Absolutely no padding, "
                "no restating, no filler summaries: if you have said "
                "everything worth saying, stop there."),
        }
        try:
            _lv = int(_prefs.get("length", 3))
        except (TypeError, ValueError):
            _lv = 3
        _lv = max(1, min(5, _lv))
        if _LEN.get(_lv):
            dated_system["content"] += "\n\nLENGTH: " + _LEN[_lv]
        if auto_web and messages:
            # THE CLOCK RIDES THE QUESTION (6b264): the system-prompt
            # binding lost to a Beijing-hosted model's own calendar
            # twice — "Wednesday morning" on a Tuesday evening, an
            # open/closed verdict inverted. The user turn is the one
            # place no model ignores.
            messages[-1] = dict(messages[-1])
            _clock_line = (
                "[for time-sensitive parts: it is %s%s]\n"
                % (_venue_stamp("%A %-I:%M%p"),
                   "" if getattr(_tl_search, "tz", "") else " where I am"))
            messages[-1]["content"] = _clock_line + str(messages[-1]["content"])
        # (6b518) the person's own arithmetic: no search ran, and the writer
        # and the critic are told the figures are premises; a mention of
        # another assistant's unseen reply: the model says it can't see it
        if messages and not _ground and auto_web:
            _extra = [x for x in (
                SC_HINT if self_contained_reasoning(strip_greeting(prompt)) else "",
                _oai_note) if x]
            if _extra:
                messages[-1] = dict(messages[-1])
                messages[-1]["content"] = (str(messages[-1]["content"]) + "\n\n"
                                           + "\n\n".join(_extra))
        full_messages = [dated_system] + messages

        # stream plain text back; the browser reads it progressively
        # (routing + engine pre-warm moved ABOVE the search, 6b243)
        self.send_response(200)
        self.send_header("Content-Type", "text/plain; charset=utf-8")
        self.send_header("Cache-Control", "no-cache")
        self.send_header("X-Accel-Buffering", "no")
        # pasted links count as the web (6b423): the page draws their row
        self.send_header("X-Web-Search", "1" if (query or _links) else "0")
        if self._turn:
            self._turn["searched"] = bool(query or _links)
            self.send_header("X-Chat-Id", self._turn["id"])
        xm_names = list(council)
        if (len(council) > 1 and cloud_allowed() and not _srv_only
                and not cloud_only and not _max):     # the bench IS the council here
            xm_names += [lbl for lbl, _c in cloud_bench()]
        if _max:                                  # Max names every cloud model it asks (6b440)
            xm_names += [lbl for lbl, _c in _max_bench]
        # whole names only, up to 2,000 characters: a cut at 300 left a big council's last
        # name in pieces ("Gemm") once six server seats with long names sat beside it
        xm_keep, xm_len = [], 0
        for _xn in xm_names:
            if xm_len + len(_xn) + (2 if xm_keep else 0) > 2000:
                break
            xm_keep.append(_xn)
            xm_len += len(_xn) + (2 if len(xm_keep) > 1 else 0)
        xm = ", ".join(xm_keep)
        # a server's name may be anything ("Sam’s server", "サーバー"),
        # and http.server writes headers as latin-1 (review of 6b334):
        # everything outside printable ASCII, and %, is percent-encoded;
        # the page decodes it (hdrText)
        self.send_header("X-Models", header_text(xm))
        # the time-left plan (6b459): measured figures, worked out up front
        # Thinking's shape since 6b515: one writer and a critic draft-and-review,
        # the rest of the roster is never asked, so the plan counts two stages
        _craft_eta = (tier == "Thinking" or (_srv_only and _so_mode == "Thinking")) \
            and len(council) > 2 and not images
        _ep = (photo_edit_eta(self.ctx) if edit_req else
               eta_plan(self.ctx, council[:2] if _craft_eta else council,
                        messages, bool(query or _links)))
        if _ep:
            self.send_header("X-Eta", json.dumps(_ep, separators=(",", ":")))
        # ANSWER NOW (6b257): an unguessable per-request id the client
        # may POST back to /api/chat/hurry. A header beats a frame here
        # — it arrives before the first body byte and costs the frame
        # parser nothing.
        hurry_id = secrets.token_hex(8)
        hurry_ev = threading.Event()
        skip_ev = threading.Event()
        with _hurry_lock:
            _hurry_jobs[hurry_id] = hurry_ev
            _skip_jobs[hurry_id] = skip_ev
        self.send_header("X-Hurry", hurry_id)
        self.end_headers()

        # Cloudflare drops a proxied response after ~100s without bytes,
        # and an engine swap + big-model load is a multi-minute SILENCE:
        # remote council runs died with "network error" while localhost
        # sailed (seen live). A heartbeat thread re-sends the last status
        # marker whenever the stream has been quiet too long. Writes are
        # serialized with a lock; the client treats repeated STATUS
        # markers as idempotent.
        wlock = threading.Lock()
        last_write = [time.time()]
        last_status = ["working"]
        hb_stop = threading.Event()

        def _write(data: bytes):
            with wlock:
                try:
                    self.wfile.write(data)
                    self.wfile.flush()
                except OSError:
                    # the page hung up (Stop, a reload): nothing after this
                    # was shown, so none of it is rescued (review of 6b322)
                    if self._turn is not None:
                        self._turn["aborted"] = True
                    raise
                last_write[0] = time.time()
                # what the page was actually sent: the turn is rebuilt
                # from this, so a stopped answer keeps what was shown
                if self._turn is not None:
                    self._turn["wire"].append(data)

        def _heartbeat():
            while not hb_stop.wait(5):
                if time.time() - last_write[0] > 20:
                    try:
                        _write(f"{NUL}STATUS:{last_status[0]}{NUL}"
                               .encode("utf-8"))
                    except Exception:
                        return
        ctx_thread(target=_heartbeat, daemon=True).start()

        sent = [0]
        shown_n = [0]       # characters of the answer on screen (6b515)

        answer_buf = []

        def emit(chunk: str):
            # an answer for a profile that is no longer the active one
            # stops here (1a 5.3): nothing more reaches the page, and its
            # turn and ledger writes are refused
            if user_base.cancel.is_set():
                raise StaleProfile("the profile changed")
            if not isinstance(chunk, Ctl):
                if chunk == "" and _client_gone(self.connection):
                    # a server model reasoning in silence ticks here once a
                    # second (6b570): a Stop ends it now, and frees the server
                    raise BrokenPipeError("the page left")
                # model text can't open a frame (see Ctl)
                chunk = strip_special(chunk).replace(NUL, "")
            if not chunk:
                return
            sent[0] += len(chunk)
            if isinstance(chunk, Ctl):
                if str(chunk) == NUL + "RESET" + NUL:
                    shown_n[0] = 0
            else:
                shown_n[0] += len(chunk)
                if not _t_first[0] and str(chunk).strip():
                    _t_first[0] = time.time()    # the first word (6b528)
            answer_buf.append(chunk)
            _write(chunk.encode("utf-8"))

        # THE PAGE SEES EVERY MODEL CALL (6b528): a USAGE frame per
        # usage_note() of this answer, from this thread and the threads the
        # run starts; switched off with the stream, so the memory pass that
        # follows reports to the ledger alone
        _tap_on = [True]

        def _usage_tap(d):
            if _tap_on[0]:
                _write((NUL + "USAGE:" + json.dumps(d, separators=(",", ":"))
                        + NUL).encode("utf-8"))
        _tap_sink[0] = _usage_tap
        for _d in list(_tap_q):          # the query plan's, from before the headers
            try:
                _usage_tap(_d)
            except Exception:
                pass
        del _tap_q[:]

        # SETTINGS › USAGE (6b325): the model paths get memit, which notes
        # that a model's own text reached the page; the app's own lines
        # (offline_hint, "That engine stopped responding", AppText) go
        # through emit, so a question that failed isn't counted an answer
        _model_said = [False]

        def memit(chunk: str):
            if (chunk and not isinstance(chunk, (Ctl, AppText))
                    and str(chunk).strip()):
                _model_said[0] = True
            emit(chunk)

        def step(sid: str, label: str, state: str = "run",
                 detail: str = ""):
            """One node of the live activity tree the UI draws."""
            try:
                _write((NUL + "STEP:" + json.dumps(
                    {"id": sid, "l": label, "s": state,
                     "d": str(detail)[:70]}) + NUL).encode("utf-8"))
            except Exception:
                pass

        def status(text: str):
            # sentinel-wrapped so the UI can show progress without it
            # ending up inside the answer text
            text = str(text).replace(NUL, "")
            last_status[0] = text
            _write(f"{NUL}STATUS:{text}{NUL}".encode("utf-8"))

        # a server that was asleep was woken before this answer (6b346)
        for _wn, _wok in server_take_wake_notes():
            status(("%s is awake." if _wok else "%s didn\u2019t wake.") % _wn)
        # A SERVER IN ITS QUIET HOURS IS LEFT ASLEEP (6b600, per Patrick): one
        # line says so and who answers instead; a picture or a video says only
        # that it wasn't woken. "<name> Only" wakes it as before (no note).
        for _qn, _qe in server_take_quiet_notes():
            try:
                _q_cloud = bool(gate_ladder(fast_cloud_ladder(), req_cloud, cloud_only))
            except Exception:
                _q_cloud = False
            status(server_quiet_line(_qn, _qe, None if (img_subject or vid_subject) else council,
                                     _q_cloud))

        # "<name> Only" on a server that sleeps (6b369): the wake goes out now
        # that the page has its headers, says "Waking <name>... 12 s" while it
        # waits (the page saw nothing for up to 75 s before), ends in one line
        # if it does not come up, and stops with the Stop button
        if _so_wake and _srv_only:
            try:
                _w_lbl, _w_why = server_only_wake(
                    _so_wake, self.ctx, status,
                    lambda: not _client_gone(self.connection), step, skip_ev)
            except (StaleProfile, BrokenPipeError, ConnectionResetError):
                raise
            except Exception:
                _w_lbl, _w_why = "", "Couldn\u2019t wake your server."
            if _w_lbl:
                _so_c0, council, model_name = _w_lbl, [_w_lbl], _w_lbl
                _srv_lbl = route_label = _w_lbl
                _so_fail = ""
                # (6b426) a mode on it alone takes its seats now it is awake
                _w_seats = (server_mode_resolve(_so_wake, _so_mode, self.ctx)
                            if _so_mode else [])
                if _w_seats:
                    # a picture goes to its reader alone; a greeting to its first seat (6b570)
                    council = _so_seats = _w_seats[:1] if (images or _brief_turn) else _w_seats
                    _so_c0 = model_name = council[0]
                    _srv_lbl = route_label = council[0] if len(council) == 1 else ""
            elif not _w_why:                 # the reader left
                hb_stop.set()
                return
            else:
                _so_fail = _w_why

        # THE CODE LANE WAKES A SLEEPING SERVER FIRST (6b461, per Patrick: "when
        # the server is asleep and a query is entered, have the gradient box
        # ... start by saying it's waking the server. Give it a timeout of 10
        # seconds ... as well as a skip button"). The page has its headers, so
        # the step shows; the Skip button POSTs to /api/chat/hurry. A server that
        # answers takes the agent's seat; one that doesn't (10 s, Skip) leaves
        # the cloud, then this computer, exactly as before.
        if _ag_wake and not _srv_only:
            try:
                _aw = server_wake_ask(_ag_wake, self.ctx, status, step, skip_ev,
                                      lambda: not _client_gone(self.connection))
            except (StaleProfile, BrokenPipeError, ConnectionResetError):
                raise
            except Exception:
                _aw = []
            if _aw is None:                  # the reader left
                hb_stop.set()
                return
            if _aw:
                try:
                    _ag2_label, _ag2, _ag2_fb = resolve_agent_seat(agent_name, self.ctx)
                except Exception:
                    _ag2_label, _ag2, _ag2_fb = "", None, ""
                if _ag2 and _ag2_label and server_label(_ag2_label):
                    council, model_name = [_ag2_label], _ag2_label
                    _seat_fb = {_ag2_label: _ag2_fb}
                    route, route_label = (None, None), None
            _start_prewarm()

        # FAST, THINKING, PRO AND MAX WAKE A SLEEPING SERVER WITH THE SAME STEP
        # (6b465, per Patrick: "Chat's Fast, Thinking and Pro modes still wake a
        # sleeping server silently, for up to a minute and with no Skip"). The
        # same server_wake_ask as the Code lane; a server that answers is
        # seated now (the roster, the merger last, the route), one that doesn't
        # leaves the roster as it was: the cloud, then this computer.
        if _ch_wake:
            try:
                _cw = server_wake_ask(_ch_wake, self.ctx, status, step, skip_ev,
                                      lambda: not _client_gone(self.connection))
            except (StaleProfile, BrokenPipeError, ConnectionResetError):
                raise
            except Exception:
                _cw = []
            if _cw is None:                  # the reader left
                hb_stop.set()
                return
            if _cw:
                try:
                    _seats = (max_tier_seats(self.ctx) if _max
                              else resolve_tier_seats(tier, self.ctx))
                except Exception:
                    _seats = []
                if _seats:
                    council = council_merger_last([x["label"] for x in _seats], req_comp, mode_pen)
                    if _brief_turn:
                        council = council[:1]    # a greeting's one pass (6b570)
                    _seat_fb = {x["label"]: x["fb"] for x in _seats if server_label(x["label"])}
                    model_name = council[0]
                    _srv_lbl = ""            # a mode's seat is never an explicit pick (6b339)
                    _resolve_route()
            _start_prewarm()

        # MAKING A PICTURE, A VIDEO OR A FILE USES THIS COMPUTER (review of
        # 6b334): a chat on your own server that took no hold takes it
        # now, and while a benchmark runs it gets the benchmark's line
        if _srv_only and (img_subject or vid_subject):
            # "<name> Only" makes no picture or video (6b339): not on this
            # computer, not with a cloud key, and no model is asked to word
            # one. A plain server pick keeps 6b334's behaviour, on purpose.
            emit(AppText("%s Only can’t make pictures or video. Nothing was made."
                         % (_so_c0.split(SERVER_SEP, 1)[0] or "Your server")))
            hb_stop.set()
            return
        if (img_subject or vid_subject or export_req or edit_req) and not self._bench_held:
            if not bench_hold():
                emit(AppText(BENCH_BUSY))
                hb_stop.set()
                return
            self._bench_held = True

        if export_req and export_req["lane"] == "retro":
            src = str(_prior[-1].get("content") or "") if _prior else ""
            ext = export_req["ext"] or _SHAPE_FMT.get(
                _export_shape(src), "md")
            if export_req.get("shape") and ext == "txt":
                blks = x_code_blocks(src)
                ext = blks[0][0] if blks else "md"
            # a server's turn is titled by that server or none; any other
            # by the person's server first, then this computer (6b357)
            ttl = next((b[2] for b in x_blocks(src) if b[0] == "h"), "") \
                or ((make_title(src[:600], server=_srv_lbl)
                     if (_srv_only or _srv_lbl) else
                     make_title(src[:600], local=not _seat_fb,
                                ask_server=not cloud_only))
                    if len(src) > 200 else "")
            step("export", "Writing the file", "run",
                 EXPORT_KIND.get(ext, ("", ext))[1])
            status("Writing the %s" % EXPORT_KIND.get(ext, ("", ext))[1])
            try:
                info = run_export(src, ext, ttl, self.ctx,
                                  export_req.get("filename", ""))
                step("export", "Wrote the file", "done", info["name"])
                emit("**%s**, %s.\n\n[[dl:%s]]"
                     % (info["name"], _x_size(info["size"]),
                        json.dumps(info, separators=(",", ":"))))
            except StaleProfile:
                raise
            except Exception as exc:
                step("export", "Couldn\u2019t write the file", "done",
                     str(exc)[:70])
                emit("Couldn’t make that file: %s." % str(exc)[:200])
            hb_stop.set()
            return

        if vid_subject:
            # YOUR SERVER FIRST (6b356, per Patrick: "Can we get image and video
            # generation on the server?"): a paired server of this profile that
            # can film it does, before this Mac or the cloud. Cloud Only never
            # asks one. If it can't, one line says so and everything below runs
            # as it always did
            if not cloud_only:
                try:
                    _sg_use, _sg_n = resolve_overrides("video", _ovr, _pnote)
                    if server_make(user_base, "video", vid_subject, _sg_use,
                                   _onotes, self.connection, emit, step, status,
                                   skip=skip_ev):
                        hb_stop.set()
                        return
                except (StaleProfile, BrokenPipeError, ConnectionResetError):
                    raise
                except Exception:
                    pass
            # A SAVED GEMINI KEY IS PERMISSION TO USE IT (Patrick, 6b326):
            # Veo runs with a working key whatever Use cloud power says;
            # with neither that nor video on this Mac nothing is sent
            _gv = (_cloud_all().get("providers") or {}).get("gemini") or {}
            _cloud_vid = (bool(_gv.get("key"))
                          and _gv.get("status", "ok") == "ok")
            if not video_ready() and not _cloud_vid:
                step("video", "Couldn\u2019t make the video", "done",
                     "nothing was sent")
                emit(studio_needs("video"))
                hb_stop.set()
                return
            where = "on this Mac" if video_ready() else "in the cloud"
            step("video", "Making the video", "run", where)
            status("filming \u00b7 " + where)
            try:
                _use, _cnotes = resolve_overrides("video", _ovr, _pnote)
                vpath, vsrc = generate_video(user_base, vid_subject, _use,
                                             sock=self.connection)
                vmade = "made on this Mac" if vsrc == "local" \
                    else "made in the cloud"
                step("video", "Made the video", "done", vmade)
                _note = ("" if not (_cnotes + _onotes) else
                         " \u00b7 " + "; ".join(_cnotes + _onotes))
                emit("[[vid:%s]]\n\n*%s \u2014 %s%s*"
                     % (json.dumps({"id": os.path.basename(vpath),
                                    "t": vid_subject[:80]},
                                   separators=(",", ":")),
                        vid_subject[:1].upper() + vid_subject[1:], vmade,
                        _note))
            except RenderBusy as rb:
                # stopped: the reader left, there is no one to tell.
                # busy: say so, and do NOT spend cloud quota on a fallback
                if str(rb) != "stopped":
                    step("video", "Another render is running", "done", "")
                    emit("Already making one. Ask again when it lands.")
            except StaleProfile:
                raise
            except Exception as exc:
                step("video", "Couldn\u2019t make the video", "done",
                     str(exc)[:70])
                if "VEO_CAP:" in str(exc):
                    # local video exists only on Apple silicon (6b317)
                    emit("Today\u2019s cloud video limit is reached (%d "
                         "clips, about $0.80 each). It resets tomorrow%s."
                         % (int(profile_local(user_base).get(
                             "veo_daily_cap", VEO_DAILY_CAP) or 0),
                            "; video made on this Mac isn\u2019t limited"
                            if studio_supported() else ""))
                elif video_ready():
                    emit("Video failed on this Mac%s. "
                         "Try again in a moment. (%s)"
                         % (" and in the cloud"
                            if _cloud_vid else "", str(exc)[:160]))
                else:
                    emit("Gemini couldn\u2019t make that video. "
                         "Try again in a moment%s. (%s)"
                         % (", or add video generation in Settings > Models"
                            ""
                            if studio_supported() else "", str(exc)[:160]))
            hb_stop.set()
            return

        if edit_req:
            # LOCAL ONLY (6b472): the photo is edited on this Mac with the
            # klein edit engine and goes nowhere else: no server, no cloud
            # painter, and a failure is said, never retried elsewhere.
            # "<name> Only" and Cloud Only are text routes; the edit runs
            # here anyway and one line says so (nothing leaves this Mac)
            _pe_note = ""
            if _srv_only or cloud_only:
                _pe_note = (" \u00b7 %s runs text, so this edit ran on this "
                            "Mac" % ("Cloud Only" if cloud_only else
                                     (_so_c0.split(SERVER_SEP, 1)[0]
                                      or "Your server") + " Only"))
                status("Editing on this computer")
            _pe_why = ("" if "photoedit-stub" in "".join(TEST_HOOKS)
                       else photo_edit_unavailable())
            if _pe_why:
                step("image", "Couldn\u2019t edit the photo", "done",
                     "nothing was sent")
                emit(_pe_why)
                hb_stop.set()
                return
            step("image", "Editing your photo", "run", "on this Mac")
            status("Editing your photo on this computer")
            try:
                _b64 = images[0].split(",", 1)[1] \
                    if images[0].startswith("data:") else images[0]
                path = edit_photo(self.ctx, _b64, edit_req,
                                  sock=self.connection)
                step("image", "Edited the photo", "done", "on this Mac")
                emit("![%s](/api/image/%s)\n\n*%s%s*"
                     % ("Edited photo: " + edit_req[:80].replace("]", ""),
                        os.path.basename(path), PE_NOTE, _pe_note))
            except RenderBusy as rb:
                if str(rb) != "stopped":
                    step("image", "Another render is running", "done", "")
                    emit("Already making a picture. Ask again when it lands.")
            except PhotoEditUnavailable as pu:
                step("image", "Couldn\u2019t edit the photo", "done",
                     "nothing was sent")
                emit(str(pu))
            except StaleProfile:
                raise
            except Exception as exc:
                step("image", "Couldn\u2019t edit the photo", "done",
                     str(exc)[:70])
                emit("The edit failed on this computer. Your photo wasn’t sent anywhere. Try again in a moment. (%s)" % str(exc)[:160])
            hb_stop.set()
            return

        if img_subject:
            # YOUR SERVER FIRST (6b356): as for a video, above
            if not cloud_only:
                try:
                    _sg_use, _sg_n = resolve_overrides("image", _ovr, _pnote)
                    if server_make(user_base, "image", img_subject, _sg_use,
                                   _onotes, self.connection, emit, step, status,
                                   skip=skip_ev):
                        hb_stop.set()
                        return
                except (StaleProfile, BrokenPipeError, ConnectionResetError):
                    raise
                except Exception:
                    pass
            # "in the cloud" only when a cloud painter exists (6b310): with
            # Pollinations gone, no local model and no Gemini key means
            # nothing is sent anywhere, and the label mustn't say it was.
            # A saved Gemini key is permission to paint with it, whatever
            # Use cloud power says (Patrick, 6b326)
            _gem = (_cloud_all().get("providers") or {}).get("gemini") or {}
            _cloud_img = (bool(_gem.get("key"))
                          and _gem.get("status", "ok") == "ok")
            if not image_ready() and not _cloud_img:
                step("image", "Couldn\u2019t generate the image", "done",
                     "nothing was sent")
                emit(studio_needs("image"))
                hb_stop.set()
                return
            where = "on this Mac" if image_ready() else "in the cloud"
            step("image", "Generating the image", "run", where)
            status("painting \u00b7 " + where)
            try:
                _use, _cnotes = resolve_overrides("image", _ovr, _pnote)
                path, src = generate_image(user_base, img_subject, _use,
                                           sock=self.connection)
                made = "made on this Mac" if src == "local" \
                    else "made in the cloud"
                step("image", "Generated the image", "done", made)
                _note = ("" if not (_cnotes + _onotes) else
                         " \u00b7 " + "; ".join(_cnotes + _onotes))
                emit("![%s](/api/image/%s)\n\n*%s \u2014 %s%s*"
                     % (img_subject.replace("]", ""), os.path.basename(path),
                        img_subject[:1].upper() + img_subject[1:], made,
                        _note))
            except RenderBusy as rb:
                if str(rb) != "stopped":
                    step("image", "Another render is running", "done", "")
                    emit("Already making one. Ask again when it lands.")
            except StaleProfile:
                raise
            except Exception as exc:
                step("image", "Couldn\u2019t generate the image", "done",
                     str(exc)[:70])
                if image_ready():
                    emit("The picture failed on this Mac%s. "
                         "Try again in a moment. (%s)"
                         % (" and in the cloud"
                            if _cloud_img else "", str(exc)[:160]))
                else:
                    emit("Gemini couldn\u2019t make that picture. "
                         "Try again in a moment%s. (%s)"
                         % (", or add image generation in Settings > Models"
                            ""
                            if image_supported() else "", str(exc)[:160]))
            hb_stop.set()
            return

        # GROUNDED SEARCH, FINISHED HERE (6b514): the plan and the fan-out
        # started before the headers; the page sees each phase as a step
        # while the reads finish, then the evidence pack takes the
        # question's place in the user turn. That dict is the one
        # full_messages holds, so the drafts and the merge both read it,
        # and the system prompt gains its one grounding line.
        if _ground is not None:
            def _ground_phase(ph, g):
                if ph == "search":
                    nq = len(g.queries)
                    status("Searching the web\u2026")
                    step("search", "Searching the web", "run",
                         "%d quer%s" % (nq, "y" if nq == 1 else "ies"))
                elif ph == "read":
                    n = len(g.sources)
                    step("search", "Searched the web", "done",
                         "%d source%s" % (n, "" if n == 1 else "s"))
                    if n:
                        nr = min(n, GROUND_READ)
                        status("Reading %d source%s\u2026" % (n, "" if n == 1 else "s"))
                        step("read", "Reading the pages", "run",
                             "%d page%s" % (nr, "" if nr == 1 else "s"))
            try:
                _ground.wait(_ground_phase, GROUND_TOTAL_S)
            except Exception:
                pass
            _gsrc, _gpack, _gread, _gpass = _ground.snapshot()
            _tl_search.rows = [{"t": (s.get("title") or s.get("host") or "")[:80],
                                "u": s.get("url") or "", "d": s.get("date") or ""}
                               for s in _gsrc if s.get("url")]
            if _ground.photos:
                _tl_search.photos = list(_ground.photos)
            if _gsrc:
                step("read", "Read the pages", "done",
                     "%d page%s \u00b7 %d passage%s" % (
                         _gread, "" if _gread == 1 else "s",
                         _gpass, "" if _gpass == 1 else "s"))
                dated_system["content"] += GROUND_SYSTEM
            if getattr(_ground, "prior", None) is not None:
                step("prior", "Kept the earlier sources", "done",
                     "%d source%s%s" % (len(_ground.prior.sources),
                                        "" if len(_ground.prior.sources) == 1 else "s",
                                        "" if _ground.search else " \u00b7 nothing new to look up"))
            _fu_note = (GROUND_FOLLOWUP if (_g_reuse and not _oai_note
                                            and "followup" not in quality_ablate()) else "")
            _gturn = grounded_turn(query, _gpack, note=_oai_note or _fu_note)
            if getattr(_tl_search, "photos", None) and _WANTS_IMAGES.search(prompt):
                _gturn += ("\n\n[The interface is displaying %d relevant "
                           "photo(s) from the sources directly beneath your "
                           "answer. Do NOT say you cannot show images \u2014 "
                           "describe what they show and carry on.]"
                           % len(_tl_search.photos))
            messages[-1]["content"] = _clock_line + _gturn + _think_tail
            full_messages[-1] = messages[-1]

        # the search ran earlier on THIS thread — hand the client its
        # structured hits so the answer carries a clickable sources row
        if query:
            nsrc = len(getattr(_tl_search, "rows", []) or [])
            step("search", "Searched the web", "done",
                 "%d source%s" % (nsrc, "" if nsrc == 1 else "s"))
            nph = len(getattr(_tl_search, "photos", []) or [])
            if nph:
                step("read", "Read the pages", "done",
                     "%d image%s found" % (nph, "" if nph == 1 else "s"))
            if getattr(_tl_search, "geo", None):
                step("geo", "Located it on the map", "done",
                     (getattr(_tl_search, "geo") or {}).get("name", ""))
            src_rows = getattr(_tl_search, "rows", [])[:GROUND_SOURCES]
            if src_rows:
                try:
                    _write((NUL + "SOURCES:" + json.dumps(src_rows) + NUL)
                           .encode("utf-8"))
                except Exception:
                    pass
            # the Fable treatment: photos from the pages actually read,
            # and a pinned map when the answer is about a real place
            ph = [p for p in dict.fromkeys(
                getattr(_tl_search, "photos", []) or [])
                if p.startswith("https://")][:3]
            if ph:
                try:
                    _write((NUL + "PHOTOS:" + json.dumps(ph) + NUL)
                           .encode("utf-8"))
                except Exception:
                    pass
            geo = getattr(_tl_search, "geo", None)
            if geo:
                try:
                    # the pin, not the whole geocode: saved chats keep
                    # what the card reads (6b323)
                    _write((NUL + "MAP:" + json.dumps(
                        {k: geo.get(k) for k in ("lat", "lon", "name")})
                        + NUL).encode("utf-8"))
                except Exception:
                    pass
            hint = _place_names(getattr(_tl_search, "rows", []) or [],
                                getattr(_tl_search, "locq", ""))
            # only when the places machinery is engaged (6b247): for a
            # plain searched answer the "venues" mined from article
            # titles are headline fragments, not places
            if hint and (placey or bookish):
                try:
                    _write((NUL + "PLACEHINT:" + json.dumps(hint) + NUL)
                           .encode("utf-8"))
                except Exception:
                    pass
            locq = getattr(_tl_search, "locq", "")
            if locq:
                try:
                    _write((NUL + "CTX:" + json.dumps({"loc": locq}) + NUL)
                           .encode("utf-8"))
                except Exception:
                    pass

        # THE PASTED LINKS (6b423): their own sources row and photos, and
        # when not one could be read, one line that says so and why, in place
        # of an answer about pages nobody saw (the Colorado listings)
        if _links:
            step("search", "Opened the links you pasted", "done",
                 "%d link%s" % (len(_links), "" if len(_links) == 1 else "s"))
            step("read", "Read the pages", "done",
                 "%d of %d read" % (_links_n, len(_links)))
            try:
                _write((NUL + "SOURCES:" + json.dumps(
                    getattr(_tl_search, "rows", [])[:PASTED_MAX]) + NUL)
                    .encode("utf-8"))
            except Exception:
                pass
            _lph = [p for p in dict.fromkeys(
                getattr(_tl_search, "photos", []) or [])
                if p.startswith("https://")][:PASTED_MAX]
            if _lph:
                try:
                    _write((NUL + "PHOTOS:" + json.dumps(_lph) + NUL)
                           .encode("utf-8"))
                except Exception:
                    pass
            if not _links_n:
                emit(AppText(links_none_line(_links)))
                hb_stop.set()
                return

        # IT KNOWS YOUR LIFE (6b530, per Patrick): a question about the
        # person's own life, decisions or work is answered with their own
        # notes and chats, found on this computer (know_search: words and
        # meaning, fused, recency-aware). The records ride under the
        # question as numbered private data (know_turn), cited [n] like web
        # evidence, and their chips join the sources row. This Mac and the
        # person's own servers only ("my servers are mine", per Patrick):
        # a server pick or a council with server seats gets the records; a
        # question bound for the cloud (Cloud Only, Max with cloud seats)
        # gets none unless the person allowed sharing, and with the records
        # in, cloud_allowed() is shut for the rest of the request, so no
        # cloud seat, ladder, polish, title or memory pass sees them.
        # Pictures, agents and the Code lane are left alone.
        _kn_hits = []
        try:
            _kn_want = 0
            if not (images or ag_remote or ag_research or export_req
                    or AGENTS.get(agent_name, {}).get("workspace")
                    or str(req_json.get("lane") or "") == "code"):
                _kn_want = know_wants(prompt)
            if _kn_want:
                _kn_cfg = know_settings(user_base)
                _kn_away = bool(cloud_only or _max_bench)     # bound for the cloud
                if _kn_away and not _kn_cfg["share"]:
                    if _kn_want == 2:
                        step("know", "Didn\u2019t look through your stuff", "done",
                             "it never goes to the cloud; this answer uses the cloud")
                else:
                    _kn_hits = know_search(
                        user_base, prompt,
                        embed=(_kn_want == 2 or know_embedder_alive()
                               or know_embed_kind() != "mlx"))
            if _kn_hits:
                _kn_web = list(getattr(_tl_search, "rows", []) or [])
                _kn_web = (_kn_web[:GROUND_SOURCES] if query
                           else _kn_web[:PASTED_MAX] if _links else [])
                _kn_pack = know_pack(_kn_hits, start=len(_kn_web) + 1)
                messages[-1] = dict(messages[-1])
                messages[-1]["content"] = know_turn(_kn_pack, str(messages[-1]["content"]))
                full_messages[-1] = messages[-1]
                dated_system["content"] += KNOW_SYSTEM
                if not _kn_cfg["share"]:
                    _tl_search.know_private = True
                elif _kn_away or cloud_allowed():
                    # the per-answer note (6b530): sharing was allowed, and
                    # this answer may go to the cloud or a server with them
                    step("know-share", "Your notes may reach the cloud",
                         "done", "you allowed this under Settings > Your stuff")
                _kn_n = len(_kn_hits)
                status("Found %d match%s in your notes and chats"
                       % (_kn_n, "" if _kn_n == 1 else "es"))
                step("know", "Looked through your stuff", "done",
                     "%d match%s" % (_kn_n, "" if _kn_n == 1 else "es"))
                try:
                    _write((NUL + "SOURCES:" + json.dumps(
                        _kn_web + know_source_rows(_kn_hits)) + NUL).encode("utf-8"))
                except Exception:
                    pass
            elif _kn_want == 2:
                step("know", "Looked through your stuff", "done", "nothing matched")
        except (StaleProfile, BrokenPipeError, ConnectionResetError):
            raise
        except Exception:
            _kn_hits = []

        kind, target = route
        # PASTED IMAGES GO TO THE CLOUD WHEN CLOUD POWER IS ON (6b308, per
        # Patrick): Haiku on Fast, Opus 5.5 on Thinking/Pro/Cloud Only,
        # Gemini Flash beside it; the local vision model is the floor.
        # Only under the one gate (6b326): an Advanced list alone used to
        # send the picture with the switch off
        # a server pick's picture goes to that server only (6b334)
        _vis_cloud = (gate_ladder(vision_ladder("Cloud Only" if cloud_only
                                                else req_tier),
                                  req_cloud, cloud_only)
                      if images and not _srv_lbl else [])
        if _cl_mode and _vis_cloud:
            # a Cloud Only mode or pick reads a picture with its own kind of
            # model (6b440): Fast and Thinking only the cheap ones (the quick
            # ladder, a small model), Pro the strong one, a pick only its own
            # provider; never a paid model the mode would not seat
            _vis_cloud = [c for c in (
                vision_ladder("Pro" if _cl_mode == "Pro" else
                              "Cloud Only" if _cl_mode == "Model" else "Fast"))
                if (_provider_of(c) == _cl_pid if _cl_mode == "Model"
                    else _cl_mode == "Pro" or _cloud_cheap(_provider_of(c), c))]
        _vis_local = bool(images) and not _srv_lbl and model_cached(
            "Qwen 3.5 Vision 9B", ollama_pulled_tags() or set())

        def _cloud_vision() -> bool:
            for _vc in _vis_cloud:
                status("Cloud: " + _vc.get("name", "cloud"))
                if cloud_stream_conf(_vc, full_messages, memit):
                    return True
                _rc = claude_refusal_conf(_vc)
                if _rc and cloud_stream_conf(_rc, full_messages, memit):
                    return True
            # (6b357) the person's server reads it next when it can
            if cloud_only or (not _vis_local and _vis_srv is None):
                emit("The cloud couldn\u2019t read that image"
                     + ("" if cloud_only else
                        ", and no local vision model is installed. Add one in Settings > Models")
                     + ". Try again in a moment.")
            return cloud_only or (not _vis_local and _vis_srv is None)
        # first image before the vision engine exists: kick the download
        # and say so, instead of a cryptic connection error
        if (images and not cloud_only and not _vis_cloud and not _vis_local
                and not _srv_lbl and _vis_srv is None):
            try:
                start_model_downloads(["Qwen 3.5 Vision 9B"])
                # a Claude or Gemini key would read it with the switch on
                # (6b326, from review): say so beside the 6.6 GB download
                _pvk = _cloud_all().get("providers") or {}
                _vkey = any((_pvk.get(p) or {}).get("key")
                            and (_pvk.get(p) or {}).get("status", "ok") == "ok"
                            for p in ("claude", "gemini"))
                emit("Downloading the vision model (6.6 GB). Paste the image again when "
                     "Settings > Models shows it done."
                     + (" Or turn on cloud models in Settings > Models > Cloud and your saved key reads "
                        "pictures now." if _vkey else ""))
            except (BrokenPipeError, ConnectionResetError):
                pass
            hb_stop.set()
            return
        def _single_polish():
            """THE POST-PASS (6b523): the single writer's finished
            answer, its arithmetic re-computed, its conversions
            checked, the machinery's words reworded, a heading
            and a recap dropped; a changed answer is re-sent after
            a RESET as the fact-check's is (verify_pass). Never
            breaks an answer."""
            try:
                _shown = shown_answer(answer_buf)
                if len(_shown.strip()) < 40:
                    return
                if LANE_ROLE.get(agent_name, "") == "code":
                    return         # the Code lane's answers are code, left as written (6b560)
                _pk = (full_messages[-1].get("content") or "") if (query or docs) else ""
                _new, _notes = answer_polish(_shown, _pk, prompt)
                if _notes and _new.strip() and _new != _shown:
                    memit(Ctl(NUL + "RESET" + NUL))
                    memit(_new)
                    _nf = sum(1 for n_ in _notes if "\u2192" in n_)
                    step("polish", "Sharpened", "done",
                         ("fixed %d figure%s" % (_nf, "" if _nf == 1 else "s")) if _nf
                         else "; ".join(_notes)[:70])
                    if DEV_HOME:
                        print("polish: %s" % " | ".join(_notes), file=sys.stderr, flush=True)
            except (StaleProfile, BrokenPipeError, ConnectionResetError):
                raise
            except Exception:
                pass
        try:
            if images and _vis_cloud and _cloud_vision():
                pass          # a cloud model read the picture (6b308)
            elif cloud_only and images:
                # no vision rung right now: a key that is only resting is
                # not "add a key" (found in review, 6b308)
                _pv = _cloud_all().get("providers") or {}
                _vk = [(p, _pv[p]) for p in ("claude", "gemini")
                       if (_pv.get(p) or {}).get("key")
                       and (_pv.get(p) or {}).get("status", "ok") == "ok"]
                if _vk:
                    _mins = max(1, min(cloud_rest_left(p, v)
                                       for p, v in _vk) // 60)
                    emit("**Cloud Only**: the vision providers are resting. Try again in "
                         "%d minute%s." % (_mins, "" if _mins == 1 else "s"))
                else:
                    emit("**Cloud Only** reads images with a Claude or Gemini key. "
                         "Add one in Settings > Models > Cloud, or switch to Fast, Thinking or Pro.")
            elif cloud_only:
                run_cloud_only(full_messages, memit, status, step, _cplan, mode_pen)
            elif ag_remote:
                # THE REMOTE AGENT (6b249): drive the user's VPS over
                # SSH. await_approval blocks on the approval channel —
                # the client answers with POST /api/remote/approve.
                rconf = remote_conf()
                if not rconf.get("host"):
                    emit("Set up the server connection first: host, user and SSH key, under the gear by the Remote agent.")
                else:
                    autonomy = str(req_json.get("autonomy") or "auto")
                    if autonomy not in ("manual", "auto", "full"):
                        autonomy = "manual"      # fail closed (6b309)

                    def _await(cmd, risk):
                        jid = secrets.token_hex(8)
                        ev = threading.Event()
                        with _remote_lock:
                            _remote_jobs[jid] = {"gate": ev, "ok": False}
                        try:
                            _write((NUL + "APPROVE:" + json.dumps(
                                {"jid": jid, "cmd": cmd, "risk": risk})
                                + NUL).encode("utf-8"))
                        except Exception:
                            pass
                        got = ev.wait(600)
                        with _remote_lock:
                            j = _remote_jobs.pop(jid, {})
                        # NOBODY ANSWERED is not "no" (6b309): a timeout
                        # used to reach the model as a decline, and an
                        # unattended run carried on for hours
                        if not got:
                            return "expired"
                        return bool(j.get("ok"))
                    run_remote_agent(messages, rconf, autonomy,
                                     memit, status, step, _await)
            # research searches the message's words: with pasted pages read
            # (6b423) the pages are the source, and the council answers
            elif (TIERS.get(tier, {}).get("research")
                  or ag_research) and not _links_n:
                run_research(council, full_messages, memit, status)
            elif _rubin and not images:
                # VERA RUBIN (6b519, per Patrick): one question, every machine,
                # round after round until Stop (the hurry id) or three rounds in
                # a row bring nothing better; the handler's grounded search is
                # its first evidence
                run_rubin(prompt, full_messages, memit, status, step, hurry_ev,
                          ctx=self.ctx, ground=_ground, web=bool(auto_web))
            elif _max and (_max_bench or len(council) > 1) and not images:
                # MAX (6b440): every local and server seat drafts as in Pro, every
                # cloud model drafts beside them, and the merge is written by
                # the first available of MAX_COMPOSITOR_ORDER (cloud rungs
                # first, then the server's strongest, then this computer's
                # largest). No review pass: every model already drafts.
                run_council(council, full_messages, memit, status,
                            hurry=hurry_ev,
                            srv_first_s=(60.0 if _seat_fb else None),
                            srv_merge=True, max_mode=True, pen=mode_pen,
                            cloud_plan={"mode": "Max", "seats": _max_bench,
                                        "comp": max_cloud_ladder(), "spare": [],
                                        "why": "", "pid": ""})
            elif (_srv_lbl and _srv_only and _so_mode == "Fast" and not _so_fail
                  and not images):
                # Fast on that server alone (6b426): its one model, and Fast's
                # second pass on it; nothing stands behind it (fallback "")
                def _so_revise(_d):
                    _sq = (ground_clip(full_messages[-1]["content"], 10000)
                           if (query or docs) else prompt)
                    return [brief_system(full_messages[0]),     # the brief (6b515)
                            {"role": "user", "content":
                             REVISE_INSTRUCTION + "QUESTION: " + _sq
                             + "\n\nFIRST DRAFT:\n" + _d[:6000]}]
                _so_res = server_first_answer(
                    _srv_lbl, "", full_messages, memit, emit, status, step,
                    first_s=None,
                    polish=(_so_revise if (effort_polish(user_prefs(user_base).get("polish", True), _effort)
                                           and (not query or bookish)
                                           and _is_substantive(prompt)) else None))
                if _so_res == "server":
                    _single_polish()      # the post-pass (6b560)
            elif _srv_lbl:
                server_answer(_srv_lbl, full_messages, memit, emit, status,
                              step, refuse=_so_fail)
            elif len(council) > 1:
                # Thinking or Pro on one server alone (6b426): its seats, its
                # merge, no cloud and nothing of this computer's
                # Max on one server alone (6b442): every model of it, no review pass
                run_council(council, full_messages, memit, status,
                            reflect=(tier == "Thinking" or (
                                _srv_only and _so_mode == "Thinking")),
                            peer=(tier == "Pro" or (_srv_only and _so_mode == "Pro")),
                            bench_allow=[] if _srv_only else req_cloud,
                            comp="" if _srv_only else req_comp,
                            hurry=hurry_ev, srv_only=_srv_only,
                            max_mode=bool(_srv_only and _so_mode == "Max"), pen=mode_pen,
                            srv_first_s=(60.0 if _seat_fb else None),
                            # Thinking: one writer, a critic, a checked final (6b515)
                            craft=(tier == "Thinking" or (
                                _srv_only and _so_mode == "Thinking")),
                            srv_merge=(tier in TIERS and not cloud_only))
            else:
                lbl = route_label or model_name
                # cloud is a pref, not a tier (Best retired in 5.3).
                # Gated on the LADDER, not on cloud_conf (6b246): the
                # old gate needed the ACTIVE provider healthy, so a dead
                # active key skipped cloud entirely while a perfectly
                # good second key sat unused. An ADVANCED run's cloud
                # list narrows the ladder (6b248); an empty list means
                # none at all. Since 6b326 it no longer engages the cloud
                # with the switch off (0a 5.5).
                # THE LANE PICKS THE ROLE (6b308): the Code tab answers on
                # Sonnet 5 at medium, writing/resumes/exports on Opus 5.5
                # at medium, everything else on the quick ladder, Haiku
                # first
                _lane = LANE_ROLE.get(agent_name, "")
                if images:
                    _fl = []       # pictures went to the vision ladder
                elif _lane == "code":
                    _fl = work_ladder("code")
                elif export_req or _lane == "work":
                    _fl = work_ladder("work")
                else:
                    _fl = fast_cloud_ladder()
                # ONE GATE (6b326, 0a 5.5): the Advanced list narrows the
                # ladder, and no longer turns the cloud on by itself
                _fl = gate_ladder(_fl, req_cloud)
                turbo = bool(_fl)

                def _run_lbl(names):
                    try:
                        emit(Ctl(NUL + "RUN:"
                                 + json.dumps({"r": names}) + NUL))
                    except Exception:
                        pass
                # THE CODE LANE: SERVER, THEN CLOUD, THEN THIS COMPUTER (6b461, per
                # Patrick: "coding doesn't use the server or cloud models ... prefer
                # server over local models"). A server coder seated for the agent
                # is asked before the cloud ladder; if it fails before its first
                # word the cloud walks next, then this computer's copy.
                _cl_fb = None
                if (_lane == "code" and lbl in _seat_fb and not images
                        and server_label(lbl)):
                    _cl_fb = _seat_fb[lbl]
                    _cs = server_first_answer(
                        lbl, "", full_messages, memit, emit, status, step,
                        first_s=60.0, polish=None, defer_fail=True)
                    if _cs != "down":
                        _seat_res[0] = _cs
                        hb_stop.set()
                        return
                    lbl = _cl_fb or ""
                if turbo:
                    # FAST WALKS THE SPEED LADDER (6b246, per Patrick:
                    # "prefer one fast cloud model over any LLM").
                    # Quickest healthy rung first, next rung on any
                    # failure \u2014 the old path took ONE shot at whichever
                    # provider happened to be 'active', which could be
                    # the slowest paid one, and gave up straight to
                    # local silicon when it hiccuped. The status speaks
                    # the UI's name: "turbo" is only the pref key.
                    for _fc in _fl:
                        _nm = _fc.get("name", "cloud")
                        status("Cloud: " + _nm)
                        _run_lbl([_nm])
                        if cloud_stream_conf(_fc, full_messages, memit):
                            hb_stop.set()
                            return
                        # a refusal gets one more Claude try (6b308)
                        _rc = claude_refusal_conf(_fc)
                        if _rc and cloud_stream_conf(_rc, full_messages,
                                                     memit):
                            hb_stop.set()
                            return
                    status("Cloud unavailable. Answering here.")
                if _cl_fb is not None and not lbl:
                    # the server didn't answer, the cloud had nothing, and this
                    # computer holds no copy of the coder (6b461)
                    emit(AppText("Your server didn’t answer, and nothing else could take the question."))
                    hb_stop.set()
                    return
                if lbl in _seat_fb:
                    # a mode's server seat (6b339): asked first, this
                    # computer's copy behind it until the first word; Fast
                    # gets the same second pass as on this computer, run on
                    # the server. A first word within 30 s (Fast) or 60 s
                    # pasted pages write once (6b423): a reviser shown 5000
                    # characters of eight pages can't check the rest
                    _pol = (effort_polish(user_prefs(user_base).get("polish", True), _effort)
                            and not images and (not query or bookish)
                            and not _links
                            and _is_substantive(prompt))

                    def _revise(_d):
                        _sq = (ground_clip(full_messages[-1]["content"], 10000)
                               if (query or docs) else prompt)
                        return [brief_system(full_messages[0]),     # the brief (6b515)
                                {"role": "user", "content":
                                 REVISE_INSTRUCTION + "QUESTION: " + _sq
                                 + "\n\nFIRST DRAFT:\n" + _d[:6000]}]
                    _seat_res[0] = server_first_answer(
                        lbl, _seat_fb[lbl], full_messages, memit, emit,
                        status, step,
                        first_s=30.0 if tier == "Fast" else 60.0,
                        polish=_revise if _pol else None)
                    # the server's answer gets the same post-pass (6b560):
                    # a mode with a paired server answers there first, so
                    # the 6b523 fixes reached almost no answer without it
                    if _seat_res[0] in ("server", "fallback"):
                        _single_polish()
                    hb_stop.set()
                    return
                _run_lbl([lbl])
                # searched answers were EXCLUDED from the polish pass, so
                # every live-data reply was a single take — that's where
                # the sloppy ones came from. Bookish (recommendations)
                # answers now get the rewrite too, fed the same grounded
                # message so the reviser can check names against data.
                # a giant on Ollama writes once (6b314): the draft-and-
                # rewrite pass doubles a few-words-a-second answer
                polish = (effort_polish(user_prefs(user_base).get("polish", True), _effort)
                          and not images and (not query or bookish)
                          and not _links          # (6b423) see _pol
                          and _is_substantive(prompt)
                          and not slow_giant(lbl))
                if polish:
                    step("draft", "Drafting the answer", "run", lbl)
                    # TWO PASS, BOTH ON SCREEN (6b539, per Patrick: "faster
                    # feels smarter"). The draft used to be written in
                    # silence, so the first visible word waited for the
                    # whole first pass (9-21 s warm on Gemma 4 26B, measured
                    # in 6b531). The draft now streams as it is written, the
                    # first word lands in a second or two, and the polished
                    # answer replaces it: a RESET, which the page turns into a
                    # soft crossfade that keeps the draft on screen until the
                    # polish has words. The byline says which pass is on. If
                    # the polish fails, the draft stays as the answer. The
                    # saved chat keeps what follows the last RESET (turn_text).
                    status(f"{lbl} is writing a first draft")
                    parts = []
                    draft = ""

                    def _draft_live(chunk, _p=parts):
                        _p.append(chunk)
                        memit(chunk)
                    try:
                        run_model(lbl, full_messages, _draft_live)
                        draft = strip_think("".join(parts))
                    except Exception:
                        draft = ""
                    if draft and not _looks_degenerate(draft):
                        step("draft", "Drafted the answer", "done",
                             "%d chars" % len(draft))
                        step("polish", "Polishing", "run", "")
                        status(f"{lbl} is polishing")
                        emit(Ctl(NUL + "RESET" + NUL))     # the polish takes the draft's place
                        # for a searched OR doc-carrying answer the
                        # "question" is the full grounded message — a
                        # reviser that can't see the data can't tell a
                        # real specific from an invented one. Given only
                        # the bare prompt, it deleted a correct answer
                        # with "you haven't attached the file" (the
                        # anti-invention rule doing its job on the
                        # wrong evidence — seen in the gauntlet).
                        src_q = (ground_clip(full_messages[-1]["content"], 10000)
                                 if (query or docs) else prompt)
                        try:
                            _stream_guarded(
                                lbl,
                                [brief_system(full_messages[0]),     # the brief (6b515)
                                 {"role": "user",
                                  "content": REVISE_INSTRUCTION
                                  + "QUESTION: " + src_q
                                  + "\n\nFIRST DRAFT:\n" + draft[:6000]}],
                                memit, status, draft,
                                "showing the first draft")
                        except (StaleProfile, BrokenPipeError, ConnectionResetError):
                            raise
                        except Exception:
                            # the polish failed or timed out: the draft is
                            # the answer (6b539), shown whole again
                            status(f"{lbl} kept the first draft")
                            emit(Ctl(NUL + "RESET" + NUL))
                            memit(draft)
                    else:
                        # a draft that wandered was on screen: it goes (6b539)
                        if parts:
                            emit(Ctl(NUL + "RESET" + NUL))
                        _stream_guarded(lbl, full_messages, memit, status,
                                        None,
                                        "kept the part before it wandered")
                    _single_polish()
                else:
                    # the page draws the step, not the status line, while
                    # nothing has streamed: that is where a giant's cold
                    # load of 300-400 GB is explained (6b314)
                    if slow_giant(lbl):
                        step("draft", "Loading %s (%d GB). Can take minutes." % (
                                 lbl, round(MODEL_INFO[lbl]["gb"])), "run", "")
                    else:
                        step("draft", "Writing the answer", "run", lbl)
                    # guarded like every other path: a lone model that
                    # collapses into repetition gets cut back to its
                    # coherent prefix instead of streaming the loop
                    _stream_guarded(lbl, full_messages,
                                    memit, status, None,
                                    "kept the part before it wandered")
                    _single_polish()
        except (BrokenPipeError, ConnectionResetError):
            pass  # user hit Stop — browser closed the connection
        except ServerError as exc:
            # a council of your own servers' models that none answered
            # (6b334): said, and no other model is tried; a server pick says
            # how to go on (6b570)
            try:
                emit(AppText("\n\u26a0\ufe0f " + str(exc)))
                if _srv_only and not _model_said[0]:
                    server_offer(emit, (_so_c0 or "").split(SERVER_SEP, 1)[0])
            except (BrokenPipeError, ConnectionResetError):
                pass
        except Exception as exc:
            try:
                emit("\n" + offline_hint(kind, exc))
            except (BrokenPipeError, ConnectionResetError):
                pass
            if not sent[0] and not cloud_only and not _srv_lbl and not _srv_only:
                # every path stayed silent (engine died mid-answer, a
                # provider returned nothing). Try the smallest brain on
                # disk before admitting defeat. Cloud Only opts out: a
                # local rescue is exactly what the user ruled out. So does
                # a pick of your own server, "<server> Only" included
                # (6b337): its failure is said, never covered.
                # the person's server first (6b357), when it isn't the one
                # that just failed and the turn carries no picture
                _rs = (server_side_pick(user_base, "fast", "normal")
                       if not images else None)
                if _rs is not None and _rs["label"] != (route_label or model_name):
                    try:
                        status(f"retrying on {_rs['label']}")
                        with server_first_deadline(SRV_SIDE_FIRST_S):
                            run_model(_rs["label"], full_messages, memit)
                    except (StaleProfile, BrokenPipeError, ConnectionResetError):
                        raise
                    except Exception as _rx:
                        server_mark_down(user_base, _rs["server"], str(_rx))
                if not sent[0]:
                    try:
                        pulled = ollama_pulled_tags() or set()
                        alt = next((l for l in reversed(MERGE_RANK)
                                    if model_cached(l, pulled)
                                    and l != (route_label or model_name)), None)
                        if alt:
                            status(f"retrying on {alt}")
                            run_model(alt, full_messages, memit)
                    except Exception:
                        pass
            if not sent[0]:
                emit("The engine stopped and the backup didn’t answer. Ask again.")
        finally:
            _srv_think.brief = False       # (6b570) a greeting's one pass ends with it
            # the effort ends with the answer (6b534): a title or a memory
            # pass after it on this thread reasons at the model's default
            _srv_think.level = _srv_think.effort = None
            # the hurry registry entry dies with the request — a set()
            # arriving after this harmlessly answers ok:false (6b257)
            with _hurry_lock:
                _hurry_jobs.pop(hurry_id, None)
                _skip_jobs.pop(hurry_id, None)
            # which provider wrote this answer, if any (6b308): titles,
            # memory and map pins go back to it and nowhere else
            _ans_conf = _answered.pop(threading.get_ident(), None)
            # the profile this answer was for is no longer the active one
            # (review of 6b329): no badge, no place pins (a call on its
            # key), no export, no log lines, no memory pass
            _gone = user_base.cancel.is_set()
            if _ans_conf and _title_cid and not _gone:
                _last_cloud[(user_base.name, _title_cid)] = (
                    _ans_conf, time.time())
            # A chat on a server's model (6b337 "<server> Only", and any
            # plain pick, 6b339): its title is written by that server's
            # model, or by none when the answer never came; never by a
            # model on this Mac, whose graphics card the person kept quiet
            # by choosing the server (Patrick's Buenos Aires hotels chat
            # ran a local title model after a failed server answer)
            # Thinking or Pro on one server alone (6b426) ran on several of its
            # models: the turn is the first seat's for its title and its memory
            # pass, as a single server model's is, unless that server just failed
            if (_srv_only and not _srv_lbl and council
                    and not server_label_down(user_base, council[0])):
                _srv_lbl = council[0]
            if (_srv_only or _srv_lbl) and _title_cid and not _gone:
                _srv_only_chats[(user_base.name, _title_cid)] = (
                    _srv_lbl if _model_said[0] and not _so_fail else "",
                    time.time())
            elif _seat_fb and _title_cid and not _gone:
                # a mode's server seat (6b339, UX review): the chat is titled
                # by the server that answered, or by none when it fell back
                # (a failed turn needs no title); never by a model on this Mac
                _seat_t = server_seat_title(
                    council, _seat_fb, _seat_res[0], _model_said[0],
                    bool(_ans_conf), lambda l: server_label_down(user_base, l))
                if _seat_t is not None:
                    _srv_only_chats[(user_base.name, _title_cid)] = (
                        _seat_t, time.time())
            if _ans_conf and not _gone:
                # the badge under the answer says "cloud", whatever the
                # line-up said up front (a picture Claude read, 6b308);
                # a chat with no id gets it too (6b326, from review)
                try:
                    _write((NUL + "RUN:" + json.dumps({"w": "cloud"})
                            + NUL).encode("utf-8"))
                except Exception:
                    pass
            # THE MODULE MUST NOT DEPEND ON THE BIG MODEL REMEMBERING a
            # trailer (it forgets ~half the time, and doesn't always
            # bold names either — both seen live). A tiny model reads
            # the finished answer and names the venues. Cheap, and it
            # only runs for place-shaped questions that searched.
            if not _gone:
                try:
                    if sent[0]:
                        # the answer's own length, not the frames' (6b515:
                        # it said 7,421 chars for a 3,095-char answer)
                        step("draft", "Answer written", "done",
                             "%d chars" % (shown_n[0] or sent[0]))
                        step("polish", "Polished", "done", "")
                    # OSM already named the venues and knows where they are,
                    # so the local extraction pass is pure cost — pin them
                    # straight from the structured rows, mentioning only the
                    # ones the answer actually talked about.
                    _osmr = getattr(_tl_search, "osm", None) or []
                    if _osmr and sent[0] > 60 and not images:
                        _ans = "".join(answer_buf).lower()
                        _named = [p for p in _osmr if p["n"].lower() in _ans]
                        _pick = (_named or _osmr)[:4]
                        step("places", "Pinned the places", "done",
                             "%d from OpenStreetMap" % len(_pick))
                        try:
                            _write((NUL + "PLACES2:" + json.dumps(
                                [{"n": p["n"],
                                  "d": p["d"],
                                  "h": (p["h"] + (" · open now" if p.get("open")
                                                  else "")) if p["h"] else ""}
                                 for p in _pick]) + NUL).encode("utf-8"))
                            if _pick and _pick[0].get("lat"):
                                _write((NUL + "MAP:" + json.dumps(
                                    {"lat": _pick[0]["lat"],
                                     "lon": _pick[0]["lon"],
                                     "name": _pick[0]["n"]}) + NUL)
                                    .encode("utf-8"))
                        except Exception:
                            pass
                    elif (query and sent[0] > 120 and _model_said[0]
                            and (placey or bookish) and not images
                            and (_ans_conf or not cloud_only)
                            and not (server_label(route_label or model_name)
                                     and server_label_down(
                                         user_base, route_label or model_name))):
                        step("places", "Finding the places", "run", "")
                        usage_role("places")     # the page's ledger row (6b528)
                        ans = "".join(answer_buf)[-2400:]
                        _pin_ask = [
                            {"role": "user", "content":
                             "From the text below, list the real venue "
                             "names it recommends (bars, restaurants, "
                             "cafes, shops). Output ONLY a JSON array of "
                             "strings, max 4, nothing else. If there are "
                             "none, output [].\n\nTEXT:\n" + ans}]
                        # the model that JUST answered is already resident —
                        # reaching for the 1B would swap engines and evict it.
                        # A cloud answer is pinned by that provider's quick
                        # model instead of loading a big local one (6b308)
                        small = route_label or model_name
                        # the answer's ticket, its key re-read now (6b326): a
                        # provider removed or re-keyed since gets no call
                        # and the chat gate again, now (6b326, from review)
                        _pc = (_ticket_conf(_ans_conf)
                               if _ans_conf and cloud_allowed(cloud_only)
                               else None)
                        _pm = (cloud_role_model(_provider_of(_pc), _pc,
                                                "utility") if _pc else "")
                        if _pm or small:
                            got2 = []
                            if _pm:
                                got2.append(cloud_text(
                                    dict(_pc, model=_pm, role="utility"),
                                    _pin_ask, timeout=20, max_tokens=400,
                                    quiet=True))
                            elif not cloud_only:
                                # an answer of this computer's: the person's
                                # server pins it first (6b357)
                                _ps = (None if server_label(small)
                                       else server_side_text(_pin_ask, user_base))
                                if _ps is not None:
                                    got2.append(_ps)
                                else:
                                    run_model(small, _pin_ask, got2.append)
                            raw2 = strip_think("".join(got2))
                            m2 = re.search(r"\[[^\[\]]*\]", raw2, re.S)
                            names = []
                            if m2:
                                try:
                                    names = [str(x)[:42] for x in
                                             json.loads(m2.group(0))
                                             if isinstance(x, str)][:4]
                                except Exception:
                                    names = []
                            low = ans.lower()
                            names = [x for x in names
                                     if 2 < len(x) < 42 and x.lower() in low]
                            step("places", "Found the places", "done",
                                 "%d pinned" % len(names))
                            # bare names with no location to pin them in
                            # are bold phrases, not places (6b437)
                            if names and getattr(_tl_search, "locq", ""):
                                _write((NUL + "PLACES2:" + json.dumps(
                                    [{"n": x, "d": "", "h": ""} for x in names])
                                    + NUL).encode("utf-8"))
                except Exception:
                    pass
            if export_req and export_req["lane"] == "draft" and not _gone:
                _txt = x_clean("".join(answer_buf))
                _ext = export_req["ext"] or _SHAPE_FMT.get(
                    _export_shape(_txt), "md")
                try:
                    _info = run_export(_txt, _ext, x_title(prompt, _txt),
                                       self.ctx,
                                       export_req.get("filename", ""))
                    emit("\n\n[[dl:%s]]" % json.dumps(
                        _info, separators=(",", ":")))
                except StaleProfile:
                    pass
                except Exception as _exc:
                    emit("\n\nThe answer is written but the file failed: %s." % str(_exc)[:200])
            # THE RUN'S CLOCK (6b528): first word and total from the request's
            # arrival, and the mode that answered, so the page's token line and
            # signature say the same on a reopened chat as they did live.
            # Then the tap goes quiet: the memory pass reports nowhere.
            _tap_on[0] = False
            usage_tap(None)
            usage_role("")
            if not _gone and _model_said[0]:
                try:
                    _now = time.time()
                    _write((NUL + "DONE:" + json.dumps({
                        "f": round(_t_first[0] - _t_req, 2) if _t_first[0] else None,
                        "t": round(_now - _t_req, 2), "mode": tier or "",
                        "effort": _effort or ""},      # the byline's shimmer follows it (OVERRIDE 4)
                        separators=(",", ":")) + NUL).encode("utf-8"))
                except Exception:
                    pass
            hb_stop.set()
            # the quality ledger: one line per answer, so "make it
            # better" has numbers instead of vibes (grep-able JSONL)
            # (in the asking profile, 1a 5.7)
            try:
                if _gone:
                    raise StaleProfile("the profile changed")
                qpath = user_base.path(QUALITY_FILE)
                if os.path.exists(qpath) and \
                        os.path.getsize(qpath) > 2_000_000:
                    user_base.remove(QUALITY_FILE)
                user_base.append(QUALITY_FILE, (json.dumps({
                    "ts": int(time.time()), "tier": tier,
                    "model": route_label or model_name,
                    "searched": bool(query), "chars": sent[0],
                }) + "\n").encode("utf-8"), mode=0o644)
            except StaleProfile:
                pass            # a stale line lands nowhere, as it should
            except Exception:
                pass
            # Settings › Usage counts answers too (6b325): one per
            # question a model's own text answered (memit), under the
            # model that wrote it
            if _model_said[0] and not _gone:
                try:
                    usage_put({"t": round(time.time(), 1), "a": 1, "m": str(
                        (_ans_conf or {}).get("model") or route_label
                        or model_name or "")[:80]})
                except StaleProfile:
                    pass
                except Exception:
                    pass
            plain = prompt[8:] if prompt.lower().startswith("/search") \
                else prompt
            # the memory pass reads the question. A cloud answer is read by
            # that same provider's quick model, so a keys-only user builds
            # memory too and the words reach no second company (6b308); a
            # local answer stays local, and Cloud Only never runs locally
            # (and none for a server pick that got no answer, 6b339: it only
            # asked the server again, a second and third request for one
            # failed turn)
            _ml = route_label or (council[0] if council else "")
            if (plain and len(plain) > 12 and (_ans_conf or not cloud_only)
                    and not _gone and not _so_fail
                    and not (_srv_lbl and not _model_said[0])
                    and not (server_label(_ml)
                             and server_label_down(user_base, _ml))):
                ctx_thread(
                    target=_extract_memory,
                    args=(route_label or (council[0] if council else ""),
                          plain, user_base),
                    kwargs={"conf": _ans_conf, "cloud_only": cloud_only},
                    daemon=True).start()


# Where the app goes when 8889 is taken: far from the engines, whose
# catalog ports climb by two from 8884 (8950 today, and the next row
# takes the next even port), from ConcordeGo's 9897, from the dev and
# gauntlet ports (9894, 9895, 9901-9903) and from 9889, the retired web
# copy's. The gauntlet fails if a catalog or retired port ever lands in
# here.
FALLBACK_PORTS = tuple(range(18890, 18899))


def bind_backend():
    """Bind the app's server BEFORE any window opens, and say which port
    it got (6b310). This used to bind on a background thread while the
    window opened http://127.0.0.1:8889 regardless. On a Mac with two
    logins, when the other person's ConcordeAI already held 8889, only
    that thread died, and this window loaded THEIR app: their chats,
    memory and keys. Now a taken port moves the desktop app to a
    fallback (dev and test instances named their port and fail
    instead), and the window opens the port actually bound."""
    global PORT
    last = None
    for p in (PORT,) + (FALLBACK_PORTS if DEFAULT_APP else ()):
        srv = socketserver.ThreadingTCPServer(
            ("127.0.0.1", p), StudioHandler, bind_and_activate=False)
        srv.daemon_threads = True
        if IS_WIN:
            # Windows' SO_REUSEADDR lets a second process bind a port
            # that is already listening; exclusive use forbids it
            srv.allow_reuse_address = False
            try:
                srv.socket.setsockopt(socket.SOL_SOCKET,
                                      socket.SO_EXCLUSIVEADDRUSE, 1)
            except (AttributeError, OSError):
                pass
        else:
            srv.allow_reuse_address = True
        try:
            srv.server_bind()
            srv.server_activate()
        except OSError as exc:
            srv.server_close()
            last = exc
            continue
        PORT = p
        return srv
    raise last or OSError("no port to listen on")


_INSTANCE_LOCK = []
INSTANCE_NOTE = os.path.join(app_dir(), "run", "instance.json")


def single_instance(wait: float = 15.0, dev: bool = False) -> bool:
    """One desktop app per OS user (6b310). A second copy on a fallback
    port would write the same chats.json as the first, and the last
    whole-list save wins. True = this process holds the lock and runs.
    False = another copy runs: it was asked to bring its window forward,
    or the person was told it's open. A copy that is quitting (the swap
    after an update) answers nothing, so the new one waits for its lock.
    A dev copy holds its own folder's lock and, when another copy holds
    it, just says no (6b319): no hand-off, no wait, no dialog."""
    path = os.path.join(app_dir(), "run", "instance.lock")
    try:
        os.makedirs(os.path.dirname(path), exist_ok=True)
        os.chmod(os.path.dirname(path), 0o700)
        f = open(path, "a+")
    except OSError:
        return True          # can't lock, can't police: don't block launch

    def _try_lock():
        try:
            if IS_WIN:
                import msvcrt
                f.seek(0)
                msvcrt.locking(f.fileno(), msvcrt.LK_NBLCK, 1)
            else:
                import fcntl
                fcntl.flock(f.fileno(), fcntl.LOCK_EX | fcntl.LOCK_NB)
            _INSTANCE_LOCK.append(f)     # held open for the process's life
            return True
        except OSError:
            return False

    if _try_lock():
        return True
    if dev:
        f.close()
        return False
    if _hand_off():
        f.close()
        return False
    deadline = time.time() + wait
    while time.time() < deadline:
        time.sleep(0.5)
        if _try_lock():
            return True
    f.close()
    _already_open_notice()
    return False


def _write_instance_note():
    """Where this copy's window lives, for a second launch to find
    (0600, in this user's own data folder: the key and the API token
    open the app). Never the boot code: that is the window's alone."""
    try:
        fd = os.open(INSTANCE_NOTE, os.O_WRONLY | os.O_CREAT | os.O_TRUNC,
                     0o600)
        with os.fdopen(fd, "w") as fh:
            json.dump({"port": PORT, "key": ACCESS_KEY, "token": API_TOKEN,
                       "pid": os.getpid()}, fh)
    except OSError:
        pass
    atexit.register(_drop_instance_note)


def _write_boot_note():
    """The 'boot-code' test hook (6b321, dev copies only): a windowless
    copy has no window to spend a boot code, so the gauntlet gets one
    here, 0600 beside the instance note. 'boot-short' makes it live 2 s,
    so expiry is tested without a 60 s wait. The native shell's sidecar
    (MILLENAI_SHELL=tauri, 6b532) writes the same note: the shell reads
    it, loads /?boot=<code> once, and deletes the file."""
    code = _mint_boot_code(2.0 if "boot-short" in TEST_HOOKS else BOOT_TTL)
    try:
        fd = os.open(os.path.join(os.path.dirname(INSTANCE_NOTE),
                                  "boot.json"),
                     os.O_WRONLY | os.O_CREAT | os.O_TRUNC, 0o600)
        with os.fdopen(fd, "w") as fh:
            json.dump({"code": code, "pid": os.getpid()}, fh)
    except OSError:
        pass


def _drop_instance_note():
    """Remove the note, if it is still this copy's."""
    try:
        with open(INSTANCE_NOTE) as fh:
            if json.load(fh).get("key") == ACCESS_KEY:
                os.remove(INSTANCE_NOTE)
    except (OSError, ValueError):
        pass


# ------------------------------- the web view's own store (0b 5.10, 6b324)
# NOTHING PERSONAL STAYS IN THE WEB VIEW (I5). The page moves its six
# per-person keys into prefs.json and deletes every other key that isn't
# on its machine allow-list (storeBoot, in the page). This is the native
# half: ONE routine with a branch per web engine, run once the page has
# done that (and, from 1a, at every profile switch). It removes every
# kind of data from every site's record but the app's own, and from the
# app's own (127.0.0.1 and localhost: every port shares it) every kind
# but LocalStorage and cookies. The one cookie is the launch cookie
# millen_key_<port>, which holds nothing personal and dies with the
# launch; without it the reload that follows gets the 403 page.
#   0b Q13: once the six keys are in prefs.json, the app's own
#   LocalStorage goes as well, one time, then the page reloads: a copy of
#   the chats an old build left under another port (8889, a fallback
#   port, a dev port) is gone with it. The allow-listed conveniences
#   (model picks, sky, sidebar width) reset once.
# profile.json's "webstore" records it: "clean" when the first pass ran,
# "want_local" when the latest boot said the six keys were safe (a later
# boot that says otherwise withdraws it), "local" when the one-time
# LocalStorage removal ran.
# ON macOS NONE OF THIS RUNS YET (review of 6b324): the app runs as the
# venv's python3, so the default WebKit store is Python's, shared with
# every pywebview app that Python runs, not ConcordeAI's. Until the
# window gets a data store of its own (a follow-up), the Mac keeps only
# the page's sweep: other sites' data, caches and other ports' copies
# stay where they are.
_WEBSTORE_OWN = ("127.0.0.1", "localhost", "::1", "[::1]")
_WINDOW = []            # the app's window, once made
_webstore_lock = threading.Lock()
_webstore_reloaded = [False]    # one reload per run, whatever the record says
_QT_CLEAR_CACHE = [False]
_webstore_keep = []     # completion blocks PyObjC must keep alive


def _web_engine() -> str:
    """The web engine this build's window runs: WKWebView on a Mac,
    WebView2 on Windows x64 (and x64 under an ARM PC's emulation), Qt's
    WebEngine on the native Windows ARM64 build, through PyQt6 (pythonnet's
    clr_loader has no ARM64 DLL; 6b328, build_windows_exe.ps1)."""
    if IS_MAC:
        return "webkit"
    if IS_WIN:
        return "qt" if (IS_WIN_ARM and not IS_WIN_EMULATED) else "webview2"
    return ""


def _webview_gui() -> dict:
    """webview.start's gui argument (6b328): "qt" when the window is Qt's,
    nothing anywhere else, so macOS and x64 pick their backend as before.
    Unasked, pywebview 6.2.1 on Windows tries only WinForms (pythonnet),
    whose clr_loader has no ARM64 DLL: the native ARM64 build died at
    start with "Failed to create a .NET runtime (coreclr)"."""
    return {"gui": "qt"} if _web_engine() == "qt" else {}


# THE QT BINDING IS PyQt6 (6b328): PySide6 has no QtWebEngine for Windows
# ARM64, PyQt6-WebEngine does. qtpy reads QT_API at its first import (by
# pywebview's Qt backend, at webview.start, or _webstore_qt_cache), and a
# frozen exe has only PyQt6 anyway; this makes the choice explicit.
if _web_engine() == "qt":
    os.environ["QT_API"] = "pyqt6"


def _webstore_plan(names, local: bool) -> dict:
    """Which records lose what: "other" loses everything; "own" (the
    app's own loopback record) keeps what "keep" names: cookies, and
    LocalStorage unless local."""
    own = [n for n in names if str(n).strip().lower() in _WEBSTORE_OWN]
    other = [n for n in names if str(n).strip().lower() not in _WEBSTORE_OWN]
    return {"own": own, "other": other,
            "keep": ["cookies"] if local else ["cookies", "local"]}


def _webstore_webkit(local: bool, timeout: float = 20.0, store=None,
                     call=None) -> bool:
    """macOS: WKWebsiteDataStore fetchDataRecordsOfTypes: and
    removeDataOfTypes:forDataRecords: on the store pywebview's window
    uses (defaultDataStore; its Cocoa backend ignores storage_path).
    Called only when that store is the app's own (_webkit_own_store,
    never true yet: today it is Python's shared store). Runs on the
    main thread through AppHelper.callAfter, from any other thread; the
    completion handlers need the app's run loop, so only once the window
    runs. store and call are the seams the gauntlet drives it with."""
    import WebKit
    if call is None:
        from PyObjCTools import AppHelper
        call = AppHelper.callAfter
    done, res = threading.Event(), {"ok": False}

    def start():
        try:
            ds = store or WebKit.WKWebsiteDataStore.defaultDataStore()
            every = WebKit.WKWebsiteDataStore.allWebsiteDataTypes()
            keep = {str(WebKit.WKWebsiteDataTypeCookies)}
            if not local:
                keep.add(str(WebKit.WKWebsiteDataTypeLocalStorage))
            own_types = [t for t in every if str(t) not in keep]

            def got(records):
                try:
                    recs = list(records or [])
                    plan = _webstore_plan([str(r.displayName()) for r in recs],
                                          local)
                    own = [r for r in recs if str(r.displayName()) in plan["own"]]
                    other = [r for r in recs
                             if str(r.displayName()) in plan["other"]]
                    jobs = [(every, other)] if other else []
                    if own and own_types:
                        try:
                            from Foundation import NSSet
                            ot = NSSet.setWithArray_(own_types)
                        except Exception:
                            ot = set(own_types)
                        jobs.append((ot, own))
                    left = [len(jobs)]
                    if not jobs:
                        res["ok"] = True
                        done.set()
                        return

                    def one():
                        left[0] -= 1
                        if left[0] <= 0:
                            res["ok"] = True
                            done.set()
                    _webstore_keep.append(one)
                    for types, rs in jobs:
                        ds.removeDataOfTypes_forDataRecords_completionHandler_(
                            types, rs, one)
                except Exception:
                    done.set()
            _webstore_keep.append(got)
            ds.fetchDataRecordsOfTypes_completionHandler_(every, got)
        except Exception:
            done.set()
    call(start)
    done.wait(timeout)
    return res["ok"]


def _webstore_wv2_kinds(K, local: bool):
    """CoreWebView2BrowsingDataKinds for WebView2's clean-up: every kind
    but local storage and cookies (all origins at once: WebView2 has no
    per-site call, and the window loads only from loopback), plus local
    storage when local. The kinds are named, never numbered."""
    names = ["FileSystems", "IndexedDb", "WebSql", "CacheStorage",
             "ServiceWorkers", "DiskCache", "DownloadHistory",
             "GeneralAutofill", "PasswordAutosave", "BrowsingHistory",
             "Settings"] + (["LocalStorage"] if local else [])
    return [getattr(K, n) for n in names if hasattr(K, n)]


def _webstore_wv2_value(K, kinds):
    """The kinds as one flags value of type K. pythonnet 3 keeps .NET
    enums typed and may not OR them, and a plain int isn't accepted
    where the enum is expected: OR them, else build K from the bits."""
    val = None
    try:
        import functools
        import operator
        val = functools.reduce(operator.or_, kinds)
    except Exception:
        val = None
    if val is None or isinstance(val, int):
        n = 0
        for k in kinds:
            n |= int(k)
        try:
            val = K(n)
        except Exception:
            import clr
            from System import Enum
            val = Enum.ToObject(clr.GetClrType(K), n)
    return val


def _webstore_wv2(window, local: bool, timeout: float = 20.0) -> bool:
    """Windows x64: CoreWebView2Profile.ClearBrowsingDataAsync on the
    window's own WebView2 (its user-data folder is app_dir()/webkit:
    pywebview's WinForms backend honours storage_path), on the window's
    UI thread. UNVERIFIED here: it needs the x64 build on Windows."""
    import clr  # noqa: F401  (pythonnet, loaded by pywebview already)
    from System import Action, Func, Type
    from System.Threading.Tasks import Task
    from Microsoft.Web.WebView2.Core import CoreWebView2BrowsingDataKinds as K
    val = _webstore_wv2_value(K, _webstore_wv2_kinds(K, local))
    form = window.native
    done = threading.Event()

    def run():
        prof = form.browser.webview.CoreWebView2.Profile
        t = prof.ClearBrowsingDataAsync(val)
        t.ContinueWith(Action[Task](lambda _t: done.set()))
    form.Invoke(Func[Type](run))
    return done.wait(timeout)


def _webstore_qt_sweep(folder: str, keep_local: bool):
    """The Qt build's store as files (0b Q16: QtWebEngine has no
    per-origin LocalStorage removal). Everything in the profile's
    persistent folder goes (cookies, IndexedDB, service workers, caches,
    session storage...) except "Local Storage" when keep_local. Run
    before the window opens, so no page holds any of it and the launch
    cookie of this run isn't set yet. (removed, failed): the names gone
    and those that couldn't all go; a caller records success only when
    nothing failed."""
    out, bad = [], []
    try:
        names = sorted(os.listdir(folder))
    except FileNotFoundError:
        return out, bad
    except OSError:
        return out, ["."]
    for n in names:
        if keep_local and n == "Local Storage":
            continue
        p = os.path.join(folder, n)
        try:
            if os.path.isdir(p) and not os.path.islink(p):
                shutil.rmtree(p)
            else:
                os.remove(p)
            out.append(n)
        except OSError:
            bad.append(n)
    return out, bad


def _webstore_state(base=MACHINE_ROOT) -> dict:
    p = _read_json(PROFILE_FILE, base, dict) or {}
    w = p.get("webstore")
    return dict(w) if isinstance(w, dict) else {}


def _webstore_mark(base=MACHINE_ROOT, **kv):
    with _profile_lock:
        p = _read_json(PROFILE_FILE, base, dict) or {}
        w = p.get("webstore") if isinstance(p.get("webstore"), dict) else {}
        w.update(kv)
        p["webstore"] = w
        _write_json(PROFILE_FILE, p, base, indent=1)


def _webstore_qt_boot(base=MACHINE_ROOT):
    """The Qt branch, at a start before the window: the first pass, and
    the one-time LocalStorage removal once the page has asked for it.
    UNVERIFIED here: it needs the ARM64 build on Windows ARM64."""
    try:
        ws = _webstore_state(base)
        need_clean = not ws.get("clean")
        need_local = bool(ws.get("want_local")) and not ws.get("local")
        if not (need_clean or need_local):
            return
        _gone, bad = _webstore_qt_sweep(os.path.join(app_dir(), "webkit"),
                                        keep_local=not need_local)
        _QT_CLEAR_CACHE[0] = True       # the HTTP cache, once the view is up
        if bad:
            # something held a file: nothing is recorded, the next start
            # tries again (review of 6b324)
            print("  (web view store: couldn't remove %s; next start)"
                  % ", ".join(bad[:5]))
            return
        now = int(time.time())
        _webstore_mark(base, clean=ws.get("clean") or now,
                       **({"local": now} if need_local else {}))
    except Exception as exc:
        print("  (web view store not cleaned: %s)" % exc)


def _webstore_qt_cache(window):
    """The Qt profile's HTTP cache (QWebEngineProfile.clearHttpCache; its
    folder is cachePath(), which setPersistentStoragePath doesn't move),
    on the Qt main thread through a queued signal."""
    if not _QT_CLEAR_CACHE[0]:
        return
    _QT_CLEAR_CACHE[0] = False
    try:
        from qtpy import QtCore
        prof = window.native.profile

        class _Run(QtCore.QObject):
            go = QtCore.Signal()

            def __init__(self):
                super().__init__()
                # scoped: PyQt6 has no unscoped enums of its own (6b328)
                self.go.connect(self.do,
                                QtCore.Qt.ConnectionType.QueuedConnection)

            @QtCore.Slot()
            def do(self):
                prof.clearHttpCache()
        r = _Run()
        r.moveToThread(QtCore.QCoreApplication.instance().thread())
        _webstore_keep.append(r)
        r.go.emit()
    except Exception as exc:
        print("  (web view cache not cleared: %s)" % exc)


APP_BUNDLE_ID = "com.millen.millenai"      # build_macos_app.sh's


def _webkit_own_store() -> bool:
    """True only when this process is the app's own bundle, so that
    WKWebsiteDataStore.defaultDataStore() is ConcordeAI's store and no
    one else's. True in the .app since 6b455: its launcher runs the
    interpreter in its own process, so the bundle is ConcordeAI.app (it
    was org.python.python when the venv's python3 ran). False for a
    python started any other way, the launcher's child fallback
    included, so the macOS branch leaves Python's shared store alone."""
    try:
        from Foundation import NSBundle
        return str(NSBundle.mainBundle().bundleIdentifier() or "") \
            == APP_BUNDLE_ID
    except Exception:
        return False


def _webkit_store_adopt(base=None) -> bool:
    """One-time (6b455): the window's WebKit store is the app's own now
    (~/Library/WebKit/<APP_BUNDLE_ID>), not Python's shared one, so the
    page's localStorage (the backdrop history, the voice, the sidebar
    width) would start empty after the update. Before the window opens,
    Python's store is copied there once, when the app's own has none
    yet; after that they go their own ways. base: the ~/Library/WebKit
    folder (a test's seam; without it, the desktop app's own only)."""
    if base is None:
        if not (IS_MAC and DEFAULT_APP and _webkit_own_store()):
            return False
        base = os.path.expanduser("~/Library/WebKit")
    src = os.path.join(base, "org.python.python", "WebsiteData")
    dst = os.path.join(base, APP_BUNDLE_ID, "WebsiteData")
    if os.path.exists(dst) or not os.path.isdir(src):
        return False
    try:
        shutil.copytree(src, dst)
        return True
    except Exception as exc:
        print("  (web view store not carried over: %s)" % exc)
        shutil.rmtree(dst, ignore_errors=True)
        return False


def _webstore_native(local: bool) -> bool:
    """The branch for this build's engine. False: it didn't run (no
    window, an engine without a live branch, or it failed); nothing is
    recorded and the next boot's page asks again."""
    if "webstore-fake" in TEST_HOOKS:
        # a dev copy's stand-in (the gauntlet has no window): records
        # what the routine was asked, and the plan for a few records
        rec = {"local": local, "plan": _webstore_plan(
            ["127.0.0.1", "localhost", "openstreetmap.org"], local)}
        p = os.path.join(app_dir(), "run", "webstore.json")
        try:
            with open(p, encoding="utf-8") as fh:
                runs = json.load(fh)
        except (OSError, ValueError):
            runs = []
        with open(p, "w", encoding="utf-8") as fh:
            json.dump(runs + [rec], fh)
        return True
    if not _WINDOW:
        return False
    eng = _web_engine()
    try:
        if eng == "webkit":
            # NOT PYTHON'S STORE (review of 6b324): the app runs as the
            # venv's python3, so the default WebKit store is Python's own,
            # shared with every pywebview app that Python runs. It is left
            # alone until the app has a store of its own
            if not _webkit_own_store():
                return False
            return _webstore_webkit(local)
        if eng == "webview2":
            return _webstore_wv2(_WINDOW[0], local)
    except Exception as exc:
        print("  (web view store not cleaned: %s)" % exc)
    return False


def webstore_clean(local: bool, base=MACHINE_ROOT) -> dict:
    """POST /api/webstore/clean, the page's call at every boot once the
    six keys are handled. local: none of the six is left in browser
    storage (0b Q13). {"reload": true} tells the page to reload (after
    the one-time LocalStorage removal). A failure changes nothing and
    never stands in the window's way; the next boot asks again. On Qt
    the files go at the next start, before the window (_webstore_qt_boot)."""
    with _webstore_lock:
        ws = _webstore_state(base)
        # the LocalStorage purge follows THIS boot's word only (review of
        # 6b324): a later boot whose keys aren't safe withdraws an earlier
        # boot's request, which the Qt branch would act on at the next start
        if local and not ws.get("want_local"):
            _webstore_mark(base, want_local=int(time.time()))
            ws["want_local"] = 1
        elif not local and ws.get("want_local") and not ws.get("local"):
            _webstore_mark(base, want_local=0)
            ws["want_local"] = 0
        need_clean = not ws.get("clean")
        need_local = local and not ws.get("local")
        if not (need_clean or need_local):
            return {"ran": False, "reload": False}
        eng = "fake" if "webstore-fake" in TEST_HOOKS else _web_engine()
        if eng == "qt":
            return {"ran": False, "reload": False, "later": True}
        if not _webstore_native(need_local):
            return {"ran": False, "reload": False}
        now = int(time.time())
        _webstore_mark(base, clean=ws.get("clean") or now,
                       **({"local": now} if need_local else {}))
        reload_ = need_local and not _webstore_reloaded[0]
        _webstore_reloaded[0] = _webstore_reloaded[0] or reload_
        return {"ran": True, "reload": reload_}


# THE SIX PER-PERSON KEYS (0b 5.10, Q10) the page kept in browser storage,
# as prefs.json holds them: millen.tier, agent, codeagent, adv, advon and
# autonomy (which keeps 6b310's remote_autonomy). model and council join
# them there (review of 6b324: tier "" means "this model", so the model
# must be kept where the tier is), though their browser keys stay
# allow-listed
PREF_SIX = ("tier", "agent", "codeagent", "adv", "advon", "remote_autonomy",
            "model", "council")


def _pref_six_ok(k, v) -> bool:
    if k in ("tier", "agent", "codeagent"):
        return isinstance(v, str) and len(v) <= 60
    if k == "model":
        return isinstance(v, str) and 0 < len(v) <= 80
    if k == "council":
        return (isinstance(v, list) and 0 < len(v) <= 12
                and all(isinstance(x, str) and 0 < len(x) <= 80 for x in v))
    if k == "adv":
        return v is None or (isinstance(v, dict)
                             and len(json.dumps(v)) <= 8000)
    if k == "advon":
        return isinstance(v, bool)
    if k == "remote_autonomy":
        return v in ("manual", "auto", "full")
    return False


def prefs_adopt(d: dict, ctx) -> dict:
    """POST /api/prefs/adopt: the page's first-run post of the six keys.
    Only keys the profile lacks are taken (Q10: the server wins, as
    remote_autonomy already did); the reply lists every one of the six
    the profile now holds, and the page removes exactly those from browser
    storage. An unreadable file raises (503) and takes nothing. They are
    PROFILE_LOCAL (1a 5.6): prefs.json for "This computer"."""
    took = []
    if not ctx.root:
        # AN ACCOUNT ADOPTS NOTHING (M9, from the review of 6b329): the six
        # keys in browser storage are what builds before 6b324 left, and
        # they were "This computer"'s. A page drawn for one profile could
        # post them after a switch; nothing of them may reach an account.
        # The reply lists none, so the page leaves them for root's next boot.
        return {"ok": True, "took": [], "prefs": {}}

    def _take(cur):
        for k, v in (d or {}).items():
            if k in PREF_SIX and k not in cur and _pref_six_ok(k, v):
                cur[k] = v
                took.append(k)
    cur = profile_local_update(ctx, _take)
    return {"ok": True, "took": sorted(took),
            "prefs": {k: cur[k] for k in PREF_SIX if k in cur}}


_WIN_STATE = {"min": False, "max": False}   # as the window's events say


def _window_url() -> str:
    return str(webview.windows[0].get_current_url() or "")


class _WindowBridge:
    """The page's js_api (6b321): ONE public method. pywebview exposes
    every public attribute and walks into public objects, so this holds
    nothing else: a window handle here would hand the page load_url and
    evaluate_js."""
    __slots__ = ()

    def api_token(self):
        """The API token, only while the window shows this app's own
        origin (0a section 9): any page the window lands on gets the
        bridge too. WebView2 keeps the URL as a System.Uri: str() it."""
        try:
            u = urllib.parse.urlsplit(_window_url())
            if (u.scheme, u.hostname, u.port) == ("http", "127.0.0.1", PORT):
                return API_TOKEN
        except Exception:
            pass
        return None


# THE ACCOUNT WINDOW (1a 5.9, M9, 6b330). Every account action opens in
# a small window of its own at /account, never in the main one: that page
# renders model answers, markdown and a third-party map, so it may ask for
# the window to open but can't fill it in, read from it or call an account
# route. The account window has its own one-time boot code and its own
# token, handed over by its own js_api and bound to the profile's epoch at
# open; /api/account/* takes that token only (the main window's is refused)
# and the profile it was opened for (X-Profile), and a switch closes every
# account window but the one running it, which gets a new token for the new
# epoch. Its page is static (/account.css, /account.js) under a strict CSP,
# builds every string with textContent, has no forms and no text selection.
# One window at a time. The screens themselves are 1e's; this is the frame.
# Everything here is behind ACCOUNTS (dev and test copies until M17).
ACCOUNT_TASKS = ("create", "signin", "approve", "forgot", "cancel-reset", "kit",
                 "password", "new-kit", "remove", "delete", "export", "import",
                 "sync-key", "signout", "status")
ACCOUNT_CSP = ("default-src 'self'; img-src 'self'; form-action 'none'; "
               "base-uri 'none'; frame-ancestors 'none'; object-src 'none'")
ACCOUNT_STATIC = ("/account", "/account.css", "/account.js")
# token: the window's API token; tag: the profile it is bound to; task:
# what it opened for; window: pywebview's, None for a headless session;
# running: a switch run from it is under way; calls: account calls the
# gate let through this run (the windowed check reads it)
_ACCT = {"token": None, "tag": None, "task": None, "window": None,
         "running": False, "calls": 0, "cancel": None}
_ACCT_LOCK = threading.RLock()
_ACCT_BOOT = {"code": None, "until": 0.0}


def _mint_acct_boot(ttl: float = BOOT_TTL) -> str:
    code = secrets.token_urlsafe(32)
    with _BOOT_LOCK:
        _ACCT_BOOT.update(code=code, until=time.monotonic() + ttl)
    return code


def _take_acct_boot(code: str) -> bool:
    """The account window's one-time code, as the main window's (6b321):
    once, inside its time; a wrong guess doesn't burn it."""
    with _BOOT_LOCK:
        live = _ACCT_BOOT["code"]
        if not live:
            return False
        if time.monotonic() > _ACCT_BOOT["until"]:
            _ACCT_BOOT["code"] = None
            return False
        if not secrets.compare_digest(str(code).encode("utf-8"),
                                      live.encode("utf-8")):
            return False
        _ACCT_BOOT["code"] = None
        return True


def account_open(task: str, headless: bool = False) -> dict:
    """Open the account window for task (the main window's open_account,
    or the headless session hook). One at a time: while one is open this
    brings it forward and says which task it has. The token is bound to
    the profile active now (1a 5.9)."""
    if not ACCOUNTS:
        return {"err": "off"}
    if task not in ACCOUNT_TASKS:
        return {"err": "task"}
    with _ACCT_LOCK:
        if _ACCT["token"]:
            w = _ACCT["window"]
            if w is not None:
                try:
                    w.restore()
                    w.show()
                except Exception:
                    pass
            return {"open": True, "task": _ACCT["task"]}
        ctx = current_ctx()
        # cancel: set when the window closes; a switch it runs checks it
        # before its commit (review of 6b330)
        _ACCT.update(token=secrets.token_urlsafe(32), tag=ctx.tag, task=task,
                     window=None, running=False, cancel=threading.Event())
        tok = _ACCT["token"]
    if headless:
        return {"ok": True, "token": tok, "tag": ctx.tag, "task": task}
    try:
        w = webview.create_window(
            "%s account" % APP_NAME,
            "http://127.0.0.1:%d/account?boot=%s" % (PORT, _mint_acct_boot()),
            js_api=_AccountBridge(), width=520, height=600, min_size=(420, 480),
            background_color="#0a0a0c",
            text_select=False)        # nothing in it is for selecting
    except Exception as exc:
        account_close()
        return {"err": "window", "why": str(exc)[:120]}
    if w is None:
        account_close()
        return {"err": "window"}
    with _ACCT_LOCK:
        _ACCT["window"] = w
    try:
        w.events.closing += lambda: _account_closing(w)
        w.events.shown += lambda: _account_shown(w)
    except Exception:
        pass
    return {"ok": True, "task": task}


def _account_shown(w):
    """macOS: the window is never brought back by state restoration at the
    next launch (setRestorable_ NO), on the main thread."""
    if not IS_MAC:
        return
    try:
        from PyObjCTools import AppHelper
        AppHelper.callAfter(lambda: w.native.setRestorable_(False))
    except Exception:
        pass


def _account_closing(w):
    """The window is closing, by its close box, Esc or the app: its token
    dies at once and whatever it was asking for is cancelled (nothing it
    hadn't committed moves). Never stands in the way of the close."""
    with _ACCT_LOCK:
        if _ACCT["window"] is w:
            if _ACCT["cancel"] is not None:
                _ACCT["cancel"].set()
            _ACCT.update(token=None, tag=None, task=None, window=None,
                         running=False)


def account_close(keep_running: bool = False) -> bool:
    """Close the account window (or end the headless session). With
    keep_running, one that is running a switch stays. True when one was
    closed."""
    with _ACCT_LOCK:
        if not _ACCT["token"] or (keep_running and _ACCT["running"]):
            return False
        w = _ACCT["window"]
        if _ACCT["cancel"] is not None:
            _ACCT["cancel"].set()
        _ACCT.update(token=None, tag=None, task=None, window=None, running=False)
    if w is not None:
        try:
            w.destroy()
        except Exception:
            pass
    return True


def _account_on_switch(ctx_new):
    """1a 5.9: every switch closes the account windows except the one
    running it, which gets a new token bound to the new epoch."""
    with _ACCT_LOCK:
        if _ACCT["token"] and _ACCT["running"]:
            _ACCT.update(token=secrets.token_urlsafe(32), tag=ctx_new.tag)
            return
    account_close()


def _webstore_switch():
    """The web view's store at every switch to another folder (1a 5.12):
    0b's routine, everything but LocalStorage and cookies, so the reload
    still opens. WebView2 (x64) clears now, on its UI thread; Qt (ARM64)
    removes the files at the next start, before the window, and clears
    its HTTP cache now. macOS: nothing native (6b324: the store is
    Python's, shared with every pywebview app that Python runs, so it is
    left alone); the page's allow-list sweep at every boot is what runs
    there, and this build's page keeps nothing personal in it."""
    eng = "fake" if "webstore-fake" in TEST_HOOKS else _web_engine()
    if eng == "qt":
        try:
            with _webstore_lock:
                _webstore_mark(clean=0)
            _QT_CLEAR_CACHE[0] = True
            if _WINDOW:
                _webstore_qt_cache(_WINDOW[0])
        except Exception as exc:
            print("  (web view store not cleaned: %s)" % exc)
        return
    ctx_thread(target=_webstore_native, args=(False,), bind=False,
               daemon=True).start()


def _after_switch(ctx_new, moved: bool):
    """What every switch does once the epoch has moved: the account
    windows (1a 5.9); and, to another folder, the web view's store and
    the main window, reloaded so it stops showing the old profile's chats
    (review of 6b330; the 409 at its next call stays as the backstop)."""
    _account_on_switch(ctx_new)
    if moved and ACCOUNTS:
        _webstore_switch()
        _main_reload()


def _main_reload():
    """The main window loads the page again, on a thread of its own (a
    window call can wait on the UI thread)."""
    if "webstore-fake" in TEST_HOOKS:
        # a dev copy's stand-in (no window): records the reload
        try:
            with open(os.path.join(app_dir(), "run", "reloads.jsonl"), "a") as fh:
                fh.write("%s\n" % json.dumps({"at": time.time()}))
        except OSError:
            pass
        return
    if not _WINDOW:
        return
    w = _WINDOW[0]

    def run():
        try:
            w.load_url("http://127.0.0.1:%d/" % PORT)
        except Exception:
            pass
    ctx_thread(target=run, bind=False, daemon=True).start()


class _AccountBridge:
    """The account window's js_api: its token and its close, nothing else.
    The account page's CSP allows no eval, and pywebview builds its
    js_api functions and delivers every reply with eval, so the page calls
    the bridge through pywebview's own callback plumbing and _bridge_guard
    delivers these two replies without eval (_bridge_reply)."""
    __slots__ = ()

    def account_token(self):
        """The window's token, only while it shows this app's /account."""
        return _account_token_for(_ACCT["window"])

    def account_close(self):
        account_close()
        return True


def _account_token_for(window):
    """The account token, only to the account window itself (never a
    window closing while a new one opened) and only while it shows this
    app's /account. Asks the window its URL, which on macOS waits for the
    UI thread: never call it there (_bridge_reply runs it on a thread)."""
    try:
        with _ACCT_LOCK:
            if window is None or window is not _ACCT["window"]:
                return None
            tok = _ACCT["token"]
        u = urllib.parse.urlsplit(str(window.get_current_url() or ""))
        if (u.scheme, u.hostname, u.port, u.path) == (
                "http", "127.0.0.1", PORT, "/account"):
            return tok
    except Exception:
        pass
    return None


class _WindowBridgeAcct(_WindowBridge):
    """The main window's js_api when the build has accounts: api_token,
    and a request for the account window to open for one allow-listed
    task. It can't fill that window in or read from it."""
    __slots__ = ()

    def open_account(self, task):
        if task not in ACCOUNT_TASKS:
            return {"err": "task"}
        return account_open(task)


def _bridge_reply(window, name: str, value_id: str):
    """The account window's two calls, answered as pywebview answers but
    without its eval wrapper (the account page's CSP allows none): the
    callback pywebview's own _checkValue registered, called with the JSON.
    On its own thread, as pywebview runs a js_api call: on macOS the
    bridge arrives on the UI thread, and asking a window its URL there
    (account_token) would wait on that same thread for good."""
    def run():
        if name == "account_token":
            value = _account_token_for(window)
        else:
            account_close()
            value = True
        window.run_js("window.pywebview._returnValuesCallbacks[%s][%s]({value: %s})"
                      % (json.dumps(name), json.dumps(str(value_id)),
                         json.dumps(json.dumps(value))))
    ctx_thread(target=run, bind=False, daemon=True).start()


