def maybe_version_splash():
    """Record that an update just landed; the page shows the dialog
    (6b282). The identity compared is short_version() — "6.0.3 nightly
    a9d6da1" — so a nightly with a new commit counts as an update
    (6b288, per Patrick: "just another 6.0.3 nightly, with an updated
    commit number") and the dialog can say exactly that."""
    try:
        # dev and test instances share this prefs file with the real
        # app: they may show the moment but never move the record
        real = not os.environ.get("MILLENAI_TESTBUILD") and DEFAULT_APP
        ident = short_version()
        _last = []

        def _stamp(prefs):
            last = prefs.get("last_ident") or prefs.get("last_version")
            _last.append(last)
            if real and "app_models" not in prefs:
                _app_models_seed(prefs, existing=last is not None)
            if real and last != ident:
                prefs["last_ident"] = ident
                prefs["last_version"] = APP_VERSION
        machine_prefs_update(_stamp)
        last = _last[0]
        if last == ident:
            return
        if last is None:
            return          # fresh install gets the boot wipe, not this
        if real:
            _UPDATE_LANDED[0] = True
        # any app window shows it: the Mac-only gate was left from the
        # old full-screen splash, so Windows never saw What's new (6b317)
        if not HAS_WEBVIEW:
            return
        _JUST_UPDATED[0] = str(last)
    except Exception:
        pass


def reap_orphan_engines():
    """MLX engines whose parent died keep multi-GB of WIRED Metal memory
    pinned forever (their RSS reads ~0, which is how it hid). Seen live:
    NINE orphans (ppid 1) starved two 12B models into OOM mid-answer.
    At boot, any listener on our engine ports whose parent is init and
    whose command looks like a python server is a corpse — reap it.
    Engines owned by a living instance (the desktop app and a dev copy
    coexist) have that instance as their parent and are left alone."""
    if IS_WIN:
        return
    # EVERY port this user listens on, not just the catalog's (6b310):
    # an engine moved off a port another account held lives on a free
    # one. Only an mlx_lm server counts, never this app itself (opened
    # from Finder, the app's own parent is launchd too).
    try:
        out = subprocess.run(
            ["lsof", "-nP", "-a", "-iTCP", "-sTCP:LISTEN", "-u",
             str(os.getuid()), "-Fp"],
            capture_output=True, text=True, timeout=5).stdout
        pids = {ln[1:] for ln in out.splitlines() if ln.startswith("p")}
    except Exception:
        pids = set()
    pids.discard(str(os.getpid()))
    for pid in pids:
        try:
            ppid = subprocess.run(
                ["ps", "-o", "ppid=", "-p", pid],
                capture_output=True, text=True, timeout=5).stdout.strip()
            cmd = subprocess.run(
                ["ps", "-o", "command=", "-p", pid],
                capture_output=True, text=True, timeout=5).stdout
            if ppid == "1" and "mlx_lm" in cmd:
                os.kill(int(pid), signal.SIGTERM)
                print(f"  reaped orphan engine (pid {pid})")
        except Exception:
            pass
    # a private Ollama serve (another account held 11434) left by a crash
    note = os.path.join(app_dir(), "run", "ollama-private")
    try:
        pid, _port = open(note).read().split()
        ppid = subprocess.run(["ps", "-o", "ppid=", "-p", pid],
                              capture_output=True, text=True,
                              timeout=5).stdout.strip()
        cmd = subprocess.run(["ps", "-o", "command=", "-p", pid],
                             capture_output=True, text=True,
                             timeout=5).stdout
        if ppid == "1" and "ollama" in cmd:
            os.kill(int(pid), signal.SIGTERM)
            print(f"  reaped a private ollama serve (pid {pid})")
    except Exception:
        pass
    try:
        os.remove(note)
    except OSError:
        pass


def _retire_contribute():
    """Contribute is gone (6b310): drop its hub credentials and switches
    from prefs, and its key, worker list and ledger files. Idempotent."""
    def _drop(p):
        for k in [k for k in p if k.startswith("contrib_")
                  or k in ("fleet_auto", "seen_share")]:
            p.pop(k, None)
    try:
        machine_prefs_update(_drop)
    except Exception:
        pass
    for fn in ("fleet_key", "fleet_workers.json", "contrib_ledger.json"):
        try:
            os.remove(os.path.join(app_dir(), fn))
        except OSError:
            pass


